        function getExamPartTemplates() {
            return {
                p1: `<div class="exam-part-box">PHẦN I. Thí sinh trả lời từ câu 1 đến câu 12 . Mỗi câu hỏi thí sinh chỉ chọn một phương án.</div>`,
                p2: `<div class="exam-part-box exam-part-box-wide">PHẦN II. Thí sinh trả lời từ câu 1 đến câu 4 . Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.</div>`,
                p3: `<div class="exam-part-box">PHẦN III. Thí sinh trả lời từ câu 1 đến câu 6.</div>`,
                end: `<div class="exam-end-line">---------- <strong>HẾT</strong> ----------</div>\n<div class="exam-final-note"><i>Thí sinh không được sử dụng tài liệu; giám thị coi thi không giải thích gì thêm.</i></div>`
            };
        }

        function stripGeneratedTieuDeBlocks(content) {
            let t = content || '';
            // Bỏ header cũ của nút Tiêu đề/Mẫu Sở nếu đã có, để bấm lại không bị lặp đầu đề.
            t = t.replace(/<div class="header-container">[\s\S]*?<div class="exam-code-box">[\s\S]*?<\/div>\s*<\/div>\s*/i, '');
            // Bỏ các dòng phân phần và cuối đề cũ để sắp lại từ đầu.
            t = t.replace(/<div class="exam-part-box(?:\s+exam-part-box-wide)?">[\s\S]*?<\/div>\s*/gi, '');
            t = t.replace(/<p[^>]*class=["']section-title["'][^>]*>[\s\S]*?<\/p>\s*/gi, '');
            t = t.replace(/<div class="exam-end-line">[\s\S]*?<\/div>\s*/gi, '');
            t = t.replace(/<div class="exam-final-note">[\s\S]*?<\/div>\s*/gi, '');
            t = t.replace(/<p>\s*<strong>\s*NỘI DUNG ĐỀ THI\s*<\/strong>\s*<\/p>\s*/gi, '');
            t = t.replace(/<div[^>]*>\s*-+\s*<strong>\s*HẾT\s*<\/strong>\s*-+\s*<\/div>\s*/gi, '');
            t = t.replace(/<div[^>]*>\s*Thí sinh không được sử dụng tài liệu[\s\S]*?<\/div>\s*/gi, '');
            t = t.replace(/PHẦN\s*I[\s\S]*?(?=Câu\s*\d+|\\begin\{ex\})/gi, '');
            t = t.replace(/PHẦN\s*II[\s\S]*?(?=Câu\s*\d+|\\begin\{ex\})/gi, '');
            t = t.replace(/PHẦN\s*III[\s\S]*?(?=Câu\s*\d+|\\begin\{ex\})/gi, '');
            return t.trim();
        }

        function classifyQuestionBlock(block, isLatexEx) {
            const raw = block || '';

            // Chuyển HTML về text nhưng vẫn giữ khoảng trắng giữa các thẻ để dò nhãn a), b), A., B. ổn định.
            const plain = raw
                .replace(/&nbsp;/gi, ' ')
                .replace(/<br\s*\/?>/gi, ' ')
                .replace(/<[^>]+>/g, ' ')
                .replace(/\s+/g, ' ')
                .trim();

            const lower = plain.toLowerCase();

            // Dò class choices robust hơn: class có thể là "choices cols-1" hoặc kèm style/class khác.
            const hasChoicesCols4 = /class=["'][^"']*\bchoices\b[^"']*\bcols-4\b[^"']*["']/i.test(raw);
            const hasChoicesCols1 = /class=["'][^"']*\bchoices\b[^"']*\bcols-1\b[^"']*["']/i.test(raw);

            // Dò nhãn trong text đã strip HTML. Không yêu cầu nhãn đứng đầu dòng vì khi export HTML thường nằm trong <label><b>...</b>.
            const hasA = /(^|\s)A\s*[.)]/.test(plain);
            const hasB = /(^|\s)B\s*[.)]/.test(plain);
            const hasC = /(^|\s)C\s*[.)]/.test(plain);
            const hasD = /(^|\s)D\s*[.)]/.test(plain);
            const hasABCD = hasA && hasB && hasC && hasD;

            const hasa = /(^|\s)a\s*[)]/.test(lower);
            const hasb = /(^|\s)b\s*[)]/.test(lower);
            const hasc = /(^|\s)c\s*[)]/.test(lower);
            const hasd = /(^|\s)d\s*[)]/.test(lower);
            const hasabcd = hasa && hasb && hasc && hasd;

            // 1) PHẦN I: trắc nghiệm A/B/C/D. Ưu tiên class cols-4 hoặc đủ A B C D.
            if (/\\choice\b/i.test(raw) || /\\choice\s*\{/i.test(raw) || hasChoicesCols4 || hasABCD) return 1;

            // 2) PHẦN II: đúng/sai. Phải kiểm tra TRƯỚC khi rơi xuống Phần III.
            // Các file của thầy thường có .choices cols-1 và đủ a), b), c), d), có thể bọc trong <span>, <u> nên dò text là chắc nhất.
            if (/\\choice\s*TF\b/i.test(raw) || /\\choiceTF\b/i.test(raw) || /\\choiceTFt\b/i.test(raw)) return 2;
            if (hasChoicesCols1 || hasabcd) return 2;
            if (/đúng\s*[,;\/]?\s*sai|đúng hay sai|đúng\s*hoặc\s*sai|xét\s+tính\s+đúng\s+sai|true\s*[,;\/]?\s*false/i.test(lower)) return 2;

            // 3) PHẦN III: trả lời ngắn / đáp số.
            if (/Đáp\s*(số|án)\s*[:：]/i.test(raw) || /Ðáp\s*(số|án)\s*[:：]/i.test(raw)) return 3;
            if (/class=["'][^"']*short-answer/i.test(raw) || /input-short-ans/i.test(raw)) return 3;
            if (/\\short(ans|answer)\b/i.test(raw) || /\\dapso\b/i.test(raw) || /\\answer\b/i.test(raw)) return 3;

            // Với khối LaTeX ex, nếu không có \choice/\choiceTF thì thường là câu trả lời ngắn của Phần III.
            if (isLatexEx) return 3;

            // HTML không rõ loại, không có A/B/C/D và không có đúng-sai thì xem là Phần III.
            return 3;
        }

        function splitLatexExBlocks(content) {
            let blocks = [];
            let regex = /\\begin\{ex\}[\s\S]*?\\end\{ex\}/gi;
            let m;
            while ((m = regex.exec(content)) !== null) blocks.push(m[0].trim());
            return blocks;
        }

        function splitHtmlQuestionBlocks(content) {
            let starts = [];
            let re = /(?:<b>\s*)?Câu\s+\d+[.:]?(?:\s*<\/b>)?/gi;
            let m;
            while ((m = re.exec(content)) !== null) starts.push(m.index);
            if (!starts.length) return [];
            let blocks = [];
            for (let i = 0; i < starts.length; i++) {
                let st = starts[i];
                let en = i + 1 < starts.length ? starts[i + 1] : content.length;
                blocks.push(content.substring(st, en).trim());
            }
            return blocks.filter(x => x.length);
        }

        function renumberHtmlQuestions(blocks) {
            return blocks.map((block, i) => block.replace(/<b>\s*Câu\s+\d+[.:]?\s*<\/b>/i, `<b> Câu ${i + 1}. </b>`));
        }

        function buildTieuDeWithAutoSections(currentContent) {
            const part = getExamPartTemplates();
            let body = stripGeneratedTieuDeBlocks(currentContent || '');
            let blocks = splitLatexExBlocks(body);
            let isLatexEx = blocks.length > 0;
            if (!isLatexEx) blocks = splitHtmlQuestionBlocks(body);

            // Nếu chưa tách được câu thì KHÔNG giữ phần linh tinh còn lại của file.
            // Chỉ tạo khung tiêu đề + 3 phần trống + cuối đề.
            if (!blocks.length) {
                return getTieuDeHeaderTemplate() + "\n\n" +
                    part.p1 + "\n\n" +
                    part.p2 + "\n\n" +
                    part.p3 + "\n\n" +
                    part.end;
            }

            function cleanQuestionOnly(block) {
                let x = (block || '').trim();
                // Nếu block cuối dính các phần không phải câu hỏi thì cắt bỏ.
                x = x.replace(/<div class="exam-end-line">[\s\S]*$/i, '');
                x = x.replace(/<div class="exam-final-note">[\s\S]*$/i, '');
                x = x.replace(/<div[^>]*>\s*-+\s*<strong>\s*HẾT\s*<\/strong>\s*-+[\s\S]*$/i, '');
                x = x.replace(/<p[^>]*>\s*<strong>\s*NỘI DUNG ĐỀ THI\s*<\/strong>\s*<\/p>/gi, '');
                x = x.replace(/<div class="exam-part-box(?:\s+exam-part-box-wide)?">[\s\S]*?<\/div>/gi, '');
                x = x.replace(/<p[^>]*class=["']section-title["'][^>]*>[\s\S]*?<\/p>/gi, '');
                x = x.replace(/Thí sinh không được sử dụng tài liệu[\s\S]*$/i, '');
                return x.trim();
            }

            blocks = blocks.map(cleanQuestionOnly).filter(x => x.length);

            let p1 = [], p2 = [], p3 = [];
            blocks.forEach(block => {
                let type = classifyQuestionBlock(block, isLatexEx);
                if (type === 2) p2.push(block);
                else if (type === 3) p3.push(block);
                else p1.push(block);
            });

            if (!isLatexEx) {
                p1 = renumberHtmlQuestions(p1);
                p2 = renumberHtmlQuestions(p2);
                p3 = renumberHtmlQuestions(p3);
            }

            let result = getTieuDeHeaderTemplate() + "\n\n" +
                part.p1 + "\n\n\n" + p1.join("\n\n") + "\n\n" +
                part.p2 + "\n\n" + p2.join("\n\n") + "\n\n" +
                part.p3 + "\n\n" + p3.join("\n\n") + "\n\n" +
                part.end;
            return result.replace(/\n{4,}/g, "\n\n\n").trim();
        }

        function resetToTieuDe() {
            if (!activeTabId) {
                createNewTab("Tiêu đề", buildTieuDeWithAutoSections('') + "\n", 'FULL');
                let tab = tabs.find(t => t.id === activeTabId);
                if (tab) tab.isDirty = true;
                showToast("📌 Đã tạo tiêu đề!");
                return;
            }

            let editor = document.getElementById('editor');
            pageNumberMode = 'FULL';
            const finalText = buildTieuDeWithAutoSections(editor.value || '') + "\n";
            executeInsertText(editor, finalText, 0, editor.value.length, finalText.length, finalText.length);
            let tab = tabs.find(t => t.id === activeTabId);
            if (tab) tab.pageNumberMode = 'FULL';
            showToast("📌 Đã chèn tiêu đề và tự xếp câu vào đúng Phần I, II, III!");
        }
        function resetToChuyenDe() { createOrReplaceTab("Mẫu C.Đề", `<div style="text-align: center; margin: 20px 0;">\n    <div style="font-family: 'Roboto', sans-serif; font-size: 16px; text-transform: uppercase; text-align: center; border: 3px solid black; border-radius: 7px; padding: 10px 20px; display: inline-block;">\n        BÀI 1 - HÀM SỐ ĐỒNG BIẾN, NGHỊCH BIẾN VÀ CỰC TRỊ HÀM SỐ\n    </div>\n    <div style="text-align: center; font-size: 20px; margin-top: 5px;">\n        ✦ 📘 ✦\n    </div>\n</div>\n\n<p><strong>NỘI DUNG CHUYÊN ĐỀ</strong></p>\n\n<div style="text-align: center; margin-top: 30px;">--------- <strong>HẾT</strong> ---------</div>`); }
        function removeHeader() { if (!activeTabId) return; let editor = document.getElementById('editor'); let content = editor.value; if (!content.trim()) return; let matchIndex = content.search(/(<p[^>]*>\s*<b[^>]*>\s*PH.N\s+(?:I|1)|<b[^>]*>\s*PH.N\s+(?:I|1)|PH.N\s+(?:I|1))/i); if (matchIndex !== -1) { pageNumberMode = 'SHORT'; executeInsertText(editor, "", 0, matchIndex, 0, 0); } }
        
        function scrollToExactPosition(editor, targetIndex, queryLength) { let clone = document.createElement('div'); let styles = window.getComputedStyle(editor); clone.style.fontFamily = styles.fontFamily; clone.style.fontSize = styles.fontSize; clone.style.lineHeight = styles.lineHeight; clone.style.padding = styles.padding; clone.style.width = styles.width; clone.style.boxSizing = styles.boxSizing; clone.style.whiteSpace = 'pre-wrap'; clone.style.wordWrap = 'break-word'; clone.style.position = 'absolute'; clone.style.visibility = 'hidden'; clone.textContent = editor.value.substring(0, targetIndex); let span = document.createElement('span'); span.textContent = editor.value.substring(targetIndex, targetIndex + queryLength); clone.appendChild(span); document.body.appendChild(clone); let spanTop = span.offsetTop; document.body.removeChild(clone); editor.scrollTop = spanTop - (editor.clientHeight / 2); }
        function findNext() { if (!activeTabId) return; let editor = document.getElementById('editor'); let query = document.getElementById('searchInput').value; if (!query) return; let lowerContent = editor.value.toLowerCase(); let lowerQuery = query.toLowerCase(); if (lowerQuery !== lastQuery) { lastQuery = lowerQuery; lastIndex = -1; } lastIndex = lowerContent.indexOf(lowerQuery, lastIndex + 1); if (lastIndex === -1) { lastIndex = lowerContent.indexOf(lowerQuery, 0); } if (lastIndex !== -1) { editor.focus(); editor.setSelectionRange(lastIndex, lastIndex + query.length); scrollToExactPosition(editor, lastIndex, query.length); } }
        function replaceCurrent() { if (!activeTabId) return; let editor = document.getElementById('editor'); let searchStr = document.getElementById('searchInput').value; let replaceStr = document.getElementById('replaceInput').value; if (!searchStr) return; let start = editor.selectionStart; let end = editor.selectionEnd; let selectedText = editor.value.substring(start, end); if (selectedText.toLowerCase() === searchStr.toLowerCase() && selectedText !== "") { executeInsertText(editor, replaceStr, start, end, start + replaceStr.length, start + replaceStr.length); findNext(); } else { findNext(); } }
        function showCustomConfirm(message, actionCallback) { document.getElementById('custom-confirm-msg').innerHTML = message; document.getElementById('custom-confirm-overlay').style.display = 'flex'; replaceAllAction = actionCallback; }
        function closeCustomConfirm(isConfirmed) { document.getElementById('custom-confirm-overlay').style.display = 'none'; if (isConfirmed && replaceAllAction) replaceAllAction(); replaceAllAction = null; if (activeTabId) document.getElementById('editor').focus(); }
        function replaceAll() { if (!activeTabId) return; let editor = document.getElementById('editor'); let searchStr = document.getElementById('searchInput').value; let replaceStr = document.getElementById('replaceInput').value; if (!searchStr) return; showCustomConfirm(`Thay thế TOÀN BỘ <b>'${searchStr}'</b> thành <b>'${replaceStr}'</b>?`, function() { let escapeRegExp = function(string) { return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }; let regex = new RegExp(escapeRegExp(searchStr), 'gi'); let count = (editor.value.match(regex) || []).length; if (count > 0) { let newContent = editor.value.replace(regex, replaceStr); executeInsertText(editor, newContent, 0, editor.value.length, savedStart || 0, savedEnd || 0); } }); }

        function lhlFindPartIndexV52(content, part) {
            // Nhận diện tiêu đề phần linh hoạt: PHẦN I / PHAN I / PH.N I / <b>PHẦN II</b>...
            // Giữ index trên chuỗi gốc để phân loại câu đúng phần trong tab hiện hành.
            var roman = part === 1 ? 'I' : (part === 2 ? 'II' : 'III');
            var digit = String(part);
            var patterns = [
                new RegExp('PH(?:Ầ|Â|A|\\.)?N\\s*(?:' + roman + '|' + digit + ')\\b', 'i'),
                new RegExp('PH\\s*[ẦÂA.]?\\s*N\\s*(?:' + roman + '|' + digit + ')\\b', 'i'),
                new RegExp('PHAN\\s*(?:' + roman + '|' + digit + ')\\b', 'i')
            ];
            for (var i = 0; i < patterns.length; i++) {
                var m = patterns[i].exec(content);
                if (m) return m.index;
            }
            return -1;
        }

        function lhlStripHtmlForStatsV53(s) {
            return String(s || '')
                .replace(/<br\s*\/?>/gi, '\n')
                .replace(/<\/(?:p|div|li|tr|td|h[1-6])>/gi, '\n')
                .replace(/<[^>]+>/g, ' ')
                .replace(/&nbsp;/gi, ' ')
                .replace(/&amp;/gi, '&')
                .replace(/\s+/g, ' ')
                .trim();
        }

        function lhlClassifyQuestionBlockV53(block, fallbackPart) {
            var plain = lhlStripHtmlForStatsV53(block);
            // Phần II: câu đúng/sai có đủ hoặc gần đủ các ý a), b), c), d).
            var tfCount = 0;
            ['a','b','c','d'].forEach(function(ch) {
                var re = new RegExp('(^|\\s)' + ch + '\\)', 'i');
                if (re.test(plain)) tfCount++;
            });
            if (tfCount >= 2 || /đúng\s*hoặc\s*sai|chọn\s*đúng\s*hoặc\s*sai/i.test(plain)) return 'II';

            // Phần I: câu trắc nghiệm có lựa chọn A. B. C. D.
            var mcCount = 0;
            ['A','B','C','D'].forEach(function(ch) {
                var re = new RegExp('(^|\\s)' + ch + '\\.', '');
                if (re.test(plain)) mcCount++;
            });
            if (mcCount >= 2) return 'I';

            // Phần III: câu trả lời ngắn thường không có lựa chọn A-D/a-d hoặc có đáp số/đáp án ngắn.
            if (/đáp\s*(?:số|án)|trả\s*lời\s*ngắn|short-answer/i.test(block + ' ' + plain)) return 'III';

            // Nếu có tiêu đề phần thì dùng fallback theo vị trí; nếu không có thì xem là TLN để không bỏ sót câu tự luận/ngắn.
            return fallbackPart || 'III';
        }

        function updateQuestionStats() {
            var statsDiv = document.getElementById('q-stats');
            if (!statsDiv) return;
            if (!activeTabId) {
                statsDiv.innerHTML = `<span class="stat-badge stat-total">Tổng: 0</span><span class="stat-badge stat-tn">TN: 0</span><span class="stat-badge stat-ds">Đ/S: 0</span><span class="stat-badge stat-tln">TLN: 0</span>`;
                return;
            }

            var editor = document.getElementById('editor');
            var content = editor ? (editor.value || '') : '';
            var p1 = lhlFindPartIndexV52(content, 1);
            var p2 = lhlFindPartIndexV52(content, 2);
            var p3 = lhlFindPartIndexV52(content, 3);
            var hasAnyPartTitle = (p1 !== -1 || p2 !== -1 || p3 !== -1);
            var counts = { 'I': 0, 'II': 0, 'III': 0, 'ALL': 0 };

            // V53: đếm theo CẤU TRÚC câu, không bắt buộc phải có tiêu đề Phần I/II/III
            // và không bắt buộc câu nằm đúng dưới tiêu đề phần.
            var qRegex = /(^|[\n\r]|<\/?(?:p|div|br|li|tr|td|h[1-6])\b[^>]*>\s*)(?:\s|&nbsp;|<\/?(?:span|b|strong|em|i|u|font)\b[^>]*>)*Câu\s*\d+\s*(?:[.:)]|<\/?(?:span|b|strong|em|i|u|font|p|div)\b[^>]*>|&nbsp;|\s)/gi;
            var matches = [], match;
            while ((match = qRegex.exec(content)) !== null) {
                var prefix = match[1] || '';
                var qIndex = match.index + prefix.length;
                matches.push({ index: qIndex });
            }

            for (var i = 0; i < matches.length; i++) {
                var start = matches[i].index;
                var end = (i + 1 < matches.length) ? matches[i + 1].index : content.length;
                var block = content.slice(start, end);
                var fallback = hasAnyPartTitle ? ((p3 !== -1 && start > p3) ? 'III' : ((p2 !== -1 && start > p2) ? 'II' : 'I')) : null;
                var part = lhlClassifyQuestionBlockV53(block, fallback);
                counts['ALL']++;
                counts[part] = (counts[part] || 0) + 1;
            }

            statsDiv.innerHTML = `<span class="stat-badge stat-total" title="Tổng số câu của file hiện hành">Tổng: ${counts['ALL']}</span><span class="stat-badge stat-tn" title="Phần I - Trắc nghiệm nhiều lựa chọn">TN: ${counts['I']}</span><span class="stat-badge stat-ds" title="Phần II - Trắc nghiệm Đúng/Sai">Đ/S: ${counts['II']}</span><span class="stat-badge stat-tln" title="Phần III - Trả lời ngắn">TLN: ${counts['III']}</span>`;
        }

        function jumpToQuestionNumber() {
            if (!activeTabId) return;

            const sectionEl = document.getElementById('jump-section');
            const numEl = document.getElementById('jump-number');
            const section = sectionEl ? String(sectionEl.value || 'I') : 'I';
            const num = numEl ? String(numEl.value || '').trim() : '';
            if (!num) return;

            const editor = document.getElementById('editor');
            if (!editor) return;
            const content = editor.value || '';

            function partLabelFromHtml(html) {
                const t = String(html || '').toUpperCase();
                if (/PH(?:Ầ|.)N\s*(?:III|3)\b/.test(t)) return 'III';
                if (/PH(?:Ầ|.)N\s*(?:II|2)\b/.test(t)) return 'II';
                if (/PH(?:Ầ|.)N\s*(?:I|1)\b/.test(t)) return 'I';
                return '';
            }

            function collectHeaders() {
                const arr = [];

                function add(start, end, html, priority) {
                    const label = partLabelFromHtml(html);
                    if (!label || start < 0 || end <= start) return;
                    arr.push({ start, end, label, priority: priority || 0 });
                }

                // Ưu tiên nguyên khối ngoài cùng exam-part-box. File ĐỀ SỐ 2 dùng dạng này.
                const regs = [
                    {re: /<div\b[^>]*class=["'][^"']*exam-part-box[^"']*["'][^>]*>[\s\S]*?<\/div>/gi, p: 100},
                    {re: /<p\b[^>]*class=["'][^"']*section-title[^"']*["'][^>]*>[\s\S]*?<\/p>/gi, p: 90},
                    {re: /<b[^>]*>\s*PH(?:Ầ|.)N\s*(?:I|II|III|1|2|3)\b[\s\S]*?<\/b>/gi, p: 50},
                    {re: /<strong[^>]*>\s*PH(?:Ầ|.)N\s*(?:I|II|III|1|2|3)\b[\s\S]*?<\/strong>/gi, p: 50}
                ];
                regs.forEach(obj => {
                    let m;
                    while ((m = obj.re.exec(content)) !== null) {
                        if (/PH(?:Ầ|.)N\s*(?:I|II|III|1|2|3)\b/i.test(m[0])) {
                            add(m.index, m.index + m[0].length, m[0], obj.p);
                        }
                    }
                });

                // Fallback chữ PHẦN không có thẻ.
                let m;
                const plain = /PH(?:Ầ|.)N\s*(?:I|II|III|1|2|3)\b/gi;
                while ((m = plain.exec(content)) !== null) {
                    if (arr.some(h => m.index >= h.start && m.index < h.end)) continue;
                    add(m.index, m.index + m[0].length, m[0], 10);
                }

                // Bỏ header bị lồng trong header khác. Giữ block ngoài cùng/ưu tiên cao hơn.
                arr.sort((a, b) => (a.start - b.start) || (b.priority - a.priority) || ((b.end-b.start) - (a.end-a.start)));
                const kept = [];
                for (const h of arr) {
                    if (kept.some(k => h.start >= k.start && h.end <= k.end)) continue;
                    for (let i = kept.length - 1; i >= 0; i--) {
                        const k = kept[i];
                        if (k.start >= h.start && k.end <= h.end) kept.splice(i, 1);
                    }
                    kept.push(h);
                }
                kept.sort((a, b) => a.start - b.start);

                // Nếu trùng cùng một phần trong đoạn rất gần nhau, giữ cái ngoài/ưu tiên hơn.
                const final = [];
                for (const h of kept) {
                    const near = final.find(x => x.label === h.label && Math.abs(x.start - h.start) < 500);
                    if (!near) final.push(h);
                    else if (h.priority > near.priority || (h.end - h.start) > (near.end - near.start)) {
                        near.start = h.start; near.end = h.end; near.priority = h.priority;
                    }
                }
                final.sort((a, b) => a.start - b.start);
                return final;
            }

            function getRange(sec) {
                const headers = collectHeaders();
                if (!headers.length || sec === 'ALL' || sec === 'Tất cả') return { start: 0, end: content.length };
                const cur = headers.find(h => h.label === sec);
                if (!cur) return { start: 0, end: content.length };
                const next = headers.find(h => h.start > cur.start);
                return { start: cur.end, end: next ? next.start : content.length };
            }

            function collectQuestions(range) {
                const sub = content.slice(range.start, range.end);
                const qs = [];
                const used = new Set();

                function add(local, n) {
                    const abs = range.start + local;
                    if (used.has(abs)) return;
                    used.add(abs);
                    qs.push({ start: abs, num: String(n) });
                }

                let m;
                const bq = /(?:<b[^>]*>|<strong[^>]*>)\s*Câu\s+(\d+)\s*[\.:]?\s*(?:<\/b>|<\/strong>)?/gi;
                while ((m = bq.exec(sub)) !== null) add(m.index, m[1]);

                const plain = /(^|\n)\s*Câu\s+(\d+)\s*[\.:]/gi;
                while ((m = plain.exec(sub)) !== null) add(m.index + (m[1] ? m[1].length : 0), m[2]);

                qs.sort((a, b) => a.start - b.start);
                return qs;
            }

            const range = getRange(section);
            const qs = collectQuestions(range);
            const idx = qs.findIndex(q => q.num === String(num));

            if (idx < 0) {
                showToast("Dạ không tìm thấy Câu " + num + " trong Phần này ạ!");
                return;
            }

            let absoluteStart = qs[idx].start;
            let absoluteEnd = (idx + 1 < qs.length) ? qs[idx + 1].start : range.end;

            // Giữ theo bản V89 ổn định: Phần III không chọn dòng Đáp số/Đáp án.
            if (section === 'III') {
                const block = content.slice(absoluteStart, absoluteEnd);
                const ans = block.search(/(?:^|\n|<br\s*\/?>)\s*(?:<b[^>]*>|<strong[^>]*>)?\s*(?:Đáp\s*(?:án|số)|Dap\s*(?:an|so))\s*[:：]/i);
                if (ans >= 0) absoluteEnd = absoluteStart + ans;
            }

            while (absoluteEnd > absoluteStart && /\s/.test(content.charAt(absoluteEnd - 1))) absoluteEnd--;

            editor.focus();
            editor.setSelectionRange(absoluteStart, absoluteEnd);

            if (typeof lhlV100ScrollSelectionTop === 'function') lhlV100ScrollSelectionTop(editor, absoluteStart);
            else if (typeof lhlV89ScrollSelectionTop === 'function') lhlV89ScrollSelectionTop(editor, absoluteStart);
            else if (typeof scrollToExactPosition === 'function') scrollToExactPosition(editor, absoluteStart, 1);

            try { savedStart = absoluteStart; savedEnd = absoluteEnd; } catch(e) {}
            showToast("🎯 Đã khoanh vùng Câu " + num + ". Thầy có thể Copy/Cắt/Xóa ngay ạ!");
        }

        function applySpacingToQuestion() {
            if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở Tab để thao tác ạ!"); return; }
            let num = document.getElementById('jump-number').value.trim(); if (!num) { showToast("⚠️ Thầy vui lòng nhập số câu cần giãn dòng!"); return; }
            jumpToQuestionNumber(); let editor = document.getElementById('editor'); let start = savedStart; let end = savedEnd; if (start === end) return;
            let searchArea = editor.value.substring(start, end);
            let choicesIdx = searchArea.search(/<div[^>]*class="choices[^>]*>/i);
            if (choicesIdx !== -1) {
                let isCols2 = searchArea.match(/class="choices cols-2"/i);
                let modifiedSearchArea = searchArea.replace(/(<div[^>]*class="choices[^>]*>)/i, function(m) { if (m.includes('style="')) { let s = m.replace(/margin-top:\s*[^;]+;?/gi, ''); s = s.replace(/margin-bottom:\s*[^;]+;?/gi, ''); return s.replace(/style="/i, 'style="margin-top: 4px !important; margin-bottom: 2px !important; '); } return m.replace('class="', 'style="margin-top: 4px !important; margin-bottom: 2px !important;" class="'); });
                let choiceCount = 0;
                modifiedSearchArea = modifiedSearchArea.replace(/(<div[^>]*class="choice"[^>]*>)/gi, function(m) { choiceCount++; let bottomMargin = "8px"; if (isCols2 && (choiceCount === 3 || choiceCount === 4)) bottomMargin = "0px"; if (!isCols2 && choiceCount === 4) bottomMargin = "0px"; if (m.includes('style="')) { let s = m.replace(/margin-bottom:\s*[^;]+;?/gi, ''); return s.replace(/style="/i, `style="margin-bottom: ${bottomMargin} !important; `); } return m.replace('class="', `style="margin-bottom: ${bottomMargin} !important;" class="`); });
                executeInsertText(editor, modifiedSearchArea, start, end, start, start + modifiedSearchArea.length); showToast("✨ Đã giãn dòng tỷ lệ vàng cho Câu " + num + "!");
            } else { showToast("Dạ câu " + num + " không có cụm đáp án để giãn ạ!"); }
        }

        function renumberQuestions() {
            if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở Tab để thao tác ạ!"); return; }
            let editor = document.getElementById('editor'); let content = editor.value; let counter = 1;
            let newContent = content.replace(/(PH.N\s+(?:I{1,3}|[1-3])\b)|((?:<b[^>]*>|<strong[^>]*>)\s*Câu\s+)\d+([.:]?)/gi, function(match, p1, p2, p3) { if (p1) { counter = 1; return match; } if (p2) { let res = p2 + counter + (p3 || ""); counter++; return res; } return match; });
            executeInsertText(editor, newContent, 0, content.length, savedStart || 0, savedEnd || 0); showToast("✨ Đã đánh lại số thứ tự câu hỏi thành công!");
        }

        function applyInlineStyle(prop, val) {
            if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở Tab để thao tác ạ!"); return; }
            if (!val) return; let editor = document.getElementById('editor'); let start = savedStart || 0; let end = savedEnd || 0;
            if (start === end) { showToast("⚠️ Thầy vui lòng bôi đen vùng cần xử lý ạ!"); return; }
            let selectedText = editor.value.substring(start, end);
            let regexSpan = new RegExp(`<span style="${prop}:[^>]*>([\\s\\S]*?)<\\/span>`, 'gi'); selectedText = selectedText.replace(regexSpan, "$1");
            let regexDiv = new RegExp(`<div style="${prop}:[^>]*>([\\s\\S]*?)<\\/div>`, 'gi'); selectedText = selectedText.replace(regexDiv, "$1");
            let isBlock = /<p|<table|<div|<br/i.test(selectedText);
            let startTag = isBlock ? `<div style="${prop}: ${val};">` : `<span style="${prop}: ${val};">`; let endTag = isBlock ? `</div>` : `</span>`;
            let newText = selectedText.replace(/(<\/?(?:table|tbody|thead|tfoot|tr|td|th)[^>]*>)/gi, `${endTag}$1${startTag}`); newText = startTag + newText + endTag;
            let escapedStart = startTag.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&'); let escapedEnd = endTag.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
            let emptyRegex = new RegExp(escapedStart + '\\s*' + escapedEnd, 'gi'); newText = newText.replace(emptyRegex, ''); newText = newText.replace(emptyRegex, '');
            executeInsertText(editor, newText, start, end, start, start + newText.length); showToast("✨ Đã áp dụng định dạng thành công!");
        }

        function applyFont(fontName) { applyInlineStyle('font-family', fontName ? `'${fontName}', serif` : ''); document.getElementById('font-select').value = ""; }
        function applyColor(colorHex) { applyInlineStyle('color', colorHex); }
        function applyFontSize(sizeValue) {
            let val = parseInt(sizeValue); if (isNaN(val) || val <= 0) return;
            if ((savedStart || 0) === (savedEnd || 0)) { currentFontSize = val; document.getElementById('paper').style.fontSize = val + 'px'; showToast("✨ Đã áp dụng cỡ chữ toàn file!"); } 
            else { applyInlineStyle('font-size', val + 'px'); }
        }

        async function performSaveAs() {
            if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở Tab để lưu ạ!"); return false; }
            let tab = tabs.find(t => t.id === activeTabId); saveCurrentTabState(); let htmlContent = generateFullHTML(false);
            let defaultName = tab.title.endsWith('.html') ? tab.title.replace('.html', '_Copy.html') : tab.title + '_Copy.html';
            let res = await window.pywebview.api.save_html_only(htmlContent, defaultName);
            if (res && res.filepath) { tab.filePath = res.filepath; tab.title = res.filename; tab.isDirty = false; renderTabs(); showToast("💾 Đã lưu thành file mới (Save As) thành công!"); return true; }
            return false;
        }

        function applyFormatPainter() {
            if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở Tab để thao tác ạ!"); return; }
            let editor = document.getElementById('editor'); let start = savedStart || 0; let end = savedEnd || 0;
            if (start === end) { showToast("⚠️ Thầy vui lòng bôi đen 'Câu X' đã định dạng mẫu để sao chép ạ!"); return; }
            let selectedText = editor.value.substring(start, end);
            if (!/Câu\s+\d+/i.test(selectedText)) { showToast("⚠️ Vùng bôi đen không chứa 'Câu X'. Thầy bôi đen lại nha!"); return; }
            let styles = []; let styleRegex = /style="([^"]+)"/gi; let match;
            while ((match = styleRegex.exec(selectedText)) !== null) { let s = match[1].trim(); if (!s.endsWith(";")) s += ";"; styles.push(s); }
            let combinedStyle = styles.join(" "); let content = editor.value;
            let qRegex = /(?:<span[^>]*>\s*)*<\/?(?:b|strong)>\s*(Câu\s+\d+[.:]?)\s*<\/?(?:b|strong)>(?:\s*<\/span>)*/gi;
            let newContent = content.replace(qRegex, function(m, p1) { if (combinedStyle) { return `<span style="${combinedStyle}"><b> ${p1} </b></span>`; } else { return `<b> ${p1} </b>`; } });
            executeInsertText(editor, newContent, 0, content.length, start, end);
            if (combinedStyle) { showToast("✨ Đã áp dụng định dạng tương tự cho TẤT CẢ các câu!"); } else { showToast("✨ Đã XÓA SẠCH định dạng thừa của TẤT CẢ các câu!"); }
        }

        function clearQuestionFormatting() {
            if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở Tab để thao tác ạ!"); return; }
            let editor = document.getElementById('editor'); let content = editor.value;
            let qRegex = /(?:<span[^>]*>\s*)*<\/?(?:b|strong)>\s*(Câu\s+\d+[.:]?)\s*<\/?(?:b|strong)>(?:\s*<\/span>)*/gi;
            let newContent = content.replace(qRegex, "<b> $1 </b>");
            executeInsertText(editor, newContent, 0, content.length, savedStart || 0, savedEnd || 0); showToast("✨ Đã khôi phục định dạng gốc cho toàn bộ chữ 'Câu X'!");
        }

        function toggleLock() {
            if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở Tab để thao tác ạ!"); return; }
            let editor = document.getElementById('editor'); let start = savedStart || 0; let end = savedEnd || 0;
            if (start === end) { showToast("⚠️ Thầy vui lòng bôi đen đoạn code cần Khóa/Mở Khóa ạ!"); return; }
            let val = editor.value; let selectedText = val.substring(start, end);
            let sTag = "<" + "!-- "; let eTag = " --" + ">"; let sMatch1 = "<" + "!-- "; let eMatch1 = " --" + ">"; let sMatch2 = "<" + "!--"; let eMatch2 = "--" + ">";
            let newText = ""; let newSelectionStart = start; let newSelectionEnd = end;
            if (start >= 5 && end <= val.length - 4 && val.substring(start - 5, start) === sMatch1 && val.substring(end, end + 4) === eMatch1) {
                start = start - 5; end = end + 4; newText = selectedText; newSelectionStart = start; newSelectionEnd = start + selectedText.length; showToast("✨ Đã MỞ KHÓA (Hiện) đoạn code thành công!");
            } else if (start >= 4 && end <= val.length - 3 && val.substring(start - 4, start) === sMatch2 && val.substring(end, end + 3) === eMatch2) {
                start = start - 4; end = end + 3; newText = selectedText; newSelectionStart = start; newSelectionEnd = start + selectedText.length; showToast("✨ Đã MỞ KHÓA (Hiện) đoạn code thành công!");
            } else if (selectedText.trim().startsWith(sMatch2) && selectedText.trim().endsWith(eMatch2)) {
                let trimmed = selectedText.trim(); newText = trimmed.substring(4, trimmed.length - 3);
                if (newText.startsWith(" ")) newText = newText.substring(1); if (newText.endsWith(" ")) newText = newText.substring(0, newText.length - 1);
                newSelectionStart = start; newSelectionEnd = start + newText.length; showToast("✨ Đã MỞ KHÓA (Hiện) đoạn code thành công!");
            } else {
                newText = sTag + selectedText + eTag; newSelectionStart = start + 5; newSelectionEnd = newSelectionStart + selectedText.length; showToast("✨ Đã KHÓA (Ẩn) đoạn code thành công!");
            }
            executeInsertText(editor, newText, start, end, newSelectionStart, newSelectionEnd);
        }

        
        // ============================================================
        // V102-CHOT-FIX4 CORE: chuẩn hóa bảng Word HTML cực sạch
        // Đặt TRƯỚC processMathHTML để mọi luồng Chuẩn Hóa đều dùng được.
        // ============================================================
        function lhlNormalizeWordTablesCoreV4(content) {
            let s = String(content || '');
            if (!/<table\b/i.test(s)) return s;

            function decodeHtml(t) {
                t = String(t || '');
                for (let i = 0; i < 6; i++) {
                    let old = t;
                    try {
                        let ta = document.createElement('textarea');
                        ta.innerHTML = t;
                        t = ta.value;
                    } catch(e) {
                        t = t.replace(/&nbsp;/gi, ' ')
                             .replace(/&amp;/gi, '&')
                             .replace(/&lt;/gi, '<')
                             .replace(/&gt;/gi, '>')
                             .replace(/&quot;/gi, '"')
                             .replace(/&#39;/gi, "'");
                    }
                    if (t === old) break;
                }
                return t;
            }

            function cellText(cellHtml) {
                let c = String(cellHtml || '');
                c = c.replace(/<br\s*\/?>/gi, ' ');
                c = c.replace(/<\/p\s*>/gi, ' ');
                c = c.replace(/<p\b[^>]*>/gi, '');
                c = c.replace(/<\/?(?:b|strong|i|em|u|span|font|o:p|st1:[^>]+)\b[^>]*>/gi, '');
                c = c.replace(/<[^>]*>/g, ' ');
                c = decodeHtml(c);
                c = c.replace(/\u00a0/g, ' ');
                c = c.replace(/\s+/g, ' ').trim();
                c = c.replace(/\s*=\s*/g, ' = ');
                c = c.replace(/\s*;\s*/g, ';');
                return c.trim();
            }

            function normalizeCell(c) {
                c = String(c || '').trim();
                if (!c) return '';

                let hadDollar = /^\s*\$[\s\S]*\$\s*$/.test(c);
                if (hadDollar) c = c.replace(/^\s*\$+|\$+\s*$/g, '').trim();

                if (/^\{[\s\S]*\}$/.test(c)) c = c.slice(1, -1).trim();

                // Sửa lỗi khoảng từ Word: [0;2)] -> [0;2)
                c = c.replace(/^([\[\(]\s*[-+]?\d+(?:[,.]\d+)?\s*;\s*[-+]?\d+(?:[,.]\d+)?\s*)\)\]$/i, '$1)');
                c = c.replace(/\s*;\s*/g, ';');

                const isNumber = /^[-+]?\d+(?:[,.]\d+)?$/.test(c);
                const isInterval = /^[\[\(]\s*[-+]?\d+(?:[,.]\d+)?\s*;\s*[-+]?\d+(?:[,.]\d+)?\s*[\]\)]$/.test(c);
                const hasLatex = /\\[a-zA-Z]+/.test(c);
                const isFormula = /^[a-zA-Z]\s*=/.test(c) || /[=+\-*/^_≤≥∞]/.test(c);

                if (isInterval) return '$' + c + '$';
                if (hadDollar || isNumber || hasLatex || isFormula) return '$' + c + '$';
                return c;
            }

            function cleanOneTable(tableHtml) {
                let rows = [];
                let trRe = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
                let tr;
                while ((tr = trRe.exec(tableHtml)) !== null) {
                    let rowHtml = tr[1];
                    let cells = [];
                    let tdRe = /<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi;
                    let td;
                    while ((td = tdRe.exec(rowHtml)) !== null) {
                        cells.push(normalizeCell(cellText(td[1])));
                    }
                    if (cells.length && cells.some(x => String(x).trim() !== '')) rows.push(cells);
                }
                if (!rows.length) return tableHtml;

                let out = '<table class="lhl-rendered-latex-table" style="border-collapse: collapse; margin: 10px auto; text-align: center;">\n<tbody>\n';
                rows.forEach(cells => {
                    out += '<tr>' + cells.map(c => '<td>' + c + '</td>').join('') + '</tr>\n';
                });
                out += '</tbody>\n</table>';
                return out;
            }

            s = s.replace(/<!--StartFragment-->/gi, '').replace(/<!--EndFragment-->/gi, '');
            s = s.replace(/<table\b[\s\S]*?<\/table>/gi, tableHtml => cleanOneTable(tableHtml));

            // Bóc wrapper Word bao quanh bảng sạch.
            s = s.replace(/<div class="lhl-word-paste-fragment"[^>]*>\s*<div>\s*(<table class="lhl-rendered-latex-table"[\s\S]*?<\/table>)\s*<\/div>\s*<\/div>/gi, '$1');
            s = s.replace(/<div class="lhl-word-paste-fragment"[^>]*>\s*(<table class="lhl-rendered-latex-table"[\s\S]*?<\/table>)\s*<\/div>/gi, '$1');
            s = s.replace(/<div>\s*(<table class="lhl-rendered-latex-table"[\s\S]*?<\/table>)\s*<\/div>/gi, '$1');

            return s.trim();
        }

function processMathHTML(content) {
            content = lhlNormalizeWordTablesCoreV4(content);
            content = content.replace(/(<div class="header-container">)/gi, '\n$1');
            content = content.replace(/<div[^>]*>\s*[-_]+\s*<strong[^>]*><\/strong>\s*<\/div>/gi, '');
            content = content.replace(/<div[^>]*>\s*[-_]+\s*<b[^>]*><\/b>\s*<\/div>/gi, '');
            content = content.replace(/<(p|div|span)[^>]*>(?:\s|[-_=.]|(<(strong|b|i|em)[^>]*>\s*<\/\3>))*<\/\1>/gi, '');
            content = content.replace(/\\int_/g, '\\displaystyle\\int\\limits_');
            content = content.replace(/\{\s*(<|>|\\le|\\ge|\\leq|\\geq)\s*\}/g, '$1');
            content = content.replace(/<p class="section-title">\s*<b[^>]*>\s*(PH.N\s+(?:I{1,3}|[1-3])[.:\-]\s*[^<]*)\s*<\/b>\s*<\/p>/gi, '$1');
            content = content.replace(/(PH.N\s+(?:I{1,3}|[1-3])[.:\-]\s*Câu[^<]*)/gi, '<p class="section-title"><b>$1</b></p>');

            let tempDiv = document.createElement('div'); tempDiv.innerHTML = content;
            let tables = tempDiv.querySelectorAll('table');
            tables.forEach(table => {
                let tds = table.querySelectorAll('td');
                if (tds.length === 4) {
                    let txt = table.textContent;
                    let isPart1 = txt.includes('A.') && txt.includes('B.') && txt.includes('C.') && txt.includes('D.');
                    let isPart2 = (txt.includes('a)') && txt.includes('b)') && txt.includes('c)') && txt.includes('d)')) || (txt.includes('a.') && txt.includes('b.') && txt.includes('c.') && txt.includes('d.'));
                    if (isPart1 || isPart2) {
                        let trs = table.querySelectorAll('tr');
                        let colClass = 'cols-4'; if (isPart2) colClass = 'cols-1'; else if (trs.length === 4) colClass = 'cols-1'; else if (trs.length === 2) colClass = 'cols-2';
                        let flexContainer = document.createElement('div'); flexContainer.className = 'choices ' + colClass; 
                        tds.forEach(td => { let choiceDiv = document.createElement('div'); choiceDiv.className = 'choice'; choiceDiv.innerHTML = td.innerHTML; flexContainer.appendChild(choiceDiv); });
                        table.parentNode.replaceChild(flexContainer, table); return;
                    }
                }
                table.style.marginLeft = 'auto'; table.style.marginRight = 'auto';
            });

            let optionBlocks = tempDiv.querySelectorAll('p, div, td, li');
            optionBlocks.forEach(block => {
                if (block.classList.contains('choice') || block.classList.contains('choices') || block.classList.contains('section-title')) return;
                if (block.querySelectorAll('p, div, td, li').length > 0) return;
                if (/^[a-dA-D][\)\.]/.test(block.textContent.trim())) block.style.paddingLeft = '25px';
            });

            let imgs = tempDiv.querySelectorAll('img');
            imgs.forEach(img => { img.style.display = 'block'; img.style.marginLeft = 'auto'; img.style.marginRight = 'auto'; img.style.marginTop = '10px'; img.style.marginBottom = '10px'; });

            content = tempDiv.innerHTML;
            content = content.replace(/>\s+</g, '><');
            content = content.replace(/(<div class="student-info-container">)/gi, '\n\n$1');
            content = content.replace(/(NỘI DUNG ĐỀ THI)/gi, '\n\n$1\n\n');
            content = content.replace(/(<div[^>]*>[^<]*<strong[^>]*>HẾT<\/strong>[^<]*<\/div>)/gi, '\n\n$1\n\n');
            content = content.replace(/(<div[^>]*>Thí sinh không được sử dụng tài liệu[^<]*<\/div>)/gi, '$1\n\n');
            content = content.replace(/(<p class="section-title"><b>)\s*(PH.N\s+(?:I{1,3}|[1-3])[.:\-]\s*[^<]*)\s*(<\/b><\/p>)/gi, '\n\n$1\n\n$2\n\n$3\n\n');
            content = content.replace(/<(b|strong)[^>]*>\s*(Câu\s+\d+[.:]?)\s*<\/\1>/gi, '<b> $2 </b>');
            content = content.replace(/(<b> Câu \d+[.:]? <\/b>)/gi, '\n\n$1\n\n');
            content = content.replace(/(<table[^>]*>)/gi, '\n\n$1\n');
            content = content.replace(/(<\/table>)/gi, '\n$1\n\n');
            content = content.replace(/(<tbody><tr><td[^>]*>)/gi, '$1\n\n');
            content = content.replace(/(<\/td><\/tr><\/tbody>)/gi, '\n\n$1');
            content = content.replace(/(<\/td><\/tr><tr><td>)/gi, '\n\n$1\n\n');
            content = content.replace(/(<img[^>]*>)/gi, '\n\n$1\n\n');
            content = content.replace(/(<br[^>]*>)/gi, '\n\n$1\n\n');
            content = content.replace(/(<div class="choices[^>]*>)/gi, '\n\n$1\n');
            content = content.replace(/(<div class="choice"[^>]*>)(<label>)?/gi, '\n$1\n$2');
            content = content.replace(/([A-Da-d][.)]\s*(?:<\/span>)?<\/(?:b|strong)>(?:<\/label>)?)/gi, '$1\n\n');
            content = content.replace(/(<\/label>)/gi, '\n\n$1');
            content = content.replace(/(<\/div>)\s*(<div class="choice"[^>]*>\s*<label>)/gi, '$1\n\n$2');
            content = content.replace(/(<\/div>)\s*(<div class="choice"[^>]*>\s*(?!<label>))/gi, '$1$2');
            content = content.replace(/\n{3,}/g, '\n\n');
            content = lhlNormalizeWordTablesCoreV4(content);
            return content.trim();
        }

        function cleanCode() {
            if (!activeTabId) return;
            let editor = document.getElementById('editor');
            if (!editor || !editor.value.trim()) return;

            let processed = lhlNormalizeWordTablesCoreV4(editor.value);
            processed = processMathHTML(processed);
            processed = lhlNormalizeWordTablesCoreV4(processed);
            processed = lhlFix25ImminiImageWidthOnly(processed);
    processed = processed.replace(/\n{3,}/g, '\n\n').trim();

            editor.value = processed;
            let pos = Math.min(processed.length, savedStart || 0);
            editor.focus();
            editor.setSelectionRange(pos, pos);
            savedStart = pos;
            savedEnd = pos;

            let tab = tabs.find(t => t.id === activeTabId);
            if (tab) {
                tab.content = processed;
                tab.savedStart = savedStart;
                tab.savedEnd = savedEnd;
                tab.isDirty = true;
            }

            isFullCodeVisible = true;
            let btn = document.getElementById('btn-toggle');
            if (btn) btn.innerText = "🙈 Thu gọn";
            if (typeof updatePreview === 'function') updatePreview();
            if (typeof renderTabs === 'function') renderTabs();
            if (typeof updateQuestionStats === 'function') updateQuestionStats();
            if (typeof updateQuestionCounts === 'function') updateQuestionCounts();
            showToast("✅ Đã chuẩn hóa code và làm sạch bảng Word!");
        }

        function importHTML() {
            if (window.pywebview && window.pywebview.api) {
                window.pywebview.api.open_html_file().then(res => {
                    if (res && res.content) {
                        let nc = res.content; if (nc.normalize) nc = nc.normalize('NFC');
                        const match = nc.match(/(PH.N\s+(?:I|1|II|2)[\s\S]*?)(?=(?:---+\s*HẾT|HẾT|<div[^>]*>Thí sinh không|<\/body>|$))/i);
                        let filtered = match ? match[1] : (nc.match(/<body[^>]*>([\s\S]*)<\/body>/i)?.[1] || nc);
                        let processed = processMathHTML(filtered);

                        if (!activeTabId) { createNewTab(res.filename, processed + '\n', 'FULL'); tabs.find(t=>t.id===activeTabId).isDirty = true; renderTabs(); return; }
                        let editor = document.getElementById('editor'); let currentVal = editor.value;
                        let placeholders = ["<p><strong>NỘI DUNG ĐỀ THI</strong></p>", "NỘI DUNG ĐỀ THI", "<p><strong>NỘI DUNG CHUYÊN ĐỀ</strong></p>", "NỘI DUNG CHUYÊN ĐỀ"];
                        let hasPlaceholder = false, startToInsert = savedStart || 0, endToInsert = savedEnd || 0;
                        for (let p of placeholders) { if (currentVal.includes(p)) { hasPlaceholder = true; startToInsert = currentVal.indexOf(p); endToInsert = startToInsert + p.length; break; } }
                        if (hasPlaceholder) {
                            executeInsertText(editor, processed + '\n', startToInsert, endToInsert, startToInsert + processed.length, startToInsert + processed.length); updateCurrentTabTitle(res.filename); tabs.find(t=>t.id===activeTabId).isDirty = true; tabs.find(t=>t.id===activeTabId).filePath = null; renderTabs();
                        } else if (currentVal.trim() === '') {
                            executeInsertText(editor, processed + '\n', 0, 0, processed.length, processed.length); updateCurrentTabTitle(res.filename); tabs.find(t=>t.id===activeTabId).isDirty = true; tabs.find(t=>t.id===activeTabId).filePath = null; renderTabs();
                        } else { createNewTab(res.filename, processed + '\n', 'FULL'); tabs.find(t=>t.id===activeTabId).isDirty = true; renderTabs(); }
                        isFullCodeVisible = true; document.getElementById('btn-toggle').innerText = "🙈 Thu gọn";
                    }
                });
            }
        }

        function convertWordToHtml() {
            if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở một Tab để sử dụng ạ!"); return; }
            let editor = document.getElementById('editor');
            let content = editor.value;
            if (!content.trim()) return;

            content = lhlCleanWordQuestionCodeV59(content);
            executeInsertText(editor, content.trim(), 0, editor.value.length, savedStart || 0, savedEnd || 0);
            isFullCodeVisible = true;
            let btnToggle = document.getElementById('btn-toggle');
            if (btnToggle) btnToggle.innerText = "🙈 Thu gọn";
            if (typeof updateCurrentTabData === 'function') updateCurrentTabData();
            if (typeof updateQuestionCounts === 'function') updateQuestionCounts();
            if (typeof updatePreview === 'function') updatePreview();
            showToast("✅ Đã chuyển Word và làm sạch câu hỏi!");
        }

        // V57 - Chuyển Word: làm sạch câu hỏi, chia đáp án theo cols-4/2/1 và giữ cấu trúc choice chuẩn.
        function lhlCleanWordQuestionCodeV57(input) {
            let content = String(input || '');
            content = lhlDecodeHtmlEntitiesV57(content);
            content = content.normalize ? content.normalize('NFC') : content;

            // Chuẩn hóa một số rác clipboard/Word thường gặp nhưng không xóa <br> thủ công của thầy.
            content = content.replace(/\r\n?/g, '\n');
            content = content.replace(/\u00a0/g, ' ');
            content = content.replace(/\\\[/g, '$').replace(/\\\]/g, '$');
            content = content.replace(/\$\s+/g, '$').replace(/\s+\$/g, '$');
            content = content.replace(/\\text\{\s*khi\s*\}/gi, '\\; \\text{khi} \\;');
            content = content.replace(/ý\s*a\)\s*,\s*b\)\s*,\s*c\)\s*,\s*d\)/gi, 'ý a, b, c, d');
            content = content.replace(/ý\s*a\)\s*,\s*b\)\s*,\s*c\)\s*và\s*d\)/gi, 'ý a, b, c và d');
            content = content.replace(/a\)\s*,\s*b\)\s*,\s*c\)\s*,\s*d\)/gi, 'a, b, c, d');

            // Nếu copy từ vùng HTML đã có choice cũ thì bóc nhẹ để chuẩn hóa lại.
            content = content.replace(/<div\s+class=["']choices[^>]*>/gi, '\n');
            content = content.replace(/<div\s+class=["']choice["'][^>]*>/gi, '\n');
            content = content.replace(/<label[^>]*>/gi, '');
            content = content.replace(/<\/label>/gi, '');
            content = content.replace(/<\/div>/gi, '\n');

            // Chuẩn hóa tiêu đề phần/câu.
            content = content.replace(/<\/?strong\b[^>]*>/gi, function(m){ return /^<\//.test(m) ? '</b>' : '<b>'; });
            content = content.replace(/<p\s+class=["']section-title["'][^>]*>\s*<b>\s*([\s\S]*?)\s*<\/b>\s*<\/p>/gi, '\n<p class="section-title"><b>$1</b></p>\n');
            content = content.replace(/^\s*(PHẦN\s+(?:I|II|III|IV|V|1|2|3|4|5)[.:][^\n]*)$/gim, '\n<p class="section-title"><b>$1</b></p>\n');
            content = content.replace(/<b>\s*(Câu\s*\d+\s*[.:])\s*<\/b>/gi, '<b> $1 </b>');
            content = content.replace(/(^|\n)\s*(Câu\s*\d+\s*[.:])/gim, '$1\n<b> $2 </b>');

            // Đưa các nhãn A/B/C/D về đầu dòng để parser bắt được dù đang nằm chung dòng.
            content = content.replace(/(<\/?u\b[^>]*>|<\/?span\b[^>]*>|<\/?b\b[^>]*>|<\/?strong\b[^>]*>)/gi, '$1');
            content = lhlMarkChoiceLettersV57(content);

            // Tách block đáp án TN A-D thành choices chuẩn.
            content = content.replace(/(?:^|\n)\s*((?:<[^>]+>\s*)*A\s*[.)][\s\S]*?)(?=(?:\n\s*(?:<[^>]+>\s*)*a\)|\n\s*<b>\s*Câu|\n\s*<p\s+class=["']section-title|\n\s*PHẦN\s+|\n\s*Câu\s+\d+|$))/gim, function(match, block) {
                const parsed = lhlParseChoicesV57(block, ['A','B','C','D'], '.');
                if (!parsed) return match;
                return '\n' + lhlBuildChoicesHtmlV57(parsed, true) + '\n';
            });

            // Tách block đúng/sai a)-d) nếu có.
            content = content.replace(/(?:^|\n)\s*(a\)\s*[\s\S]*?)(?=(?:\n\s*<b>\s*Câu|\n\s*<p\s+class=["']section-title|\n\s*PHẦN\s+|\n\s*Câu\s+\d+|$))/gim, function(match, block) {
                const parsed = lhlParseChoicesV57(block, ['a','b','c','d'], ')');
                if (!parsed) return match;
                return '\n' + lhlBuildChoicesHtmlV57(parsed, false, 'cols-1') + '\n';
            });

            // Đảm bảo có bảng FontDung sau mỗi câu có đáp án nếu chưa có ngay sau block choices.
            content = content.replace(/(<\/div>\s*<\/div>)(?!\s*<table\s+class=["']FontDung["'])/gi, '$1\n\n<table class="FontDung" width="100%" style="margin-left: auto; margin-right: auto;">\n<tbody><tr><td></td></tr></tbody></table>');

            // Làm đẹp khoảng cách code, không tự xóa <br> thầy gõ.
            content = content.replace(/<br\s*\/?>\s*(<b>\s*Câu\s*\d+)/gi, '<br>\n$1');
            content = content.replace(/(<p class="section-title"><b>[\s\S]*?<\/b><\/p>)\s*<br\s*\/?>/gi, '$1');
            content = content.replace(/\n{3,}/g, '\n\n');
            return content.trim();
        }

        function lhlDecodeHtmlEntitiesV57(s) {
            const ta = document.createElement('textarea');
            ta.innerHTML = s;
            return ta.value;
        }

        function lhlStripTagsV57(s) {
            return String(s || '').replace(/<[^>]*>/g, ' ').replace(/\$[^$]*\$/g, function(m){ return m.replace(/\s+/g, ''); }).replace(/\s+/g, ' ').trim();
        }

        function lhlChoicePlainLenV57(s) {
            let t = String(s || '');
            t = t.replace(/<img\b[^>]*>/gi, ' img ');
            t = t.replace(/\$([\s\S]*?)\$/g, '$1');
            t = t.replace(/\\dfrac|\\frac|\\displaystyle|\\left|\\right|\\text|\\overrightarrow|\\vec|\\int|\\sqrt|\\mathbb/gi, '');
            t = t.replace(/\\[a-zA-Z]+/g, 'x');
            t = t.replace(/[{}\\]/g, '');
            t = lhlStripTagsV57(t);
            t = t.replace(/\s+/g, '');
            return t.length;
        }

        function lhlDetectChoiceColsV57(items) {
            // V60: Theo yêu cầu của thầy: đáp án thật ngắn thì 4 cột, còn lại luôn 2 cột.
            // Không tự rơi về cols-1 nữa để file Word xuất ra gọn và đều hơn.
            const arr = Array.isArray(items) ? items : [];
            const lens = arr.map(it => lhlChoicePlainLenV57((it && it.text) || ''));
            const maxLen = lens.length ? Math.max.apply(null, lens) : 0;
            const hasImage = arr.some(it => /<img\b/i.test((it && it.text) || ''));
            if (!hasImage && maxLen <= 8) return 'cols-4';
            return 'cols-2';
        }

        function lhlMarkChoiceLettersV57(content) {
            // Đưa A. B. C. D. về đầu dòng, nhưng tránh các chữ cái nằm trong công thức hoặc từ tiếng Việt.
            let out = content;
            ['A','B','C','D'].forEach(function(ch){
                const re = new RegExp('([^\\n])\\s*((?:<[^>]+>\\s*)*' + ch + '\\s*[.)])\\s+', 'g');
                out = out.replace(re, function(m, before, letter){
                    if (/[$\\wÀ-ỹ)]$/.test(before)) return m;
                    return before + '\n' + letter + ' ';
                });
            });
            return out;
        }

        function lhlParseChoicesV57(block, letters, punct) {
            let s = String(block || '').trim();
            let positions = [];
            letters.forEach(function(letter){
                const p = punct === ')' ? '\\)' : '[\\.)]';
                const re = new RegExp('(?:^|\\n)\\s*((?:<[^>]+>\\s*)*' + letter + '\\s*' + p + '(?:\\s*<\\/[^>]+>)*)', 'i');
                const m = re.exec(s);
                if (m) positions.push({ letter: letter, index: m.index + m[0].indexOf(m[1]), marker: m[1] });
            });
            positions.sort(function(a,b){ return a.index - b.index; });
            if (positions.length !== letters.length) return null;
            for (let i = 0; i < letters.length; i++) if (positions[i].letter.toLowerCase() !== letters[i].toLowerCase()) return null;
            let items = [];
            for (let i = 0; i < positions.length; i++) {
                const cur = positions[i];
                const nextIndex = (i + 1 < positions.length) ? positions[i+1].index : s.length;
                let raw = s.slice(cur.index, nextIndex).trim();
                let markerRe = punct === ')' ? new RegExp('^\\s*((?:<[^>]+>\\s*)*' + cur.letter + '\\s*\\)(?:\\s*<\\/[^>]+>)*)\\s*', 'i') : new RegExp('^\\s*((?:<[^>]+>\\s*)*' + cur.letter + '\\s*[\\.)](?:\\s*<\\/[^>]+>)*)\\s*', 'i');
                let mm = raw.match(markerRe);
                let marker = mm ? mm[1] : cur.marker;
                let text = raw.replace(markerRe, '').trim();
                text = text.replace(/^[:：\-–—]\s*/, '').trim();
                const isCorrect = /<u\b|text-decoration\s*:\s*underline/i.test(marker);
                items.push({letter: cur.letter, text: text, isCorrect: isCorrect});
            }
            return items;
        }

        function lhlBuildChoicesHtmlV57(items, isMultipleChoice, forcedCols) {
            const cols = forcedCols || lhlDetectChoiceColsV57(items);
            let html = '<div class="choices ' + cols + '">\n\n';
            items.forEach(function(it, idx){
                let letterHtml;
                if (it.isCorrect && isMultipleChoice) {
                    letterHtml = '<b><span style="color:black;"><u>' + it.letter.toUpperCase() + '.</u></span></b>';
                } else {
                    letterHtml = '<b>' + (isMultipleChoice ? it.letter.toUpperCase() + '.' : it.letter.toLowerCase() + ')') + '</b>';
                }
                html += '<div class="choice">\n<label>' + letterHtml + '\n\n ' + (it.text || '').trim() + '\n\n</label></div>';
                if (idx < items.length - 1) html += '';
            });
            html += '</div>';
            return html;
        }


        // V58 - Chuyển Word mạnh hơn: bóc sạch fragment Word, giữ ảnh HINH_ANH_n,
        // gom A/B/C/D thành choices chuẩn. Nếu không nhận ra đủ A-D thì quay về bộ V57.
        function lhlCleanWordQuestionCodeV58(input) {
            let raw = String(input || '');
            let parsed = lhlTryNormalizeOneWordMultipleChoiceV58(raw);
            if (parsed) return parsed;
            return lhlCleanWordQuestionCodeV57(raw);
        }

        function lhlV58Decode(s) {
            try { return lhlDecodeHtmlEntitiesV57(s); } catch(e) { return String(s || ''); }
        }

        function lhlV58CleanImgTag(imgTag) {
            let src = '';
            let m = String(imgTag || '').match(/\bsrc\s*=\s*(["'])(.*?)\1/i);
            if (m) src = m[2];
            if (!src) return '';
            return '<div style="display: flex; justify-content: center; width: 100%; margin: 10px 0; clear: both;">\n' +
                   '<img src="' + src + '" style="max-width: 250px; height: auto;">\n' +
                   '</div>';
        }

        function lhlV58FinalCleanText(s) {
            return String(s || '')
                .replace(/\r\n?/g, '\n')
                .replace(/\u00a0/g, ' ')
                .replace(/[ \t]+\n/g, '\n')
                .replace(/\n[ \t]+/g, '\n')
                .replace(/[ \t]{2,}/g, ' ')
                .replace(/\$\s+/g, '$')
                .replace(/\s+\$/g, '$')
                .replace(/\s+([,.;:?])/g, '$1')
                .replace(/([\p{L}\p{N}])\$/gu, '$1 $')
                .replace(/\$([\p{L}\p{N}])/gu, '$ $1')
                .replace(/\n{3,}/g, '\n\n')
                .trim();
        }

        function lhlV58StripWordJunk(s) {
            s = String(s || '');
            s = lhlV58Decode(s);
            s = s.normalize ? s.normalize('NFC') : s;
            s = s.replace(/\r\n?/g, '\n').replace(/\u00a0/g, ' ');

            // Bỏ comment Word/VML, conditional comment, StartFragment/EndFragment.
            s = s.replace(/<!--\s*\[if[\s\S]*?<!\s*\[endif\]\s*-->/gi, '');
            s = s.replace(/<!--\s*\[if[\s\S]*?-->/gi, '');
            s = s.replace(/<!--\s*\[endif\]\s*-->/gi, '');
            s = s.replace(/<!--[\s\S]*?-->/g, '');

            // Xóa anchor Word nhưng giữ nội dung bên trong.
            s = s.replace(/<a\b[^>]*\bname\s*=\s*["'][^"']*["'][^>]*>/gi, '');
            s = s.replace(/<a\b[^>]*>/gi, '');
            s = s.replace(/<\/a>/gi, '');

            // Chuẩn hóa thẻ thường gặp.
            s = s.replace(/<\/?strong\b[^>]*>/gi, function(m){ return /^<\//.test(m) ? '</b>' : '<b>'; });
            s = s.replace(/<b\b[^>]*>/gi, '<b>').replace(/<\/b>/gi, '</b>');
            s = s.replace(/<u\b[^>]*>/gi, '<u>').replace(/<\/u>/gi, '</u>');
            s = s.replace(/<span\b[^>]*>/gi, '<span>').replace(/<\/span>/gi, '</span>');

            // Giữ ảnh bằng token riêng để không bị strip mất.
            s = s.replace(/<img\b[^>]*>/gi, function(m){ return '\n@@IMG:' + encodeURIComponent(m) + '@@\n'; });

            // Các tag block của Word đổi thành xuống dòng; các tag còn lại bỏ.
            s = s.replace(/<br\s*\/?>/gi, '\n');
            s = s.replace(/<\/?p\b[^>]*>/gi, '\n');
            s = s.replace(/<\/?div\b[^>]*>/gi, '\n');
            s = s.replace(/<\/?tbody\b[^>]*>|<\/?tr\b[^>]*>|<\/?td\b[^>]*>|<\/?table\b[^>]*>/gi, '\n');

            // Đánh dấu đáp án đúng trước khi xóa tag.
            s = s.replace(/<b>\s*(?:<span>\s*)?<u>\s*([ABCD])\s*\.?\s*<\/u>\s*(?:<\/span>\s*)?<\/b>\s*\.?/gi, '\n@@CHOICE:$1:1@@ ');
            s = s.replace(/<u>\s*([ABCD])\s*\.?\s*<\/u>\s*\.?/gi, '\n@@CHOICE:$1:1@@ ');
            s = s.replace(/<b>\s*([ABCD])\s*[\.)]\s*<\/b>/gi, '\n@@CHOICE:$1:0@@ ');

            // Bỏ các tag còn lại.
            s = s.replace(/<[^>]*>/g, ' ');

            // Nếu còn nhãn A. B. C. D. dạng text trần thì đánh dấu tiếp.
            // V60: nhận thêm dấu ), dấu ：/:, khoảng trắng hẹp của Word, và trường hợp nhãn bị xuống dòng/tách span.
            ['A','B','C','D'].forEach(function(ch){
                const re = new RegExp('(^|\\n|\\s)(' + ch + ')\\s*[\\.)：:]\\s*', 'g');
                s = s.replace(re, function(m, pre, letter){
                    // Tránh bắt nhầm chữ trong công thức LaTeX kiểu $A.B$ bằng cách yêu cầu phía trước không phải ký tự \ hoặc $.
                    if (pre && /[\\$]$/.test(pre)) return m;
                    return pre + '@@CHOICE:' + letter + ':0@@ ';
                });
            });

            return s.replace(/\n{3,}/g, '\n\n').trim();
        }

        function lhlV58RestoreImages(s) {
            return String(s || '').replace(/@@IMG:([^@]+)@@/g, function(_, enc){
                try { return '\n' + lhlV58CleanImgTag(decodeURIComponent(enc)) + '\n'; }
                catch(e) { return ''; }
            });
        }


        // V60 - Các hàm phụ trợ cho chuyển Word hàng loạt: cắt rác đuôi đáp án,
        // bảo vệ tiêu đề phần và chuẩn hóa cụm A-B-C-D ổn định hơn.
        function lhlV60CleanQuestionPieceText(s) {
            return lhlV58RestoreImages(lhlV58FinalCleanText(String(s || '')
                .replace(/@@CHOICE:[ABCD]:[01]@@/gi, '')
                .replace(/(?:^|\n)\s*(?:Đáp\s*(?:án|s[ốôo])|Lời\s*giải|Giải)\s*[:：][\s\S]*$/i, '')
            ));
        }

        function lhlV60CleanChoiceText(s) {
            let t = String(s || '');
            // Không để lời giải/đáp án/tên phần/hình Word rác sau câu dính vào đáp án D.
            t = t.replace(/(?:^|\n|\s)(?:Đáp\s*(?:án|s[ốôo])|Lời\s*giải|Giải)\s*[:：][\s\S]*$/i, '');
            t = t.replace(/(?:^|\n)\s*(PHẦN\s+(?:I|II|III|IV|V|1|2|3|4|5)\s*[.:][\s\S]*)$/i, '');
            t = t.replace(/@@CHOICE:[ABCD]:[01]@@/gi, '');
            t = lhlV58RestoreImages(lhlV58FinalCleanText(t));
            t = t.replace(/^[\s.:：\-–—]+/, '').trim();
            return t;
        }

        function lhlV60BuildQuestionHtml(qNo, questionPart, items) {
            let out = '<b> Câu ' + qNo + '. </b>\n\n';
            out += (questionPart || '').trim() + '\n\n';
            out += lhlBuildChoicesHtmlV57(items, true) + '\n\n\n';
            out += '<table class="FontDung" width="100%" style="margin-left: auto; margin-right: auto;">\n<tbody><tr><td></td></tr></tbody></table>';
            return out.replace(/\n{4,}/g, '\n\n\n').trim();
        }

        function lhlV60FindABCDSequence(marks) {
            if (!Array.isArray(marks) || marks.length < 4) return null;
            marks.sort(function(a,b){ return a.index - b.index; });
            for (let i = 0; i <= marks.length - 4; i++) {
                if (marks[i].letter === 'A' && marks[i+1].letter === 'B' && marks[i+2].letter === 'C' && marks[i+3].letter === 'D') {
                    return marks.slice(i, i + 4);
                }
            }
            return null;
        }

        function lhlTryNormalizeOneWordMultipleChoiceV58(input) {
            let s = lhlV58StripWordJunk(input);
            if (!/@@CHOICE:A:/i.test(s) || !/@@CHOICE:B:/i.test(s) || !/@@CHOICE:C:/i.test(s) || !/@@CHOICE:D:/i.test(s)) return null;

            let qm = s.match(/Câu\s*(\d+)\s*[\.:]/i);
            if (!qm) return null;
            let qNo = qm[1];
            let afterQ = s.slice(qm.index + qm[0].length);

            let re = /@@CHOICE:([ABCD]):([01])@@/gi, m, marks = [];
            while ((m = re.exec(afterQ)) !== null) marks.push({letter: m[1].toUpperCase(), correct: m[2] === '1', index: m.index, end: re.lastIndex});
            marks = lhlV60FindABCDSequence(marks);
            if (!marks) return null;

            let questionPart = lhlV60CleanQuestionPieceText(afterQ.slice(0, marks[0].index));

            let items = [];
            for (let i = 0; i < 4; i++) {
                let cur = marks[i];
                let nextIndex = (i < 3) ? marks[i+1].index : afterQ.length;
                let txt = lhlV60CleanChoiceText(afterQ.slice(cur.end, nextIndex));
                items.push({letter: cur.letter, text: txt, isCorrect: cur.correct});
            }

            // Nếu nhãn bị gạch chân kiểu <b><u>C</u></b>. thì isCorrect đã giữ lại.
            return lhlV60BuildQuestionHtml(qNo, questionPart, items);
        }




        // V59 - Chuyển Word hàng loạt: nhận nhiều câu Word-paste rác trong cùng một file/tab,
        // tách từng Câu n., chuẩn hóa riêng từng câu rồi ghép lại. Giữ lại lõi ổn định V58/V57.
        function lhlCleanWordQuestionCodeV59(input) {
            let raw = String(input || '');
            let stripped = lhlV58StripWordJunk(raw);
            let qMatches = [];
            let qRe = /Câu\s*(\d+)\s*[\.:]/gi;
            let m;
            while ((m = qRe.exec(stripped)) !== null) {
                qMatches.push({ no: m[1], index: m.index, end: qRe.lastIndex, text: m[0] });
            }

            // Không phải nhiều câu thì giữ đường xử lý từng câu của V58/V57.
            if (qMatches.length <= 1) return lhlCleanWordQuestionCodeV58(raw);

            let out = [];
            let okCount = 0;

            // Giữ lại tiêu đề phần/đoạn dẫn trước câu đầu nếu có, tránh mất PHẦN I/II/III.
            let intro = stripped.slice(0, qMatches[0].index).trim();
            if (intro) {
                intro = lhlV58RestoreImages(lhlV58FinalCleanText(intro));
                intro = intro.replace(/^\s*(PHẦN\s+(?:I|II|III|IV|V|1|2|3|4|5)\s*[.:][^\n]*)\s*$/gim, '<p class="section-title"><b>$1</b></p>');
                if (intro.trim()) out.push(intro.trim());
            }

            for (let i = 0; i < qMatches.length; i++) {
                let start = qMatches[i].index;
                let end = (i + 1 < qMatches.length) ? qMatches[i + 1].index : stripped.length;
                let chunk = stripped.slice(start, end).trim();
                let html = lhlTryNormalizeOneStrippedQuestionV59(chunk);
                if (html) { out.push(html); okCount++; }
                else {
                    // Nếu một câu nào đó chưa đủ A-D thì vẫn làm sạch nhẹ, không làm hỏng các câu khác.
                    let fallback = lhlV58RestoreImages(lhlV58FinalCleanText(chunk));
                    if (fallback.trim()) out.push(fallback.trim());
                }
            }

            // Chỉ dùng V59/V60 khi thật sự chuẩn hóa được ít nhất 2 câu, tránh phá cấu trúc lạ.
            if (okCount >= 2) {
                return out.join('\n\n').replace(/\n{4,}/g, '\n\n\n').trim();
            }
            return lhlCleanWordQuestionCodeV58(raw);
        }

        function lhlTryNormalizeOneStrippedQuestionV59(chunk) {
            let s = String(chunk || '').trim();
            let qm = s.match(/^\s*Câu\s*(\d+)\s*[\.:]/i);
            if (!qm) return null;
            let qNo = qm[1];
            let afterQ = s.slice(qm[0].length);

            let re = /@@CHOICE:([ABCD]):([01])@@/gi, m, marks = [];
            while ((m = re.exec(afterQ)) !== null) {
                marks.push({ letter: m[1].toUpperCase(), correct: m[2] === '1', index: m.index, end: re.lastIndex });
            }
            marks = lhlV60FindABCDSequence(marks);
            if (!marks) return null;

            let questionPart = lhlV60CleanQuestionPieceText(afterQ.slice(0, marks[0].index));

            let items = [];
            for (let i = 0; i < 4; i++) {
                let cur = marks[i];
                let nextIndex = (i < 3) ? marks[i+1].index : afterQ.length;
                let txt = lhlV60CleanChoiceText(afterQ.slice(cur.end, nextIndex));
                items.push({ letter: cur.letter, text: txt, isCorrect: cur.correct });
            }

            return lhlV60BuildQuestionHtml(qNo, questionPart, items);
        }


        function restoreHiddenAnswerLines(root) {
            (root || document).querySelectorAll('[data-answer-hidden="1"]').forEach(function(el) {
                const prevDisplay = el.getAttribute('data-prev-display');
                if (prevDisplay !== null) el.style.display = prevDisplay;
                else el.style.removeProperty('display');
                el.removeAttribute('data-answer-hidden');
                el.removeAttribute('data-prev-display');
            });
        }

        function hideManualAnswerLines(root) {
            const container = root || document;
            const answerLineRegex = /^(Đáp\s*(?:án|s[ốôo])|Lời\s*giải|Giải)\s*[:：]/i;

            // Ẩn riêng các thẻ in đậm chứa Đáp án/Đáp số, kể cả nằm trong cùng dòng câu hỏi.
            container.querySelectorAll('b, strong, span, i').forEach(function(el) {
                if (!el || !el.textContent) return;
                if (el.closest('.solution')) return;
                const txt = (el.textContent || '').replace(/\s+/g, ' ').trim();
                if (answerLineRegex.test(txt)) {
                    el.setAttribute('data-answer-hidden', '1');
                    el.setAttribute('data-prev-display', el.style.display || '');
                    el.style.display = 'none';
                }
            });

            const blockSelector = 'p, div, li, table, .short-answer';
            container.querySelectorAll(blockSelector).forEach(function(el) {
                if (!el || !el.textContent) return;
                if (el.closest('.solution')) return;
                if (el.classList && el.classList.contains('short-answer')) {
                    el.setAttribute('data-answer-hidden', '1');
                    el.setAttribute('data-prev-display', el.style.display || '');
                    el.style.display = 'none';
                    return;
                }
                const txt = (el.textContent || '').replace(/\s+/g, ' ').trim();
                if (!txt) return;
                if (answerLineRegex.test(txt)) {
                    el.setAttribute('data-answer-hidden', '1');
                    el.setAttribute('data-prev-display', el.style.display || '');
                    el.style.display = 'none';
                }
            });
        }

        function applyAnswerSolutionVisibility() {
            let paper = document.getElementById('paper');
            let btn = document.getElementById('btn-toggle-answer-solution');
            if (!paper) return;
            restoreHiddenAnswerLines(paper);
            if (isAnswerSolutionVisible) {
                paper.classList.remove('hide-answer-solution');
                if (btn) btn.innerText = '🙈 Ẩn ĐA/LG';
            } else {
                paper.classList.add('hide-answer-solution');
                hideManualAnswerLines(paper);
                if (btn) btn.innerText = '👁️ Hiện ĐA/LG';
            }
        }

        function toggleAnswerSolutionVisibility() {
            isAnswerSolutionVisible = !isAnswerSolutionVisible;
            document.body.classList.toggle('hide-answer-mode', !isAnswerSolutionVisible);
            updatePreview();
            showToast(isAnswerSolutionVisible ? '👁️ Đã hiện đáp án/lời giải và làm sạch đáp số PHẦN III!' : '🙈 Đã ẩn đáp án/lời giải và khóa đúng nhãn đáp số PHẦN III!');
        }


        // --- CHUYỂN LATEX DẠNG EX SANG HTML ---
        function stripLatexComments(text) {
            return text.split('\n').map(line => line.replace(/(^|[^\\])%.*/g, '$1')).join('\n');
        }

        function readLatexGroup(text, openIndex) {
            if (openIndex < 0 || text[openIndex] !== '{') return null;
            let depth = 0;
            for (let i = openIndex; i < text.length; i++) {
                let ch = text[i];
                let prev = i > 0 ? text[i - 1] : '';
                if (ch === '{' && prev !== '\\') depth++;
                else if (ch === '}' && prev !== '\\') {
                    depth--;
                    if (depth === 0) return { content: text.substring(openIndex + 1, i), end: i + 1 };
                }
            }
            return null;
        }

        function findCommandGroups(text, commandName, groupCount) {
            let regex = new RegExp('\\\\' + commandName + '\\b');
            let match = regex.exec(text);
            if (!match) return null;
            let pos = match.index + match[0].length;
            let groups = [];
            for (let i = 0; i < groupCount; i++) {
                while (pos < text.length && /\s/.test(text[pos])) pos++;
                let group = readLatexGroup(text, pos);
                if (!group) return null;
                groups.push(group.content);
                pos = group.end;
            }
            return { start: match.index, end: pos, groups: groups, commandName: commandName };
        }

        function findLatexCommandGroups(text, commandName, groupCount, allowOptionalArg = false) {
            let regex = new RegExp('\\\\' + commandName + '\\b');
            let match = regex.exec(text);
            if (!match) return null;
            let pos = match.index + match[0].length;
            let optionalArg = '';
            while (pos < text.length && /\s/.test(text[pos])) pos++;
            if (allowOptionalArg && text[pos] === '[') {
                let depth = 0;
                let startOpt = pos;
                for (; pos < text.length; pos++) {
                    let ch = text[pos];
                    let prev = pos > 0 ? text[pos - 1] : '';
                    if (ch === '[' && prev !== '\\') depth++;
                    else if (ch === ']' && prev !== '\\') {
                        depth--;
                        if (depth === 0) {
                            optionalArg = text.substring(startOpt + 1, pos);
                            pos++;
                            break;
                        }
                    }
                }
            }
            let groups = [];
            for (let i = 0; i < groupCount; i++) {
                while (pos < text.length && /\s/.test(text[pos])) pos++;
                let group = readLatexGroup(text, pos);
                if (!group) return null;
                groups.push(group.content);
                pos = group.end;
            }
            return { start: match.index, end: pos, groups: groups, optionalArg: optionalArg, commandName: commandName };
        }

        function extractCommandBlock(text, commandName) {
            let regex = new RegExp('\\\\' + commandName + '\\b');
            let match = regex.exec(text);
            if (!match) return null;
            let pos = match.index + match[0].length;
            while (pos < text.length && /\s/.test(text[pos])) pos++;
            let group = readLatexGroup(text, pos);
            if (!group) return null;
            return { start: match.index, end: group.end, content: group.content };
        }

        function cleanLatexChoice(choiceText) {
            let isTrue = /\True\b/i.test(choiceText);
            let cleaned = (choiceText || '')
                .replace(/\True\b/gi, '')
                .replace(/^\\+\s*/g, '')
                .trim();
            let html = latexInlineToHtml(cleaned);
            return { html: html, isTrue: isTrue };
        }

        function findChoiceCommand(work) {
            return findCommandGroups(work, 'choiceTF', 4)
                || findCommandGroups(work, 'haicot', 4)
                || findCommandGroups(work, 'boncot', 4)
                || findCommandGroups(work, 'motcot', 4)
                || findCommandGroups(work, 'choice', 4);
        }

        function buildChoicesHtml(choice) {
            if (!choice) return '';
            let parsedChoices = choice.groups.map(cleanLatexChoice);
            let command = (choice.commandName || '').toLowerCase();
            if (command === 'choicetf') {
                return '\n<div class="choices cols-1" style="margin-top: 4px; margin-bottom: 0px;">\n' +
                    parsedChoices.map((c, i) => {
                        let label = String.fromCharCode(97 + i) + ')';
                        let correctClass = c.isTrue ? ' correct-choice' : '';
                        return `<div class="choice${correctClass}" style="margin-bottom: ${i === 3 ? '0px' : '8px'};"><b>${label}</b> ${c.html}</div>`;
                    }).join('\n') + '\n</div>\n';
            }
            let colClass = 'cols-2';
            if (command === 'boncot') colClass = 'cols-4';
            if (command === 'motcot') colClass = 'cols-1';
            return `\n<div class="choices ${colClass}" style="margin-top: 4px; margin-bottom: 0px;">\n` +
                parsedChoices.map((c, i) => {
                    let label = String.fromCharCode(65 + i) + '.';
                    let mb = (i === 2 || i === 3) ? '0px' : '8px';
                    if (colClass === 'cols-1' && i < 3) mb = '8px';
                    if (colClass === 'cols-4') mb = '0px';
                    let correctClass = c.isTrue ? ' correct-choice' : '';
                    return `<div class="choice${correctClass}" style="margin-bottom: ${mb};"><b>${label}</b> ${c.html}</div>`;
                }).join('\n') + '\n</div>\n';
        }

        function convertLatexTextWithInlineChoices(text) {
            let work = text || '';
            let choice = findChoiceCommand(work);
            let choicesHtml = '';
            if (choice) {
                choicesHtml = buildChoicesHtml(choice);
                work = work.substring(0, choice.start) + work.substring(choice.end);
            }
            let html = latexInlineToHtml(work).trim();
            if (choicesHtml) html += '\n\n' + choicesHtml.trim();
            return html.trim();
        }

        function convertImminiBlocks(text) {
            let result = '';
            let pos = 0;
            while (pos < text.length) {
                let tail = text.substring(pos);
                let im = findLatexCommandGroups(tail, 'immini', 2, true);
                if (!im) {
                    result += tail;
                    break;
                }
                result += tail.substring(0, im.start);
                let leftHtml = convertLatexTextWithInlineChoices(im.groups[0]);
                let rightHtml = latexInlineToHtml(im.groups[1]).trim();
                result += `\n<div class="immini-wrap">\n    <div class="immini-text">${leftHtml}</div>\n    <div class="immini-figure">${rightHtml}</div>\n</div>\n`;
                pos += im.end;
            }
            return result;
        }

        function latexInlineToHtml(text) {
            if (!text) return '';
            let t = text;
            t = t.replace(/\\vec\s*\{([^{}]+)\}/g, '\\overrightarrow{$1}');
            t = t.replace(/\\begin\{center\}/gi, '<div style="text-align:center;">');
t = t.replace(/\\end\{center\}/gi, '</div>');

t = t.replace(/\\begin\{tabular\}\{[^}]*\}([\s\S]*?)\\end\{tabular\}/gi, function(match, body){
    body = body
        .replace(/\\hline/g, '')
        .trim();

    let rows = body
        .split(/\\\\/g)
        .map(r => r.trim())
        .filter(r => r.length > 0);

    let htmlRows = rows.map(row => {
        let cells = row.split('&').map(cell => {
            cell = cell.trim();
            return `<td>${cell}</td>`;
        }).join('');
        return `<tr>${cells}</tr>`;
    }).join('');

    return `<table class="latex-table">${htmlRows}</table>`;
});
            t = t.replace(
    /\\subsubsection\*\s*\{([\s\S]*?)\}/gi,
    '<p class="section-title"><b>$1</b></p>'
);
            t = t.replace(/([0-9]+)\\%/g, '\\($1\\%\\)');
            t = t
    .replace(/\\dfrac/g, '\\frac')
    .replace(/\\times/g, '\\times ')
    .replace(/\\cap/g, '\\cap ')
    .replace(/\\Leftrightarrow/g, '\\Leftrightarrow ');
            t = t.replace(/\\\[/g, '$$').replace(/\\\]/g, '$$').replace(/\\\(/g, '$').replace(/\\\)/g, '$');
            t = t.replace(/\\dfrac/g, '\\dfrac').replace(/\\frac/g, '\\dfrac');
            t = t.replace(/\\textbf\s*\{([^{}]*)\}/g, '<b>$1</b>');
            t = t.replace(/\\textit\s*\{([^{}]*)\}/g, '<i>$1</i>');
            t = t.replace(/\\emph\s*\{([^{}]*)\}/g, '<i>$1</i>');
            t = t.replace(/\\underline\s*\{([^{}]*)\}/g, '<u>$1</u>');
            t = t.replace(/\\begin\{center\}/gi, '<div style="text-align: center;">');
            t = t.replace(/\\end\{center\}/gi, '</div>');
            t = t.replace(/\\begin\{enumerate\}/gi, '<ol>').replace(/\\end\{enumerate\}/gi, '</ol>');
            t = t.replace(/\\begin\{itemize\}/gi, '<ul>').replace(/\\end\{itemize\}/gi, '</ul>');
            t = t.replace(/\\item\s*/gi, '<li>');
            t = t.replace(/\\par\b/g, '\n\n');
            t = t.replace(/\\newline\b/g, '<br>');
            t = t.replace(/\\\\\s*/g, '<br>');
            t = t.replace(/\n{3,}/g, '\n\n');
            return t.trim();
        }


        function cleanShortAnswerText(ans) {
    let cleaned = (ans || '').trim();

    // Bỏ cặp $...$ ngoài cùng
    if (cleaned.startsWith('$') && cleaned.endsWith('$')) {
        cleaned = cleaned.substring(1, cleaned.length - 1).trim();
    }

    // Giữ dấu phẩy thập phân LaTeX: 26{,}47 -> 26,47
    cleaned = cleaned
        .replace(/\{\s*,\s*\}/g, ',')
        .replace(/\{\s*\.\s*\}/g, '.');

    // Xóa các cặp ngoặc nhọn còn lại
    cleaned = cleaned.replace(/[{}]/g, '');

    // Chỉ đổi lệnh khoảng trắng LaTeX \, thành khoảng trắng
    cleaned = cleaned.replace(/\\,/g, ' ');

    // Xử lý phần trăm nếu có
    cleaned = cleaned.replace(/\\%/g, '%');

    return cleaned.trim();
}

        function buildShortAnswerHtml(ans) {
            return `
<div class="short-answer">
    <span class="short-answer-label">Đáp án:</span>
    <span class="short-answer-box">${ans}</span>
</div>`;
        }

        function convertOneExBlock(blockText, questionNumber) {
            let work = blockText.trim();
            let solution = extractCommandBlock(work, 'loigiai');
            let solutionHtml = '';
            if (solution) {
                solutionHtml = latexInlineToHtml(
        solution.content
        .replace(/\\\(/g, '$')
        .replace(/\\\)/g, '$')
        .replace(/\\\[/g, '$$')
        .replace(/\\\]/g, '$$')
        
);
        solutionHtml = solutionHtml
    .replace(/([abcd])\)\s*/g, '<br><b>$1)</b> ');
                work = work.substring(0, solution.start) + work.substring(solution.end);
            }

            work = convertImminiBlocks(work);

            // ===== SHORT ANSWER / PHẦN III =====
            // Dùng parser đếm ngoặc thật để không bị lỗi với đáp án dạng $26{,}478$.
            let shortAnswer = findLatexCommandGroups(work, 'shortans', 1, true);
            while (shortAnswer) {
                let ans = cleanShortAnswerText(shortAnswer.groups[0]);
                let shortHtml = buildShortAnswerHtml(ans);
                work = work.substring(0, shortAnswer.start) + shortHtml + work.substring(shortAnswer.end);
                shortAnswer = findLatexCommandGroups(work, 'shortans', 1, true);
            }

            let choice = findChoiceCommand(work);
            let choicesHtml = '';
            if (choice) {
                choicesHtml = buildChoicesHtml(choice);
                work = work.substring(0, choice.start) + work.substring(choice.end);
            }

            work = work.replace(/\\begin\{ex\}/gi, '').replace(/\\end\{ex\}/gi, '');
            let questionHtml = latexInlineToHtml(work).trim();
            let html = '';
            if (/<div class=["']immini-wrap["']>/i.test(questionHtml)) {
                // Với câu có \immini: đưa nhãn "Câu X." vào trong cột trái,
                // để nhãn câu và nội dung đề bài nằm cùng dòng.
                questionHtml = questionHtml.replace(
                    /(<div class=["']immini-text["']>)\s*/i,
                    `$1<b> Câu ${questionNumber}. </b> `
                );
                html = questionHtml;
            } else {
                html = `<b> Câu ${questionNumber}. </b>\n\n${questionHtml}`;
            }
            if (choicesHtml) html += '\n\n' + choicesHtml.trim();
            if (solutionHtml) html += `\n\n<div class="solution"><b>Lời giải.</b> ${solutionHtml}</div>`;
            return html.trim();
        }

        function extractLatexPreambleForTikz(source) {
            let firstEx = source.search(/\\begin\{ex\}/i);
            let preamble = firstEx >= 0 ? source.substring(0, firstEx) : source;
            return preamble.split('\n').filter(line => {
                let t = line.trim();
                return /^\\(usepackage|usetikzlibrary|tikzset|pgfplotsset|newcommand|renewcommand|DeclareMathOperator)\b/i.test(t);
            }).join('\n');
        }

        async function renderTikzBlocksBeforeExConversion(source) {
            let tikzRegex = /\\begin\{tikzpicture\}[\s\S]*?\\end\{tikzpicture\}/gi;
            let tikzBlocks = [];
            let match;
            while ((match = tikzRegex.exec(source)) !== null) tikzBlocks.push(match[0]);
            if (tikzBlocks.length === 0) return { source: source, rendered: 0, failed: 0 };

            if (!(window.pywebview && window.pywebview.api && window.pywebview.api.render_tikz_images)) {
                showToast("⚠️ Chưa có API render TikZ từ Python. Em sẽ giữ nguyên code TikZ.");
                return { source: source, rendered: 0, failed: tikzBlocks.length };
            }

            showToast(`🖼️ Đang render ${tikzBlocks.length} hình TikZ...`);
            let results = await window.pywebview.api.render_tikz_images(tikzBlocks, extractLatexPreambleForTikz(source));
            let idx = 0;
            let rendered = 0;
            let failed = 0;
            let newSource = source.replace(tikzRegex, function(originalBlock) {
                let res = results && results[idx] ? results[idx] : null;
                idx++;
                if (res && res.ok && res.data_url) {
                    rendered++;
                    return `\n<div class="tikz-image-wrap">\n    <img class="tikz-image" src="${res.data_url}" style="max-width:100%; height:auto; display:block; margin:0 auto 0 0;">\n</div>\n`;
                }
                failed++;
                let err = res && res.error ? res.error : 'Không rõ lỗi render TikZ.';
                return `\n<div class="tikz-render-error" title="${err.replace(/"/g, '&quot;')}">⚠️ Chưa render được hình TikZ. ${err}</div>\n<pre style="display:none;">${originalBlock.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</pre>\n`;
            });
            return { source: newSource, rendered: rendered, failed: failed };
        }

        async function convertLatexExToHtml() {
            if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở một Tab để sử dụng ạ!"); return; }
            let editor = document.getElementById('editor');
            let source = editor.value;
            if (!source.trim()) { showToast("⚠️ Editor đang trống ạ!"); return; }

            let stripped = stripLatexComments(source);
            source = stripped.normalize ? stripped.normalize('NFC') : stripped;

            try {
                let tikzResult = await renderTikzBlocksBeforeExConversion(source);
                source = tikzResult.source;
            } catch (e) {
                console.log(e);
                showToast("⚠️ TikZ render gặp lỗi, em vẫn tiếp tục chuyển EX sang HTML ạ!");
            }

            let sectionRegex = /\\subsubsection\*\s*\{([\s\S]*?)\}|\\begin\{ex\}([\s\S]*?)\\end\{ex\}/gi;

            let resultParts = [];
            let questionCounter = 1;
            let exCount = 0;
            let match;

            while ((match = sectionRegex.exec(source)) !== null) {

                if (match[1]) {
                    questionCounter = 1;

                    resultParts.push(
                        `<p class="section-title"><b>${latexInlineToHtml(match[1].trim())}</b></p>`
                    );

                } else if (match[2]) {
                    exCount++;
                    resultParts.push(
                        convertOneExBlock(match[2], questionCounter++)
                    );
                }
            }

            if (exCount === 0) {
                showToast("⚠️ Em chưa tìm thấy cấu trúc \\begin{ex} ... \\end{ex} trong nội dung ạ!");
                return;
            }

            let result = resultParts.join('\n\n');

            result = processMathHTML(result);
            executeInsertText(editor, result, 0, editor.value.length, 0, result.length);
            showToast(`🧮 Đã chuyển ${exCount} câu LaTeX EX sang HTML! Nếu có TikZ, hình đã được chèn vào nội dung.`);
        }

