let scorePart1=0,correctP1=0,p1Blocks=document.querySelectorAll('.part1-question-block'),totalP1=p1Blocks.length;let scorePart2=0,totalCorrectYPart2=0,correctP2Count=0,p2Blocks=document.querySelectorAll('.part2-question-block'),totalYPart2=0,p2Details=[];let scorePart3=0,correctP3=0,p3Blocks=document.querySelectorAll('.part3-question-block'),totalP3=p3Blocks.length;p1Blocks.forEach(function(block){let selected=block.querySelector('input[type="radio"]:checked');if(selected&&selected.closest('.choice').getAttribute('data-correct')==='true'){scorePart1+=PART1_POINT;correctP1++;}});let mapPoints={0:0,1:0.1,2:0.25,3:0.5,4:1.0};p2Blocks.forEach(function(block,idx){let rows=block.querySelectorAll('.tf-row'),c=0;totalYPart2+=rows.length;rows.forEach(function(row){let a=row.getAttribute('data-ans'),u=row.getAttribute('data-user-select');if(u&&u.trim()===a.trim()){c++;totalCorrectYPart2++;}});let point=mapPoints[c]||0;scorePart2+=point;p2Details.push({q:idx+1,correct:c,total:rows.length,point:point});if(c===rows.length&&rows.length>0)correctP2Count++;});p3Blocks.forEach(function(block){let input=block.querySelector('input[type="text"]');let user=normalizeAns(input?input.value:''),correct=normalizeAns(block.getAttribute('data-ans'));if(user&&correct&&user===correct){scorePart3+=PART3_POINT;correctP3++;}});let totalScore=scorePart1+scorePart2+scorePart3;
let submitStatus=lockedByTabSwitch?'Tự nộp do chuyển tab/rời trang':(forceSubmit?'Tự nộp do hết giờ':'Nộp bài');if(lockedByTabSwitch){markExamLocked(submitStatus);}
let currentExamCode=(document.getElementById('examCodeBox')?document.getElementById('examCodeBox').innerText:'').replace(/\s+/g,' ').trim();
let p2DetailText=p2Details.map(function(d){return 'Câu '+d.q+': '+d.correct+'/'+d.total+' ý = '+d.point.toFixed(2)+' điểm';}).join('; ');
document.querySelectorAll('input[type="radio"],input[type="text"]').forEach(function(el){el.disabled=true;});document.querySelectorAll('.tf-btn').forEach(function(el){el.disabled=true;});let name=document.getElementById('studentName').value.trim()||'....................................';let lop=document.getElementById('studentClass').value.trim()||'...........';let p2DetailRows=p2Details.map(function(d){return '<tr><td style="padding:6px;border:1px solid #ddd;text-align:center;">Câu '+d.q+'</td><td style="padding:6px;border:1px solid #ddd;text-align:center;">'+d.correct+'/'+d.total+' ý</td><td style="padding:6px;border:1px solid #ddd;text-align:center;font-weight:bold;color:#2e7d32;">'+d.point.toFixed(2)+' đ</td></tr>';}).join('');let lockMsg=lockedByTabSwitch?'<p style="color:#d32f2f;font-weight:bold;">Bài đã tự nộp do chuyển tab/rời trang. Không được làm lại.</p>':'';document.getElementById('resultBox').style.display='block';document.getElementById('scoreDetail').innerHTML='<p><strong>Học sinh:</strong> '+name+' | <strong>Lớp:</strong> '+lop+'</p>'+lockMsg+'<p style="color:#d32f2f;font-size:20px;font-weight:bold;margin:10px 0;">Tổng điểm đạt được: '+totalScore.toFixed(2)+' / 10 điểm</p><hr><table style="width:100%;border-collapse:collapse;margin-top:10px;font-size:16px;"><tr style="background:#0b3142;color:#fff;text-align:center;font-weight:bold;"><td style="padding:8px;border:1px solid #0b3142;">Phần thi</td><td style="padding:8px;border:1px solid #0b3142;">Số câu/ý đúng</td><td style="padding:8px;border:1px solid #0b3142;">Điểm đạt</td></tr><tr><td style="padding:8px;border:1px solid #ccc;"><strong>Phần I</strong></td><td style="padding:8px;border:1px solid #ccc;text-align:center;">'+correctP1+'/'+totalP1+' câu</td><td style="padding:8px;border:1px solid #ccc;text-align:center;font-weight:bold;color:#2e7d32;">+'+scorePart1.toFixed(2)+' đ</td></tr><tr><td style="padding:8px;border:1px solid #ccc;"><strong>Phần II</strong></td><td style="padding:8px;border:1px solid #ccc;text-align:center;">'+correctP2Count+'/'+p2Blocks.length+' câu ('+totalCorrectYPart2+'/'+totalYPart2+' ý)</td><td style="padding:8px;border:1px solid #ccc;text-align:center;font-weight:bold;color:#2e7d32;">+'+scorePart2.toFixed(2)+' đ</td></tr><tr><td colspan="3" style="padding:8px;border:1px solid #ccc;"><strong>Chi tiết Phần II theo thang Đ/S:</strong><table style="width:100%;border-collapse:collapse;margin-top:6px;"><tr style="background:#e8f1f5;font-weight:bold;"><td style="padding:6px;border:1px solid #ddd;text-align:center;">Câu</td><td style="padding:6px;border:1px solid #ddd;text-align:center;">Số ý đúng</td><td style="padding:6px;border:1px solid #ddd;text-align:center;">Điểm</td></tr>'+p2DetailRows+'</table></td></tr><tr><td style="padding:8px;border:1px solid #ccc;"><strong>Phần III</strong></td><td style="padding:8px;border:1px solid #ccc;text-align:center;">'+correctP3+'/'+totalP3+' câu</td><td style="padding:8px;border:1px solid #ccc;text-align:center;font-weight:bold;color:#2e7d32;">+'+scorePart3.toFixed(2)+' đ</td></tr></table>';
