// V42 RESTORE: chống lỗi khởi động làm mất tab bar / editor bị gõ được.
// ============================================================
function lhlEnsureInitialEditorStateV42() {
    try {
        const editorEl = document.getElementById('editor');
        if (!editorEl) return;
        if (!activeTabId) {
            editorEl.disabled = true;
            editorEl.placeholder = "Thầy vui lòng tạo Tab mới (Mẫu Sở, C.Đề...) để bắt đầu soạn thảo ạ!";
        }
        if (typeof renderTabs === 'function') renderTabs();
        if (typeof updatePreview === 'function') updatePreview();
        if (typeof updateQuestionStats === 'function') updateQuestionStats();
    } catch (e) {
        console.warn('V42 init guard:', e);
    }
}

