// ============================================================
// V43 FIX: Trộn đề dùng lại generateFullHTML(false) đã sửa ở V42
// để giữ đúng CSS/MathJax/structure giống phần biên dịch, không dính câu.
// ============================================================
function lhlMixEnsureMathJaxInFullHtmlV43(fullHtml) {
    let s = String(fullHtml || '');
    if (!/<html[\s>]/i.test(s)) return s;
    if (!/window\.MathJax/i.test(s)) {
        s = s.replace(/<head[^>]*>/i, m => m + `\n<script>window.MathJax = { tex: { inlineMath: [['$','$'], ['\\\\(','\\\\)']], displayMath: [['$$','$$']] } };<\/script>`);
    }
    if (!/MathJax-script/i.test(s)) {
        s = s.replace(/<\/head>/i, `<script id="MathJax-script" async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"><\/script>\n</head>`);
    }
    return s;
}

