// V43 helper: đảm bảo mỗi câu sau khi trộn là một khối riêng, tránh Đáp số dính Câu kế tiếp.
function lhlMixWrapQuestionBlockV43(html) {
    let s = String(html || '').trim();
    if (!s) return '';
    if (!/<(p|div|table|section|br|img|ul|ol)\b/i.test(s)) {
        s = s.replace(/\r?\n/g, '<br>');
    }
    return '<div class="lhl-mix-question-block">' + s + '</div>';
}

// Override parser để bọc từng câu thành block riêng và thêm CSS chống dính dòng.
function lhlMixParseAndGenerate(sourceFullHtml, count, duration, startCode, examTitle, examSubject, examGrade, schoolName) {
    const shell = lhlMixBodyAndShell(sourceFullHtml);
    let head = shell.head;
    if (!/MathJax-script/i.test(head)) {
        head = head.replace(/<\/head>/i, '<script id="MathJax-script" async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"><\/script>\n</head>');
    }
    if (!/window\.MathJax/i.test(head)) {
        head = head.replace(/<head[^>]*>/i, m => m + "\n<script>window.MathJax = { tex: { inlineMath: [['$','$'], ['\\\\(','\\\\)']], displayMath: [['$$','$$']] } };<\\/script>");
    }
    if (!/lhl-mix-question-block/i.test(head)) {
        head = head.replace(/<\/style>/i, `.lhl-mix-question-block{display:block;clear:both;margin:6px 0 8px 0;}\n</style>`);
    }

    const body = shell.body;
    const parts = lhlMixFindPartTitles(body);
    if (!parts.I || !parts.II || !parts.III) throw new Error('Chưa nhận diện đủ tiêu đề PHẦN I, PHẦN II, PHẦN III trong file.');

    const header = body.slice(0, parts.I.start);
    const p1Title = parts.I.html;
    const p1Content = body.slice(parts.I.end, parts.II.start);
    const p2Title = parts.II.html;
    const p2Content = body.slice(parts.II.end, parts.III.start);
    const p3Title = parts.III.html;
    let p3AndFooter = body.slice(parts.III.end);
    let footer = '';
    const footerIdx = p3AndFooter.search(/<div\b[^>]*class=["'][^"']*exam-end-line|[-–—]{3,}\s*(?:<strong[^>]*>)?\s*HẾT/i);
    if (footerIdx > 0) {
        footer = p3AndFooter.slice(footerIdx);
        p3AndFooter = p3AndFooter.slice(0, footerIdx);
    }

    const p1Original = lhlMixSplitQuestions(p1Content);
    const p2Original = lhlMixSplitQuestions(p2Content);
    const p3Original = lhlMixSplitQuestions(p3AndFooter);
    if (!p1Original.length && !p2Original.length && !p3Original.length) throw new Error('Chưa tách được câu hỏi để trộn.');

    const files = [], codes = [], p1AnswerRows = [], p2AnswerRows = [], p3AnswerRows = [];
    const codeList = lhlMixBuildCodeList(startCode, count);
    for (let k = 0; k < count; k++) {
        const code = codeList[k];
        codes.push(code);
        const p1Ans = [], p2Ans = [], p3Ans = [];
        const p1Blocks = lhlMixShuffleEnsureChanged(p1Original).map((b,i)=>{ const r = lhlMixProcessPart1Block(b, i+1); p1Ans.push(r.answer); return lhlMixWrapQuestionBlockV43(r.html); });
        const p2Blocks = lhlMixShuffleEnsureChanged(p2Original).map((b,i)=>{ const r = lhlMixProcessPart2Block(b, i+1); p2Ans.push(r.answer); return lhlMixWrapQuestionBlockV43(r.html); });
        const p3Blocks = lhlMixShuffleEnsureChanged(p3Original).map((b,i)=>{ const r = lhlMixProcessPart3Block(b, i+1); p3Ans.push(r.answer); return lhlMixWrapQuestionBlockV43(r.html); });
        p1AnswerRows.push(p1Ans); p2AnswerRows.push(p2Ans); p3AnswerRows.push(p3Ans);
        const newBody = header + p1Title + '\n' + p1Blocks.join('\n') + '\n' + p2Title + '\n' + p2Blocks.join('\n') + '\n' + p3Title + '\n' + p3Blocks.join('\n') + '\n' + footer;
        let full = '<!DOCTYPE html>\n<html>\n' + head + '\n<body>\n' + newBody + '\n</body>\n</html>';
        full = lhlMixApplyCodeAndTime(full, code, duration, examTitle, examSubject, examGrade, schoolName);
        files.push({ filename: 'De_' + code + '.html', content: full });
    }
    return { files, answerHtml: lhlMixBuildAnswerXls(codes, p1AnswerRows, p2AnswerRows, p3AnswerRows), codes };
}




// ============================================================
// V44 FIX: Xóa <br> dư ngay trước tiêu đề phần exam-part-box.
// ============================================================
function lhlFixExtraBrBeforeExamPartBoxV44(html) {
    // V54: dọn <br> dư quanh tiêu đề PHẦN để khoảng cách PHẦN - Câu 1 gọn lại.
    // Chỉ đụng đúng khối exam-part-box, không xóa <br> tự do trong nội dung câu hỏi.
    return String(html || '')
        .replace(/(?:<br\s*\/?>\s*)+(<div\s+class=["'][^"']*exam-part-box[^"']*["'][^>]*>)/gi, '$1')
        .replace(/(<div\s+class=["'][^"']*exam-part-box[^"']*["'][^>]*>[\s\S]*?<\/div>)\s*(?:<br\s*\/?>\s*)+(?=(?:\s|&nbsp;|<\/?(?:b|strong|span|p|div)[^>]*>)*Câu\s*\d+)/gi, '$1\n');
}




// V44: bọc updatePreview để tự dọn <br> dư trước tiêu đề phần khi biên dịch.
if (typeof updatePreview === 'function' && !window.__lhlV44WrappedUpdatePreview) {
    window.__lhlV44WrappedUpdatePreview = true;
    const __oldUpdatePreviewV44 = updatePreview;
    updatePreview = function() {
        try {
            const editor = document.getElementById('editor');
            if (editor && editor.value && editor.value.includes('exam-part-box')) {
                const fixed = lhlFixExtraBrBeforeExamPartBoxV44(editor.value);
                if (fixed !== editor.value) editor.value = fixed;
            }
        } catch(e) {}
        return __oldUpdatePreviewV44.apply(this, arguments);
    };
}




// ============================================================
// V45 FIX PASTE: Ctrl+V và nút Paste đều dán được text + hình từ Word.
// Ảnh được lưu thành mã HINH_ANH_n, base64 nằm trong imageDictionary như cách dán ảnh cũ.
// ============================================================
function lhlRegisterImageDataUrlV45(dataUrl) {
    dataUrl = String(dataUrl || '').trim();
    if (!activeTabId || !dataUrl || !/^data:image\//i.test(dataUrl)) return "";
    imageIndex++;
    const key = 'HINH_ANH_' + imageIndex;
    imageDictionary[key] = dataUrl;
    // Đồng bộ ngay vào tab hiện tại để preview/save không bị mất dictionary ảnh.
    try {
        const tab = tabs.find(t => t.id === activeTabId);
        if (tab) {
            tab.imageDictionary = {...imageDictionary};
            tab.imageIndex = imageIndex;
            tab.isDirty = true;
        }
    } catch(e) {}
    return key;
}

function lhlImageHtmlFromDataUrlV45(dataUrl) {
    const key = lhlRegisterImageDataUrlV45(dataUrl);
    if (!key) return "";
    return '\n<div style="display: flex; justify-content: center; width: 100%; margin: 10px 0; clear: both;">\n' +
           '    <img src="' + key + '" style="max-width: 250px; height: auto;">\n' +
           '</div>\n';
}

function lhlPrepareClipboardHtmlV45(html) {
    let s = String(html || "");

    // Bỏ wrapper HTML/body nếu có.
    const bodyMatch = s.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    if (bodyMatch) s = bodyMatch[1];

    // Đổi ảnh base64 trong HTML clipboard thành mã HINH_ANH_n.
    s = s.replace(/<img\b[^>]*src\s*=\s*(["'])(data:image\/[^"']+)\1[^>]*>/gi, function(match, q, dataUrl) {
        return lhlImageHtmlFromDataUrlV45(dataUrl);
    });

    // Dọn HTML Word rối.
    s = s.replace(/<!--\[if[\s\S]*?<!\[endif\]-->/gi, "");
    s = s.replace(/<\/?span\b[^>]*>/gi, "");
    s = s.replace(/<o:p>\s*<\/o:p>/gi, "");
    s = s.replace(/<p\b[^>]*>/gi, "\n<p>");
    s = s.replace(/<div\b[^>]*>/gi, "\n<div>");
    s = s.replace(/<\/p>\s*/gi, "</p>\n");
    s = s.replace(/<\/div>\s*/gi, "</div>\n");
    return s.trim();
}

function lhlInsertIntoEditorV45(text) {
    if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở một Tab để dán ạ!"); return false; }
    const editor = document.getElementById('editor');
    if (!editor || editor.disabled) { showToast("⚠️ Thầy vui lòng mở một Tab để dán ạ!"); return false; }
    editor.focus();
    const start = (typeof editor.selectionStart === "number") ? editor.selectionStart : (savedStart || 0);
    const end = (typeof editor.selectionEnd === "number") ? editor.selectionEnd : (savedEnd || start);
    executeInsertText(editor, text, start, end, start + text.length, start + text.length);
    return true;
}

async function lhlReadClipboardTextV45() {
    if (window.pywebview && window.pywebview.api && window.pywebview.api.get_clipboard_text) {
        const text = await window.pywebview.api.get_clipboard_text();
        if (text === "ERROR_NO_PYPERCLIP") return "";
        return text || "";
    }
    if (navigator.clipboard && navigator.clipboard.readText) {
        return await navigator.clipboard.readText();
    }
    return "";
}

async function lhlPasteFromClipboardApiV45() {
    // 1) Ưu tiên HTML clipboard từ Word: có thể chứa cả text + img.
    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.get_clipboard_html_data) {
            const htmlRes = await window.pywebview.api.get_clipboard_html_data();
            if (htmlRes && htmlRes.ok && htmlRes.html) {
                const prepared = lhlPrepareClipboardHtmlV45(htmlRes.html);
                if (prepared) {
                    lhlInsertIntoEditorV45(prepared);
                    showToast("📋🖼️ Đã dán nội dung Word gồm text/hình!");
                    return true;
                }
            }
        }
    } catch (e) { console.log("Không đọc được HTML clipboard:", e); }

    // 2) Nếu clipboard là ảnh riêng.
    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.get_clipboard_image_data) {
            const imgRes = await window.pywebview.api.get_clipboard_image_data();
            if (imgRes && imgRes.ok && imgRes.data_url) {
                lhlInsertIntoEditorV45(lhlImageHtmlFromDataUrlV45(imgRes.data_url));
                showToast("🖼️ Đã dán ảnh từ Clipboard!");
                return true;
            }
        }
    } catch (e) { console.log("Không đọc được ảnh clipboard:", e); }

    // 3) Cuối cùng mới dán text.
    try {
        const text = await lhlReadClipboardTextV45();
        if (text) {
            lhlInsertIntoEditorV45(text);
            showToast("📋 Đã dán văn bản!");
            return true;
        }
    } catch (e) { console.log("Không đọc được text clipboard:", e); }

    showToast("⚠️ Clipboard đang trống hoặc chưa cấp quyền dán ạ!");
    return false;
}

// Override nút Paste.
async function pasteText() {
    const active = document.activeElement;
    const editor = document.getElementById('editor');

    function isOtherInput(el) {
        if (!el || el === editor) return false;
        const tag = (el.tagName || "").toUpperCase();
        if (tag === "TEXTAREA") return true;
        if (tag === "INPUT") {
            const type = (el.type || "text").toLowerCase();
            return ["text", "search", "url", "tel", "email", "number", "password"].includes(type);
        }
        return !!el.isContentEditable;
    }

    // Nếu đang ở ô tìm/thay/input khác thì nút Paste dán text vào ô đó như cũ.
    if (isOtherInput(active)) {
        try {
            const text = await lhlReadClipboardTextV45();
            if (!text) { showToast("⚠️ Clipboard text đang trống ạ!"); return; }
            const value = active.value || "";
            const start = (typeof active.selectionStart === "number") ? active.selectionStart : value.length;
            const end = (typeof active.selectionEnd === "number") ? active.selectionEnd : value.length;
            active.value = value.substring(0, start) + text + value.substring(end);
            if (typeof active.setSelectionRange === "function") active.setSelectionRange(start + text.length, start + text.length);
            active.dispatchEvent(new Event("input", { bubbles: true }));
            active.focus();
            showToast("📋 Đã dán vào ô đang chọn!");
            return;
        } catch(e) {}
    }

    await lhlPasteFromClipboardApiV45();
}

// Ctrl+V: bắt sự kiện paste trong editor để dán ảnh/text/hỗn hợp.
if (!window.__lhlV45PasteHandlerInstalled) {
    window.__lhlV45PasteHandlerInstalled = true;

    document.addEventListener('paste', async function(e) {
        // V49 dùng một handler thống nhất ở cuối file. Khi V49 đã cài,
        // bỏ qua handler cũ để tránh Ctrl+V bị dán trùng 2 ảnh.
        if (window.__lhlV49UnifiedPasteHandlerInstalled) return;
        const editor = document.getElementById('editor');
        if (!activeTabId || !editor || editor.disabled) return;

        const active = document.activeElement;
        const isEditorPaste = (active === editor);
        if (!isEditorPaste) return; // ô tìm/thay để trình duyệt xử lý bình thường.

        e.preventDefault();

        const dt = e.clipboardData || window.clipboardData;

        // V47 quality route: handler V45 cũ được giữ, nhưng chạy logic mới ngay tại đây
        // để copy riêng hình không bị lấy ảnh preview trong HTML Word.
        if (typeof lhlClipboardItemsImageFileV47 === 'function' && dt) {
            try {
                const htmlV47 = dt.getData && dt.getData('text/html');
                const htmlHasTextV47 = lhlHtmlHasMeaningfulTextV47(htmlV47);
                const htmlHasImageV47 = lhlHtmlHasImageV47(htmlV47);
                const imageFileV47 = lhlClipboardItemsImageFileV47(dt);

                if (!htmlHasTextV47 && imageFileV47) {
                    lhlInsertImageFileV47(imageFileV47, "🖼️ Đã dán ảnh chất lượng cao bằng Ctrl+V!");
                    e.__lhlV47Handled = true;
                    return;
                }

                if (htmlV47) {
                    const preparedV47 = lhlPrepareClipboardHtmlV45(htmlV47);
                    if (preparedV47) {
                        lhlInsertIntoEditorV45(preparedV47);
                        showToast(htmlHasImageV47 ? "📋🖼️ Đã dán nội dung HTML gồm text/hình!" : "📋 Đã dán nội dung HTML!");
                        e.__lhlV47Handled = true;
                        return;
                    }
                }

                if (imageFileV47) {
                    lhlInsertImageFileV47(imageFileV47, "🖼️ Đã dán ảnh bằng Ctrl+V!");
                    e.__lhlV47Handled = true;
                    return;
                }

                const textV47 = dt.getData && dt.getData('text/plain');
                if (textV47) {
                    lhlInsertIntoEditorV45(textV47);
                    showToast("📋 Đã dán text bằng Ctrl+V!");
                    e.__lhlV47Handled = true;
                    return;
                }
            } catch(errV47) {
                console.log("Paste V47 trong handler V45 lỗi, quay về logic cũ:", errV47);
            }
        }

        if (dt) {
            try {
                const html = dt.getData && dt.getData('text/html');
                if (html) {
                    const prepared = lhlPrepareClipboardHtmlV45(html);
                    if (prepared) {
                        lhlInsertIntoEditorV45(prepared);
                        showToast("📋🖼️ Đã dán nội dung HTML từ Ctrl+V!");
                        return;
                    }
                }

                // Ảnh copy riêng qua Ctrl+V.
                if (dt.items && dt.items.length) {
                    for (const item of dt.items) {
                        if (item.kind === 'file' && /^image\//i.test(item.type || "")) {
                            const file = item.getAsFile();
                            if (file) {
                                const reader = new FileReader();
                                reader.onload = function(ev) {
                                    lhlInsertIntoEditorV45(lhlImageHtmlFromDataUrlV45(ev.target.result));
                                    showToast("🖼️ Đã dán ảnh bằng Ctrl+V!");
                                };
                                reader.readAsDataURL(file);
                                return;
                            }
                        }
                    }
                }

                const text = dt.getData && dt.getData('text/plain');
                if (text) {
                    lhlInsertIntoEditorV45(text);
                    showToast("📋 Đã dán text bằng Ctrl+V!");
                    return;
                }
            } catch(err) {
                console.log("Paste event lỗi, thử API:", err);
            }
        }

        await lhlPasteFromClipboardApiV45();
    }, true);
}




// ============================================================
// V46 FIX: Render ảnh Word dạng VML <v:imagedata> và data:image thô.
// Word đôi khi dán ảnh dưới dạng <v:shape><v:imagedata src="data:image/...">
// Trình duyệt không render VML, nên đổi sang <img> chuẩn.
// ============================================================
function lhlV46ImageBlockFromSrc(src) {
    src = String(src || '').trim();
    if (!src) return '';

    if (/^data:image\//i.test(src) && typeof lhlImageHtmlFromDataUrlV45 === 'function') {
        return lhlImageHtmlFromDataUrlV45(src);
    }

    return '\n<div style="display: flex; justify-content: center; width: 100%; margin: 10px 0; clear: both;">\n' +
           '    <img src="' + src + '" style="max-width: 250px; height: auto;">\n' +
           '</div>\n';
}

function lhlFixWordVmlImagesV46(html) {
    let s = String(html || '');

    // Đổi nguyên khối <v:shape> có <v:imagedata src="..."> thành ảnh chuẩn.
    s = s.replace(/<v:shape\b[^>]*>[\s\S]*?<v:imagedata\b[^>]*\bsrc\s*=\s*(["'])(.*?)\1[^>]*>[\s\S]*?<\/v:shape>/gi,
        function(match, q, src) { return lhlV46ImageBlockFromSrc(src); });

    // Đổi riêng <v:imagedata src="..."> còn sót.
    s = s.replace(/<v:imagedata\b[^>]*\bsrc\s*=\s*(["'])(.*?)\1[^>]*\/?>/gi,
        function(match, q, src) { return lhlV46ImageBlockFromSrc(src); });

    // Một vài Word dùng o:href/href thay vì src.
    s = s.replace(/<v:imagedata\b[^>]*\b(?:o:href|href)\s*=\s*(["'])(.*?)\1[^>]*\/?>/gi,
        function(match, q, src) { return lhlV46ImageBlockFromSrc(src); });

    // Dọn tag VML/Office còn sót.
    s = s.replace(/<\/?v:[^>]+>/gi, '');
    s = s.replace(/<\/?o:[^>]+>/gi, '');
    return s;
}

// Preview: xử lý VML trước khi processCode cũ chạy.
if (typeof processCode === 'function' && !window.__lhlV46WrappedProcessCode) {
    window.__lhlV46WrappedProcessCode = true;
    const __oldProcessCodeV46 = processCode;
    processCode = function(rawCode) {
        return __oldProcessCodeV46.call(this, lhlFixWordVmlImagesV46(rawCode));
    };
}

// Paste V45: xử lý VML ngay khi dán từ Word.
if (typeof lhlPrepareClipboardHtmlV45 === 'function' && !window.__lhlV46WrappedPrepareClipboard) {
    window.__lhlV46WrappedPrepareClipboard = true;
    const __oldPrepareClipboardV45 = lhlPrepareClipboardHtmlV45;
    lhlPrepareClipboardHtmlV45 = function(html) {
        return __oldPrepareClipboardV45.call(this, lhlFixWordVmlImagesV46(html));
    };
}

// Nếu tài liệu cũ đang chứa <v:imagedata>, tự sửa trong editor khi biên dịch.
if (typeof updatePreview === 'function' && !window.__lhlV46WrappedUpdatePreview) {
    window.__lhlV46WrappedUpdatePreview = true;
    const __oldUpdatePreviewV46 = updatePreview;
    updatePreview = function() {
        try {
            const editor = document.getElementById('editor');
            if (editor && editor.value && /<v:imagedata|<v:shape/i.test(editor.value)) {
                const fixed = lhlFixWordVmlImagesV46(editor.value);
                if (fixed !== editor.value) {
                    editor.value = fixed;
                    if (activeTabId) {
                        let tab = tabs.find(t => t.id === activeTabId);
                        if (tab) tab.content = fixed;
                    }
                }
            }
        } catch(e) { console.log('V46 image fix:', e); }
        return __oldUpdatePreviewV46.apply(this, arguments);
    };
}




// ============================================================
// V47 FIX PASTE QUALITY:
// - Copy riêng hình: ưu tiên ảnh trực tiếp từ clipboard để giữ chất lượng cao.
// - Copy text + hình từ Word: vẫn ưu tiên HTML để giữ đủ nội dung.
// - Nút Paste và Ctrl+V dùng cùng tiêu chí phân biệt HTML chỉ có ảnh hay có text thật.
// ============================================================
function lhlHtmlHasMeaningfulTextV47(html) {
    let s = String(html || "");
    s = s.replace(/<style[\s\S]*?<\/style>/gi, "");
    s = s.replace(/<script[\s\S]*?<\/script>/gi, "");
    s = s.replace(/<!--([\s\S]*?)-->/g, "");
    s = s.replace(/<img\b[^>]*>/gi, "");
    s = s.replace(/<v:shape\b[\s\S]*?<\/v:shape>/gi, "");
    s = s.replace(/<v:imagedata\b[^>]*\/?>/gi, "");
    s = s.replace(/<[^>]+>/g, " ");
    s = s.replace(/&nbsp;|&#160;/gi, " ");
    s = s.replace(/&[a-z]+;|&#\d+;/gi, " ");
    s = s.replace(/\s+/g, " ").trim();
    return s.length > 0;
}

function lhlHtmlHasImageV47(html) {
    return /<img\b|<v:imagedata\b|data:image\//i.test(String(html || ""));
}

function lhlClipboardItemsImageFileV47(dt) {
    if (!dt || !dt.items || !dt.items.length) return null;
    for (const item of dt.items) {
        if (item && item.kind === 'file' && /^image\//i.test(item.type || "")) {
            const file = item.getAsFile();
            if (file) return file;
        }
    }
    return null;
}

function lhlInsertImageFileV47(file, toastMessage) {
    if (!file) return false;
    const reader = new FileReader();
    reader.onload = function(ev) {
        lhlInsertIntoEditorV45(lhlImageHtmlFromDataUrlV45(ev.target.result));
        showToast(toastMessage || "🖼️ Đã dán ảnh chất lượng cao!");
    };
    reader.readAsDataURL(file);
    return true;
}

async function lhlReadClipboardImageDataV47() {
    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.get_clipboard_image_data) {
            const imgRes = await window.pywebview.api.get_clipboard_image_data();
            if (imgRes && imgRes.ok && imgRes.data_url) return imgRes.data_url;
        }
    } catch (e) {
        console.log("Không đọc được ảnh clipboard V47:", e);
    }
    return "";
}

async function lhlReadClipboardHtmlDataV47() {
    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.get_clipboard_html_data) {
            const htmlRes = await window.pywebview.api.get_clipboard_html_data();
            if (htmlRes && htmlRes.ok && htmlRes.html) return htmlRes.html;
        }
    } catch (e) {
        console.log("Không đọc được HTML clipboard V47:", e);
    }
    return "";
}

// Override lại hàm Paste: ảnh riêng dùng image clipboard trước, text+hình dùng HTML.
async function lhlPasteFromClipboardApiV47() {
    const html = await lhlReadClipboardHtmlDataV47();
    const htmlHasText = lhlHtmlHasMeaningfulTextV47(html);
    const htmlHasImage = lhlHtmlHasImageV47(html);

    // Nếu HTML không có chữ thật, nhiều khả năng Thầy copy riêng 1 hình từ Word.
    // Khi đó ảnh trực tiếp từ clipboard thường nét hơn ảnh preview trong HTML.
    if (!htmlHasText) {
        const directImage = await lhlReadClipboardImageDataV47();
        if (directImage) {
            lhlInsertIntoEditorV45(lhlImageHtmlFromDataUrlV45(directImage));
            showToast("🖼️ Đã dán ảnh chất lượng cao từ Clipboard!");
            return true;
        }
    }

    // Nếu có text hoặc text+hình thì giữ HTML để không mất nội dung Word.
    if (html) {
        const prepared = lhlPrepareClipboardHtmlV45(html);
        if (prepared) {
            lhlInsertIntoEditorV45(prepared);
            showToast(htmlHasImage ? "📋🖼️ Đã dán nội dung Word gồm text/hình!" : "📋 Đã dán nội dung Word!");
            return true;
        }
    }

    // Fallback ảnh trực tiếp.
    const directImage = await lhlReadClipboardImageDataV47();
    if (directImage) {
        lhlInsertIntoEditorV45(lhlImageHtmlFromDataUrlV45(directImage));
        showToast("🖼️ Đã dán ảnh từ Clipboard!");
        return true;
    }

    // Fallback text.
    try {
        const text = await lhlReadClipboardTextV45();
        if (text) {
            lhlInsertIntoEditorV45(text);
            showToast("📋 Đã dán văn bản!");
            return true;
        }
    } catch (e) { console.log("Không đọc được text clipboard V47:", e); }

    showToast("⚠️ Clipboard đang trống hoặc chưa cấp quyền dán ạ!");
    return false;
}

// Đè hàm cũ để nút Paste gọi bản V47.
async function lhlPasteFromClipboardApiV45() {
    return await lhlPasteFromClipboardApiV47();
}

// Cài handler Ctrl+V V47 ở capture phase và chặn handler V45 cũ bằng stopImmediatePropagation.
if (!window.__lhlV47PasteQualityHandlerInstalled) {
    window.__lhlV47PasteQualityHandlerInstalled = true;
    document.addEventListener('paste', async function(e) {
        if (e.__lhlV47Handled) return;
        const editor = document.getElementById('editor');
        if (!activeTabId || !editor || editor.disabled) return;
        if (document.activeElement !== editor) return;

        e.preventDefault();
        e.stopImmediatePropagation();

        const dt = e.clipboardData || window.clipboardData;
        if (dt) {
            try {
                const html = dt.getData && dt.getData('text/html');
                const htmlHasText = lhlHtmlHasMeaningfulTextV47(html);
                const htmlHasImage = lhlHtmlHasImageV47(html);
                const imageFile = lhlClipboardItemsImageFileV47(dt);

                // Ctrl+V copy riêng hình: lấy file ảnh trực tiếp trước để nét hơn.
                if (!htmlHasText && imageFile) {
                    lhlInsertImageFileV47(imageFile, "🖼️ Đã dán ảnh chất lượng cao bằng Ctrl+V!");
                    return;
                }

                // Ctrl+V text+hình hoặc HTML có chữ: giữ HTML để không mất text/công thức.
                if (html) {
                    const prepared = lhlPrepareClipboardHtmlV45(html);
                    if (prepared) {
                        lhlInsertIntoEditorV45(prepared);
                        showToast(htmlHasImage ? "📋🖼️ Đã dán nội dung HTML gồm text/hình!" : "📋 Đã dán nội dung HTML!");
                        return;
                    }
                }

                if (imageFile) {
                    lhlInsertImageFileV47(imageFile, "🖼️ Đã dán ảnh bằng Ctrl+V!");
                    return;
                }

                const text = dt.getData && dt.getData('text/plain');
                if (text) {
                    lhlInsertIntoEditorV45(text);
                    showToast("📋 Đã dán text bằng Ctrl+V!");
                    return;
                }
            } catch(err) {
                console.log("Paste V47 lỗi, thử API:", err);
            }
        }

        await lhlPasteFromClipboardApiV47();
    }, true);
}



// ============================================================
// V49 FIX PASTE FINAL:
// - Copy file ảnh từ Explorer: nút Paste/Ctrl+V đều đọc bytes gốc qua Python nếu có.
// - Copy riêng ảnh trong Word: ưu tiên ảnh trực tiếp để nét hơn HTML preview.
// - Copy đoạn Word gồm text + hình: giữ HTML để không mất chữ/công thức; ảnh được đổi sang HINH_ANH_n.
// - Chặn các handler cũ để Ctrl+V không bị dán trùng 2 ảnh.
// ============================================================
window.__lhlV49UnifiedPasteHandlerInstalled = true;

function lhlV49SafeDataTransferHasMeaningfulHtml(dt) {
    try {
        const html = dt && dt.getData ? (dt.getData('text/html') || '') : '';
        return {
            html: html,
            hasText: lhlHtmlHasMeaningfulTextV47(html),
            hasImage: lhlHtmlHasImageV47(html)
        };
    } catch(e) {
        return { html: '', hasText: false, hasImage: false };
    }
}

function lhlV49DataTransferImageFile(dt) {
    return (typeof lhlClipboardItemsImageFileV47 === 'function') ? lhlClipboardItemsImageFileV47(dt) : null;
}

async function lhlV49ReadPythonImageData() {
    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.get_clipboard_image_data) {
            const imgRes = await window.pywebview.api.get_clipboard_image_data();
            if (imgRes && imgRes.ok && imgRes.data_url && /^data:image\//i.test(String(imgRes.data_url))) {
                return imgRes.data_url;
            }
        }
    } catch(e) {
        console.log('V49 không đọc được ảnh qua Python:', e);
    }
    return '';
}

function lhlV49InsertDataUrl(dataUrl, toastMessage) {
    const html = lhlImageHtmlFromDataUrlV45(dataUrl);
    if (!html) return false;
    const ok = lhlInsertIntoEditorV45(html);
    if (ok) {
        showToast(toastMessage || '🖼️ Đã dán ảnh!');
        try { updatePreview(); } catch(e) {}
    }
    return ok;
}

async function lhlV49InsertFileImage(file, toastMessage) {
    if (!file) return false;
    return await new Promise(resolve => {
        try {
            const reader = new FileReader();
            reader.onload = function(ev) {
                resolve(lhlV49InsertDataUrl(ev.target.result, toastMessage || '🖼️ Đã dán ảnh bằng Ctrl+V!'));
            };
            reader.onerror = function() { resolve(false); };
            reader.readAsDataURL(file);
        } catch(e) {
            console.log('V49 FileReader lỗi:', e);
            resolve(false);
        }
    });
}

async function lhlV49PasteUnified(dt, sourceName) {
    const info = lhlV49SafeDataTransferHasMeaningfulHtml(dt);
    const imageFile = lhlV49DataTransferImageFile(dt);

    // 1) Ảnh riêng / file ảnh riêng: ưu tiên Python API để giữ nguyên bytes file gốc từ Explorer.
    // Với ảnh copy riêng trong Word, HTML thường không có chữ thật, nên cũng ưu tiên ảnh trực tiếp.
    if (!info.hasText) {
        const pyImage = await lhlV49ReadPythonImageData();
        if (pyImage && lhlV49InsertDataUrl(pyImage, sourceName === 'button' ? '🖼️ Đã dán ảnh chất lượng cao!' : '🖼️ Đã dán ảnh chất lượng cao bằng Ctrl+V!')) return true;
        if (imageFile && await lhlV49InsertFileImage(imageFile, sourceName === 'button' ? '🖼️ Đã dán ảnh!' : '🖼️ Đã dán ảnh bằng Ctrl+V!')) return true;
    }

    // 2) HTML có text hoặc text+hình: giữ HTML để không mất nội dung Word.
    let html = info.html;
    if (!html && sourceName === 'button') {
        html = await lhlReadClipboardHtmlDataV47();
        info.hasImage = lhlHtmlHasImageV47(html);
    }
    if (html) {
        const prepared = lhlPrepareClipboardHtmlV45(html);
        if (prepared) {
            lhlInsertIntoEditorV45(prepared);
            showToast(info.hasImage ? '📋🖼️ Đã dán nội dung Word gồm text/hình!' : '📋 Đã dán nội dung Word!');
            try { updatePreview(); } catch(e) {}
            return true;
        }
    }

    // 3) Fallback ảnh nếu chưa dán được ở trên.
    const pyImage2 = await lhlV49ReadPythonImageData();
    if (pyImage2 && lhlV49InsertDataUrl(pyImage2, '🖼️ Đã dán ảnh từ Clipboard!')) return true;
    if (imageFile && await lhlV49InsertFileImage(imageFile, '🖼️ Đã dán ảnh bằng Ctrl+V!')) return true;

    // 4) Fallback text.
    let text = '';
    try {
        text = dt && dt.getData ? (dt.getData('text/plain') || '') : '';
    } catch(e) {}
    if (!text) {
        try { text = await lhlReadClipboardTextV45(); } catch(e) {}
    }
    if (text) {
        lhlInsertIntoEditorV45(text);
        showToast('📋 Đã dán văn bản!');
        try { updatePreview(); } catch(e) {}
        return true;
    }

    showToast('⚠️ Clipboard đang trống hoặc chưa cấp quyền dán ạ!');
    return false;
}

// Nút Paste gọi cùng một luồng xử lý với Ctrl+V.
pasteText = async function() {
    const active = document.activeElement;
    const editor = document.getElementById('editor');

    function isOtherInput(el) {
        if (!el || el === editor) return false;
        const tag = (el.tagName || '').toUpperCase();
        if (tag === 'TEXTAREA') return true;
        if (tag === 'INPUT') {
            const type = (el.type || 'text').toLowerCase();
            return ['text','search','url','tel','email','number','password'].includes(type);
        }
        return !!el.isContentEditable;
    }

    if (isOtherInput(active)) {
        try {
            const text = await lhlReadClipboardTextV45();
            if (!text) { showToast('⚠️ Clipboard text đang trống ạ!'); return; }
            const value = active.value || '';
            const start = (typeof active.selectionStart === 'number') ? active.selectionStart : value.length;
            const end = (typeof active.selectionEnd === 'number') ? active.selectionEnd : value.length;
            active.value = value.substring(0, start) + text + value.substring(end);
            if (typeof active.setSelectionRange === 'function') active.setSelectionRange(start + text.length, start + text.length);
            active.dispatchEvent(new Event('input', { bubbles: true }));
            active.focus();
            showToast('📋 Đã dán vào ô đang chọn!');
            return;
        } catch(e) {}
    }

    await lhlV49PasteUnified(null, 'button');
};

// Đè hàm API cũ để các nút/shortcut cũ nếu còn gọi vẫn đi qua V49.
lhlPasteFromClipboardApiV45 = async function() {
    return await lhlV49PasteUnified(null, 'button');
};

// Ctrl+V: dùng một handler thống nhất, chặn handler target/bubble cũ.
if (!window.__lhlV49CtrlVPasteListenerInstalled) {
    window.__lhlV49CtrlVPasteListenerInstalled = true;
    document.addEventListener('paste', async function(e) {
        const editor = document.getElementById('editor');
        if (!activeTabId || !editor || editor.disabled) return;
        if (document.activeElement !== editor) return;

        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        await lhlV49PasteUnified(e.clipboardData || window.clipboardData, 'ctrlv');
    }, true);
}


// ============================================================
// V50 FIX PASTE ỔN ĐỊNH HƠN:
// - Nút Paste đọc được file ảnh copy từ thư mục/Explorer nhờ Python CF_HDROP.
// - Copy riêng ảnh Word: so sánh ảnh trực tiếp và ảnh trong HTML Word, chọn bản có dữ liệu lớn hơn.
// - Paste text+hình bằng nút Paste nhiều lần: sau khi chèn thì đồng bộ tab + cập nhật preview ngay và trễ.
// ============================================================
function lhlV50DataUrlBytes(dataUrl) {
    dataUrl = String(dataUrl || '');
    const i = dataUrl.indexOf('base64,');
    if (i < 0) return 0;
    return dataUrl.length - i - 7;
}

function lhlV50LargestDataImageFromHtml(html) {
    let best = '';
    const s = String(html || '');
    const re = /data:image\/[a-zA-Z0-9.+-]+;base64,[^"'\s<>]+/gi;
    let m;
    while ((m = re.exec(s)) !== null) {
        const x = m[0];
        if (lhlV50DataUrlBytes(x) > lhlV50DataUrlBytes(best)) best = x;
    }
    return best;
}

function lhlV50SyncAndPreviewNow() {
    try {
        const editor = document.getElementById('editor');
        if (editor && activeTabId) {
            const tab = tabs.find(t => t.id === activeTabId);
            if (tab) {
                tab.content = editor.value;
                tab.imageDictionary = {...imageDictionary};
                tab.imageIndex = imageIndex;
                tab.isDirty = true;
            }
        }
    } catch(e) {}
    try { updatePreview(); } catch(e) {}
    setTimeout(function(){ try { updatePreview(); } catch(e) {} }, 80);
    setTimeout(function(){ try { updatePreview(); } catch(e) {} }, 250);
}

function lhlV50InsertPrepared(prepared, toastMessage) {
    if (!prepared) return false;
    const ok = lhlInsertIntoEditorV45(prepared);
    if (ok) {
        showToast(toastMessage || '📋 Đã dán nội dung!');
        lhlV50SyncAndPreviewNow();
    }
    return ok;
}

// Ghi đè hàm insert ảnh của V49 để luôn sync preview chắc hơn.
lhlV49InsertDataUrl = function(dataUrl, toastMessage) {
    const html = lhlImageHtmlFromDataUrlV45(dataUrl);
    if (!html) return false;
    const ok = lhlInsertIntoEditorV45(html);
    if (ok) {
        showToast(toastMessage || '🖼️ Đã dán ảnh!');
        lhlV50SyncAndPreviewNow();
    }
    return ok;
};

// Ghi đè luồng paste chính. Listener Ctrl+V V49 cũ vẫn gọi tên hàm này nên sẽ tự dùng bản V50.
lhlV49PasteUnified = async function(dt, sourceName) {
    let info = lhlV49SafeDataTransferHasMeaningfulHtml(dt);
    let html = info.html || '';

    // Nút Paste không có DataTransfer, nên đọc HTML bằng Python ngay từ đầu.
    if (!html && sourceName === 'button') {
        html = await lhlReadClipboardHtmlDataV47();
        info = {
            html: html,
            hasText: lhlHtmlHasMeaningfulTextV47(html),
            hasImage: lhlHtmlHasImageV47(html)
        };
    }

    const imageFile = lhlV49DataTransferImageFile(dt);

    // 1) Clipboard chỉ là ảnh/file ảnh riêng.
    // - File ảnh từ thư mục: Python trả bytes gốc qua CF_HDROP.
    // - Ảnh riêng từ Word: nếu HTML Word có data ảnh lớn hơn bitmap trực tiếp thì dùng HTML/data đó.
    if (!info.hasText) {
        const pyImage = await lhlV49ReadPythonImageData();
        const htmlImage = lhlV50LargestDataImageFromHtml(html);

        if (htmlImage || pyImage) {
            const chosen = (lhlV50DataUrlBytes(htmlImage) > lhlV50DataUrlBytes(pyImage) * 1.15) ? htmlImage : pyImage;
            if (chosen && lhlV49InsertDataUrl(chosen, sourceName === 'button' ? '🖼️ Đã dán ảnh chất lượng cao!' : '🖼️ Đã dán ảnh chất lượng cao bằng Ctrl+V!')) return true;
        }

        if (imageFile && await lhlV49InsertFileImage(imageFile, sourceName === 'button' ? '🖼️ Đã dán ảnh!' : '🖼️ Đã dán ảnh bằng Ctrl+V!')) {
            lhlV50SyncAndPreviewNow();
            return true;
        }
    }

    // 2) HTML có text hoặc text+hình: luôn giữ HTML để không mất chữ/công thức/hình.
    if (html) {
        const prepared = lhlPrepareClipboardHtmlV45(html);
        if (prepared) {
            return lhlV50InsertPrepared(prepared, info.hasImage ? '📋🖼️ Đã dán nội dung Word gồm text/hình!' : '📋 Đã dán nội dung Word!');
        }
    }

    // 3) Fallback ảnh.
    const pyImage2 = await lhlV49ReadPythonImageData();
    if (pyImage2 && lhlV49InsertDataUrl(pyImage2, '🖼️ Đã dán ảnh từ Clipboard!')) return true;
    if (imageFile && await lhlV49InsertFileImage(imageFile, '🖼️ Đã dán ảnh bằng Ctrl+V!')) {
        lhlV50SyncAndPreviewNow();
        return true;
    }

    // 4) Fallback text.
    let text = '';
    try { text = dt && dt.getData ? (dt.getData('text/plain') || '') : ''; } catch(e) {}
    if (!text) {
        try { text = await lhlReadClipboardTextV45(); } catch(e) {}
    }
    if (text) {
        return lhlV50InsertPrepared(text, '📋 Đã dán văn bản!');
    }

    showToast('⚠️ Clipboard đang trống hoặc chưa cấp quyền dán ạ!');
    return false;
};

// Nút Paste V50: vẫn dùng chung luồng với Ctrl+V, nhưng giữ editor/cursor chắc hơn khi bấm nút nhiều lần.
pasteText = async function() {
    if (!activeTabId) { showToast('⚠️ Thầy vui lòng mở một Tab để dán ạ!'); return; }
    const active = document.activeElement;
    const editor = document.getElementById('editor');

    function isOtherInput(el) {
        if (!el || el === editor) return false;
        const tag = (el.tagName || '').toUpperCase();
        if (tag === 'TEXTAREA') return true;
        if (tag === 'INPUT') {
            const type = (el.type || 'text').toLowerCase();
            return ['text','search','url','tel','email','number','password'].includes(type);
        }
        return !!el.isContentEditable;
    }

    if (isOtherInput(active)) {
        try {
            const text = await lhlReadClipboardTextV45();
            if (!text) { showToast('⚠️ Clipboard text đang trống ạ!'); return; }
            const value = active.value || '';
            const start = (typeof active.selectionStart === 'number') ? active.selectionStart : value.length;
            const end = (typeof active.selectionEnd === 'number') ? active.selectionEnd : value.length;
            active.value = value.substring(0, start) + text + value.substring(end);
            if (typeof active.setSelectionRange === 'function') active.setSelectionRange(start + text.length, start + text.length);
            active.dispatchEvent(new Event('input', { bubbles: true }));
            active.focus();
            showToast('📋 Đã dán vào ô đang chọn!');
            return;
        } catch(e) {}
    }

    if (editor && !editor.disabled) {
        editor.focus();
        try {
            // Sau mỗi lần paste, cursor đã được executeInsertText đưa về cuối đoạn vừa dán.
            // Dòng này giúp nút Paste không làm mất vị trí cursor khi bấm liên tục.
            editor.setSelectionRange(savedStart || editor.selectionStart || editor.value.length, savedEnd || editor.selectionEnd || editor.value.length);
        } catch(e) {}
    }

    await lhlV49PasteUnified(null, 'button');
};

lhlPasteFromClipboardApiV45 = async function() {
    return await lhlV49PasteUnified(null, 'button');
};


// ============================================================
// V51 FIX NÚT PASTE WORD TEXT + HÌNH NHIỀU LẦN:
// Một số HTML clipboard của Word khi đọc qua nút Paste có tag/style/comment
// phức tạp. Lần dán thứ 2 có thể vẫn vào editor nhưng preview bị nuốt/ẩn
// do fragment chưa được chuẩn hóa. V51 chuẩn hóa fragment bằng template,
// bọc mỗi lần dán trong một khối độc lập và ép preview refresh sau khi DOM ổn định.
// ============================================================
function lhlV51CleanWordHtmlFragment(html) {
    let s = String(html || '');
    // Bỏ những phần không nên xuất hiện lặp lại trong innerHTML preview.
    s = s.replace(/<\/?html\b[^>]*>/gi, '');
    s = s.replace(/<\/?body\b[^>]*>/gi, '');
    s = s.replace(/<head\b[\s\S]*?<\/head>/gi, '');
    s = s.replace(/<style\b[\s\S]*?<\/style>/gi, '');
    s = s.replace(/<script\b[\s\S]*?<\/script>/gi, '');
    s = s.replace(/<meta\b[^>]*>/gi, '');
    s = s.replace(/<link\b[^>]*>/gi, '');
    s = s.replace(/<!--\s*StartFragment\s*-->/gi, '');
    s = s.replace(/<!--\s*EndFragment\s*-->/gi, '');
    // Dọn conditional/comment Word còn sót lại.
    s = s.replace(/<!--\[if[\s\S]*?<!\[endif\]-->/gi, '');

    // Cho trình duyệt tự cân bằng tag để lần dán sau không bị fragment trước nuốt mất.
    try {
        const tpl = document.createElement('template');
        tpl.innerHTML = s;
        s = tpl.innerHTML;
    } catch(e) {}

    s = s.trim();
    if (!s) return '';
    return '\n<div class="lhl-word-paste-fragment" style="display:block; clear:both; width:100%;">\n' + s + '\n</div>\n';
}

// Bọc lại hàm chuẩn bị HTML: chỉ áp dụng thêm bước normalize sau khi V45/V46 đã đổi ảnh sang HINH_ANH_n.
if (typeof lhlPrepareClipboardHtmlV45 === 'function' && !window.__lhlV51WrappedPrepareClipboardHtml) {
    window.__lhlV51WrappedPrepareClipboardHtml = true;
    const __oldPrepareClipboardHtmlV51 = lhlPrepareClipboardHtmlV45;
    lhlPrepareClipboardHtmlV45 = function(html) {
        const prepared = __oldPrepareClipboardHtmlV51.call(this, html);
        // Chỉ bọc khi là HTML Word/text+hình. Ảnh riêng đã đi nhánh ảnh riêng nên không ảnh hưởng.
        if (/<img\b|HINH_ANH_\d+|<p\b|<div\b|<table\b|<br\b/i.test(String(prepared || ''))) {
            return lhlV51CleanWordHtmlFragment(prepared);
        }
        return prepared;
    };
}

function lhlV51ForcePreviewAfterPaste() {
    try { lhlV50SyncAndPreviewNow(); } catch(e) { try { updatePreview(); } catch(_) {} }
    [60, 150, 350, 700].forEach(function(ms) {
        setTimeout(function(){
            try { lhlV50SyncAndPreviewNow(); } catch(e) { try { updatePreview(); } catch(_) {} }
        }, ms);
    });
}

// Ghi đè insert prepared để mỗi lần bấm Paste đều là một fragment độc lập và preview chắc chắn refresh.
lhlV50InsertPrepared = function(prepared, toastMessage) {
    if (!prepared) return false;
    const ok = lhlInsertIntoEditorV45(prepared);
    if (ok) {
        showToast(toastMessage || '📋 Đã dán nội dung!');
        lhlV51ForcePreviewAfterPaste();
    }
    return ok;
};

// Nút Paste V51: không đặt lại selection bằng savedStart cũ nếu editor đang mất focus do bấm nút.
// Cứ giữ vị trí cursor hiện tại của textarea, nếu không có thì dán cuối văn bản.
pasteText = async function() {
    if (!activeTabId) { showToast('⚠️ Thầy vui lòng mở một Tab để dán ạ!'); return; }
    const active = document.activeElement;
    const editor = document.getElementById('editor');

    function isOtherInput(el) {
        if (!el || el === editor) return false;
        const tag = (el.tagName || '').toUpperCase();
        if (tag === 'TEXTAREA') return true;
        if (tag === 'INPUT') {
            const type = (el.type || 'text').toLowerCase();
            return ['text','search','url','tel','email','number','password'].includes(type);
        }
        return !!el.isContentEditable;
    }

    if (isOtherInput(active)) {
        try {
            const text = await lhlReadClipboardTextV45();
            if (!text) { showToast('⚠️ Clipboard text đang trống ạ!'); return; }
            const value = active.value || '';
            const start = (typeof active.selectionStart === 'number') ? active.selectionStart : value.length;
            const end = (typeof active.selectionEnd === 'number') ? active.selectionEnd : value.length;
            active.value = value.substring(0, start) + text + value.substring(end);
            if (typeof active.setSelectionRange === 'function') active.setSelectionRange(start + text.length, start + text.length);
            active.dispatchEvent(new Event('input', { bubbles: true }));
            active.focus();
            showToast('📋 Đã dán vào ô đang chọn!');
            return;
        } catch(e) {}
    }

    if (editor && !editor.disabled) {
        editor.focus();
        try {
            let start = (typeof editor.selectionStart === 'number') ? editor.selectionStart : editor.value.length;
            let end = (typeof editor.selectionEnd === 'number') ? editor.selectionEnd : start;
            if (start < 0 || start > editor.value.length) start = editor.value.length;
            if (end < 0 || end > editor.value.length) end = start;
            savedStart = start;
            savedEnd = end;
            editor.setSelectionRange(start, end);
        } catch(e) {}
    }

    const ok = await lhlV49PasteUnified(null, 'button');
    if (ok) lhlV51ForcePreviewAfterPaste();
};

lhlPasteFromClipboardApiV45 = async function() {
    return await lhlV49PasteUnified(null, 'button');
};


// ============================================================
// V54 FIX: Đếm câu theo cấu trúc mạnh hơn và không để tiêu đề PHẦN II
// làm nhiễu câu cuối của PHẦN I. Đồng thời loại <br> dư sau tiêu đề phần.
// ============================================================
function lhlFindAllPartTitlePositionsV54(content) {
    var arr = [];
    var re = /<div\b[^>]*class=["'][^"']*exam-part-box[^"']*["'][^>]*>[\s\S]*?<\/div>|PH(?:Ầ|Â|A|\.)?N\s*(?:I{1,3}|1|2|3)\b/gi;
    var m;
    while ((m = re.exec(content || '')) !== null) arr.push(m.index);
    return arr.sort(function(a,b){return a-b;});
}

function lhlFindQuestionStartsV54(content) {
    var starts = [];
    // Chỉ nhận "Câu n" thật sự: đầu dòng, sau thẻ block, hoặc sau thẻ định dạng; không bắt các chữ "câu 1 đến câu 12" trong tiêu đề phần.
    var re = /(?:^|[\n\r]|<br\s*\/?\s*>|<\/(?:p|div|li|tr|td|h[1-6])>|<(?:p|div|li|tr|td|h[1-6])\b[^>]*>|<\/?(?:b|strong|span|em|i|u|font)\b[^>]*>\s*)\s*(?:&nbsp;|\s|<\/?(?:b|strong|span|em|i|u|font)\b[^>]*>)*Câu\s*\d+\s*(?:[.:)]|<\/?(?:b|strong|span|em|i|u|font)\b[^>]*>|&nbsp;|\s)/gi;
    var m;
    while ((m = re.exec(content || '')) !== null) {
        var txt = m[0];
        var rel = txt.search(/Câu\s*\d+/i);
        if (rel >= 0) starts.push(m.index + rel);
    }
    // Khử trùng vị trí gần nhau do nhiều thẻ bao quanh cùng một Câu.
    var out = [];
    starts.sort(function(a,b){return a-b;}).forEach(function(x){
        if (!out.length || Math.abs(x - out[out.length-1]) > 3) out.push(x);
    });
    return out;
}

function lhlClassifyQuestionBlockV54(block, fallbackPart) {
    var raw = String(block || '');
    // Cắt phần tiêu đề PHẦN nếu vô tình dính cuối block, tránh câu 12 TN bị đẩy sang Đ/S vì tiêu đề Phần II có a),b),c),d).
    raw = raw.replace(/<div\b[^>]*class=["'][^"']*exam-part-box[^"']*["'][^>]*>[\s\S]*$/i, '');
    raw = raw.replace(/PH(?:Ầ|Â|A|\.)?N\s*(?:I{1,3}|1|2|3)\b[\s\S]*$/i, '');
    var plain = lhlStripHtmlForStatsV53(raw);

    var hasChoiceClass = /class=["'][^"']*\bchoices\b[^"']*\bcols-[124]\b[^"']*["']/i.test(raw);
    var hasTfClass = /class=["'][^"']*\bchoices\b[^"']*\bcols-1\b[^"']*["']/i.test(raw) || /\btf-row\b|\btf-text\b|choiceTF/i.test(raw);

    var mcCount = 0;
    ['A','B','C','D'].forEach(function(ch) {
        var re = new RegExp('(^|\\s|>|&nbsp;)' + ch + '\\s*[\\.)]', '');
        if (re.test(plain) || new RegExp('>\\s*' + ch + '\\s*[\\.)]', '').test(raw)) mcCount++;
    });

    var tfCount = 0;
    ['a','b','c','d'].forEach(function(ch) {
        var re = new RegExp('(^|\\s|>|&nbsp;)' + ch + '\\s*\\)', 'i');
        if (re.test(plain) || new RegExp('>\\s*' + ch + '\\s*\\)', 'i').test(raw)) tfCount++;
    });

    // Ưu tiên Phần II khi có cấu trúc đúng/sai rõ. Nhưng nếu có đủ A/B/C/D thì là TN.
    if (mcCount >= 3 || (/\\choice\b/i.test(raw) && !/choiceTF/i.test(raw))) return 'I';
    if (hasTfClass || tfCount >= 3 || /đúng\s*hoặc\s*sai|chọn\s*đúng\s*hoặc\s*sai|xét\s+tính\s+đúng\s+sai/i.test(plain)) return 'II';
    if (hasChoiceClass && mcCount >= 2) return 'I';
    if (mcCount >= 2) return 'I';
    if (/đáp\s*(?:số|án)|trả\s*lời\s*ngắn|short-answer|input-short-ans/i.test(raw + ' ' + plain)) return 'III';
    return fallbackPart || 'III';
}

updateQuestionStats = function() {
    var statsDiv = document.getElementById('q-stats');
    if (!statsDiv) return;
    if (!activeTabId) {
        statsDiv.innerHTML = `<span class="stat-badge stat-total">Tổng: 0</span><span class="stat-badge stat-tn">TN: 0</span><span class="stat-badge stat-ds">Đ/S: 0</span><span class="stat-badge stat-tln">TLN: 0</span>`;
        return;
    }
    var editor = document.getElementById('editor');
    var content = editor ? (editor.value || '') : '';
    var p1 = lhlFindPartIndexV52(content, 1);
    var p2 = lhlFindPartIndexV52(content, 2);
    var p3 = lhlFindPartIndexV52(content, 3);
    var hasAnyPartTitle = (p1 !== -1 || p2 !== -1 || p3 !== -1);
    var partPositions = lhlFindAllPartTitlePositionsV54(content);
    var qStarts = lhlFindQuestionStartsV54(content);
    var counts = { 'I': 0, 'II': 0, 'III': 0, 'ALL': 0 };

    for (var i = 0; i < qStarts.length; i++) {
        var start = qStarts[i];
        var nextQ = (i + 1 < qStarts.length) ? qStarts[i + 1] : content.length;
        var nextPart = content.length;
        for (var j = 0; j < partPositions.length; j++) {
            if (partPositions[j] > start) { nextPart = partPositions[j]; break; }
        }
        var end = Math.min(nextQ, nextPart);
        var block = content.slice(start, end);
        if (!/Câu\s*\d+/i.test(block)) continue;
        var fallback = hasAnyPartTitle ? ((p3 !== -1 && start > p3) ? 'III' : ((p2 !== -1 && start > p2) ? 'II' : 'I')) : null;
        var part = lhlClassifyQuestionBlockV54(block, fallback);
        counts.ALL++;
        counts[part] = (counts[part] || 0) + 1;
    }
    statsDiv.innerHTML = `<span class="stat-badge stat-total" title="Tổng số câu của file hiện hành">Tổng: ${counts.ALL}</span><span class="stat-badge stat-tn" title="Phần I - Trắc nghiệm nhiều lựa chọn">TN: ${counts.I}</span><span class="stat-badge stat-ds" title="Phần II - Trắc nghiệm Đúng/Sai">Đ/S: ${counts.II}</span><span class="stat-badge stat-tln" title="Phần III - Trả lời ngắn">TLN: ${counts.III}</span>`;
};

// Ghi đè mẫu tiêu đề phần: không kèm <br> sau Phần I/III nữa.
if (typeof getExamPartTemplates === 'function') {
    getExamPartTemplates = function() {
        return {
            p1: `<div class="exam-part-box">PHẦN I. Thí sinh trả lời từ câu 1 đến câu 12 . Mỗi câu hỏi thí sinh chỉ chọn một phương án.</div>`,
            p2: `<div class="exam-part-box exam-part-box-wide">PHẦN II. Thí sinh trả lời từ câu 1 đến câu 4 . Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.</div>`,
            p3: `<div class="exam-part-box">PHẦN III. Thí sinh trả lời từ câu 1 đến câu 6.</div>`,
            end: `<div class="exam-end-line">---------- <strong>HẾT</strong> ----------</div>\n<div class="exam-final-note"><i>Thí sinh không được sử dụng tài liệu; giám thị coi thi không giải thích gì thêm.</i></div>`
        };
    };
}


// ============================================================
// V56 FIX: PHẦN III - không để dòng "Đáp số" dính với "Câu" kế tiếp.
// Áp dụng khi mở file, bấm Tiêu đề, biên dịch, in PDF/trộn đề.
// ============================================================
function lhlFixPart3AnswerGlueV56(html) {
    let s = String(html || '');

    // 1) Nếu sau thẻ <b>/<strong>Đáp số...</b> là nhãn Câu kế tiếp thì ép xuống dòng.
    s = s.replace(
        /(<(?:b|strong)\b[^>]*>\s*Đáp\s*(?:án|s[ốôo])\s*[:：][\s\S]*?<\/(?:b|strong)>)(\s*)(?=(?:<[^>]+>\s*)*Câu\s*\d+\s*[.:]?)/gi,
        '$1\n<br>\n'
    );

    // 2) Trường hợp đáp số dạng text thường: "Đáp số: 2000 Câu 5.".
    // Chỉ cắt khi sau Đáp số có nhãn Câu thật; không đụng các câu văn bình thường.
    s = s.replace(
        /(Đáp\s*(?:án|s[ốôo])\s*[:：]\s*[^\n<]{1,80}?)(\s+)((?:<b[^>]*>\s*)?Câu\s*\d+\s*[.:]?)/gi,
        function(m, ans, sp, cau) {
            // Nếu đáp số đã có <br> hoặc xuống dòng sát trước Câu thì giữ nguyên.
            if (/<br\s*\/?>\s*$/i.test(ans) || /\n\s*$/.test(ans)) return m;
            return ans.replace(/\s+$/,'') + '\n<br>\n' + cau;
        }
    );

    // 3) Nếu sau short-answer/đáp số là thẻ <b> Câu ... </b>, ép thành khối mới.
    s = s.replace(
        /(<br\s*\/?>\s*){2,}/gi,
        '<br>\n'
    );
    return s;
}

if (typeof processCode === 'function' && !window.__lhlV56WrappedProcessCode) {
    window.__lhlV56WrappedProcessCode = true;
    const __oldProcessCodeV56 = processCode;
    processCode = function(rawCode) {
        return lhlFixPart3AnswerGlueV56(__oldProcessCodeV56.apply(this, arguments));
    };
}

// Khi nhấn nút Tiêu đề/Chuẩn hóa hoặc khi mở file làm editor có sẵn lỗi dính dòng,
// dọn nhẹ trong editor để lần lưu sau cũng sạch. Không động vào <br> tự gõ bình thường.
function lhlFixEditorAnswerGlueV56() {
    try {
        const editor = document.getElementById('editor');
        if (!editor || !editor.value) return;
        const fixed = lhlFixPart3AnswerGlueV56(editor.value);
        if (fixed !== editor.value) {
            const ss = editor.selectionStart || 0, se = editor.selectionEnd || 0;
            editor.value = fixed;
            try { editor.setSelectionRange(Math.min(ss, fixed.length), Math.min(se, fixed.length)); } catch(e) {}
            if (activeTabId) {
                const tab = (tabs || []).find(t => t.id === activeTabId);
                if (tab) { tab.content = fixed; tab.isDirty = true; }
            }
        }
    } catch(e) {}
}

if (typeof updatePreview === 'function' && !window.__lhlV56WrappedUpdatePreview) {
    window.__lhlV56WrappedUpdatePreview = true;
    const __oldUpdatePreviewV56 = updatePreview;
    updatePreview = function() {
        lhlFixEditorAnswerGlueV56();
        return __oldUpdatePreviewV56.apply(this, arguments);
    };
}



// ============================================================
// V61 - CHUYỂN WORD CHO CÂU ĐÚNG/SAI a), b), c), d)
// Mục tiêu: bất kỳ câu Đ/S Word-paste nào cũng đưa về code sạch,
// mặc định choices cols-1. Hỗ trợ cả 1 câu và nhiều câu trong 1 file.
// ============================================================
function lhlV61StripWordJunk(input) {
    let s = String(input || '');
    try { s = lhlDecodeHtmlEntitiesV57(s); } catch(e) {}
    s = s.normalize ? s.normalize('NFC') : s;
    s = s.replace(/\r\n?/g, '\n').replace(/\u00a0/g, ' ');

    s = s.replace(/<!--\s*\[if[\s\S]*?<!\s*\[endif\]\s*-->/gi, '');
    s = s.replace(/<!--\s*\[if[\s\S]*?-->/gi, '');
    s = s.replace(/<!--\s*\[endif\]\s*-->/gi, '');
    s = s.replace(/<!--[\s\S]*?-->/g, '');

    s = s.replace(/<a\b[^>]*\bname\s*=\s*["'][^"']*["'][^>]*>/gi, '');
    s = s.replace(/<a\b[^>]*>/gi, '');
    s = s.replace(/<\/a>/gi, '');

    s = s.replace(/<\/?strong\b[^>]*>/gi, function(m){ return /^<\//.test(m) ? '</b>' : '<b>'; });
    s = s.replace(/<b\b[^>]*>/gi, '<b>').replace(/<\/b>/gi, '</b>');
    s = s.replace(/<u\b[^>]*>/gi, '<u>').replace(/<\/u>/gi, '</u>');
    s = s.replace(/<span\b[^>]*>/gi, '<span>').replace(/<\/span>/gi, '</span>');

    s = s.replace(/<img\b[^>]*>/gi, function(m){ return '\n@@IMG:' + encodeURIComponent(m) + '@@\n'; });

    s = s.replace(/<br\s*\/?>/gi, '\n');
    s = s.replace(/<\/?p\b[^>]*>/gi, '\n');
    s = s.replace(/<\/?div\b[^>]*>/gi, '\n');
    s = s.replace(/<\/?tbody\b[^>]*>|<\/?tr\b[^>]*>|<\/?td\b[^>]*>|<\/?table\b[^>]*>/gi, '\n');

    // Trắc nghiệm A/B/C/D (giữ nguyên lõi cũ)
    s = s.replace(/<b>\s*(?:<span>\s*)?<u>\s*([ABCD])\s*\.?\s*<\/u>\s*(?:<\/span>\s*)?<\/b>\s*\.?/gi, '\n@@CHOICE:$1:1@@ ');
    s = s.replace(/<u>\s*([ABCD])\s*\.?\s*<\/u>\s*\.?/gi, '\n@@CHOICE:$1:1@@ ');
    s = s.replace(/<b>\s*(?:<span>\s*)?([ABCD])\s*[\.)]\s*(?:<\/span>\s*)?<\/b>/gi, '\n@@CHOICE:$1:0@@ ');

    // Đúng/Sai a), b), c), d)
    s = s.replace(/<b>\s*(?:<span>\s*)?<u>\s*([a-d])\s*[\)]?\s*\.?\s*<\/u>\s*(?:<\/span>\s*)?<\/b>/gi, function(_, ch){ return '\n@@TFCHOICE:' + ch.toLowerCase() + ':1@@ '; });
    s = s.replace(/<u>\s*([a-d])\s*[\)]?\s*\.?\s*<\/u>/gi, function(_, ch){ return '\n@@TFCHOICE:' + ch.toLowerCase() + ':1@@ '; });
    s = s.replace(/<b>\s*(?:<span>\s*)?([a-d])\s*[\.)]\s*(?:<\/span>\s*)?<\/b>/gi, function(_, ch){ return '\n@@TFCHOICE:' + ch.toLowerCase() + ':0@@ '; });

    s = s.replace(/<[^>]*>/g, ' ');

    ['A','B','C','D'].forEach(function(ch){
        const re = new RegExp('(^|\\n|\\s)(' + ch + ')\\s*[\\.)：:]\\s*', 'g');
        s = s.replace(re, function(m, pre, letter){
            if (pre && /[\\$]$/.test(pre)) return m;
            return pre + '@@CHOICE:' + letter + ':0@@ ';
        });
    });
    ['a','b','c','d'].forEach(function(ch){
        const re = new RegExp('(^|\\n)\\s*(' + ch + ')\\s*[\\.)：:]\\s*', 'gim');
        s = s.replace(re, function(m, pre, letter){
            return (pre || '') + '@@TFCHOICE:' + letter.toLowerCase() + ':0@@ ';
        });
    });

    return s.replace(/\n{3,}/g, '\n\n').trim();
}

function lhlV61FindabcdSequence(marks) {
    if (!Array.isArray(marks) || marks.length < 4) return null;
    marks.sort(function(a,b){ return a.index - b.index; });
    for (let i = 0; i <= marks.length - 4; i++) {
        if (marks[i].letter === 'a' && marks[i+1].letter === 'b' && marks[i+2].letter === 'c' && marks[i+3].letter === 'd') {
            return marks.slice(i, i + 4);
        }
    }
    return null;
}

function lhlV61CleanQuestionPieceText(s) {
    return lhlV58RestoreImages(lhlV58FinalCleanText(String(s || '')
        .replace(/@@CHOICE:[ABCD]:[01]@@/gi, '')
        .replace(/@@TFCHOICE:[a-d]:[01]@@/gi, '')
        .replace(/(?:^|\n)\s*(?:Đáp\s*(?:án|s[ốôo])|Lời\s*giải|Giải)\s*[:：][\s\S]*$/i, '')
    ));
}

function lhlV61CleanTfChoiceText(s) {
    let t = String(s || '');
    t = t.replace(/(?:^|\n|\s)(?:Đáp\s*(?:án|s[ốôo])|Lời\s*giải|Giải)\s*[:：][\s\S]*$/i, '');
    t = t.replace(/(?:^|\n)\s*(PHẦN\s+(?:I|II|III|IV|V|1|2|3|4|5)\s*[.:][\s\S]*)$/i, '');
    t = t.replace(/@@CHOICE:[ABCD]:[01]@@/gi, '');
    t = t.replace(/@@TFCHOICE:[a-d]:[01]@@/gi, '');
    t = lhlV58RestoreImages(lhlV58FinalCleanText(t));
    t = t.replace(/^[\s.:：\-–—]+/, '').trim();
    return t;
}

function lhlV61LooksLikeTrueFalseQuestion(s) {
    let t = String(s || '');
    let tfCount = (t.match(/@@TFCHOICE:[a-d]:[01]@@/gi) || []).length;
    let mcCount = (t.match(/@@CHOICE:[ABCD]:[01]@@/gi) || []).length;
    if (tfCount >= 4 && mcCount < 4) return true;
    if (tfCount >= 4 && /đúng\s*hay\s*sai|đúng\s*hoặc\s*sai|khẳng\s*định\s*sau/i.test(t)) return true;
    return false;
}

function lhlV61BuildTrueFalseHtml(qNo, questionPart, items) {
    let out = '<b> Câu ' + qNo + '. </b>\n\n';
    out += (questionPart || '').trim() + '\n\n';
    out += '<div class="choices cols-1">\n\n';
    items.forEach(function(it){
        let letterHtml;
        if (it.isCorrect) letterHtml = '<b><span style="color:black;"><u>' + it.letter.toLowerCase() + ')</u></span></b>';
        else letterHtml = '<b><span style="color:black;">' + it.letter.toLowerCase() + ')</span></b>';
        out += '<div class="choice">\n<label>' + letterHtml + '\n\n  ' + (it.text || '').trim() + '\n\n</label></div>';
    });
    out += '</div>\n\n\n';
    out += '<table class="FontDung" width="100%" style="margin-left: auto; margin-right: auto;">\n<tbody><tr><td></td></tr></tbody></table>';
    return out.replace(/\n{4,}/g, '\n\n\n').trim();
}

function lhlTryNormalizeOneStrippedTrueFalseV61(chunk) {
    let s = String(chunk || '').trim();
    if (!lhlV61LooksLikeTrueFalseQuestion(s)) return null;
    let qm = s.match(/^\s*Câu\s*(\d+)\s*[\.:]/i);
    if (!qm) return null;
    let qNo = qm[1];
    let afterQ = s.slice(qm[0].length);

    let re = /@@TFCHOICE:([a-d]):([01])@@/gi, m, marks = [];
    while ((m = re.exec(afterQ)) !== null) {
        marks.push({ letter: m[1].toLowerCase(), correct: m[2] === '1', index: m.index, end: re.lastIndex });
    }
    marks = lhlV61FindabcdSequence(marks);
    if (!marks) return null;

    let questionPart = lhlV61CleanQuestionPieceText(afterQ.slice(0, marks[0].index));
    let items = [];
    for (let i = 0; i < 4; i++) {
        let cur = marks[i];
        let nextIndex = (i < 3) ? marks[i+1].index : afterQ.length;
        let txt = lhlV61CleanTfChoiceText(afterQ.slice(cur.end, nextIndex));
        items.push({ letter: cur.letter, text: txt, isCorrect: cur.correct });
    }
    return lhlV61BuildTrueFalseHtml(qNo, questionPart, items);
}

function lhlTryNormalizeOneWordTrueFalseV61(input) {
    return lhlTryNormalizeOneStrippedTrueFalseV61(lhlV61StripWordJunk(input));
}

function lhlTryNormalizeOneStrippedQuestionV61(chunk) {
    return lhlTryNormalizeOneStrippedTrueFalseV61(chunk) || lhlTryNormalizeOneStrippedQuestionV59(chunk);
}

function lhlCleanWordQuestionCodeV61(input) {
    let raw = String(input || '');
    let oneTf = lhlTryNormalizeOneWordTrueFalseV61(raw);
    if (oneTf) return oneTf;

    let stripped = lhlV61StripWordJunk(raw);
    let qMatches = [];
    let qRe = /Câu\s*(\d+)\s*[\.:]/gi;
    let m;
    while ((m = qRe.exec(stripped)) !== null) {
        qMatches.push({ no: m[1], index: m.index, end: qRe.lastIndex, text: m[0] });
    }

    if (qMatches.length <= 1) {
        let one = lhlTryNormalizeOneStrippedQuestionV61(stripped);
        if (one) return one;
        return lhlCleanWordQuestionCodeV59(raw);
    }

    let out = [];
    let okCount = 0;
    let intro = stripped.slice(0, qMatches[0].index).trim();
    if (intro) {
        intro = lhlV58RestoreImages(lhlV58FinalCleanText(intro));
        intro = intro.replace(/^\s*(PHẦN\s+(?:I|II|III|IV|V|1|2|3|4|5)[.:][^\n]*)$/gim, '<p class="section-title"><b>$1</b></p>');
        if (intro.trim()) out.push(intro.trim());
    }

    for (let i = 0; i < qMatches.length; i++) {
        let start = qMatches[i].index;
        let end = (i + 1 < qMatches.length) ? qMatches[i + 1].index : stripped.length;
        let chunk = stripped.slice(start, end).trim();
        let html = lhlTryNormalizeOneStrippedQuestionV61(chunk);
        if (html) { out.push(html); okCount++; }
        else {
            let fallback = lhlV58RestoreImages(lhlV58FinalCleanText(chunk));
            if (fallback.trim()) out.push(fallback.trim());
        }
    }

    if (okCount >= 1) {
        return out.join('\n\n').replace(/\n{4,}/g, '\n\n\n').trim();
    }
    return lhlCleanWordQuestionCodeV59(raw);
}

// Ghi đè nút Chuyển Word dùng V61 để hỗ trợ cả TN A/B/C/D và Đúng/Sai a)/b)/c)/d().
convertWordToHtml = function() {
    if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở một Tab để sử dụng ạ!"); return; }
    let editor = document.getElementById('editor');
    let content = editor.value;
    if (!content.trim()) return;

    content = lhlCleanWordQuestionCodeV61(content);
    executeInsertText(editor, content.trim(), 0, editor.value.length, savedStart || 0, savedEnd || 0);
    isFullCodeVisible = true;
    let btnToggle = document.getElementById('btn-toggle');
    if (btnToggle) btnToggle.innerText = "🙈 Thu gọn";
    if (typeof updateCurrentTabData === 'function') updateCurrentTabData();
    if (typeof updateQuestionCounts === 'function') updateQuestionCounts();
    if (typeof updatePreview === 'function') updatePreview();
    showToast("✅ Đã chuyển Word và làm sạch câu hỏi!");
};



// ============================================================
// V62 - CHUYỂN WORD HỖN HỢP: TN A/B/C/D + ĐÚNG/SAI a/b/c/d + TRẢ LỜI NGẮN
// Không tự chèn PHẦN I/II/III, chỉ chuẩn hóa sạch từng loại câu trong cùng một file.
// Câu TLN chuẩn: <b> Câu n. </b> ... <br> <b>Đáp số: ...</b> <br> <table class="FontDung"...>
// ============================================================
function lhlV62CleanShortAnswerText(s) {
    let t = String(s || '');
    t = t.replace(/@@CHOICE:[ABCD]:[01]@@/gi, '');
    t = t.replace(/@@TFCHOICE:[a-d]:[01]@@/gi, '');
    t = lhlV58RestoreImages(lhlV58FinalCleanText(t));
    t = t.replace(/^[\s.:：\-–—]+/, '').trim();
    return t;
}

function lhlV62BuildShortAnswerHtml(qNo, questionPart, answerText) {
    let q = lhlV62CleanShortAnswerText(questionPart);
    let a = lhlV62CleanShortAnswerText(answerText);
    a = a.replace(/^Đáp\s*(?:án|s[ốôo])\s*[:：]\s*/i, '').trim();

    let out = '<b> Câu ' + qNo + '. </b>\n\n';
    out += q + '<br>\n';
    out += '<b>Đáp số: ' + a + '</b>\n\n';
    out += '<br>\n';
    out += '<table class="FontDung" width="100%" style="margin-left: auto; margin-right: auto;">\n<tbody><tr><td></td></tr></tbody></table>';
    return out.replace(/\n{4,}/g, '\n\n\n').trim();
}

function lhlTryNormalizeOneStrippedShortAnswerV62(chunk) {
    let s = String(chunk || '').trim();
    let qm = s.match(/^\s*Câu\s*(\d+)\s*[\.:]/i);
    if (!qm) return null;

    // Nếu có lựa chọn TN hoặc Đ/S đủ bộ thì không xử lý TLN.
    if ((s.match(/@@CHOICE:[ABCD]:[01]@@/gi) || []).length >= 4) return null;
    if ((s.match(/@@TFCHOICE:[a-d]:[01]@@/gi) || []).length >= 4) return null;

    let qNo = qm[1];
    let afterQ = s.slice(qm[0].length);

    // Nhận "Đáp số:", "Đáp án:", kể cả bị bọc <b> trước khi strip đã thành text thường.
    let ansRe = /(?:^|\n|\s)(Đáp\s*(?:án|s[ốôo])\s*[:：]\s*)/i;
    let m = ansRe.exec(afterQ);
    if (!m) return null;

    let ansStart = m.index + m[0].indexOf(m[1]);
    let questionPart = afterQ.slice(0, ansStart);
    let answerPart = afterQ.slice(ansStart + m[1].length);

    // Cắt lời giải nếu dính sau đáp số.
    answerPart = answerPart.replace(/(?:^|\n|\s)(?:Lời\s*giải|Giải)\s*[:：][\s\S]*$/i, '');
    // Cắt tiêu đề phần nếu dính sau đáp số.
    answerPart = answerPart.replace(/(?:^|\n)\s*(PHẦN\s+(?:I|II|III|IV|V|1|2|3|4|5)\s*[.:][\s\S]*)$/i, '');

    if (!lhlV62CleanShortAnswerText(answerPart)) return null;
    return lhlV62BuildShortAnswerHtml(qNo, questionPart, answerPart);
}

function lhlTryNormalizeOneStrippedQuestionV62(chunk) {
    return lhlTryNormalizeOneStrippedTrueFalseV61(chunk)
        || lhlTryNormalizeOneStrippedQuestionV59(chunk)
        || lhlTryNormalizeOneStrippedShortAnswerV62(chunk);
}

function lhlCleanWordQuestionCodeV62(input) {
    let raw = String(input || '');

    // Một câu lẻ: ưu tiên Đ/S, TN, rồi TLN.
    let stripped = lhlV61StripWordJunk(raw);
    let one = lhlTryNormalizeOneStrippedQuestionV62(stripped);
    if (one) return one;

    let qMatches = [];
    let qRe = /Câu\s*(\d+)\s*[\.:]/gi;
    let m;
    while ((m = qRe.exec(stripped)) !== null) {
        qMatches.push({ no: m[1], index: m.index, end: qRe.lastIndex, text: m[0] });
    }

    if (qMatches.length <= 1) {
        return lhlCleanWordQuestionCodeV61(raw);
    }

    let out = [];
    let okCount = 0;

    // Giữ đoạn dẫn/tiêu đề phần nếu thầy đã có sẵn; không tự thêm phần mới.
    let intro = stripped.slice(0, qMatches[0].index).trim();
    if (intro) {
        intro = lhlV58RestoreImages(lhlV58FinalCleanText(intro));
        intro = intro.replace(/^\s*(PHẦN\s+(?:I|II|III|IV|V|1|2|3|4|5)[.:][^\n]*)$/gim, '<p class="section-title"><b>$1</b></p>');
        if (intro.trim()) out.push(intro.trim());
    }

    for (let i = 0; i < qMatches.length; i++) {
        let start = qMatches[i].index;
        let end = (i + 1 < qMatches.length) ? qMatches[i + 1].index : stripped.length;
        let chunk = stripped.slice(start, end).trim();
        let html = lhlTryNormalizeOneStrippedQuestionV62(chunk);

        if (html) {
            out.push(html);
            okCount++;
        } else {
            // Câu chưa nhận dạng được thì chỉ làm sạch nhẹ, không làm hỏng file.
            let fallback = lhlV58RestoreImages(lhlV58FinalCleanText(chunk));
            if (fallback.trim()) out.push(fallback.trim());
        }
    }

    if (okCount >= 1) {
        return out.join('\n\n').replace(/\n{4,}/g, '\n\n\n').trim();
    }
    return lhlCleanWordQuestionCodeV61(raw);
}

// Ghi đè cuối cùng cho nút Chuyển Word: bản V62 hỗn hợp 3 loại câu.
