// ============================================================
// V68 - FIX PHẦN II ĐÚNG/SAI:
// - Câu có đủ a), b), c), d) và không có đủ A/B/C/D => Đúng/Sai, kể cả không ghi "đúng hay sai" trong từng câu.
// - Tách Câu n chắc hơn: nhận "Câu 2", "Câu 2.", "Câu 2:" nhưng tránh bắt cụm "từ câu 1 đến câu 4".
// - Không để lộ token @@TFCHOICE khi một chunk phải fallback.
// ============================================================
function lhlV68FindQuestionMatches(stripped) {
    let s = String(stripped || '');
    let out = [];
    let re = /Câu\s*(\d+)\s*(?:[\.:])?/g;
    let m;
    while ((m = re.exec(s)) !== null) {
        let before = s.slice(Math.max(0, m.index - 25), m.index).toLowerCase();
        let after = s.slice(re.lastIndex, re.lastIndex + 60);

        // Tránh bắt mô tả "từ câu 1 đến câu 12", "các câu 1-4".
        if (/(từ|den|đến|cac|các)\s*$/.test(before)) continue;

        // Nhận khi sau nhãn câu là khoảng trắng + chữ/công thức/tag/token, hoặc kết thúc.
        if (after && !/^\s*(?:[A-ZÀ-Ỵa-zà-ỵ0-9$<@]|\\)/.test(after)) continue;

        out.push({ no: m[1], index: m.index, end: re.lastIndex, text: m[0] });
    }

    // Khử trùng vị trí gần nhau.
    let clean = [];
    out.forEach(function(x){
        if (!clean.length || Math.abs(x.index - clean[clean.length - 1].index) > 5) clean.push(x);
    });
    return clean;
}

function lhlV68RemoveInternalTokens(s) {
    return String(s || '')
        .replace(/@@CHOICE:[ABCD]:[01]@@/g, '')
        .replace(/@@TFCHOICE:[a-d]:[01]@@/g, '');
}

function lhlTryNormalizeOneStrippedQuestionV68(chunk) {
    let s = String(chunk || '');

    // 1) TN A/B/C/D vẫn ưu tiên tuyệt đối.
    if (lhlV65HasABCDSequence(s)) {
        let tn = lhlTryNormalizeOneStrippedQuestionV59(s);
        if (tn) return lhlV67CleanOutput(tn);
    }

    // 2) Đúng/Sai: chỉ cần có đủ a/b/c/d chữ thường và không phải TN A/B/C/D.
    // Điều này đúng với đề của thầy: TN luôn A/B/C/D, Đ/S luôn a)/b)/c)/d).
    if (lhlV65HasabcdSequence(s)) {
        let tf = lhlTryNormalizeOneStrippedTrueFalseV64(s);
        if (tf) return lhlV67CleanOutput(tf);
    }

    // 3) TLN.
    let shortAns = lhlTryNormalizeOneStrippedShortAnswerV62(s);
    if (shortAns) return lhlV67CleanOutput(shortAns);

    return null;
}

function lhlCleanWordQuestionCodeV68(input) {
    let raw = String(input || '');
    let stripped = lhlV67StripWordJunk(raw);

    let qMatches = lhlV68FindQuestionMatches(stripped);

    if (qMatches.length >= 2) {
        let out = [];
        let okCount = 0;

        let intro = stripped.slice(0, qMatches[0].index).trim();
        if (intro) {
            intro = lhlV58RestoreImages(lhlV58FinalCleanText(lhlV68RemoveInternalTokens(intro)));
            intro = lhlV67CleanOutput(intro);
            intro = intro.replace(/^\s*(PHẦN\s+(?:I|II|III|IV|V|1|2|3|4|5)[.:][^\n]*)$/gim, '<p class="section-title"><b>$1</b></p>');
            if (intro.trim()) out.push(intro.trim());
        }

        for (let i = 0; i < qMatches.length; i++) {
            let start = qMatches[i].index;
            let end = (i + 1 < qMatches.length) ? qMatches[i + 1].index : stripped.length;
            let chunk = stripped.slice(start, end).trim();

            let html = lhlTryNormalizeOneStrippedQuestionV68(chunk);
            if (html) {
                out.push(html);
                okCount++;
            } else {
                let fallback = lhlV58RestoreImages(lhlV58FinalCleanText(lhlV68RemoveInternalTokens(chunk)));
                fallback = lhlV67CleanOutput(fallback);
                if (fallback.trim()) out.push(fallback.trim());
            }
        }

        if (okCount >= 1) {
            return lhlV67CleanOutput(out.join('\n\n').replace(/\n{4,}/g, '\n\n\n').trim());
        }
    }

    let one = lhlTryNormalizeOneStrippedQuestionV68(stripped);
    if (one) return lhlV67CleanOutput(one);

    return lhlV67CleanOutput(lhlCleanWordQuestionCodeV67(raw));
}

convertWordToHtml = function() {
    if (!activeTabId) { showToast("⚠️ Thầy vui lòng mở một Tab để sử dụng ạ!"); return; }
    let editor = document.getElementById('editor');
    let content = editor.value;
    if (!content.trim()) return;

    content = lhlCleanWordQuestionCodeV68(content);
    executeInsertText(editor, content.trim(), 0, editor.value.length, savedStart || 0, savedEnd || 0);
    isFullCodeVisible = true;
    let btnToggle = document.getElementById('btn-toggle');
    if (btnToggle) btnToggle.innerText = "🙈 Thu gọn";
    if (typeof updateCurrentTabData === 'function') updateCurrentTabData();
    if (typeof updateQuestionCounts === 'function') updateQuestionCounts();
    if (typeof updatePreview === 'function') updatePreview();
    showToast("✅ Đã chuyển Word và làm sạch câu hỏi hỗn hợp!");
};



