// V69 - FIX IN PDF: Câu 1 không được nhảy lên cùng dòng tiêu đề PHẦN
// Lỗi chỉ xảy ra ở bản in do CSS/HTML print làm phần-title và câu kế tiếp
// nằm cùng flow. V69 ép tiêu đề phần là block 100%, clear both và ngắt dòng.
// ============================================================
function lhlV69FixPartTitlePrintGlue(html) {
    let s = String(html || '');

    // Nếu sau tiêu đề phần là Câu 1 ngay sát, ép có ngắt dòng thật.
    s = s.replace(
        /(<div\b[^>]*class=["'][^"']*\bexam-part-box\b[^"']*["'][^>]*>[\s\S]*?<\/div>)(\s*)(?=(?:<[^>]+>\s*)*Câu\s*\d+\s*[.:]?)/gi,
        '$1\n<div class="lhl-print-part-break"></div>\n'
    );

    // Trường hợp tiêu đề phần dạng p.section-title.
    s = s.replace(
        /(<p\b[^>]*class=["'][^"']*\bsection-title\b[^"']*["'][^>]*>[\s\S]*?<\/p>)(\s*)(?=(?:<[^>]+>\s*)*Câu\s*\d+\s*[.:]?)/gi,
        '$1\n<div class="lhl-print-part-break"></div>\n'
    );

    return s;
}

