// ============================================================
// V75 - ẨN ĐÁP ÁN/ĐÁP SỐ PHẦN III THÌ CO KHOẢNG CÁCH GIỮA CÁC CÂU
// Khi Ẩn ĐA/LG: ẩn luôn <br> dư quanh dòng Đáp số/Đáp án và giảm margin,
// áp dụng cả biên dịch và file IN PDF.
// ============================================================
function lhlV75CompactHiddenPart3Answers(root) {
    try {
        root = root || document;
        const scope = root.querySelectorAll ? root : document;

        // Tìm các dòng đáp số/đáp án đang bị ẩn bởi nút Ẩn ĐA/LG.
        scope.querySelectorAll('[data-answer-hidden="1"], .answer-hidden, .hidden-answer').forEach(function(el) {
            const txt = (el.textContent || '').trim();
            if (!/Đáp\s*(?:án|s[ốôo])\s*[:：]/i.test(txt)) return;

            el.classList.add('lhl-v75-hidden-answer-line');
            el.style.setProperty('display', 'none', 'important');
            el.style.setProperty('margin', '0', 'important');
            el.style.setProperty('padding', '0', 'important');
            el.style.setProperty('height', '0', 'important');
            el.style.setProperty('line-height', '0', 'important');

            // Ẩn các <br> ngay trước/sau dòng đáp số nếu có.
            let p = el.previousSibling;
            let guard = 0;
            while (p && guard++ < 4) {
                if (p.nodeType === 3 && !String(p.nodeValue || '').trim()) { p = p.previousSibling; continue; }
                if (p.nodeType === 1 && p.tagName && p.tagName.toLowerCase() === 'br') {
                    p.classList.add('lhl-v75-hidden-answer-br');
                    p.style.setProperty('display', 'none', 'important');
                    p = p.previousSibling;
                    continue;
                }
                break;
            }

            let n = el.nextSibling;
            guard = 0;
            while (n && guard++ < 4) {
                if (n.nodeType === 3 && !String(n.nodeValue || '').trim()) { n = n.nextSibling; continue; }
                if (n.nodeType === 1 && n.tagName && n.tagName.toLowerCase() === 'br') {
                    n.classList.add('lhl-v75-hidden-answer-br');
                    n.style.setProperty('display', 'none', 'important');
                    n = n.nextSibling;
                    continue;
                }
                break;
            }

            // Nếu nằm trong block câu TLN thì giảm margin.
            let box = el.closest ? el.closest('.part3-question-block, .question-line, p, div') : null;
            if (box) box.classList.add('lhl-v75-compact-p3');
        });

        // Trường hợp code đáp số là <b>Đáp số...</b> bị ẩn inline bằng style display none.
        scope.querySelectorAll('b,strong,span').forEach(function(el) {
            const txt = (el.textContent || '').trim();
            if (!/Đáp\s*(?:án|s[ốôo])\s*[:：]/i.test(txt)) return;
            const cs = window.getComputedStyle ? window.getComputedStyle(el) : null;
            const hidden = (el.style && /none/i.test(el.style.display || '')) || (cs && cs.display === 'none') || el.getAttribute('data-answer-hidden') === '1';
            if (!hidden) return;

            el.classList.add('lhl-v75-hidden-answer-line');
            el.style.setProperty('display', 'none', 'important');

            let p = el.previousSibling;
            let guard = 0;
            while (p && guard++ < 4) {
                if (p.nodeType === 3 && !String(p.nodeValue || '').trim()) { p = p.previousSibling; continue; }
                if (p.nodeType === 1 && p.tagName && p.tagName.toLowerCase() === 'br') {
                    p.style.setProperty('display', 'none', 'important');
                    p = p.previousSibling;
                    continue;
                }
                break;
            }
            let n = el.nextSibling;
            guard = 0;
            while (n && guard++ < 4) {
                if (n.nodeType === 3 && !String(n.nodeValue || '').trim()) { n = n.nextSibling; continue; }
                if (n.nodeType === 1 && n.tagName && n.tagName.toLowerCase() === 'br') {
                    n.style.setProperty('display', 'none', 'important');
                    n = n.nextSibling;
                    continue;
                }
                break;
            }
        });
    } catch(e) {}
}

