// ============================================================
// FIX33-NH: Ngân hàng đề thi theo thư mục 22 file
// - Khởi tạo NH đề thi: TN, Đ/S, TLN theo số câu tùy nhập.
// - Tạo thư mục và các file TN-1.html, DS-1.html, TLN-1.html...
// - Hiển thị danh sách file, số câu hiện có.
// - Nhập code đang bôi đen vào file tương ứng.
// - Xem / Sửa nhanh bằng cách mở file vào tab mới / Xóa file.
// ============================================================
const LHL_QBANK_EXAM_FOLDER_KEY = 'lhl_qbank_exam_folder_v1';

function lhlExamBankGetFolder() {
    return localStorage.getItem(LHL_QBANK_EXAM_FOLDER_KEY) || '';
}
function lhlExamBankSetFolder(folder) {
    if (folder) localStorage.setItem(LHL_QBANK_EXAM_FOLDER_KEY, folder);
}
function lhlExamBankSelectedCode() {
    const editor = document.getElementById('editor');
    if (!editor) return '';
    const a = editor.selectionStart || 0;
    const b = editor.selectionEnd || 0;
    return editor.value.slice(Math.min(a,b), Math.max(a,b)).trim();
}
function lhlExamBankLabel(filename) {
    const s = String(filename || '');
    const m = s.match(/^(TN|DS|TLN)-(\d+)/i);
    if (!m) return s;
    const prefix = m[1].toUpperCase() === 'DS' ? 'Đ/S' : m[1].toUpperCase();
    return prefix + '-' + m[2];
}
function lhlExamBankFilePart(filename) {
    const s = String(filename || '').toUpperCase();
    if (s.startsWith('TN-')) return 'TN';
    if (s.startsWith('DS-')) return 'Đ/S';
    if (s.startsWith('TLN-')) return 'TLN';
    return '';
}

async function lhlExamBankInitFolder() {
    const tn = parseInt(document.getElementById('examBankTN')?.value || '12', 10) || 0;
    const ds = parseInt(document.getElementById('examBankDS')?.value || '4', 10) || 0;
    const tln = parseInt(document.getElementById('examBankTLN')?.value || '6', 10) || 0;

    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_init_exam_folder)) {
        showToast('❌ Chức năng tạo thư mục NH cần chạy trong phần mềm desktop.');
        return;
    }
    const res = await window.pywebview.api.qbank_init_exam_folder(tn, ds, tln);
    if (res && res.ok) {
        lhlExamBankSetFolder(res.folder);
        document.getElementById('examBankFolderPath').textContent = res.folder;
        showToast('✅ Đã khởi tạo ngân hàng đề thi: ' + (res.files ? res.files.length : 0) + ' file.');
        await lhlExamBankRefreshFiles();
    } else if (res && res.cancelled) {
        showToast('ℹ️ Thầy đã hủy chọn thư mục.');
    } else {
        showToast('❌ Lỗi khởi tạo NH: ' + ((res && res.error) || 'Không rõ lỗi'));
    }
}

async function lhlExamBankChooseFolder() {
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_choose_exam_folder)) {
        showToast('❌ Chức năng chọn thư mục NH cần chạy trong phần mềm desktop.');
        return;
    }
    const res = await window.pywebview.api.qbank_choose_exam_folder();
    if (res && res.ok) {
        lhlExamBankSetFolder(res.folder);
        document.getElementById('examBankFolderPath').textContent = res.folder;
        await lhlExamBankRefreshFiles();
        showToast('📂 Đã chọn thư mục ngân hàng.');
    } else if (res && res.cancelled) {
        showToast('ℹ️ Thầy đã hủy chọn thư mục.');
    } else {
        showToast('❌ Lỗi chọn thư mục: ' + ((res && res.error) || 'Không rõ lỗi'));
    }
}

async function lhlExamBankRefreshFiles() {
    const box = document.getElementById('examBankFileList');
    if (!box) return;
    const folder = lhlExamBankGetFolder();
    document.getElementById('examBankFolderPath').textContent = folder || 'Chưa chọn thư mục ngân hàng';
    if (!folder) {
        box.innerHTML = '<div class="qbank-empty">Chưa có thư mục NH. Thầy nhập số câu TN/Đ-S/TLN rồi bấm <b>OK khởi tạo</b>.</div>';
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_list_exam_folder)) {
        box.innerHTML = '<div class="qbank-empty">Chức năng này cần chạy trong phần mềm desktop.</div>';
        return;
    }
    const res = await window.pywebview.api.qbank_list_exam_folder(folder);
    if (!res || !res.ok) {
        box.innerHTML = '<div class="qbank-empty">Không đọc được thư mục NH: ' + lhlQBankEscapeHtml((res && res.error) || '') + '</div>';
        return;
    }
    const files = res.files || [];
    if (!files.length) {
        box.innerHTML = '<div class="qbank-empty">Thư mục chưa có file TN-*, DS-*, TLN-*.</div>';
        return;
    }
    const groups = { 'TN': [], 'Đ/S': [], 'TLN': [] };
    files.forEach(f => {
        const p = lhlExamBankFilePart(f.filename);
        if (!groups[p]) groups[p] = [];
        groups[p].push(f);
    });
    let html = '';
    ['TN','Đ/S','TLN'].forEach(part => {
        if (!groups[part] || !groups[part].length) return;
        html += `<div class="exam-bank-group"><div class="exam-bank-group-title">${part}</div>`;
        groups[part].forEach(f => {
            html += `<div class="exam-bank-file">
                <div class="exam-bank-file-name"><b>${lhlQBankEscapeHtml(lhlExamBankLabel(f.filename))}</b><span>${lhlQBankEscapeHtml(f.filename)}</span></div>
                <div class="exam-bank-count">Số câu: <b>${f.count || 0}</b></div>
                <div class="exam-bank-actions">
                    <button onclick="lhlExamBankAppend('${lhlQBankEscapeHtml(f.filename)}')">Nhập</button>
                    <button onclick="lhlExamBankView('${lhlQBankEscapeHtml(f.filename)}')">Xem</button>
                    <button onclick="lhlExamBankEdit('${lhlQBankEscapeHtml(f.filename)}')">Sửa</button>
                    <button class="danger" onclick="lhlExamBankDelete('${lhlQBankEscapeHtml(f.filename)}')">Xóa</button>
                </div>
            </div>`;
        });
        html += '</div>';
    });
    box.innerHTML = html;
}

async function lhlExamBankAppend(filename) {
    const code = lhlExamBankSelectedCode();
    if (!code) {
        showToast('⚠️ Thầy bôi đen các câu đã chuẩn hóa rồi bấm Nhập vào file cần lưu.');
        return;
    }
    const folder = lhlExamBankGetFolder();
    if (!folder) {
        showToast('⚠️ Chưa chọn thư mục ngân hàng.');
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_append_questions_to_file)) {
        showToast('❌ Chức năng nhập cần chạy trong phần mềm desktop.');
        return;
    }
    const res = await window.pywebview.api.qbank_append_questions_to_file(folder, filename, code);
    if (res && res.ok) {
        showToast('✅ Đã nhập vào ' + filename + '. Tổng số câu hiện có: ' + res.count);
        await lhlExamBankRefreshFiles();
    } else {
        showToast('❌ Lỗi nhập câu: ' + ((res && res.error) || 'Không rõ lỗi'));
    }
}

async function lhlExamBankView(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        showToast('❌ Không đọc được file: ' + ((res && res.error) || ''));
        return;
    }
    const modal = document.getElementById('qbankPreview');
    const body = document.getElementById('qbankPreviewBody');
    if (!modal || !body) return;
    body.innerHTML = `<div class="qbank-code-title">${lhlQBankEscapeHtml(filename)} - Mã code</div>
        <textarea readonly>${String(res.content || '').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea>
        <div class="qbank-code-title">Biên dịch nhanh</div>
        <div class="qbank-render">${processCode(String(res.content || '').replace(/<body[^>]*>|<\/body>|<html[^>]*>|<\/html>|<head[\s\S]*?<\/head>/gi,''))}</div>`;
    modal.style.display = 'flex';
    setTimeout(() => {
        if (window.MathJax && MathJax.typesetPromise) MathJax.typesetPromise([body]).catch(()=>{});
    }, 50);
}

async function lhlExamBankEdit(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        showToast('❌ Không đọc được file để sửa.');
        return;
    }
    if (typeof createOrReplaceTab === 'function') {
        createOrReplaceTab(filename, String(res.content || ''), null);
        showToast('📝 Đã mở file NH vào tab để thầy xem/sửa. Nếu muốn lưu lại file gốc, dùng Save As hoặc copy lại nội dung.');
    } else {
        const editor = document.getElementById('editor');
        if (editor) editor.value = String(res.content || '');
    }
}

async function lhlExamBankDelete(filename) {
    if (!confirm('Thầy chắc muốn xóa file ' + filename + ' khỏi ngân hàng?')) return;
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_delete_file)) return;
    const res = await window.pywebview.api.qbank_delete_file(folder, filename);
    if (res && res.ok) {
        showToast('🗑️ Đã xóa file ' + filename);
        await lhlExamBankRefreshFiles();
    } else {
        showToast('❌ Lỗi xóa file: ' + ((res && res.error) || 'Không rõ lỗi'));
    }
}

