// ============================================================
// FIX39-NH: Đổi tiêu đề nhóm trong hộp thoại Ngân hàng
// TN  -> TRẮC NGHIỆM NHIỀU PHƯƠNG ÁN LỰA CHỌN
// Đ/S -> TRẮC NGHIỆM ĐÚNG, SAI
// TLN -> TRẮC NGHIỆM TRẢ LỜI NGẮN
// Chỉ đổi chữ hiển thị, không đổi tên file.
// ============================================================
function lhlExamBankGroupTitle(part) {
    const p = String(part || '').toUpperCase();
    if (p === 'TN') return 'TRẮC NGHIỆM NHIỀU PHƯƠNG ÁN LỰA CHỌN';
    if (p === 'Đ/S' || p === 'DS') return 'TRẮC NGHIỆM ĐÚNG, SAI';
    if (p === 'TLN') return 'TRẮC NGHIỆM TRẢ LỜI NGẮN';
    return part || '';
}

// Ghi đè lại hàm làm mới danh sách để dùng tiêu đề nhóm đầy đủ.
async function lhlExamBankRefreshFiles() {
    const box = document.getElementById('examBankFileList');
    if (!box) return;
    const folder = lhlExamBankGetFolder();
    document.getElementById('examBankFolderPath').textContent = folder || 'Chưa chọn thư mục ngân hàng';
    if (!folder) {
        box.innerHTML = '<div class="qbank-empty">Chưa có thư mục NH. Thầy nhập số câu TN/Đ-S/TLN rồi bấm <b>OK khởi tạo</b>.</div>';
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_list_exam_folder)) {
        box.innerHTML = '<div class="qbank-empty">Chức năng này cần chạy trong phần mềm desktop.</div>';
        return;
    }
    const res = await window.pywebview.api.qbank_list_exam_folder(folder);
    if (!res || !res.ok) {
        box.innerHTML = '<div class="qbank-empty">Không đọc được thư mục NH: ' + lhlQBankEscapeHtml((res && res.error) || '') + '</div>';
        return;
    }
    const files = res.files || [];
    if (!files.length) {
        box.innerHTML = '<div class="qbank-empty">Thư mục chưa có file TN-*, DS-*, TLN-*.</div>';
        return;
    }
    const groups = { 'TN': [], 'Đ/S': [], 'TLN': [] };
    files.forEach(f => {
        const p = lhlExamBankFilePart(f.filename);
        if (!groups[p]) groups[p] = [];
        groups[p].push(f);
    });
    let html = '';
    ['TN','Đ/S','TLN'].forEach(part => {
        if (!groups[part] || !groups[part].length) return;
        html += `<div class="exam-bank-group"><div class="exam-bank-group-title">${lhlQBankEscapeHtml(lhlExamBankGroupTitle(part))}</div>`;
        groups[part].forEach(f => {
            html += `<div class="exam-bank-file">
                <div class="exam-bank-file-name"><b>${lhlQBankEscapeHtml(lhlExamBankLabel(f.filename))}</b><span>${lhlQBankEscapeHtml(f.filename)}</span></div>
                <div class="exam-bank-count">Số câu: <b>${f.count || 0}</b></div>
                <div class="exam-bank-actions">
                    <button onclick="lhlExamBankAppend('${lhlQBankEscapeHtml(f.filename)}')">Nhập</button>
                    <button onclick="lhlExamBankView('${lhlQBankEscapeHtml(f.filename)}')">Xem</button>
                    <button onclick="lhlExamBankEdit('${lhlQBankEscapeHtml(f.filename)}')">Sửa</button>
                    <button class="danger" onclick="lhlExamBankDelete('${lhlQBankEscapeHtml(f.filename)}')">Xóa</button>
                </div>
            </div>`;
        });
        html += '</div>';
    });
    box.innerHTML = html;
}



// ============================================================
// FIX40-NH: Sửa lỗi không nhập được câu vào file ngân hàng
// Nguyên nhân thường gặp: mở hộp thoại Ngân hàng làm mất vùng bôi đen trong editor.
// Cách sửa: ghi nhớ đoạn code đang bôi đen trước khi mở hộp thoại, khi bấm Nhập dùng lại nếu selection mất.
// ============================================================
window.__lhlExamBankCachedSelectedCode = window.__lhlExamBankCachedSelectedCode || '';

function lhlExamBankCaptureSelection() {
    const editor = document.getElementById('editor');
    if (!editor) return '';
    const a = editor.selectionStart || 0;
    const b = editor.selectionEnd || 0;
    if (a !== b) {
        const code = editor.value.slice(Math.min(a,b), Math.max(a,b)).trim();
        if (code) window.__lhlExamBankCachedSelectedCode = code;
        return code;
    }
    return window.__lhlExamBankCachedSelectedCode || '';
}

// Ghi đè hàm lấy code đang chọn: ưu tiên selection hiện tại, nếu mất thì dùng cache.
function lhlExamBankSelectedCode() {
    return lhlExamBankCaptureSelection();
}

// Bọc lại openQuestionBankDialog để lưu vùng bôi đen trước khi hộp thoại lấy focus.
if (typeof openQuestionBankDialog === 'function' && !window.__lhlFix40WrappedOpenQuestionBankDialog) {
    window.__lhlFix40WrappedOpenQuestionBankDialog = true;
    const __oldOpenQuestionBankDialogFix40 = openQuestionBankDialog;
    openQuestionBankDialog = function() {
        lhlExamBankCaptureSelection();
        return __oldOpenQuestionBankDialogFix40.apply(this, arguments);
    };
}

// Ghi đè Nhập để báo rõ và dùng cache selection.
async function lhlExamBankAppend(filename) {
    const code = lhlExamBankSelectedCode();
    if (!code) {
        showToast('⚠️ Chưa có code để nhập. Thầy hãy bôi đen câu hỏi trong editor trước, rồi mở Ngân hàng và bấm Nhập.');
        return;
    }
    const folder = lhlExamBankGetFolder();
    if (!folder) {
        showToast('⚠️ Chưa chọn thư mục ngân hàng.');
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_append_questions_to_file)) {
        showToast('❌ Chức năng nhập cần chạy trong phần mềm desktop.');
        return;
    }

    showToast('⏳ Đang nhập vào ' + filename + '...');
    const res = await window.pywebview.api.qbank_append_questions_to_file(folder, filename, code);
    if (res && res.ok) {
        showToast('✅ Đã nhập vào ' + filename + '. Tổng số câu hiện có: ' + res.count);
        await lhlExamBankRefreshFiles();
    } else {
        showToast('❌ Lỗi nhập câu: ' + ((res && res.error) || 'Không rõ lỗi'));
    }
}



// ============================================================
// FIX41-NH: Nhập câu chắc hơn + hiển thị nội dung đang chờ nhập
// ============================================================
function lhlExamBankUpdatePendingBox() {
    const box = document.getElementById('examBankPendingInfo');
    if (!box) return;
    const code = window.__lhlExamBankCachedSelectedCode || lhlExamBankCaptureSelection() || '';
    if (code && code.trim()) {
        box.innerHTML = '✅ Đã bắt được nội dung chờ nhập: <b>' + code.trim().length + '</b> ký tự. Thầy bấm <b>Nhập</b> ở file cần lưu.';
        box.style.color = '#c8e6c9';
        box.style.borderColor = 'rgba(76,175,80,.7)';
    } else {
        box.innerHTML = '⚠️ Chưa bắt được nội dung. Thầy hãy bôi đen code câu hỏi trong editor trước khi mở Ngân hàng.';
        box.style.color = '#ffecb3';
        box.style.borderColor = 'rgba(ff,193,7,.7)';
    }
}

// Ghi đè capture: lấy selection, nếu không có thì giữ cache cũ.
function lhlExamBankCaptureSelection() {
    const editor = document.getElementById('editor');
    if (!editor) return window.__lhlExamBankCachedSelectedCode || '';
    try {
        const a = editor.selectionStart || 0;
        const b = editor.selectionEnd || 0;
        if (a !== b) {
            const code = editor.value.slice(Math.min(a,b), Math.max(a,b)).trim();
            if (code) {
                window.__lhlExamBankCachedSelectedCode = code;
                return code;
            }
        }
    } catch(e) {}
    return window.__lhlExamBankCachedSelectedCode || '';
}

function lhlExamBankSelectedCode() {
    return lhlExamBankCaptureSelection();
}

// Bọc openQuestionBankDialog lần nữa để thêm ô pending info sau khi mở.
if (typeof openQuestionBankDialog === 'function' && !window.__lhlFix41WrappedOpenQuestionBankDialog) {
    window.__lhlFix41WrappedOpenQuestionBankDialog = true;
    const __oldOpenQuestionBankDialogFix41 = openQuestionBankDialog;
    openQuestionBankDialog = function() {
        lhlExamBankCaptureSelection();
        const ret = __oldOpenQuestionBankDialogFix41.apply(this, arguments);
        setTimeout(() => {
            const body = document.querySelector('#qbankOverlay .qbank-body');
            if (body && !document.getElementById('examBankPendingInfo')) {
                const div = document.createElement('div');
                div.id = 'examBankPendingInfo';
                div.style.cssText = 'font-size:13px;border:1px solid rgba(76,175,80,.55);border-radius:6px;background:#151515;padding:7px 9px;margin:0 0 10px 0;';
                const folderLine = document.getElementById('examBankFolderPath');
                if (folderLine) folderLine.insertAdjacentElement('afterend', div);
                else body.prepend(div);
            }
            lhlExamBankUpdatePendingBox();
        }, 80);
        return ret;
    };
}

// Ghi đè Nhập: dùng cache, báo rõ số ký tự, cập nhật pending box và danh sách.
async function lhlExamBankAppend(filename) {
    const code = lhlExamBankSelectedCode();
    lhlExamBankUpdatePendingBox();

    if (!code || !code.trim()) {
        showToast('⚠️ Chưa có code để nhập. Thầy bôi đen câu hỏi trong editor rồi mở Ngân hàng lại.');
        return;
    }

    const folder = lhlExamBankGetFolder();
    if (!folder) {
        showToast('⚠️ Chưa chọn thư mục ngân hàng.');
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_append_questions_to_file)) {
        showToast('❌ Không thấy API qbank_append_questions_to_file. Thầy cần chạy bằng main.py bản mới.');
        return;
    }

    showToast('⏳ Đang nhập ' + code.trim().length + ' ký tự vào ' + filename + '...');
    let res = null;
    try {
        res = await window.pywebview.api.qbank_append_questions_to_file(folder, filename, code);
    } catch(e) {
        showToast('❌ Lỗi gọi API nhập câu: ' + (e && e.message ? e.message : e));
        return;
    }

    if (res && res.ok) {
        showToast('✅ Đã nhập vào ' + filename + '. Tổng số câu: ' + res.count + ' | Ký tự thêm: ' + (res.added_chars || code.length));
        await lhlExamBankRefreshFiles();
        lhlExamBankUpdatePendingBox();
    } else {
        showToast('❌ Lỗi nhập câu: ' + ((res && res.error) || 'Không rõ lỗi'));
    }
}



// ============================================================
// FIX42-NH: Sửa nút Nhập im re bằng event delegation + trạng thái trực tiếp
// Không phụ thuộc onclick inline nữa.
// ============================================================
function lhlExamBankSetStatus(msg, type) {
    let box = document.getElementById('examBankActionStatus');
    const body = document.querySelector('#qbankOverlay .qbank-body');
    if (!box && body) {
        box = document.createElement('div');
        box.id = 'examBankActionStatus';
        box.style.cssText = 'font-size:13px;border:1px solid rgba(3,169,244,.55);border-radius:6px;background:#101820;padding:7px 9px;margin:0 0 10px 0;color:#b3e5fc;';
        const list = document.getElementById('examBankFileList');
        if (list) list.insertAdjacentElement('beforebegin', box);
        else body.appendChild(box);
    }
    if (!box) return;
    box.textContent = msg || '';
    if (type === 'ok') {
        box.style.color = '#c8e6c9';
        box.style.borderColor = 'rgba(76,175,80,.7)';
        box.style.background = '#0b1b0d';
    } else if (type === 'err') {
        box.style.color = '#ffcdd2';
        box.style.borderColor = 'rgba(244,67,54,.7)';
        box.style.background = '#240909';
    } else {
        box.style.color = '#b3e5fc';
        box.style.borderColor = 'rgba(3,169,244,.55)';
        box.style.background = '#101820';
    }
}

// Ghi đè refresh để nút có data-action/data-file, không phụ thuộc onclick.
async function lhlExamBankRefreshFiles() {
    const box = document.getElementById('examBankFileList');
    if (!box) return;
    const folder = lhlExamBankGetFolder();
    const folderEl = document.getElementById('examBankFolderPath');
    if (folderEl) folderEl.textContent = folder || 'Chưa chọn thư mục ngân hàng';
    if (!folder) {
        box.innerHTML = '<div class="qbank-empty">Chưa có thư mục NH. Thầy nhập số câu TN/Đ-S/TLN rồi bấm <b>OK khởi tạo</b>.</div>';
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_list_exam_folder)) {
        box.innerHTML = '<div class="qbank-empty">Chức năng này cần chạy trong phần mềm desktop.</div>';
        return;
    }
    let res = null;
    try {
        res = await window.pywebview.api.qbank_list_exam_folder(folder);
    } catch(e) {
        box.innerHTML = '<div class="qbank-empty">Lỗi gọi API đọc thư mục NH: ' + lhlQBankEscapeHtml(e && e.message ? e.message : e) + '</div>';
        return;
    }
    if (!res || !res.ok) {
        box.innerHTML = '<div class="qbank-empty">Không đọc được thư mục NH: ' + lhlQBankEscapeHtml((res && res.error) || '') + '</div>';
        return;
    }
    const files = res.files || [];
    if (!files.length) {
        box.innerHTML = '<div class="qbank-empty">Thư mục chưa có file TN-*, DS-*, TLN-*.</div>';
        return;
    }
    const groups = { 'TN': [], 'Đ/S': [], 'TLN': [] };
    files.forEach(f => {
        const p = lhlExamBankFilePart(f.filename);
        if (!groups[p]) groups[p] = [];
        groups[p].push(f);
    });
    let html = '';
    ['TN','Đ/S','TLN'].forEach(part => {
        const title = (typeof lhlExamBankGroupTitle === 'function') ? lhlExamBankGroupTitle(part) : part;
        html += `<div class="exam-bank-group"><div class="exam-bank-group-title">${lhlQBankEscapeHtml(title)}</div>`;
        groups[part].forEach(f => {
            const safeFile = lhlQBankEscapeHtml(f.filename);
            html += `<div class="exam-bank-file" data-file="${safeFile}">
                <div class="exam-bank-file-name"><b>${lhlQBankEscapeHtml(lhlExamBankLabel(f.filename))}</b><span>${safeFile}</span></div>
                <div class="exam-bank-count">Số câu: <b>${f.count || 0}</b></div>
                <div class="exam-bank-actions">
                    <button type="button" data-action="append" data-file="${safeFile}">Nhập</button>
                    <button type="button" data-action="view" data-file="${safeFile}">Xem</button>
                    <button type="button" data-action="edit" data-file="${safeFile}">Sửa</button>
                    <button type="button" class="danger" data-action="delete" data-file="${safeFile}">Xóa</button>
                </div>
            </div>`;
        });
        html += '</div>';
    });
    box.innerHTML = html;
}

// Ghi đè nhập: không im re; status hiện từng bước.
async function lhlExamBankAppend(filename) {
    lhlExamBankSetStatus('Đã bấm Nhập cho ' + filename + '. Đang kiểm tra nội dung...', 'info');

    const code = lhlExamBankSelectedCode();
    lhlExamBankUpdatePendingBox && lhlExamBankUpdatePendingBox();

    if (!code || !code.trim()) {
        const msg = 'Chưa có code để nhập. Thầy bôi đen câu hỏi trong editor rồi mở Ngân hàng lại.';
        lhlExamBankSetStatus('⚠️ ' + msg, 'err');
        showToast('⚠️ ' + msg);
        return;
    }

    const folder = lhlExamBankGetFolder();
    if (!folder) {
        lhlExamBankSetStatus('⚠️ Chưa chọn thư mục ngân hàng.', 'err');
        showToast('⚠️ Chưa chọn thư mục ngân hàng.');
        return;
    }

    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_append_questions_to_file)) {
        const msg = 'Không thấy API ghi file. Thầy cần chạy bằng app desktop bản FIX42.';
        lhlExamBankSetStatus('❌ ' + msg, 'err');
        showToast('❌ ' + msg);
        return;
    }

    lhlExamBankSetStatus('⏳ Đang gửi ' + code.trim().length + ' ký tự vào ' + filename + '...', 'info');
    let res = null;
    try {
        res = await window.pywebview.api.qbank_append_questions_to_file(folder, filename, code);
    } catch(e) {
        const msg = e && e.message ? e.message : String(e);
        lhlExamBankSetStatus('❌ Lỗi gọi Python API: ' + msg, 'err');
        showToast('❌ Lỗi gọi Python API.');
        return;
    }

    if (res && res.ok) {
        const msg = '✅ Đã nhập vào ' + filename + '. Tổng số câu: ' + res.count + '. Đã thêm ' + (res.added_chars || code.length) + ' ký tự.';
        lhlExamBankSetStatus(msg, 'ok');
        showToast(msg);
        await lhlExamBankRefreshFiles();
        if (typeof lhlExamBankUpdatePendingBox === 'function') lhlExamBankUpdatePendingBox();
    } else {
        const msg = (res && res.error) || 'Không rõ lỗi';
        lhlExamBankSetStatus('❌ Lỗi nhập câu: ' + msg, 'err');
        showToast('❌ Lỗi nhập câu: ' + msg);
    }
}

// Bắt click bằng event delegation ở capture phase để chắc chắn nút Nhập chạy.
if (!window.__lhlFix42BankClickDelegate) {
    window.__lhlFix42BankClickDelegate = true;
    document.addEventListener('click', function(e) {
        const btn = e.target && e.target.closest ? e.target.closest('#qbankOverlay button[data-action]') : null;
        if (!btn) return;
        const action = btn.getAttribute('data-action');
        const filename = btn.getAttribute('data-file');
        if (!action || !filename) return;

        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        if (action === 'append') return void lhlExamBankAppend(filename);
        if (action === 'view') return void lhlExamBankView(filename);
        if (action === 'edit') return void lhlExamBankEdit(filename);
        if (action === 'delete') return void lhlExamBankDelete(filename);
    }, true);
}



// ============================================================
// FIX44-NH: Làm mới xóa cache nhập + xem đẹp + chọn file/số câu rút
// ============================================================
function lhlExamBankClearPending() {
    window.__lhlExamBankCachedSelectedCode = '';
    const box = document.getElementById('examBankPendingInfo');
    if (box) {
        box.innerHTML = '⚠️ Chưa bắt được nội dung. Thầy hãy bôi đen code câu hỏi trong editor trước khi mở Ngân hàng.';
        box.style.color = '#ffecb3';
        box.style.borderColor = 'rgba(255,193,7,.7)';
        box.style.background = '#151515';
    }
    lhlExamBankSetStatus && lhlExamBankSetStatus('Đã làm mới danh sách và xóa nội dung chờ nhập.', 'info');
}

async function lhlExamBankRefreshButton() {
    lhlExamBankClearPending();
    await lhlExamBankRefreshFiles();
}

function lhlExamBankExtractBodyOnly(html) {
    let s = String(html || '');
    const m = s.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    if (m) s = m[1];
    s = s.replace(/<script\b[\s\S]*?<\/script>/gi, '');
    s = s.replace(/<style\b[\s\S]*?<\/style>/gi, '');
    s = s.replace(/<!--\s*LHL_QBANK_FILE:[\s\S]*?-->/gi, '');
    s = s.replace(/<!--\s*LHL_QBANK_APPEND\s*-->/gi, '');
    return s.trim();
}

function lhlExamBankQuestionCountInHtml(html) {
    const text = lhlQBankPlainText ? lhlQBankPlainText(html) : String(html || '').replace(/<[^>]+>/g, ' ');
    const m = text.match(/\bCâu\s+\d+[\.:]?/gi);
    return m ? m.length : 0;
}

function lhlExamBankResetPickCounts() {
    document.querySelectorAll('#examBankFileList .exam-bank-pick-count').forEach(inp => {
        inp.value = 1;
    });
    document.querySelectorAll('#examBankFileList .exam-bank-pick-check').forEach(chk => {
        chk.checked = false;
    });
    lhlExamBankSetStatus && lhlExamBankSetStatus('Đã reset số câu cần rút của các file về 1.', 'ok');
}

function lhlExamBankGetPickConfig() {
    return Array.from(document.querySelectorAll('#examBankFileList .exam-bank-file')).map(row => {
        const file = row.getAttribute('data-file') || '';
        const checked = !!row.querySelector('.exam-bank-pick-check')?.checked;
        const count = parseInt(row.querySelector('.exam-bank-pick-count')?.value || '1', 10) || 1;
        return { file, checked, count };
    }).filter(x => x.file);
}

// Ghi đè refresh: thêm checkbox chọn file + ô số câu cần rút.
async function lhlExamBankRefreshFiles() {
    const box = document.getElementById('examBankFileList');
    if (!box) return;
    const folder = lhlExamBankGetFolder();
    const folderEl = document.getElementById('examBankFolderPath');
    if (folderEl) folderEl.textContent = folder || 'Chưa chọn thư mục ngân hàng';
    if (!folder) {
        box.innerHTML = '<div class="qbank-empty">Chưa có thư mục NH. Thầy nhập số câu TN/Đ-S/TLN rồi bấm <b>OK khởi tạo</b>.</div>';
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_list_exam_folder)) {
        box.innerHTML = '<div class="qbank-empty">Chức năng này cần chạy trong phần mềm desktop.</div>';
        return;
    }
    let res = null;
    try {
        res = await window.pywebview.api.qbank_list_exam_folder(folder);
    } catch(e) {
        box.innerHTML = '<div class="qbank-empty">Lỗi gọi API đọc thư mục NH: ' + lhlQBankEscapeHtml(e && e.message ? e.message : e) + '</div>';
        return;
    }
    if (!res || !res.ok) {
        box.innerHTML = '<div class="qbank-empty">Không đọc được thư mục NH: ' + lhlQBankEscapeHtml((res && res.error) || '') + '</div>';
        return;
    }
    const files = res.files || [];
    if (!files.length) {
        box.innerHTML = '<div class="qbank-empty">Thư mục chưa có file TN-*, DS-*, TLN-*.</div>';
        return;
    }
    const groups = { 'TN': [], 'Đ/S': [], 'TLN': [] };
    files.forEach(f => {
        const p = lhlExamBankFilePart(f.filename);
        if (!groups[p]) groups[p] = [];
        groups[p].push(f);
    });

    let html = '';
    ['TN','Đ/S','TLN'].forEach(part => {
        if (!groups[part] || !groups[part].length) return;
        const title = (typeof lhlExamBankGroupTitle === 'function') ? lhlExamBankGroupTitle(part) : part;
        html += `<div class="exam-bank-group"><div class="exam-bank-group-title">${lhlQBankEscapeHtml(title)}</div>`;
        groups[part].forEach(f => {
            const safeFile = lhlQBankEscapeHtml(f.filename);
            html += `<div class="exam-bank-file" data-file="${safeFile}" style="grid-template-columns:38px 1fr 100px 96px 230px;">
                <div style="text-align:center;"><input class="exam-bank-pick-check" type="checkbox" title="Chọn file này để rút câu"></div>
                <div class="exam-bank-file-name"><b>${lhlQBankEscapeHtml(lhlExamBankLabel(f.filename))}</b><span>${safeFile}</span></div>
                <div class="exam-bank-count">Số câu: <b>${f.count || 0}</b></div>
                <div class="exam-bank-pick-box" style="display:flex;align-items:center;gap:4px;justify-content:center;color:#e8f5e9;font-size:12px;">
                    <span class="qbank-pick-label">Chọn/đề</span><input class="exam-bank-pick-count" type="number" min="1" value="1" style="width:44px;height:26px;background:#111;color:#fff;border:1px solid #4caf50;border-radius:4px;text-align:center;font-weight:800;">
                </div>
                <div class="exam-bank-actions">
                    <button type="button" data-action="append" data-file="${safeFile}">Nhập</button>
                    <button type="button" data-action="view" data-file="${safeFile}">Xem</button>
                    <button type="button" data-action="edit" data-file="${safeFile}">Sửa</button>
                    <button type="button" class="danger" data-action="delete" data-file="${safeFile}">Xóa</button>
                </div>
            </div>`;
        });
        html += '</div>';
    });
    box.innerHTML = html;
}

// Ghi đè Xem: chỉ render phần BODY, bỏ head/script để đẹp hơn.
async function lhlExamBankView(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        showToast('❌ Không đọc được file: ' + ((res && res.error) || ''));
        return;
    }
    const modal = document.getElementById('qbankPreview');
    const body = document.getElementById('qbankPreviewBody');
    if (!modal || !body) return;
    const raw = String(res.content || '');
    const bodyOnly = lhlExamBankExtractBodyOnly(raw);
    const count = lhlExamBankQuestionCountInHtml(bodyOnly);
    body.innerHTML = `<div class="qbank-code-title">${lhlQBankEscapeHtml(filename)} - Nội dung câu hỏi (${count} câu)</div>
        <textarea readonly>${bodyOnly.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea>
        <div class="qbank-code-title">Biên dịch nhanh</div>
        <div class="qbank-render" style="font-size:18px;line-height:1.35;text-align:left;">${processCode(bodyOnly)}</div>`;
    modal.style.display = 'flex';
    setTimeout(() => {
        if (window.MathJax && MathJax.typesetPromise) MathJax.typesetPromise([body]).catch(()=>{});
    }, 80);
}

// Bọc lại open dialog để nút Làm mới gọi đúng hàm clear cache và thêm nút Reset số rút.
if (typeof openQuestionBankDialog === 'function' && !window.__lhlFix44WrappedOpenQuestionBankDialog) {
    window.__lhlFix44WrappedOpenQuestionBankDialog = true;
    const __oldOpenQuestionBankDialogFix44 = openQuestionBankDialog;
    openQuestionBankDialog = function() {
        const ret = __oldOpenQuestionBankDialogFix44.apply(this, arguments);
        setTimeout(() => {
            const body = document.querySelector('#qbankOverlay .qbank-body');
            if (!body) return;

            // Đổi nút Làm mới cũ sang hàm mới.
            const refreshBtns = Array.from(body.querySelectorAll('button')).filter(b => /Làm mới danh sách/i.test(b.textContent || ''));
            refreshBtns.forEach(b => {
                b.onclick = function(ev){ ev.preventDefault(); lhlExamBankRefreshButton(); };
            });

            if (!document.getElementById('examBankResetPickBtn')) {
                const holder = refreshBtns[0]?.parentElement;
                if (holder) {
                    const btn = document.createElement('button');
                    btn.id = 'examBankResetPickBtn';
                    btn.className = 'exam-bank-btn';
                    btn.style.marginLeft = '6px';
                    btn.textContent = '🔄 Reset số rút';
                    btn.onclick = function(ev){ ev.preventDefault(); lhlExamBankResetPickCounts(); };
                    holder.insertBefore(btn, holder.children[1] || null);
                }
            }
        }, 120);
        return ret;
    };
}



