async function lhlExamBankRenumberFilesOnly(showMsg=true) {
    const folder = lhlExamBankGetFolder();
    if (!folder) return;
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_renumber_exam_files)) {
        if (showMsg) showToast('⚠️ Chưa có API đánh số lại file NH.');
        return;
    }
    const res = await window.pywebview.api.qbank_renumber_exam_files(folder);
    if (res && res.ok) {
        if (showMsg) showToast('🔢 Đã đánh số lại file NH. Số file đổi tên: ' + (res.renamed || 0));
    } else if (showMsg) {
        showToast('❌ Lỗi đánh số lại file: ' + ((res && res.error) || 'Không rõ lỗi'));
    }
}

