// Ghi đè refresh: thêm Reset câu cạnh Nhập + layout vừa phải.
async function lhlExamBankRefreshFiles() {
    const box = document.getElementById('examBankFileList');
    if (!box) return;
    const folder = lhlExamBankGetFolder();
    const folderEl = document.getElementById('examBankFolderPath');
    if (folderEl) folderEl.textContent = folder || 'Chưa chọn thư mục ngân hàng';
    if (!folder) {
        box.innerHTML = '<div class="qbank-empty">Chưa có thư mục NH. Thầy nhập số câu TN/Đ-S/TLN rồi bấm <b>OK khởi tạo</b>.</div>';
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_list_exam_folder)) {
        box.innerHTML = '<div class="qbank-empty">Chức năng này cần chạy trong phần mềm desktop.</div>';
        return;
    }
    let res = null;
    try {
        res = await window.pywebview.api.qbank_list_exam_folder(folder);
    } catch(e) {
        box.innerHTML = '<div class="qbank-empty">Lỗi gọi API đọc thư mục NH: ' + lhlQBankEscapeHtml(e && e.message ? e.message : e) + '</div>';
        return;
    }
    if (!res || !res.ok) {
        box.innerHTML = '<div class="qbank-empty">Không đọc được thư mục NH: ' + lhlQBankEscapeHtml((res && res.error) || '') + '</div>';
        return;
    }
    const files = res.files || [];
    if (!files.length) {
        box.innerHTML = '<div class="qbank-empty">Thư mục chưa có file TN-*, DS-*, TLN-*.</div>';
        return;
    }
    const groups = { 'TN': [], 'Đ/S': [], 'TLN': [] };
    files.forEach(f => {
        const p = lhlExamBankFilePart(f.filename);
        if (!groups[p]) groups[p] = [];
        groups[p].push(f);
    });
    let html = '';
    ['TN','Đ/S','TLN'].forEach(part => {
        if (!groups[part] || !groups[part].length) return;
        const title = (typeof lhlExamBankGroupTitle === 'function') ? lhlExamBankGroupTitle(part) : part;
        html += `<div class="exam-bank-group"><div class="exam-bank-group-title">${lhlQBankEscapeHtml(title)}</div>`;
        groups[part].forEach(f => {
            const safeFile = lhlQBankEscapeHtml(f.filename);
            html += `<div class="exam-bank-file" data-file="${safeFile}" style="grid-template-columns:34px 1fr 86px 82px 310px;">
                <div style="text-align:center;"><input class="exam-bank-pick-check" type="checkbox" title="Chọn file này để rút câu"></div>
                <div class="exam-bank-file-name"><b>${lhlQBankEscapeHtml(lhlExamBankLabel(f.filename))}</b><span>${safeFile}</span></div>
                <div class="exam-bank-count">Số câu: <b>${f.count || 0}</b></div>
                <div class="exam-bank-pick-box" style="display:flex;align-items:center;gap:4px;justify-content:center;color:#e8f5e9;font-size:12px;">
                    <span class="qbank-pick-label">Chọn/đề</span><input class="exam-bank-pick-count" type="number" min="1" value="1" style="width:40px;height:25px;background:#111;color:#fff;border:1px solid #4caf50;border-radius:4px;text-align:center;font-weight:800;">
                </div>
                <div class="exam-bank-actions">
                    <button type="button" data-action="append" data-file="${safeFile}">Nhập</button>
                    <button type="button" data-action="resetfile" data-file="${safeFile}" style="background:#ef6c00;">Reset câu</button>
                    <button type="button" data-action="view" data-file="${safeFile}">Xem</button>
                    <button type="button" data-action="edit" data-file="${safeFile}">Sửa</button>
                    <button type="button" class="danger" data-action="delete" data-file="${safeFile}">Xóa</button>
                </div>
            </div>`;
        });
        html += '</div>';
    });
    box.innerHTML = html;
}

// Xem nhanh: dùng style gần giống paper preview bên ngoài hơn.
async function lhlExamBankView(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        showToast('❌ Không đọc được file: ' + ((res && res.error) || ''));
        return;
    }
    const modal = document.getElementById('qbankPreview');
    const body = document.getElementById('qbankPreviewBody');
    if (!modal || !body) return;

    const raw = String(res.content || '');
    const bodyOnly = (typeof lhlExamBankPrettyBodyOnly === 'function') ? lhlExamBankPrettyBodyOnly(raw) : lhlExamBankExtractBodyOnly(raw);
    const count = lhlExamBankQuestionCountInHtml ? lhlExamBankQuestionCountInHtml(bodyOnly) : 0;

    body.innerHTML = `
    <div class="qbank-view-fixed">
        <div class="qbank-code-title">${lhlQBankEscapeHtml(filename)} - Mã code nội dung (${count} câu)</div>
        <textarea readonly>${bodyOnly.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea>
    </div>
    <div class="qbank-code-title">Biên dịch nhanh</div>
    <div class="qbank-render qbank-render-pretty"><div class="qbank-preview-paper">${processCode(bodyOnly)}</div></div>`;

    modal.style.display = 'flex';

    const styleId = 'lhl-fix46-qbank-view-style';
    if (!document.getElementById(styleId)) {
        const st = document.createElement('style');
        st.id = styleId;
        st.textContent = `
        .qbank-preview-box{
            display:flex !important;
            flex-direction:column !important;
            max-height:90vh !important;
            overflow:hidden !important;
            width:min(980px,calc(100% - 34px)) !important;
        }
        #qbankPreviewBody{
            display:flex !important;
            flex-direction:column !important;
            min-height:0 !important;
            overflow:hidden !important;
        }
        .qbank-view-fixed{flex:0 0 auto !important;}
        .qbank-view-fixed textarea{
            height:120px !important;
            max-height:120px !important;
            overflow:auto !important;
            background:#161616 !important;
            color:#f5f5f5 !important;
            border:1px solid #666 !important;
            border-radius:5px !important;
            padding:8px !important;
            font-family:Consolas,monospace !important;
            font-size:13px !important;
            line-height:1.35 !important;
        }
        .qbank-render-pretty{
            flex:1 1 auto !important;
            min-height:350px !important;
            overflow:auto !important;
            background:#e9e9e9 !important;
            padding:14px !important;
        }
        .qbank-preview-paper{
            background:#fff !important;
            color:#000 !important;
            max-width:820px !important;
            min-height:300px !important;
            margin:0 auto !important;
            padding:22px 28px !important;
            font-family:"Times New Roman", Times, serif !important;
            font-size:18px !important;
            line-height:1.35 !important;
            text-align:left !important;
            box-shadow:0 0 0 1px #ddd, 0 2px 8px rgba(0,0,0,.18) !important;
        }
        .qbank-preview-paper .choices{
            display:grid;
            gap:6px 22px;
            margin:8px 0 10px 0;
        }
        .qbank-preview-paper .choices.cols-4{grid-template-columns:repeat(4,1fr);}
        .qbank-preview-paper .choices.cols-2{grid-template-columns:repeat(2,1fr);}
        .qbank-preview-paper .choice{break-inside:avoid;}
        .qbank-preview-paper table{
            border-collapse:collapse;
            margin:10px auto;
            text-align:center;
        }
        .qbank-preview-paper td,.qbank-preview-paper th{
            border:1px solid #555;
            padding:4px 8px;
        }
        .qbank-preview-paper img{max-width:100%;height:auto;}
        .qbank-preview-paper .immini-wrap{
            display:flex;
            align-items:flex-start;
            gap:var(--immini-gap,6px);
            margin:4px 0 8px 0;
        }
        .qbank-preview-paper .immini-text{flex:1 1 auto;min-width:0;}
        .qbank-preview-paper .immini-figure{flex:0 0 var(--immini-figure-col,26%);text-align:right;}
        `;
        document.head.appendChild(st);
    }

    setTimeout(() => {
        if (window.MathJax && MathJax.typesetPromise) MathJax.typesetPromise([body]).catch(()=>{});
    }, 80);
}

// Bọc open dialog: thêm nút Xóa toàn bộ cạnh Reset số rút; Làm mới gọi refresh+renumber.
if (typeof openQuestionBankDialog === 'function' && !window.__lhlFix46WrappedOpenQuestionBankDialog) {
    window.__lhlFix46WrappedOpenQuestionBankDialog = true;
    const __oldOpenQuestionBankDialogFix46 = openQuestionBankDialog;
    openQuestionBankDialog = function() {
        const ret = __oldOpenQuestionBankDialogFix46.apply(this, arguments);
        setTimeout(() => {
            const body = document.querySelector('#qbankOverlay .qbank-body');
            if (!body) return;
            const refreshBtns = Array.from(body.querySelectorAll('button')).filter(b => /Làm mới danh sách/i.test(b.textContent || ''));
            refreshBtns.forEach(b => {
                b.onclick = function(ev){ ev.preventDefault(); lhlExamBankRefreshButton(); };
            });
            const holder = refreshBtns[0]?.parentElement;
            if (holder && !document.getElementById('examBankClearAllBtn')) {
                let resetBtn = document.getElementById('examBankResetPickBtn');
                if (!resetBtn) {
                    resetBtn = document.createElement('button');
                    resetBtn.id = 'examBankResetPickBtn';
                    resetBtn.className = 'exam-bank-btn';
                    resetBtn.style.marginLeft = '6px';
                    resetBtn.textContent = '🔄 Reset số rút';
                    resetBtn.onclick = function(ev){ ev.preventDefault(); lhlExamBankResetPickCounts(); };
                    holder.insertBefore(resetBtn, holder.children[1] || null);
                }
                const delBtn = document.createElement('button');
                delBtn.id = 'examBankClearAllBtn';
                delBtn.className = 'exam-bank-btn';
                delBtn.style.marginLeft = '6px';
                delBtn.style.background = 'linear-gradient(#e53935,#b71c1c)';
                delBtn.textContent = '🗑️ Xóa toàn bộ câu hỏi';
                delBtn.onclick = function(ev){ ev.preventDefault(); lhlExamBankClearAllQuestions(); };
                resetBtn.insertAdjacentElement('afterend', delBtn);
            }
        }, 140);
        return ret;
    };
}

// Bổ sung event delegation action resetfile.
if (!window.__lhlFix46BankClickDelegate) {
    window.__lhlFix46BankClickDelegate = true;
    document.addEventListener('click', function(e) {
        const btn = e.target && e.target.closest ? e.target.closest('#qbankOverlay button[data-action="resetfile"]') : null;
        if (!btn) return;
        const filename = btn.getAttribute('data-file');
        if (!filename) return;
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        lhlExamBankResetFileQuestions(filename);
    }, true);
}



// ============================================================
// FIX47-NH: hoàn thiện UI/logic ngân hàng
// - Gộp thông báo bắt nội dung + hành động vào một dòng.
// - Reset câu từng file chạy qua event delegation chắc hơn.
// - Xóa file dùng hộp thoại đẹp, không dùng confirm mặc định.
// - Xóa file xong cập nhật số TN/ĐS/TLN phía trên.
// - Xem nhanh dùng iframe srcdoc giống trình duyệt hơn.
// - Sửa file không thu nhỏ giao diện.
// ============================================================
function lhlExamBankSetUnifiedStatus(msg, type) {
    let box = document.getElementById('examBankPendingInfo');
    const body = document.querySelector('#qbankOverlay .qbank-body');
    if (!box && body) {
        box = document.createElement('div');
        box.id = 'examBankPendingInfo';
        box.style.cssText = 'font-size:13px;border:1px solid rgba(76,175,80,.55);border-radius:6px;background:#151515;padding:7px 9px;margin:0 0 10px 0;';
        const folderLine = document.getElementById('examBankFolderPath');
        if (folderLine) folderLine.insertAdjacentElement('afterend', box);
        else body.prepend(box);
    }
    if (!box) return;
    box.innerHTML = msg || '';
    if (type === 'err') {
        box.style.color = '#ffcdd2';
        box.style.borderColor = 'rgba(244,67,54,.7)';
        box.style.background = '#240909';
    } else if (type === 'ok') {
        box.style.color = '#c8e6c9';
        box.style.borderColor = 'rgba(76,175,80,.75)';
        box.style.background = '#0b1b0d';
    } else {
        box.style.color = '#ffecb3';
        box.style.borderColor = 'rgba(255,193,7,.7)';
        box.style.background = '#151515';
    }
}

function lhlExamBankUpdateTopCountsFromFiles(files) {
    try {
        const cnt = {TN:0, DS:0, TLN:0};
        (files || []).forEach(f => {
            const name = String(f.filename || '').toUpperCase();
            if (name.startsWith('TN-')) cnt.TN++;
            else if (name.startsWith('DS-')) cnt.DS++;
            else if (name.startsWith('TLN-')) cnt.TLN++;
        });
        const tn = document.getElementById('examBankTN');
        const ds = document.getElementById('examBankDS');
        const tln = document.getElementById('examBankTLN');
        if (tn) tn.value = cnt.TN;
        if (ds) ds.value = cnt.DS;
        if (tln) tln.value = cnt.TLN;
    } catch(e) {}
}

function lhlExamBankClearPending() {
    window.__lhlExamBankCachedSelectedCode = '';
    lhlExamBankSetUnifiedStatus('⚠️ Chưa bắt được nội dung. Thầy hãy bôi đen code câu hỏi trong editor trước khi mở Ngân hàng.', 'warn');
}

function lhlExamBankUpdatePendingBox() {
    const code = window.__lhlExamBankCachedSelectedCode || lhlExamBankCaptureSelection() || '';
    if (code && code.trim()) {
        lhlExamBankSetUnifiedStatus('✅ Đã bắt được nội dung chờ nhập: <b>' + code.trim().length + '</b> ký tự. Thầy bấm <b>Nhập</b> ở file cần lưu.', 'ok');
    } else {
        lhlExamBankSetUnifiedStatus('⚠️ Chưa bắt được nội dung. Thầy hãy bôi đen code câu hỏi trong editor trước khi mở Ngân hàng.', 'warn');
    }
}

// Dialog đẹp thay confirm mặc định
function lhlExamBankConfirm(title, message, okText, danger=false) {
    return new Promise(resolve => {
        const old = document.getElementById('examBankConfirmModal');
        if (old) old.remove();
        const div = document.createElement('div');
        div.id = 'examBankConfirmModal';
        div.style.cssText = 'position:fixed;inset:0;z-index:200000;background:rgba(0,0,0,.62);display:flex;align-items:center;justify-content:center;font-family:Segoe UI,Tahoma,Arial,sans-serif;';
        div.innerHTML = `
        <div style="width:min(520px,calc(100% - 40px));background:#2d2d30;color:#fff;border:1px solid ${danger?'#e53935':'#4caf50'};border-radius:10px;box-shadow:0 18px 45px rgba(0,0,0,.75);overflow:hidden;">
            <div style="padding:14px 18px;font-size:20px;font-weight:900;color:${danger?'#ff8a80':'#81c784'};border-bottom:1px solid rgba(255,255,255,.12);">${title}</div>
            <div style="padding:18px;font-size:15px;line-height:1.45;">${message}</div>
            <div style="display:flex;justify-content:flex-end;gap:10px;padding:12px 18px;background:#242426;">
                <button id="examBankConfirmCancel" style="border:0;border-radius:6px;background:#546e7a;color:#fff;font-weight:900;padding:9px 16px;cursor:pointer;">Hủy</button>
                <button id="examBankConfirmOk" style="border:0;border-radius:6px;background:${danger?'#c62828':'#2e7d32'};color:#fff;font-weight:900;padding:9px 16px;cursor:pointer;">${okText || 'OK'}</button>
            </div>
        </div>`;
        document.body.appendChild(div);
        div.querySelector('#examBankConfirmCancel').onclick = () => { div.remove(); resolve(false); };
        div.querySelector('#examBankConfirmOk').onclick = () => { div.remove(); resolve(true); };
    });
}

async function lhlExamBankRefreshFiles() {
    const box = document.getElementById('examBankFileList');
    if (!box) return;
    const folder = lhlExamBankGetFolder();
    const folderEl = document.getElementById('examBankFolderPath');
    if (folderEl) folderEl.textContent = folder || 'Chưa chọn thư mục ngân hàng';
    if (!folder) {
        box.innerHTML = '<div class="qbank-empty">Chưa có thư mục NH. Thầy nhập số câu TN/Đ-S/TLN rồi bấm <b>OK khởi tạo</b>.</div>';
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_list_exam_folder)) {
        box.innerHTML = '<div class="qbank-empty">Chức năng này cần chạy trong phần mềm desktop.</div>';
        return;
    }
    let res = null;
    try { res = await window.pywebview.api.qbank_list_exam_folder(folder); }
    catch(e) {
        box.innerHTML = '<div class="qbank-empty">Lỗi gọi API đọc thư mục NH: ' + lhlQBankEscapeHtml(e && e.message ? e.message : e) + '</div>';
        return;
    }
    if (!res || !res.ok) {
        box.innerHTML = '<div class="qbank-empty">Không đọc được thư mục NH: ' + lhlQBankEscapeHtml((res && res.error) || '') + '</div>';
        return;
    }
    const files = res.files || [];
    lhlExamBankUpdateTopCountsFromFiles(files);
    if (!files.length) {
        box.innerHTML = '<div class="qbank-empty">Thư mục chưa có file TN-*, DS-*, TLN-*.</div>';
        return;
    }
    const groups = { 'TN': [], 'Đ/S': [], 'TLN': [] };
    files.forEach(f => {
        const p = lhlExamBankFilePart(f.filename);
        if (!groups[p]) groups[p] = [];
        groups[p].push(f);
    });
    let html = '';
    ['TN','Đ/S','TLN'].forEach(part => {
        if (!groups[part] || !groups[part].length) return;
        const title = (typeof lhlExamBankGroupTitle === 'function') ? lhlExamBankGroupTitle(part) : part;
        html += `<div class="exam-bank-group"><div class="exam-bank-group-title">${lhlQBankEscapeHtml(title)}</div>`;
        groups[part].forEach(f => {
            const safeFile = lhlQBankEscapeHtml(f.filename);
            html += `<div class="exam-bank-file" data-file="${safeFile}" style="grid-template-columns:34px 1fr 86px 82px 310px;">
                <div style="text-align:center;"><input class="exam-bank-pick-check" type="checkbox" title="Chọn file này để rút câu"></div>
                <div class="exam-bank-file-name"><b>${lhlQBankEscapeHtml(lhlExamBankLabel(f.filename))}</b><span>${safeFile}</span></div>
                <div class="exam-bank-count">Số câu: <b>${f.count || 0}</b></div>
                <div class="exam-bank-pick-box" style="display:flex;align-items:center;gap:4px;justify-content:center;color:#e8f5e9;font-size:12px;">
                    <span class="qbank-pick-label">Chọn/đề</span><input class="exam-bank-pick-count" type="number" min="1" value="1" style="width:40px;height:25px;background:#111;color:#fff;border:1px solid #4caf50;border-radius:4px;text-align:center;font-weight:800;">
                </div>
                <div class="exam-bank-actions">
                    <button type="button" data-action="append" data-file="${safeFile}">Nhập</button>
                    <button type="button" data-action="resetfile" data-file="${safeFile}" style="background:#ef6c00;">Reset câu</button>
                    <button type="button" data-action="view" data-file="${safeFile}">Xem</button>
                    <button type="button" data-action="edit" data-file="${safeFile}">Sửa</button>
                    <button type="button" class="danger" data-action="delete" data-file="${safeFile}">Xóa</button>
                </div>
            </div>`;
        });
        html += '</div>';
    });
    box.innerHTML = html;
}

async function lhlExamBankAppend(filename) {
    const code = lhlExamBankSelectedCode();
    if (!code || !code.trim()) {
        lhlExamBankSetUnifiedStatus('⚠️ Chưa có code để nhập. Thầy bôi đen câu hỏi trong editor rồi mở Ngân hàng lại.', 'err');
        return;
    }
    const folder = lhlExamBankGetFolder();
    if (!folder) {
        lhlExamBankSetUnifiedStatus('⚠️ Chưa chọn thư mục ngân hàng.', 'err');
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_append_questions_to_file)) {
        lhlExamBankSetUnifiedStatus('❌ Không thấy API ghi file. Thầy cần chạy bản FIX47.', 'err');
        return;
    }
    lhlExamBankSetUnifiedStatus('⏳ Đang nhập ' + code.trim().length + ' ký tự vào ' + filename + '...', 'warn');
    let res = null;
    try { res = await window.pywebview.api.qbank_append_questions_to_file(folder, filename, code); }
    catch(e) {
        lhlExamBankSetUnifiedStatus('❌ Lỗi gọi Python API: ' + (e && e.message ? e.message : e), 'err');
        return;
    }
    if (res && res.ok) {
        await lhlExamBankRefreshFiles();
        lhlExamBankSetUnifiedStatus('✅ Đã nhập vào ' + filename + '. Tổng số câu: ' + res.count + '. Đã thêm ' + (res.added_chars || code.length) + ' ký tự.', 'ok');
    } else {
        lhlExamBankSetUnifiedStatus('❌ Lỗi nhập câu: ' + ((res && res.error) || 'Không rõ lỗi'), 'err');
    }
}

async function lhlExamBankResetFileQuestions(filename) {
    const ok = await lhlExamBankConfirm('Reset câu hỏi', 'Thầy chắc muốn xóa hết câu hỏi trong file <b>' + lhlQBankEscapeHtml(filename) + '</b> không?', 'Reset câu', true);
    if (!ok) return;
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_reset_file_questions)) {
        lhlExamBankSetUnifiedStatus('❌ Chưa có API reset file NH.', 'err');
        return;
    }
    const res = await window.pywebview.api.qbank_reset_file_questions(folder, filename);
    if (res && res.ok) {
        await lhlExamBankRefreshFiles();
        lhlExamBankSetUnifiedStatus('✅ Đã xóa hết câu hỏi trong ' + filename, 'ok');
    } else {
        lhlExamBankSetUnifiedStatus('❌ Lỗi reset file: ' + ((res && res.error) || 'Không rõ lỗi'), 'err');
    }
}

async function lhlExamBankDelete(filename) {
    const ok = await lhlExamBankConfirm('Xóa file ngân hàng', 'Thầy chắc muốn xóa file <b>' + lhlQBankEscapeHtml(filename) + '</b> khỏi ngân hàng không?', 'Xóa file', true);
    if (!ok) return;
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_delete_file)) return;
    const res = await window.pywebview.api.qbank_delete_file(folder, filename);
    if (res && res.ok) {
        await lhlExamBankRenumberFilesOnly(false);
        await lhlExamBankRefreshFiles();
        lhlExamBankSetUnifiedStatus('🗑️ Đã xóa file ' + filename + ' và cập nhật lại số lượng file.', 'ok');
    } else {
        lhlExamBankSetUnifiedStatus('❌ Lỗi xóa file: ' + ((res && res.error) || 'Không rõ lỗi'), 'err');
    }
}

// Xem nhanh bằng iframe srcdoc để gần giống trình duyệt/preview bên ngoài hơn.
async function lhlExamBankView(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        lhlExamBankSetUnifiedStatus('❌ Không đọc được file: ' + ((res && res.error) || ''), 'err');
        return;
    }
    const modal = document.getElementById('qbankPreview');
    const body = document.getElementById('qbankPreviewBody');
    if (!modal || !body) return;
    const raw = String(res.content || '');
    const bodyOnly = String(res.body || ((typeof lhlExamBankPrettyBodyOnly === 'function') ? lhlExamBankPrettyBodyOnly(raw) : raw));
    const count = lhlExamBankQuestionCountInHtml ? lhlExamBankQuestionCountInHtml(bodyOnly) : 0;
    body.innerHTML = `
    <div class="qbank-view-fixed">
        <div class="qbank-code-title">${lhlQBankEscapeHtml(filename)} - Mã code nội dung (${count} câu)</div>
        <textarea readonly>${bodyOnly.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea>
    </div>
    <div class="qbank-code-title">Biên dịch nhanh</div>
    <iframe class="qbank-preview-iframe"></iframe>`;
    modal.style.display = 'flex';
    const styleId = 'lhl-fix47-qbank-view-style';
    if (!document.getElementById(styleId)) {
        const st = document.createElement('style');
        st.id = styleId;
        st.textContent = `
        .qbank-preview-box{display:flex!important;flex-direction:column!important;max-height:90vh!important;overflow:hidden!important;width:min(1080px,calc(100% - 34px))!important;}
        #qbankPreviewBody{display:flex!important;flex-direction:column!important;min-height:0!important;overflow:hidden!important;}
        .qbank-view-fixed{flex:0 0 auto!important;}
        .qbank-view-fixed textarea{height:110px!important;max-height:110px!important;overflow:auto!important;background:#161616!important;color:#f5f5f5!important;border:1px solid #666!important;border-radius:5px!important;padding:8px!important;font-family:Consolas,monospace!important;font-size:13px!important;line-height:1.35!important;}
        .qbank-preview-iframe{flex:1 1 auto!important;min-height:430px!important;width:100%!important;border:1px solid #aaa!important;border-radius:6px!important;background:#fff!important;}
        `;
        document.head.appendChild(st);
    }
    const iframe = body.querySelector('.qbank-preview-iframe');
    if (iframe) iframe.srcdoc = raw;
}

// Sửa file: mở tab rồi cố gắng phục hồi tỉ lệ panel, tránh bị co giao diện.
async function lhlExamBankEdit(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        lhlExamBankSetUnifiedStatus('❌ Không đọc được file để sửa.', 'err');
        return;
    }
    if (typeof createOrReplaceTab === 'function') {
        createOrReplaceTab(filename, String(res.content || ''), null);
    } else {
        const editor = document.getElementById('editor');
        if (editor) editor.value = String(res.content || '');
    }
    setTimeout(() => {
        try {
            const left = document.querySelector('.editor-pane') || document.getElementById('leftPane') || document.getElementById('editor-container');
            const right = document.querySelector('.preview-pane') || document.getElementById('rightPane') || document.getElementById('paper');
            if (left) { left.style.minWidth = ''; left.style.width = ''; }
            if (right) { right.style.minWidth = ''; right.style.width = ''; }
            window.dispatchEvent(new Event('resize'));
        } catch(e) {}
    }, 120);
    lhlExamBankSetUnifiedStatus('📝 Đã mở ' + filename + ' vào tab để thầy xem/sửa.', 'ok');
}

// Event delegation chắc chắn cho mọi nút action trong NH.
if (!window.__lhlFix47BankClickDelegate) {
    window.__lhlFix47BankClickDelegate = true;
    document.addEventListener('click', function(e) {
        const btn = e.target && e.target.closest ? e.target.closest('#qbankOverlay button[data-action]') : null;
        if (!btn) return;
        const action = btn.getAttribute('data-action');
        const filename = btn.getAttribute('data-file');
        if (!action || !filename) return;
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        if (action === 'append') return void lhlExamBankAppend(filename);
        if (action === 'resetfile') return void lhlExamBankResetFileQuestions(filename);
        if (action === 'view') return void lhlExamBankView(filename);
        if (action === 'edit') return void lhlExamBankEdit(filename);
        if (action === 'delete') return void lhlExamBankDelete(filename);
    }, true);
}



// ============================================================
// FIX48-NH: sửa reset câu bị chặn, xem nhanh bỏ tiêu đề thừa, sửa không co giao diện,
// bỏ thanh cuộn ngoài hộp thoại: cố định phần trên, chỉ cuộn danh sách file.
// ============================================================

function lhlExamBankCleanBodyForView(html) {
    let s = String(html || '');
    const m = s.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    if (m) s = m[1];
    s = s.replace(/<script\b[\s\S]*?<\/script>/gi, '');
    s = s.replace(/<style\b[\s\S]*?<\/style>/gi, '');
    s = s.replace(/<!--\s*LHL_QBANK_FILE:[\s\S]*?-->/gi, '');
    s = s.replace(/<h[1-6][^>]*class=["'][^"']*qbank-doc-title[^"']*["'][^>]*>[\s\S]*?<\/h[1-6]>/gi, '');
    s = s.replace(/<!--\s*LHL_QBANK_APPEND\s*-->/gi, '');
    s = s.replace(/<table\b(?=[^>]*class=["'][^"']*FontDung[^"']*["'])[^>]*>\s*<tbody>\s*<tr>\s*<td>\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi, '');
    return s.trim();
}

function lhlExamBankApplyFixedDialogLayout() {
    const styleId = 'lhl-fix48-qbank-fixed-dialog-layout';
    if (!document.getElementById(styleId)) {
        const st = document.createElement('style');
        st.id = styleId;
        st.textContent = `
        #qbankOverlay .qbank-box{
            height: min(94vh, 900px) !important;
            max-height: min(94vh, 900px) !important;
            overflow: hidden !important;
        }
        #qbankOverlay .qbank-body{
            display: flex !important;
            flex-direction: column !important;
            overflow: hidden !important;
            min-height: 0 !important;
            flex: 1 1 auto !important;
        }
        #examBankFileList{
            flex: 1 1 auto !important;
            min-height: 0 !important;
            overflow: auto !important;
            max-height: none !important;
        }
        #qbankOverlay .exam-bank-actions button{
            font-size: 12px !important;
            padding: 6px 7px !important;
        }
        `;
        document.head.appendChild(st);
    }
}

// Ghi đè refresh: nút Reset câu không dùng data-action để tránh listener cũ chặn.
async function lhlExamBankRefreshFiles() {
    const box = document.getElementById('examBankFileList');
    if (!box) return;
    lhlExamBankApplyFixedDialogLayout();

    const folder = lhlExamBankGetFolder();
    const folderEl = document.getElementById('examBankFolderPath');
    if (folderEl) folderEl.textContent = folder || 'Chưa chọn thư mục ngân hàng';
    if (!folder) {
        box.innerHTML = '<div class="qbank-empty">Chưa có thư mục NH. Thầy nhập số câu TN/Đ-S/TLN rồi bấm <b>OK khởi tạo</b>.</div>';
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_list_exam_folder)) {
        box.innerHTML = '<div class="qbank-empty">Chức năng này cần chạy trong phần mềm desktop.</div>';
        return;
    }
    let res = null;
    try { res = await window.pywebview.api.qbank_list_exam_folder(folder); }
    catch(e) {
        box.innerHTML = '<div class="qbank-empty">Lỗi gọi API đọc thư mục NH: ' + lhlQBankEscapeHtml(e && e.message ? e.message : e) + '</div>';
        return;
    }
    if (!res || !res.ok) {
        box.innerHTML = '<div class="qbank-empty">Không đọc được thư mục NH: ' + lhlQBankEscapeHtml((res && res.error) || '') + '</div>';
        return;
    }
    const files = res.files || [];
    if (typeof lhlExamBankUpdateTopCountsFromFiles === 'function') lhlExamBankUpdateTopCountsFromFiles(files);

    if (!files.length) {
        box.innerHTML = '<div class="qbank-empty">Thư mục chưa có file TN-*, DS-*, TLN-*.</div>';
        return;
    }

    const groups = { 'TN': [], 'Đ/S': [], 'TLN': [] };
    files.forEach(f => {
        const p = lhlExamBankFilePart(f.filename);
        if (!groups[p]) groups[p] = [];
        groups[p].push(f);
    });

    let html = '';
    ['TN','Đ/S','TLN'].forEach(part => {
        if (!groups[part] || !groups[part].length) return;
        const title = (typeof lhlExamBankGroupTitle === 'function') ? lhlExamBankGroupTitle(part) : part;
        html += `<div class="exam-bank-group"><div class="exam-bank-group-title">${lhlQBankEscapeHtml(title)}</div>`;
        groups[part].forEach(f => {
            const safeFile = lhlQBankEscapeHtml(f.filename);
            const jsFile = String(f.filename).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
            html += `<div class="exam-bank-file" data-file="${safeFile}" style="grid-template-columns:34px 1fr 86px 82px 310px;">
                <div style="text-align:center;"><input class="exam-bank-pick-check" type="checkbox" title="Chọn file này để rút câu"></div>
                <div class="exam-bank-file-name"><b>${lhlQBankEscapeHtml(lhlExamBankLabel(f.filename))}</b><span>${safeFile}</span></div>
                <div class="exam-bank-count">Số câu: <b>${f.count || 0}</b></div>
                <div class="exam-bank-pick-box" style="display:flex;align-items:center;gap:4px;justify-content:center;color:#e8f5e9;font-size:12px;">
                    <span class="qbank-pick-label">Chọn/đề</span><input class="exam-bank-pick-count" type="number" min="1" value="1" style="width:40px;height:25px;background:#111;color:#fff;border:1px solid #4caf50;border-radius:4px;text-align:center;font-weight:800;">
                </div>
                <div class="exam-bank-actions">
                    <button type="button" data-action="append" data-file="${safeFile}">Nhập</button>
                    <button type="button" onclick="event.preventDefault(); event.stopPropagation(); lhlExamBankResetFileQuestions('${jsFile}');" style="background:#ef6c00;">Reset câu</button>
                    <button type="button" data-action="view" data-file="${safeFile}">Xem</button>
                    <button type="button" data-action="edit" data-file="${safeFile}">Sửa</button>
                    <button type="button" class="danger" data-action="delete" data-file="${safeFile}">Xóa</button>
                </div>
            </div>`;
        });
        html += '</div>';
    });
    box.innerHTML = html;
}

// Reset câu từng file: không phụ thuộc data-action.
async function lhlExamBankResetFileQuestions(filename) {
    const ok = await lhlExamBankConfirm('Reset câu hỏi', 'Thầy chắc muốn xóa hết câu hỏi trong file <b>' + lhlQBankEscapeHtml(filename) + '</b> không?', 'Reset câu', true);
    if (!ok) return;
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_reset_file_questions)) {
        lhlExamBankSetUnifiedStatus ? lhlExamBankSetUnifiedStatus('❌ Chưa có API reset file NH.', 'err') : showToast('❌ Chưa có API reset file NH.');
        return;
    }
    let res = null;
    try { res = await window.pywebview.api.qbank_reset_file_questions(folder, filename); }
    catch(e) {
        lhlExamBankSetUnifiedStatus ? lhlExamBankSetUnifiedStatus('❌ Lỗi reset file: ' + (e.message || e), 'err') : showToast('❌ Lỗi reset file.');
        return;
    }
    if (res && res.ok) {
        await lhlExamBankRefreshFiles();
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('✅ Đã xóa hết câu hỏi trong ' + filename, 'ok');
        else showToast('✅ Đã reset câu.');
    } else {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Lỗi reset file: ' + ((res && res.error) || 'Không rõ lỗi'), 'err');
        else showToast('❌ Lỗi reset file.');
    }
}

// Xem nhanh: iframe srcdoc nhưng dùng body đã làm sạch, không hiện TN-1 thừa/ô chữ nhật rỗng.
async function lhlExamBankView(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Không đọc được file: ' + ((res && res.error) || ''), 'err');
        return;
    }
    const modal = document.getElementById('qbankPreview');
    const body = document.getElementById('qbankPreviewBody');
    if (!modal || !body) return;
    const raw = String(res.content || '');
    const bodyOnly = lhlExamBankCleanBodyForView(res.body || raw);
    const count = lhlExamBankQuestionCountInHtml ? lhlExamBankQuestionCountInHtml(bodyOnly) : 0;

    const title = String(filename || '').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const srcdoc = `<!DOCTYPE html>
<html><head><meta charset="UTF-8">
<script>
window.MathJax={tex:{inlineMath:[['$','$'],['\\\\(','\\\\)']],displayMath:[['$$','$$'],['\\\\[','\\\\]']]},options:{enableMenu:false}};
</script>
<script async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
<style>
body{margin:22px auto;max-width:820px;font-family:"Times New Roman",Times,serif;font-size:18px;line-height:1.35;color:#000;background:#fff;}
.choices{display:grid;gap:6px 22px;margin:8px 0 10px 0;}
.choices.cols-4{grid-template-columns:repeat(4,1fr);}
.choices.cols-2{grid-template-columns:repeat(2,1fr);}
.choice{break-inside:avoid;}
.choice label{display:block;}
table{border-collapse:collapse;margin:10px auto;text-align:center;}
td,th{border:1px solid #555;padding:4px 8px;}
table.FontDung{display:none!important;}
img{max-width:100%;height:auto;}
.immini-wrap{display:flex;align-items:flex-start;gap:var(--immini-gap,6px);margin:4px 0 8px 0;}
.immini-text{flex:1 1 auto;min-width:0;}
.immini-figure{flex:0 0 var(--immini-figure-col,26%);text-align:right;}
</style></head><body>${bodyOnly}</body></html>`;

    body.innerHTML = `
    <div class="qbank-view-fixed">
        <div class="qbank-code-title">${title} - Mã code nội dung (${count} câu)</div>
        <textarea readonly>${bodyOnly.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea>
    </div>
    <div class="qbank-code-title">Biên dịch nhanh</div>
    <iframe class="qbank-preview-iframe"></iframe>`;
    modal.style.display = 'flex';

    const styleId = 'lhl-fix48-qbank-view-style';
    if (!document.getElementById(styleId)) {
        const st = document.createElement('style');
        st.id = styleId;
        st.textContent = `
        .qbank-preview-box{display:flex!important;flex-direction:column!important;max-height:90vh!important;overflow:hidden!important;width:min(1080px,calc(100% - 34px))!important;}
        #qbankPreviewBody{display:flex!important;flex-direction:column!important;min-height:0!important;overflow:hidden!important;}
        .qbank-view-fixed{flex:0 0 auto!important;}
        .qbank-view-fixed textarea{height:105px!important;max-height:105px!important;overflow:auto!important;background:#161616!important;color:#f5f5f5!important;border:1px solid #666!important;border-radius:5px!important;padding:8px!important;font-family:Consolas,monospace!important;font-size:13px!important;line-height:1.35!important;}
        .qbank-preview-iframe{flex:1 1 auto!important;min-height:430px!important;width:100%!important;border:1px solid #aaa!important;border-radius:6px!important;background:#fff!important;}
        `;
        document.head.appendChild(st);
    }
    const iframe = body.querySelector('.qbank-preview-iframe');
    if (iframe) iframe.srcdoc = srcdoc;
}

// Sửa file: chỉ mở phần BODY để không kéo CSS/HTML làm co giao diện.
async function lhlExamBankEdit(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Không đọc được file để sửa.', 'err');
        return;
    }
    const bodyOnly = lhlExamBankCleanBodyForView(res.body || res.content || '');
    if (typeof createOrReplaceTab === 'function') createOrReplaceTab(filename, bodyOnly, null);
    else {
        const editor = document.getElementById('editor');
        if (editor) editor.value = bodyOnly;
    }
    setTimeout(() => {
        try {
            window.dispatchEvent(new Event('resize'));
            if (typeof updatePreview === 'function') updatePreview();
        } catch(e) {}
    }, 120);
    if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('📝 Đã mở nội dung ' + filename + ' vào tab để thầy sửa, không kéo theo CSS/head.', 'ok');
}

// Bọc mở dialog để áp dụng layout cố định và nút làm mới đúng.
if (typeof openQuestionBankDialog === 'function' && !window.__lhlFix48WrappedOpenQuestionBankDialog) {
    window.__lhlFix48WrappedOpenQuestionBankDialog = true;
    const __oldOpenQuestionBankDialogFix48 = openQuestionBankDialog;
    openQuestionBankDialog = function() {
        const ret = __oldOpenQuestionBankDialogFix48.apply(this, arguments);
        setTimeout(() => {
            lhlExamBankApplyFixedDialogLayout();
            const body = document.querySelector('#qbankOverlay .qbank-body');
            if (!body) return;
            const refreshBtns = Array.from(body.querySelectorAll('button')).filter(b => /Làm mới danh sách/i.test(b.textContent || ''));
            refreshBtns.forEach(b => {
                b.onclick = function(ev){ ev.preventDefault(); lhlExamBankRefreshButton(); };
            });
        }, 150);
        return ret;
    };
}



