// ============================================================
// FIX50-NH: Đổi hộp xác nhận "Xóa toàn bộ câu hỏi" sang hộp thoại đẹp
// Không dùng confirm() mặc định của trình duyệt nữa.
// ============================================================
async function lhlExamBankClearAllQuestions() {
    let ok = true;
    if (typeof lhlExamBankConfirm === 'function') {
        ok = await lhlExamBankConfirm(
            'Xóa toàn bộ câu hỏi',
            'Thầy chắc muốn <b>XÓA HẾT câu hỏi</b> trong <b>TẤT CẢ file ngân hàng</b> không?<br><br>Các file TN/Đ-S/TLN vẫn được giữ lại, chỉ xóa nội dung câu hỏi bên trong.',
            'Xóa toàn bộ',
            true
        );
    } else {
        ok = confirm('Thầy chắc muốn XÓA HẾT câu hỏi trong TẤT CẢ file ngân hàng không?');
    }
    if (!ok) return;

    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_clear_all_questions)) {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') {
            lhlExamBankSetUnifiedStatus('❌ Chưa có API xóa toàn bộ NH.', 'err');
        } else {
            showToast('❌ Chưa có API xóa toàn bộ NH.');
        }
        return;
    }

    let res = null;
    try {
        res = await window.pywebview.api.qbank_clear_all_questions(folder);
    } catch(e) {
        const msg = e && e.message ? e.message : String(e);
        if (typeof lhlExamBankSetUnifiedStatus === 'function') {
            lhlExamBankSetUnifiedStatus('❌ Lỗi xóa toàn bộ: ' + msg, 'err');
        } else {
            showToast('❌ Lỗi xóa toàn bộ.');
        }
        return;
    }

    if (res && res.ok) {
        await lhlExamBankRefreshFiles();
        if (typeof lhlExamBankSetUnifiedStatus === 'function') {
            lhlExamBankSetUnifiedStatus('🗑️ Đã xóa hết câu hỏi trong ' + (res.files || 0) + ' file NH.', 'ok');
        } else {
            showToast('🗑️ Đã xóa hết câu hỏi trong ' + (res.files || 0) + ' file NH.');
        }
    } else {
        const msg = (res && res.error) || 'Không rõ lỗi';
        if (typeof lhlExamBankSetUnifiedStatus === 'function') {
            lhlExamBankSetUnifiedStatus('❌ Lỗi xóa toàn bộ: ' + msg, 'err');
        } else {
            showToast('❌ Lỗi xóa toàn bộ: ' + msg);
        }
    }
}



// ============================================================
// FIX51-NH: sửa tiếp ngân hàng
// 1) Xem nhanh câu có hình: bỏ khung viền bao hình/bảng rỗng.
// 2) Sửa file NH rồi bấm Lưu File sẽ lưu đè về file gốc.
// 3) Xóa toàn bộ: chọn xóa file hoặc chỉ xóa câu hỏi.
// 4) Thêm thống kê tổng số câu toàn NH/TN/ĐS/TLN.
// ============================================================
window.__lhlQBankEditingFile = window.__lhlQBankEditingFile || null;
window.__lhlQBankEditingFolder = window.__lhlQBankEditingFolder || null;

function lhlQBankInstallFix51Style() {
    const id = 'lhl-fix51-qbank-style';
    if (document.getElementById(id)) return;
    const st = document.createElement('style');
    st.id = id;
    st.textContent = `
    .qbank-choice-modal {
        position: fixed; inset: 0; z-index: 210000;
        background: rgba(0,0,0,.66);
        display: flex; align-items: center; justify-content: center;
        font-family: "Segoe UI", Tahoma, Arial, sans-serif;
    }
    .qbank-choice-box {
        width: min(620px, calc(100% - 40px));
        background:#2d2d30; color:#fff;
        border:1px solid #4caf50; border-radius:10px;
        box-shadow:0 20px 50px rgba(0,0,0,.78);
        overflow:hidden;
    }
    .qbank-choice-title {
        padding:14px 18px; font-size:20px; font-weight:900;
        color:#81c784; border-bottom:1px solid rgba(255,255,255,.14);
    }
    .qbank-choice-body { padding:16px 18px; font-size:15px; line-height:1.45; }
    .qbank-choice-actions {
        display:flex; justify-content:flex-end; gap:10px;
        padding:12px 18px; background:#242426;
    }
    .qbank-choice-actions button {
        border:0; border-radius:7px; padding:9px 14px;
        font-weight:900; color:#fff; cursor:pointer;
    }
    .qbank-choice-actions .blue{background:#0277bd;}
    .qbank-choice-actions .red{background:#c62828;}
    .qbank-choice-actions .green{background:#2e7d32;}
    .qbank-choice-actions .gray{background:#546e7a;}
    `;
    document.head.appendChild(st);
}

function lhlQBankChoiceDialog(title, message, actions) {
    lhlQBankInstallFix51Style();
    return new Promise(resolve => {
        const old = document.getElementById('qbankChoiceModal');
        if (old) old.remove();
        const div = document.createElement('div');
        div.id = 'qbankChoiceModal';
        div.className = 'qbank-choice-modal';
        const buttons = (actions || []).map(a => `<button class="${a.cls || 'blue'}" data-value="${a.value}">${a.label}</button>`).join('');
        div.innerHTML = `
        <div class="qbank-choice-box">
          <div class="qbank-choice-title">${title}</div>
          <div class="qbank-choice-body">${message}</div>
          <div class="qbank-choice-actions">
            ${buttons}
            <button class="gray" data-value="cancel">Hủy</button>
          </div>
        </div>`;
        document.body.appendChild(div);
        div.addEventListener('click', e => {
            const btn = e.target.closest('button[data-value]');
            if (!btn) return;
            const val = btn.getAttribute('data-value');
            div.remove();
            resolve(val);
        });
    });
}

// Xem nhanh: bỏ viền bao hình/bảng hình và dùng body sạch.
async function lhlExamBankView(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Không đọc được file: ' + ((res && res.error) || ''), 'err');
        return;
    }
    const modal = document.getElementById('qbankPreview');
    const body = document.getElementById('qbankPreviewBody');
    if (!modal || !body) return;
    const raw = String(res.content || '');
    let bodyOnly = '';
    if (typeof lhlExamBankCleanBodyForView === 'function') bodyOnly = lhlExamBankCleanBodyForView(res.body || raw);
    else if (typeof lhlExamBankPrettyBodyOnly === 'function') bodyOnly = lhlExamBankPrettyBodyOnly(res.body || raw);
    else bodyOnly = String(res.body || raw);

    // Loại bảng FontDung rỗng/khung bao rỗng gây viền xấu quanh hình.
    bodyOnly = bodyOnly
      .replace(/<table\b(?=[^>]*class=["'][^"']*FontDung[^"']*["'])[^>]*>\s*<tbody>\s*<tr>\s*<td>\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi, '')
      .replace(/<table\b([^>]*)>\s*<tbody>\s*<tr>\s*<td([^>]*)>\s*(<img\b[\s\S]*?>)\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi, '<div class="qbank-img-wrap">$3</div>');

    const count = lhlExamBankQuestionCountInHtml ? lhlExamBankQuestionCountInHtml(bodyOnly) : 0;
    const title = String(filename || '').replace(/</g,'&lt;').replace(/>/g,'&gt;');

    const srcdoc = `<!DOCTYPE html>
<html><head><meta charset="UTF-8">
<script>
window.MathJax={tex:{inlineMath:[['$','$'],['\\\\(','\\\\)']],displayMath:[['$$','$$'],['\\\\[','\\\\]']]},options:{enableMenu:false}};
</script>
<script async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
<style>
body{margin:22px auto;max-width:820px;font-family:"Times New Roman",Times,serif;font-size:18px;line-height:1.35;color:#000;background:#fff;}
.choices{display:grid;gap:6px 22px;margin:8px 0 10px 0;}
.choices.cols-4{grid-template-columns:repeat(4,1fr);}
.choices.cols-2{grid-template-columns:repeat(2,1fr);}
.choice{break-inside:avoid;}
.choice label{display:block;}
table{border-collapse:collapse;margin:10px auto;text-align:center;}
td,th{border:1px solid #555;padding:4px 8px;}
table.FontDung{display:none!important;}
.qbank-img-wrap{text-align:center;margin:8px auto;border:0!important;}
.qbank-img-wrap img{max-width:100%;height:auto;border:0!important;outline:0!important;box-shadow:none!important;}
img{max-width:100%;height:auto;border:0;outline:0;box-shadow:none;}
.immini-wrap{display:flex;align-items:flex-start;gap:var(--immini-gap,6px);margin:4px 0 8px 0;}
.immini-text{flex:1 1 auto;min-width:0;}
.immini-figure{flex:0 0 var(--immini-figure-col,26%);text-align:right;}
.immini-figure table,.immini-figure td{border:0!important;}
</style></head><body>${bodyOnly}</body></html>`;

    body.innerHTML = `
    <div class="qbank-view-fixed">
        <div class="qbank-code-title">${title} - Mã code nội dung (${count} câu)</div>
        <textarea readonly>${bodyOnly.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea>
    </div>
    <div class="qbank-code-title">Biên dịch nhanh</div>
    <iframe class="qbank-preview-iframe"></iframe>`;
    modal.style.display = 'flex';
    const iframe = body.querySelector('.qbank-preview-iframe');
    if (iframe) iframe.srcdoc = srcdoc;
}

// Sửa file: mở nội dung body, ghi nhớ file gốc để Lưu File ghi đè.
async function lhlExamBankEdit(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Không đọc được file để sửa.', 'err');
        return;
    }
    let bodyOnly = '';
    if (typeof lhlExamBankCleanBodyForView === 'function') bodyOnly = lhlExamBankCleanBodyForView(res.body || res.content || '');
    else bodyOnly = String(res.body || res.content || '');

    window.__lhlQBankEditingFile = filename;
    window.__lhlQBankEditingFolder = folder;
    if (typeof createOrReplaceTab === 'function') createOrReplaceTab(filename, bodyOnly, null);
    else {
        const editor = document.getElementById('editor');
        if (editor) editor.value = bodyOnly;
    }
    setTimeout(() => {
        try {
            window.dispatchEvent(new Event('resize'));
            if (typeof updatePreview === 'function') updatePreview();
        } catch(e) {}
    }, 120);
    if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('📝 Đã mở ' + filename + ' để sửa. Bấm Lưu File sẽ lưu đè file gốc trong NH.', 'ok');
}

// Bắt nút Lưu File để lưu đè file NH nếu đang sửa từ Ngân hàng.
async function lhlQBankSaveEditingFileIfNeeded() {
    if (!window.__lhlQBankEditingFile || !window.__lhlQBankEditingFolder) return false;
    const editor = document.getElementById('editor');
    const content = editor ? editor.value : '';
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_write_file_content)) {
        showToast('❌ Chưa có API lưu đè file ngân hàng.');
        return true;
    }
    const res = await window.pywebview.api.qbank_write_file_content(window.__lhlQBankEditingFolder, window.__lhlQBankEditingFile, content);
    if (res && res.ok) {
        showToast('✅ Đã lưu đè ' + window.__lhlQBankEditingFile + ' vào ngân hàng. Số câu: ' + res.count);
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('✅ Đã lưu đè ' + window.__lhlQBankEditingFile + ' vào file gốc NH.', 'ok');
        return true;
    } else {
        showToast('❌ Lỗi lưu file NH: ' + ((res && res.error) || 'Không rõ lỗi'));
        return true;
    }
}

// Hook các nút Lưu File/Lưu nếu có. Không chặn Save As.
if (!window.__lhlFix51SaveHook) {
    window.__lhlFix51SaveHook = true;
    document.addEventListener('click', async function(e) {
        const btn = e.target && e.target.closest ? e.target.closest('button') : null;
        if (!btn) return;
        const txt = (btn.textContent || '').trim().toLowerCase();
        const title = (btn.getAttribute('title') || '').toLowerCase();
        const isSaveFile = txt.includes('lưu file') || title.includes('lưu file') || (txt === 'save' || txt === 'lưu');
        const isSaveAs = txt.includes('save as') || title.includes('save as');
        if (isSaveFile && !isSaveAs && window.__lhlQBankEditingFile) {
            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();
            await lhlQBankSaveEditingFileIfNeeded();
        }
    }, true);
}

// Xóa toàn bộ: cho chọn 2 chế độ.
async function lhlExamBankClearAllQuestions() {
    const choice = await lhlQBankChoiceDialog(
        'Xóa toàn bộ ngân hàng',
        'Thầy muốn xóa theo kiểu nào?<br><br><b>1.</b> Xóa toàn bộ file: xóa luôn các file TN/Đ-S/TLN trong thư mục.<br><b>2.</b> Chỉ xóa câu hỏi: giữ lại file, chỉ làm rỗng nội dung câu hỏi.',
        [
            {value:'delete_files', label:'Xóa toàn bộ file', cls:'red'},
            {value:'clear_questions', label:'Chỉ xóa câu hỏi', cls:'green'}
        ]
    );
    if (!choice || choice === 'cancel') return;
    const folder = lhlExamBankGetFolder();

    if (choice === 'delete_files') {
        if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_delete_all_files)) {
            if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Chưa có API xóa toàn bộ file NH.', 'err');
            return;
        }
        const res = await window.pywebview.api.qbank_delete_all_files(folder);
        if (res && res.ok) {
            await lhlExamBankRefreshFiles();
            if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('🗑️ Đã xóa ' + (res.deleted || 0) + ' file ngân hàng.', 'ok');
        } else {
            if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Lỗi xóa file: ' + ((res && res.error) || 'Không rõ lỗi'), 'err');
        }
        return;
    }

    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_clear_all_questions)) {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Chưa có API xóa câu hỏi NH.', 'err');
        return;
    }
    const res = await window.pywebview.api.qbank_clear_all_questions(folder);
    if (res && res.ok) {
        await lhlExamBankRefreshFiles();
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('🗑️ Đã xóa hết câu hỏi trong ' + (res.files || 0) + ' file NH, vẫn giữ file.', 'ok');
    } else {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Lỗi xóa câu hỏi: ' + ((res && res.error) || 'Không rõ lỗi'), 'err');
    }
}

// Thống kê tổng số câu.
async function lhlExamBankShowStats() {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_stats)) {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Chưa có API thống kê NH.', 'err');
        return;
    }
    const res = await window.pywebview.api.qbank_stats(folder);
    if (res && res.ok) {
        const s = res.stats || {};
        const msg = `📊 Tổng số câu: <b>${s.TOTAL || 0}</b> | TN: <b>${s.TN || 0}</b> | Đ/S: <b>${s.DS || 0}</b> | TLN: <b>${s.TLN || 0}</b> | Số file: <b>${s.files || 0}</b>`;
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus(msg, 'ok');
    } else {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Lỗi thống kê: ' + ((res && res.error) || 'Không rõ lỗi'), 'err');
    }
}

// Thêm nút Tổng số câu cạnh Xóa toàn bộ câu hỏi.
if (typeof openQuestionBankDialog === 'function' && !window.__lhlFix51WrappedOpenQuestionBankDialog) {
    window.__lhlFix51WrappedOpenQuestionBankDialog = true;
    const __oldOpenQuestionBankDialogFix51 = openQuestionBankDialog;
    openQuestionBankDialog = function() {
        const ret = __oldOpenQuestionBankDialogFix51.apply(this, arguments);
        setTimeout(() => {
            const body = document.querySelector('#qbankOverlay .qbank-body');
            if (!body) return;
            const clearBtn = document.getElementById('examBankClearAllBtn') || Array.from(body.querySelectorAll('button')).find(b => /Xóa toàn bộ câu hỏi/i.test(b.textContent || ''));
            if (clearBtn && !document.getElementById('examBankStatsBtn')) {
                const statBtn = document.createElement('button');
                statBtn.id = 'examBankStatsBtn';
                statBtn.className = 'exam-bank-btn';
                statBtn.style.marginLeft = '6px';
                statBtn.style.background = 'linear-gradient(#7e57c2,#512da8)';
                statBtn.textContent = '📊 Tổng số câu';
                statBtn.onclick = function(ev){ ev.preventDefault(); lhlExamBankShowStats(); };
                clearBtn.insertAdjacentElement('afterend', statBtn);
            }
        }, 180);
        return ret;
    };
}



