// Ghi đè Sửa: mở tab, ghi nhớ file gốc, đóng hộp thoại NH.
async function lhlExamBankEdit(filename) {
    const folder = lhlExamBankGetFolder();
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_read_file)) return;
    const res = await window.pywebview.api.qbank_read_file(folder, filename);
    if (!res || !res.ok) {
        if (typeof lhlExamBankSetUnifiedStatus === 'function') lhlExamBankSetUnifiedStatus('❌ Không đọc được file để sửa.', 'err');
        return;
    }
    let bodyOnly = '';
    if (typeof lhlExamBankCleanBodyForView === 'function') bodyOnly = lhlExamBankCleanBodyForView(res.body || res.content || '');
    else bodyOnly = String(res.body || res.content || '');

    window.__lhlQBankEditingFile = filename;
    window.__lhlQBankEditingFolder = folder;

    if (typeof createOrReplaceTab === 'function') createOrReplaceTab(filename, bodyOnly, null);
    else {
        const editor = document.getElementById('editor');
        if (editor) editor.value = bodyOnly;
    }

    // Gắn metadata trực tiếp vào tab đang mở để nút Lưu File biết lưu đè NH.
    try {
        if (typeof tabs !== 'undefined' && typeof activeTabId !== 'undefined') {
            const tab = tabs.find(t => t.id === activeTabId);
            if (tab) {
                tab.qbankFolder = folder;
                tab.qbankFilename = filename;
                tab.isDirty = true;
            }
        }
    } catch(e) {}

    // Đóng hộp thoại Ngân hàng sau khi mở file lên editor.
    const ov = document.getElementById('qbankOverlay');
    if (ov) ov.remove();

    setTimeout(() => {
        try {
            window.dispatchEvent(new Event('resize'));
            if (typeof updatePreview === 'function') updatePreview();
        } catch(e) {}
    }, 120);
    showToast('📝 Đã mở ' + filename + ' để sửa. Bấm Lưu File sẽ lưu đè file gốc trong NH.');
}

async function lhlQBankSaveEditingFileIfNeeded() {
    let qFile = window.__lhlQBankEditingFile || null;
    let qFolder = window.__lhlQBankEditingFolder || null;

    try {
        if (typeof tabs !== 'undefined' && typeof activeTabId !== 'undefined') {
            const tab = tabs.find(t => t.id === activeTabId);
            if (tab && tab.qbankFilename && tab.qbankFolder) {
                qFile = tab.qbankFilename;
                qFolder = tab.qbankFolder;
            }
        }
    } catch(e) {}

    if (!qFile || !qFolder) return false;

    const editor = document.getElementById('editor');
    const content = editor ? editor.value : '';

    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_write_file_content)) {
        showToast('❌ Chưa có API lưu đè file ngân hàng.');
        return true;
    }

    const res = await window.pywebview.api.qbank_write_file_content(qFolder, qFile, content);
    if (res && res.ok) {
        try {
            if (typeof tabs !== 'undefined' && typeof activeTabId !== 'undefined') {
                const tab = tabs.find(t => t.id === activeTabId);
                if (tab) {
                    tab.isDirty = false;
                    tab.qbankFolder = qFolder;
                    tab.qbankFilename = qFile;
                    tab.content = content;
                    if (typeof renderTabs === 'function') renderTabs();
                }
            }
        } catch(e) {}
        showToast('✅ Đã lưu đè ' + qFile + ' vào ngân hàng. Số câu: ' + res.count);
        return true;
    } else {
        showToast('❌ Lỗi lưu file NH: ' + ((res && res.error) || 'Không rõ lỗi'));
        return true;
    }
}

// Ghi đè performSave ở tầng hàm để Lưu File không gọi Save As khi đang sửa file NH.
if (typeof performSave === 'function' && !window.__lhlFix52PerformSaveWrapped) {
    window.__lhlFix52PerformSaveWrapped = true;
    window.__lhlOldPerformSaveFix52 = performSave;
    performSave = async function() {
        const handled = await lhlQBankSaveEditingFileIfNeeded();
        if (handled) return true;
        return await window.__lhlOldPerformSaveFix52.apply(this, arguments);
    };
}

// Bắt nút Lưu File lần nữa ở capture để tránh nhánh Save As cũ.
if (!window.__lhlFix52SaveClickHook) {
    window.__lhlFix52SaveClickHook = true;
    document.addEventListener('click', async function(e) {
        const btn = e.target && e.target.closest ? e.target.closest('button') : null;
        if (!btn) return;
        const text = (btn.textContent || '').trim().toLowerCase();
        const title = (btn.getAttribute('title') || '').toLowerCase();
        const isSaveFile = text.includes('lưu file') || title.includes('lưu lại toàn bộ nội dung');
        if (isSaveFile && (window.__lhlQBankEditingFile || (typeof tabs !== 'undefined' && typeof activeTabId !== 'undefined' && (tabs.find(t=>t.id===activeTabId)||{}).qbankFilename))) {
            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();
            await lhlQBankSaveEditingFileIfNeeded();
        }
    }, true);
}



