        if (!preview || preview.style.display === 'none') return;

        const btn = e.target && e.target.closest ? e.target.closest('button') : null;
        if (!btn) return;
        const isClose = /đóng/i.test(btn.textContent || '') && btn.closest('#qbankPreview');
