// ============================================================
// FIX56-NH:
// Thêm nút "Nhập file hiện hành" trong Ngân hàng.
// Tách file đang mở theo PHẦN I/II/III rồi nhập:
//   Phần I  -> TN-1, TN-2, ...
//   Phần II -> DS-1, DS-2, ...
//   Phần III-> TLN-1, TLN-2, ...
// ============================================================
function lhlQBankStripPartTitle(block) {
    let s = String(block || '');
    s = s.replace(/<div[^>]*class=["'][^"']*lhl-part-title[^"']*["'][^>]*>[\s\S]*?<\/div>/i, '');
    s = s.replace(/<h[1-6][^>]*>\s*PHẦN\s*(I|II|III)[\s\S]*?<\/h[1-6]>/i, '');
    s = s.replace(/<[^>]*>\s*PHẦN\s*(I|II|III)[\s\S]{0,180}?<\/[^>]+>/i, '');
    return s.trim();
}

function lhlQBankNormalizePartName(raw) {
    const t = String(raw || '').toUpperCase();
    if (/(PHẦN|PHAN)\s*I(?!I)/.test(t) || /\bPART\s*I(?!I)/.test(t)) return 'TN';
    if (/(PHẦN|PHAN)\s*II(?!I)/.test(t) || /\bPART\s*II(?!I)/.test(t)) return 'DS';
    if (/(PHẦN|PHAN)\s*III/.test(t) || /\bPART\s*III/.test(t)) return 'TLN';
    return '';
}

function lhlQBankFindPartBoundaries(code) {
    const s = String(code || '');
    const regs = [
        {part:'TN', re: /(?:PHẦN|PHAN)\s*I(?!I)[\s\S]{0,260}?(?:một phương án|nhiều phương án|trắc nghiệm|chọn một|chọn 1)/ig},
        {part:'DS', re: /(?:PHẦN|PHAN)\s*II(?!I)[\s\S]{0,260}?(?:đúng[\s,;-]*sai|dung[\s,;-]*sai)/ig},
        {part:'TLN', re: /(?:PHẦN|PHAN)\s*III[\s\S]{0,260}?(?:trả lời ngắn|tra loi ngan|tự luận ngắn|tu luan ngan)/ig},
        {part:'TN', re: /(?:PHẦN|PHAN)\s*I(?!I)/ig},
        {part:'DS', re: /(?:PHẦN|PHAN)\s*II(?!I)/ig},
        {part:'TLN', re: /(?:PHẦN|PHAN)\s*III/ig}
    ];
    const found = [];
    regs.forEach(obj => {
        let m;
        while ((m = obj.re.exec(s)) !== null) {
            found.push({part: obj.part, index: m.index, text: m[0]});
        }
    });
    // lấy mốc đầu tiên cho mỗi phần
    const first = {};
    found.sort((a,b)=>a.index-b.index).forEach(x => {
        if (!first[x.part]) first[x.part] = x;
    });
    const arr = Object.values(first).sort((a,b)=>a.index-b.index);
    return arr;
}

function lhlQBankSplitPartsFromCurrentCode(code) {
    const s = String(code || '');
    const bounds = lhlQBankFindPartBoundaries(s);
    const parts = {TN:'', DS:'', TLN:''};

    if (bounds.length) {
        for (let i=0; i<bounds.length; i++) {
            const cur = bounds[i];
            const next = bounds[i+1];
            parts[cur.part] = s.slice(cur.index, next ? next.index : s.length).trim();
        }
    } else {
        // fallback: không thấy tiêu đề phần thì coi toàn bộ là TN
        parts.TN = s.trim();
    }

    return parts;
}

function lhlQBankSplitQuestionsInPart(partCode) {
    let s = lhlQBankStripPartTitle(partCode || '');
    if (!s.trim()) return [];

    // Tách theo nhãn câu. Giữ nhãn câu trong từng block.
    const re = /(<b>\s*)?Câu\s*\d+\s*[\.:]?\s*(<\/b>)?/ig;
    const matches = [];
    let m;
    while ((m = re.exec(s)) !== null) {
        matches.push({index:m.index, text:m[0]});
    }
    if (!matches.length) {
        return s.trim() ? [s.trim()] : [];
    }

    const qs = [];
    for (let i=0; i<matches.length; i++) {
        const start = matches[i].index;
        const end = (i+1 < matches.length) ? matches[i+1].index : s.length;
        const block = s.slice(start, end).trim();
        if (block) qs.push(block);
    }
    return qs;
}

function lhlQBankBuildImportItemsFromCurrentEditor() {
    const editor = document.getElementById('editor');
    const code = editor ? editor.value : '';
    const parts = lhlQBankSplitPartsFromCurrentCode(code);
    const items = [];
    const summary = {TN:0, DS:0, TLN:0};

    [['TN','TN'], ['DS','DS'], ['TLN','TLN']].forEach(([part, prefix]) => {
        const qs = lhlQBankSplitQuestionsInPart(parts[part] || '');
        summary[part] = qs.length;
        qs.forEach((q, idx) => {
            items.push({filename: `${prefix}-${idx+1}.html`, code: q});
        });
    });

    return {items, summary};
}

async function lhlExamBankImportCurrentFile() {
    const folder = lhlExamBankGetFolder();
    if (!folder) {
        lhlExamBankSetUnifiedStatus ? lhlExamBankSetUnifiedStatus('⚠️ Chưa chọn thư mục ngân hàng.', 'err') : showToast('⚠️ Chưa chọn thư mục ngân hàng.');
        return;
    }
    const data = lhlQBankBuildImportItemsFromCurrentEditor();
    const items = data.items || [];
    const sm = data.summary || {};
    if (!items.length) {
        lhlExamBankSetUnifiedStatus ? lhlExamBankSetUnifiedStatus('⚠️ File hiện hành chưa có câu hỏi để nhập.', 'err') : showToast('⚠️ File hiện hành chưa có câu hỏi để nhập.');
        return;
    }

    let ok = true;
    if (typeof lhlExamBankConfirm === 'function') {
        ok = await lhlExamBankConfirm(
            'Nhập file hiện hành',
            `Phần mềm sẽ nhập file đang mở vào ngân hàng:<br><br>
            TN: <b>${sm.TN || 0}</b> câu → TN-1, TN-2,...<br>
            Đ/S: <b>${sm.DS || 0}</b> câu → DS-1, DS-2,...<br>
            TLN: <b>${sm.TLN || 0}</b> câu → TLN-1, TLN-2,...<br><br>
            Các câu sẽ được <b>thêm vào</b> file ngân hàng hiện có.`,
            'Nhập ngay',
            false
        );
    } else {
        ok = confirm(`Nhập file hiện hành vào ngân hàng?\nTN: ${sm.TN||0}, Đ/S: ${sm.DS||0}, TLN: ${sm.TLN||0}`);
    }
    if (!ok) return;

    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_bulk_append_questions)) {
        // fallback gọi từng file nếu API bulk chưa có
        let okCount = 0, errCount = 0;
        for (const it of items) {
            const res = await window.pywebview.api.qbank_append_questions_to_file(folder, it.filename, it.code);
            if (res && res.ok) okCount++; else errCount++;
        }
        await lhlExamBankRefreshFiles();
        lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus(`✅ Đã nhập file hiện hành: thành công ${okCount}, lỗi ${errCount}.`, errCount ? 'err' : 'ok');
        return;
    }

    lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus('⏳ Đang nhập file hiện hành vào ngân hàng...', 'warn');
    const res = await window.pywebview.api.qbank_bulk_append_questions(folder, items);
    await lhlExamBankRefreshFiles();
    if (res && (res.ok || res.ok_count > 0)) {
        lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus(
            `✅ Đã nhập file hiện hành. Thành công: <b>${res.ok_count || 0}</b>, lỗi: <b>${res.err_count || 0}</b>. ` +
            `TN: ${sm.TN || 0}, Đ/S: ${sm.DS || 0}, TLN: ${sm.TLN || 0}.`,
            (res.err_count || 0) ? 'err' : 'ok'
        );
    } else {
        lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus('❌ Lỗi nhập file hiện hành: ' + ((res && res.error) || 'Không rõ lỗi'), 'err');
    }
}

// Thêm nút Nhập file hiện hành kế bên nút Tổng số câu.
if (typeof openQuestionBankDialog === 'function' && !window.__lhlFix56WrappedOpenQuestionBankDialog) {
    window.__lhlFix56WrappedOpenQuestionBankDialog = true;
    const __oldOpenQuestionBankDialogFix56 = openQuestionBankDialog;
    openQuestionBankDialog = function() {
        const ret = __oldOpenQuestionBankDialogFix56.apply(this, arguments);
        setTimeout(() => {
            const body = document.querySelector('#qbankOverlay .qbank-body');
            if (!body) return;

            let statsBtn = document.getElementById('examBankStatsBtn');
            if (!statsBtn) {
                const clearBtn = document.getElementById('examBankClearAllBtn') || Array.from(body.querySelectorAll('button')).find(b => /Xóa toàn bộ câu hỏi/i.test(b.textContent || ''));
                if (clearBtn) {
                    statsBtn = document.createElement('button');
                    statsBtn.id = 'examBankStatsBtn';
                    statsBtn.className = 'exam-bank-btn';
                    statsBtn.style.marginLeft = '6px';
                    statsBtn.style.background = 'linear-gradient(#7e57c2,#512da8)';
                    statsBtn.textContent = '📊 Tổng số câu';
                    statsBtn.onclick = function(ev){ ev.preventDefault(); lhlExamBankShowStats(); };
                    clearBtn.insertAdjacentElement('afterend', statsBtn);
                }
            }

            if (statsBtn && !document.getElementById('examBankImportCurrentBtn')) {
                const btn = document.createElement('button');
                btn.id = 'examBankImportCurrentBtn';
                btn.className = 'exam-bank-btn';
                btn.style.marginLeft = '6px';
                btn.style.background = 'linear-gradient(#009688,#00695c)';
                btn.textContent = '📥 Nhập file hiện hành';
                btn.onclick = function(ev){ ev.preventDefault(); lhlExamBankImportCurrentFile(); };
                statsBtn.insertAdjacentElement('afterend', btn);
            }
        }, 220);
        return ret;
    };
}



// ============================================================
// FIX57-NH:
// Sửa "Nhập file hiện hành" bị đếm dư câu.
// - Không bắt nhầm chữ "câu" trong tiêu đề phần.
// - Ưu tiên tách theo <div class="lhl-mix-question-block"> nếu có.
// - Chỉ nhận nhãn "Câu ..." viết hoa đúng dạng câu hỏi.
// - Chỉ nhập vào file đã tồn tại trong NH; không tự tạo thêm file.
// ============================================================
function lhlQBankGetExistingFileSetFromDialog() {
    const set = new Set();
    document.querySelectorAll('#examBankFileList .exam-bank-file[data-file]').forEach(row => {
        const f = (row.getAttribute('data-file') || '').trim();
        if (f) set.add(f.toLowerCase());
    });
    return set;
}

function lhlQBankRemovePartHeaderStrict(block) {
    let s = String(block || '');
    // Bỏ các tiêu đề phần dạng div/h/b/strong/table row có chữ PHẦN...
    s = s.replace(/<div[^>]*class=["'][^"']*(?:part|section|lhl-part-title)[^"']*["'][^>]*>[\s\S]*?<\/div>/ig, '');
    s = s.replace(/<h[1-6][^>]*>\s*(?:PHẦN|PHAN)\s*(?:I|II|III)[\s\S]*?<\/h[1-6]>/ig, '');
    s = s.replace(/<p[^>]*>\s*(?:<[^>]+>\s*)*(?:PHẦN|PHAN)\s*(?:I|II|III)[\s\S]*?<\/p>/ig, '');
    // Bỏ dòng text tiêu đề phần ở đầu block cho tới trước câu hỏi đầu tiên.
    const firstQuestion = s.search(/(?:^|[\n\r]|>|<\/[^>]+>)\s*(?:<b>\s*)?Câu\s+\d+\s*[\.:]?/);
    if (firstQuestion > 0) s = s.slice(firstQuestion).replace(/^[\s>]+/, '');
    return s.trim();
}

function lhlQBankSplitByQuestionBlocks(s) {
    const code = String(s || '').trim();
    if (!code) return [];

    const positions = [];
    const re = /<div\b[^>]*class=["'][^"']*lhl-mix-question-block[^"']*["'][^>]*>/ig;
    let m;
    while ((m = re.exec(code)) !== null) positions.push(m.index);
    if (positions.length >= 2 || (positions.length === 1 && positions[0] < 80)) {
        const qs = [];
        for (let i = 0; i < positions.length; i++) {
            const start = positions[i];
            const end = (i + 1 < positions.length) ? positions[i + 1] : code.length;
            const block = code.slice(start, end).trim();
            if (/Câu\s+\d+/g.test(block)) qs.push(block);
        }
        if (qs.length) return qs;
    }
    return [];
}

function lhlQBankSplitQuestionsInPart(partCode) {
    let s = lhlQBankRemovePartHeaderStrict(partCode || '');
    if (!s.trim()) return [];

    const blockQs = lhlQBankSplitByQuestionBlocks(s);
    if (blockQs.length) return blockQs;

    // Chỉ bắt nhãn câu thật: "Câu" viết hoa, đầu dòng/sau thẻ đóng/sau div; không dùng /i.
    const re = /(?:^|[\n\r]|>|<\/div>|<\/p>|<br\s*\/?>)\s*((?:<b>\s*)?Câu\s+\d+\s*[\.:]?\s*(?:<\/b>)?)/g;
    const matches = [];
    let m;
    while ((m = re.exec(s)) !== null) {
        const labelIndex = m.index + m[0].indexOf(m[1]);
        matches.push({index: labelIndex, text: m[1]});
    }

    // Fallback rất nhẹ: nếu code bắt đầu bằng Câu 1.
    if (!matches.length) {
        const m0 = s.match(/^\s*((?:<b>\s*)?Câu\s+\d+\s*[\.:]?\s*(?:<\/b>)?)/);
        if (m0) matches.push({index: s.indexOf(m0[1]), text: m0[1]});
    }

    if (!matches.length) return s.trim() ? [s.trim()] : [];

    const qs = [];
    for (let i = 0; i < matches.length; i++) {
        const start = matches[i].index;
        const end = (i + 1 < matches.length) ? matches[i + 1].index : s.length;
        const block = s.slice(start, end).trim();
        // Loại block quá ngắn chỉ là nhãn câu rỗng.
        const plain = block.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        if (plain.length > 12) qs.push(block);
    }
    return qs;
}

function lhlQBankSplitPartsFromCurrentCode(code) {
    const s = String(code || '');
    const marks = [];
    const patterns = [
        {part:'TN', re: /(?:PHẦN|PHAN)\s*I(?!I)[\s\S]{0,350}?(?:một phương án|nhiều phương án|trắc nghiệm|chọn một|chọn 1)/ig},
        {part:'DS', re: /(?:PHẦN|PHAN)\s*II(?!I)[\s\S]{0,350}?(?:đúng[\s,;.-]*sai|dung[\s,;.-]*sai)/ig},
        {part:'TLN', re: /(?:PHẦN|PHAN)\s*III[\s\S]{0,350}?(?:trả lời ngắn|tra loi ngan|tự luận ngắn|tu luan ngan)/ig},
        {part:'TN', re: /(?:PHẦN|PHAN)\s*I(?!I)/ig},
        {part:'DS', re: /(?:PHẦN|PHAN)\s*II(?!I)/ig},
        {part:'TLN', re: /(?:PHẦN|PHAN)\s*III/ig}
    ];
    patterns.forEach(p => {
        let m;
        while ((m = p.re.exec(s)) !== null) marks.push({part:p.part, index:m.index});
    });
    const first = {};
    marks.sort((a,b)=>a.index-b.index).forEach(x => { if (!first[x.part]) first[x.part] = x; });
    const arr = Object.values(first).sort((a,b)=>a.index-b.index);
    const parts = {TN:'', DS:'', TLN:''};

    if (!arr.length) {
        parts.TN = s.trim();
        return parts;
    }

    for (let i = 0; i < arr.length; i++) {
        const cur = arr[i];
        const next = arr[i+1];
        parts[cur.part] = s.slice(cur.index, next ? next.index : s.length).trim();
    }
    return parts;
}

function lhlQBankBuildImportItemsFromCurrentEditorStrict(existingSet) {
    const editor = document.getElementById('editor');
    const code = editor ? editor.value : '';
    const parts = lhlQBankSplitPartsFromCurrentCode(code);
    const items = [];
    const summary = {TN:0, DS:0, TLN:0, skipped:0};

    [['TN','TN'], ['DS','DS'], ['TLN','TLN']].forEach(([part, prefix]) => {
        const qs = lhlQBankSplitQuestionsInPart(parts[part] || '');
        summary[part] = qs.length;
        qs.forEach((q, idx) => {
            const fn = `${prefix}-${idx+1}.html`;
            if (existingSet && existingSet.size && !existingSet.has(fn.toLowerCase())) {
                summary.skipped++;
                return;
            }
            items.push({filename: fn, code: q});
        });
    });
    return {items, summary};
}

async function lhlExamBankImportCurrentFile() {
    const folder = lhlExamBankGetFolder();
    if (!folder) {
        lhlExamBankSetUnifiedStatus ? lhlExamBankSetUnifiedStatus('⚠️ Chưa chọn thư mục ngân hàng.', 'err') : showToast('⚠️ Chưa chọn thư mục ngân hàng.');
        return;
    }

    // Đọc danh sách file đang có để không tự tạo thêm file ngoài ngân hàng.
    if (typeof lhlExamBankRefreshFiles === 'function') await lhlExamBankRefreshFiles();
    const existingSet = lhlQBankGetExistingFileSetFromDialog();

    const data = lhlQBankBuildImportItemsFromCurrentEditorStrict(existingSet);
    const items = data.items || [];
    const sm = data.summary || {};

    if (!items.length) {
        lhlExamBankSetUnifiedStatus ? lhlExamBankSetUnifiedStatus('⚠️ Không có câu phù hợp với các file đang có trong ngân hàng để nhập.', 'err') : showToast('⚠️ Không có câu phù hợp để nhập.');
        return;
    }

    let ok = true;
    if (typeof lhlExamBankConfirm === 'function') {
        ok = await lhlExamBankConfirm(
            'Nhập file hiện hành',
            `Phần mềm đã tách file đang mở theo câu hỏi thật:<br><br>
            Phần I/TN: <b>${sm.TN || 0}</b> câu<br>
            Phần II/Đ-S: <b>${sm.DS || 0}</b> câu<br>
            Phần III/TLN: <b>${sm.TLN || 0}</b> câu<br><br>
            Sẽ nhập: <b>${items.length}</b> câu vào các file đang có trong NH.<br>
            Bỏ qua do không có file tương ứng: <b>${sm.skipped || 0}</b> câu.<br><br>
            Nguyên tắc: <b>không tự tạo thêm file mới</b>.`,
            'Nhập ngay',
            false
        );
    } else {
        ok = confirm(`Nhập file hiện hành?\nTN ${sm.TN||0}, Đ/S ${sm.DS||0}, TLN ${sm.TLN||0}\nSẽ nhập ${items.length}, bỏ qua ${sm.skipped||0}.`);
    }
    if (!ok) return;

    lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus('⏳ Đang nhập file hiện hành vào ngân hàng...', 'warn');

    let res = null;
    if (window.pywebview && window.pywebview.api && window.pywebview.api.qbank_bulk_append_questions_existing_only) {
        res = await window.pywebview.api.qbank_bulk_append_questions_existing_only(folder, items);
    } else if (window.pywebview && window.pywebview.api && window.pywebview.api.qbank_append_questions_to_file) {
        let okCount = 0, errCount = 0;
        for (const it of items) {
            const r = await window.pywebview.api.qbank_append_questions_to_file(folder, it.filename, it.code);
            if (r && r.ok) okCount++; else errCount++;
        }
        res = {ok: errCount === 0, ok_count: okCount, err_count: errCount, skipped: sm.skipped || 0};
    } else {
        lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus('❌ Chưa có API nhập ngân hàng.', 'err');
        return;
    }

    await lhlExamBankRefreshFiles();
    if (res && (res.ok || res.ok_count > 0)) {
        lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus(
            `✅ Đã nhập file hiện hành. Thành công: <b>${res.ok_count || 0}</b>, lỗi: <b>${res.err_count || 0}</b>, bỏ qua: <b>${res.skipped || 0}</b>. ` +
            `Tách được TN: ${sm.TN || 0}, Đ/S: ${sm.DS || 0}, TLN: ${sm.TLN || 0}.`,
            (res.err_count || 0) ? 'err' : 'ok'
        );
    } else {
        lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus('❌ Lỗi nhập file hiện hành: ' + ((res && res.error) || 'Không rõ lỗi'), 'err');
    }
}



// ============================================================
// FIX58-NH:
// Khi "Nhập file hiện hành" vào ngân hàng, tự cắt phần cuối đề:
//   ---------- HẾT ----------
//   Thí sinh không được sử dụng tài liệu...
//   giám thị coi thi...
//   các footer/header cuối đề...
// để câu cuối phần III chỉ còn nội dung câu hỏi.
// ============================================================
function lhlQBankCutExamFooterFromBlock(block) {
    let s = String(block || '');

    // Cắt từ dòng HẾT trở đi, bao gồm các dạng có nhiều dấu gạch.
    const patterns = [
        /(?:<[^>]+>\s*)*[-–—_=\s]*HẾT[-–—_=\s]*(?:<[^>]+>\s*)*[\s\S]*$/i,
        /(?:<[^>]+>\s*)*[-–—_=\s]*HET[-–—_=\s]*(?:<[^>]+>\s*)*[\s\S]*$/i,
        /Thí\s*sinh\s*không\s*được\s*sử\s*dụng\s*tài\s*liệu[\s\S]*$/i,
        /Thi\s*sinh\s*khong\s*duoc\s*su\s*dung\s*tai\s*lieu[\s\S]*$/i,
        /giám\s*thị\s*coi\s*thi\s*không\s*giải\s*thích\s*gì\s*thêm[\s\S]*$/i,
        /giam\s*thi\s*coi\s*thi\s*khong\s*giai\s*thich\s*gi\s*them[\s\S]*$/i
    ];
    for (const re of patterns) {
        s = s.replace(re, '');
    }

    // Cắt các khối cuối đề thường gặp nếu còn sót.
    s = s.replace(/<div[^>]*class=["'][^"']*(?:footer|exam-footer|page-footer)[^"']*["'][^>]*>[\s\S]*?<\/div>\s*$/ig, '');
    s = s.replace(/<table[^>]*>\s*<tbody>\s*<tr>\s*<td[^>]*>\s*(?:ThS\.|GV|Giáo viên|SỞ GIÁO DỤC|TRƯỜNG)[\s\S]*?<\/table>\s*$/ig, '');

    // Dọn các br/trống còn sót ở cuối.
    s = s.replace(/(?:<br\s*\/?>|\s|&nbsp;)+$/ig, '');
    return s.trim();
}

// Ghi đè hàm tách câu trong từng phần: sau khi cắt được block câu, loại footer cuối đề.
function lhlQBankSplitQuestionsInPart(partCode) {
    let s = lhlQBankRemovePartHeaderStrict(partCode || '');
    if (!s.trim()) return [];

    const blockQs = lhlQBankSplitByQuestionBlocks(s);
    if (blockQs.length) return blockQs.map(lhlQBankCutExamFooterFromBlock).filter(x => {
        const plain = x.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        return plain.length > 12;
    });

    // Chỉ bắt nhãn câu thật: "Câu" viết hoa, đầu dòng/sau thẻ đóng/sau div; không dùng /i.
    const re = /(?:^|[\n\r]|>|<\/div>|<\/p>|<br\s*\/?>)\s*((?:<b>\s*)?Câu\s+\d+\s*[\.:]?\s*(?:<\/b>)?)/g;
    const matches = [];
    let m;
    while ((m = re.exec(s)) !== null) {
        const labelIndex = m.index + m[0].indexOf(m[1]);
        matches.push({index: labelIndex, text: m[1]});
    }

    if (!matches.length) {
        const m0 = s.match(/^\s*((?:<b>\s*)?Câu\s+\d+\s*[\.:]?\s*(?:<\/b>)?)/);
        if (m0) matches.push({index: s.indexOf(m0[1]), text: m0[1]});
    }

    if (!matches.length) {
        const only = lhlQBankCutExamFooterFromBlock(s);
        return only.trim() ? [only.trim()] : [];
    }

    const qs = [];
    for (let i = 0; i < matches.length; i++) {
        const start = matches[i].index;
        const end = (i + 1 < matches.length) ? matches[i + 1].index : s.length;
        let block = s.slice(start, end).trim();
        block = lhlQBankCutExamFooterFromBlock(block);
        const plain = block.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        if (plain.length > 12) qs.push(block);
    }
    return qs;
}

// Chặn thêm một lớp trước khi gửi vào Python API để chắc chắn không còn footer.
function lhlQBankBuildImportItemsFromCurrentEditorStrict(existingSet) {
    const editor = document.getElementById('editor');
    const code = editor ? editor.value : '';
    const parts = lhlQBankSplitPartsFromCurrentCode(code);
    const items = [];
    const summary = {TN:0, DS:0, TLN:0, skipped:0};

    [['TN','TN'], ['DS','DS'], ['TLN','TLN']].forEach(([part, prefix]) => {
        const qs = lhlQBankSplitQuestionsInPart(parts[part] || '').map(lhlQBankCutExamFooterFromBlock).filter(x => {
            const plain = String(x || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            return plain.length > 12;
        });
        summary[part] = qs.length;
        qs.forEach((q, idx) => {
            const fn = `${prefix}-${idx+1}.html`;
            if (existingSet && existingSet.size && !existingSet.has(fn.toLowerCase())) {
                summary.skipped++;
                return;
            }
            items.push({filename: fn, code: q});
        });
    });
    return {items, summary};
}



// ============================================================
// FIX59-NH:
// Sửa lỗi cắt lố vào mã base64 ảnh khi nhập câu cuối.
// Nguyên nhân FIX58 có mẫu HET không dấu quá rộng, có thể trùng chuỗi trong base64.
// FIX59 chỉ cắt footer khi gặp dòng HẾT thật hoặc ghi chú cuối đề thật.
// ============================================================
function lhlQBankCutExamFooterFromBlock(block) {
    let s = String(block || '');

    // Tách theo dòng HTML mềm để chỉ xét HẾT ở ngữ cảnh cuối đề, không quét trong base64.
    // Các mẫu này yêu cầu HẾT nằm riêng như một dòng/ngữ cảnh có gạch hoặc thẻ HTML xung quanh.
    const safePatterns = [
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/b>)\s*(?:<[^>]+>\s*)*[-–—_= ]{3,}\s*HẾT\s*[-–—_= ]{3,}[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/b>)\s*(?:<[^>]+>\s*)*HẾT\s*(?:<[^>]+>\s*)*(?:[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|$)[\s\S]*$/i,

        // Ghi chú cuối đề thật. Các cụm này dài nên ít có nguy cơ trùng base64.
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>)\s*(?:<[^>]+>\s*)*Thí\s*sinh\s*không\s*được\s*sử\s*dụng\s*tài\s*liệu[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>)\s*(?:<[^>]+>\s*)*Thi\s*sinh\s*khong\s*duoc\s*su\s*dung\s*tai\s*lieu[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>)\s*(?:<[^>]+>\s*)*giám\s*thị\s*coi\s*thi\s*không\s*giải\s*thích\s*gì\s*thêm[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>)\s*(?:<[^>]+>\s*)*giam\s*thi\s*coi\s*thi\s*khong\s*giai\s*thich\s*gi\s*them[\s\S]*$/i
    ];

    for (const re of safePatterns) {
        s = s.replace(re, '');
    }

    // Không cắt theo "HET" trơn nữa để tránh trúng mã base64 ảnh.
    // Dọn các khối footer rõ ràng nếu còn sót.
    s = s.replace(/<div[^>]*class=["'][^"']*(?:footer|exam-footer|page-footer)[^"']*["'][^>]*>[\s\S]*?<\/div>\s*$/ig, '');
    s = s.replace(/(?:<br\s*\/?>|\s|&nbsp;)+$/ig, '');
    return s.trim();
}

// Ghi đè lại hàm build item để mọi câu trước khi gửi đều dùng bộ cắt an toàn FIX59.
function lhlQBankBuildImportItemsFromCurrentEditorStrict(existingSet) {
    const editor = document.getElementById('editor');
    const code = editor ? editor.value : '';
    const parts = lhlQBankSplitPartsFromCurrentCode(code);
    const items = [];
    const summary = {TN:0, DS:0, TLN:0, skipped:0};

    [['TN','TN'], ['DS','DS'], ['TLN','TLN']].forEach(([part, prefix]) => {
        const qs = lhlQBankSplitQuestionsInPart(parts[part] || '').map(lhlQBankCutExamFooterFromBlock).filter(x => {
            const plain = String(x || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            return plain.length > 12;
        });
        summary[part] = qs.length;
        qs.forEach((q, idx) => {
            const fn = `${prefix}-${idx+1}.html`;
            if (existingSet && existingSet.size && !existingSet.has(fn.toLowerCase())) {
                summary.skipped++;
                return;
            }
            items.push({filename: fn, code: q});
        });
    });
    return {items, summary};
}



// ============================================================
// FIX60-NH:
// 1) Cắt sạch dòng "---------- HẾT ----------" còn sót nhưng không ăn vào base64 ảnh.
// 2) Danh sách file NH hiện thêm đoạn đầu đại diện nội dung câu hỏi.
// ============================================================
function lhlQBankCutExamFooterFromBlock(block) {
    let s = String(block || '');

    // Cắt từ một dòng HẾT thật ở cuối đề. Không dùng HET không dấu trơn để tránh ăn base64.
    // Bắt được cả dạng: <b>---------- HẾT ----------</b>, <center>--- HẾT ---</center>, hoặc text riêng dòng.
    const hetLine = /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/b>|<\/table>)\s*(?:<[^>]+>\s*)*[-–—_= ]{2,}\s*HẾT\s*[-–—_= ]{2,}\s*(?:<[^>]+>\s*)*(?=$|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/b>)[\s\S]*$/i;
    s = s.replace(hetLine, '');

    // Dạng HẾT đứng riêng dòng không có gạch.
    const hetOnlyLine = /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/b>|<\/table>)\s*(?:<[^>]+>\s*)*HẾT\s*(?:<[^>]+>\s*)*(?=$|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/b>)[\s\S]*$/i;
    s = s.replace(hetOnlyLine, '');

    // Ghi chú cuối đề thật.
    const notePatterns = [
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/table>)\s*(?:<[^>]+>\s*)*Thí\s*sinh\s*không\s*được\s*sử\s*dụng\s*tài\s*liệu[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/table>)\s*(?:<[^>]+>\s*)*Thi\s*sinh\s*khong\s*duoc\s*su\s*dung\s*tai\s*lieu[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/table>)\s*(?:<[^>]+>\s*)*giám\s*thị\s*coi\s*thi\s*không\s*giải\s*thích\s*gì\s*thêm[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/p>|<\/div>|<\/center>|<\/table>)\s*(?:<[^>]+>\s*)*giam\s*thi\s*coi\s*thi\s*khong\s*giai\s*thich\s*gi\s*them[\s\S]*$/i
    ];
    notePatterns.forEach(re => { s = s.replace(re, ''); });

    s = s.replace(/<div[^>]*class=["'][^"']*(?:footer|exam-footer|page-footer)[^"']*["'][^>]*>[\s\S]*?<\/div>\s*$/ig, '');
    s = s.replace(/(?:<br\s*\/?>|\s|&nbsp;)+$/ig, '');
    return s.trim();
}

// Khi xem nhanh hoặc lưu sửa nhanh, cũng làm sạch HẾT nếu còn sót.
function lhlQBankNormalizePreviewBodyFromTextarea(text) {
    let s = String(text || '').trim();
    if (typeof lhlExamBankCleanBodyForView === 'function') s = lhlExamBankCleanBodyForView(s);
    s = lhlQBankCutExamFooterFromBlock(s);
    s = s
      .replace(/<table\b(?=[^>]*class=["'][^"']*FontDung[^"']*["'])[^>]*>\s*<tbody>\s*<tr>\s*<td>\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi, '')
      .replace(/<table\b([^>]*)>\s*<tbody>\s*<tr>\s*<td([^>]*)>\s*(<img\b[\s\S]*?>)\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi, '<div class="qbank-img-wrap">$3</div>');
    return s;
}

// Ghi đè build item để cắt HẾT bằng hàm an toàn mới trước khi nhập.
function lhlQBankBuildImportItemsFromCurrentEditorStrict(existingSet) {
    const editor = document.getElementById('editor');
    const code = editor ? editor.value : '';
    const parts = lhlQBankSplitPartsFromCurrentCode(code);
    const items = [];
    const summary = {TN:0, DS:0, TLN:0, skipped:0};

    [['TN','TN'], ['DS','DS'], ['TLN','TLN']].forEach(([part, prefix]) => {
        const qs = lhlQBankSplitQuestionsInPart(parts[part] || '').map(lhlQBankCutExamFooterFromBlock).filter(x => {
            const plain = String(x || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            return plain.length > 12;
        });
        summary[part] = qs.length;
        qs.forEach((q, idx) => {
            const fn = `${prefix}-${idx+1}.html`;
            if (existingSet && existingSet.size && !existingSet.has(fn.toLowerCase())) {
                summary.skipped++;
                return;
            }
            items.push({filename: fn, code: q});
        });
    });
    return {items, summary};
}

function lhlQBankEscapeAttr(s) {
    return String(s || '').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

// Ghi đè refresh danh sách: thêm preview nội dung và thu gọn cụm số câu/rút/nút.
async function lhlExamBankRefreshFiles() {
    const box = document.getElementById('examBankFileList');
    if (!box) return;
    if (typeof lhlExamBankApplyFixedDialogLayout === 'function') lhlExamBankApplyFixedDialogLayout();

    const folder = lhlExamBankGetFolder();
    const folderEl = document.getElementById('examBankFolderPath');
    if (folderEl) folderEl.textContent = folder || 'Chưa chọn thư mục ngân hàng';

    if (!folder) {
        box.innerHTML = '<div class="qbank-empty">Chưa có thư mục NH. Thầy nhập số câu TN/Đ-S/TLN rồi bấm <b>OK khởi tạo</b>.</div>';
        return;
    }
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_list_exam_folder)) {
        box.innerHTML = '<div class="qbank-empty">Chức năng này cần chạy trong phần mềm desktop.</div>';
        return;
    }

    let res = null;
    try { res = await window.pywebview.api.qbank_list_exam_folder(folder); }
    catch(e) {
        box.innerHTML = '<div class="qbank-empty">Lỗi gọi API đọc thư mục NH: ' + lhlQBankEscapeHtml(e && e.message ? e.message : e) + '</div>';
        return;
    }
    if (!res || !res.ok) {
        box.innerHTML = '<div class="qbank-empty">Không đọc được thư mục NH: ' + lhlQBankEscapeHtml((res && res.error) || '') + '</div>';
        return;
    }

    const files = res.files || [];
    if (typeof lhlExamBankUpdateTopCountsFromFiles === 'function') lhlExamBankUpdateTopCountsFromFiles(files);

    if (!files.length) {
        box.innerHTML = '<div class="qbank-empty">Thư mục chưa có file TN-*, DS-*, TLN-*.</div>';
        return;
    }

    const styleId = 'lhl-fix60-qbank-file-snippet-style';
    if (!document.getElementById(styleId)) {
        const st = document.createElement('style');
        st.id = styleId;
        st.textContent = `
        #examBankFileList .exam-bank-file{
            grid-template-columns:28px minmax(160px,1.05fr) minmax(260px,2.3fr) 70px 70px 292px !important;
            gap:8px !important;
            align-items:center !important;
        }
        .exam-bank-snippet{
            color:#c8e6c9;
            font-size:13px;
            white-space:nowrap;
            overflow:hidden;
            text-overflow:ellipsis;
            opacity:.95;
        }
        .exam-bank-snippet.empty{
            color:#888;
            font-style:italic;
        }
        #examBankFileList .exam-bank-count{
            white-space:nowrap;
            font-size:13px !important;
            text-align:center;
        }
        #examBankFileList .exam-bank-pick-box{
            white-space:nowrap;
            font-size:12px !important;
        }
        #examBankFileList .exam-bank-actions{
            display:flex;
            justify-content:flex-end;
            gap:5px;
        }
        #examBankFileList .exam-bank-actions button{
            font-size:12px!important;
            padding:6px 6px!important;
        }`;
        document.head.appendChild(st);
    }

    const groups = { 'TN': [], 'Đ/S': [], 'TLN': [] };
    files.forEach(f => {
        const p = lhlExamBankFilePart(f.filename);
        if (!groups[p]) groups[p] = [];
        groups[p].push(f);
    });

    let html = '';
    ['TN','Đ/S','TLN'].forEach(part => {
        if (!groups[part] || !groups[part].length) return;
        const title = (typeof lhlExamBankGroupTitle === 'function') ? lhlExamBankGroupTitle(part) : part;
        html += `<div class="exam-bank-group"><div class="exam-bank-group-title">${lhlQBankEscapeHtml(title)}</div>`;
        groups[part].forEach(f => {
            const safeFile = lhlQBankEscapeHtml(f.filename);
            const jsFile = String(f.filename).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
            const preview = (f.preview || '').trim();
            const previewHtml = preview ? lhlQBankEscapeHtml(preview) : 'Chưa có câu hỏi';
            const previewCls = preview ? 'exam-bank-snippet' : 'exam-bank-snippet empty';
            html += `<div class="exam-bank-file" data-file="${safeFile}">
                <div style="text-align:center;"><input class="exam-bank-pick-check" type="checkbox" title="Chọn file này để rút câu"></div>
                <div class="exam-bank-file-name"><b>${lhlQBankEscapeHtml(lhlExamBankLabel(f.filename))}</b><span>${safeFile}</span></div>
                <div class="${previewCls}" title="${lhlQBankEscapeAttr(previewHtml)}">${previewHtml}</div>
                <div class="exam-bank-count">Câu: <b>${f.count || 0}</b></div>
                <div class="exam-bank-pick-box" style="display:flex;align-items:center;gap:4px;justify-content:center;color:#e8f5e9;">
                    <span class="qbank-pick-label">Chọn/đề</span><input class="exam-bank-pick-count" type="number" min="1" value="1" style="width:36px;height:25px;background:#111;color:#fff;border:1px solid #4caf50;border-radius:4px;text-align:center;font-weight:800;">
                </div>
                <div class="exam-bank-actions">
                    <button type="button" data-action="append" data-file="${safeFile}">Nhập</button>
                    <button type="button" onclick="event.preventDefault(); event.stopPropagation(); lhlExamBankResetFileQuestions('${jsFile}');" style="background:#ef6c00;">Reset</button>
                    <button type="button" data-action="view" data-file="${safeFile}">Xem</button>
                    <button type="button" data-action="edit" data-file="${safeFile}">Sửa</button>
                    <button type="button" class="danger" data-action="delete" data-file="${safeFile}">Xóa</button>
                </div>
            </div>`;
        });
        html += '</div>';
    });
    box.innerHTML = html;
}



// ============================================================
// FIX61-NH:
// Vá lỗi Nhập file hiện hành báo "Không rõ lỗi" và preview file rỗng hiện TN-1.
// - File 0 câu: đại diện = Chưa có câu hỏi.
// - Tách câu bền hơn với <b> Câu 1. </b>, <b>Câu 1.</b>, Câu 1.
// - Báo lỗi chi tiết hơn.
// ============================================================
function lhlQBankPreviewIsEmptyText(s) {
    const t = String(s || '').trim();
    return !t || /^(TN|DS|TLN)-\d+$/i.test(t);
}

function lhlQBankSplitQuestionsInPart(partCode) {
    let s = lhlQBankRemovePartHeaderStrict(partCode || '');
    if (!s.trim()) return [];

    const blockQs = (typeof lhlQBankSplitByQuestionBlocks === 'function') ? lhlQBankSplitByQuestionBlocks(s) : [];
    if (blockQs && blockQs.length) {
        return blockQs.map(x => typeof lhlQBankCutExamFooterFromBlock === 'function' ? lhlQBankCutExamFooterFromBlock(x) : x).filter(x => {
            const plain = x.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            return plain.length > 12;
        });
    }

    // Bắt nhãn Câu thật, nhưng không bắt chữ "câu" thường trong tiêu đề vì phân biệt hoa/thường.
    // Cho phép phía trước là đầu chuỗi, xuống dòng, thẻ đóng, <br>, hoặc khoảng trắng sau thẻ.
    const re = /(?:^|[\n\r]|<br\s*\/?>|<\/(?:div|p|table|tbody|tr|td|h[1-6]|center)>|>)\s*((?:<b>\s*)?Câu\s+\d+\s*[\.:]?\s*(?:<\/b>)?)/g;
    const matches = [];
    let m;
    while ((m = re.exec(s)) !== null) {
        const labelIndex = m.index + m[0].indexOf(m[1]);
        matches.push({index: labelIndex, text: m[1]});
    }
    if (!matches.length) {
        const m0 = s.match(/^\s*((?:<b>\s*)?Câu\s+\d+\s*[\.:]?\s*(?:<\/b>)?)/);
        if (m0) matches.push({index: s.indexOf(m0[1]), text: m0[1]});
    }
    if (!matches.length) {
        const only = typeof lhlQBankCutExamFooterFromBlock === 'function' ? lhlQBankCutExamFooterFromBlock(s) : s;
        return only.trim() ? [only.trim()] : [];
    }

    const qs = [];
    for (let i = 0; i < matches.length; i++) {
        const start = matches[i].index;
        const end = (i + 1 < matches.length) ? matches[i + 1].index : s.length;
        let block = s.slice(start, end).trim();
        if (typeof lhlQBankCutExamFooterFromBlock === 'function') block = lhlQBankCutExamFooterFromBlock(block);
        const plain = block.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        if (plain.length > 12) qs.push(block);
    }
    return qs;
}

function lhlQBankBuildImportItemsFromCurrentEditorStrict(existingSet) {
    const editor = document.getElementById('editor');
    const code = editor ? editor.value : '';
    const parts = lhlQBankSplitPartsFromCurrentCode(code);
    const items = [];
    const summary = {TN:0, DS:0, TLN:0, skipped:0};

    [['TN','TN'], ['DS','DS'], ['TLN','TLN']].forEach(([part, prefix]) => {
        const qs = lhlQBankSplitQuestionsInPart(parts[part] || '').map(x => {
            return typeof lhlQBankCutExamFooterFromBlock === 'function' ? lhlQBankCutExamFooterFromBlock(x) : x;
        }).filter(x => {
            const plain = String(x || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            return plain.length > 12;
        });
        summary[part] = qs.length;
        qs.forEach((q, idx) => {
            const fn = `${prefix}-${idx+1}.html`;
            if (existingSet && existingSet.size && !existingSet.has(fn.toLowerCase())) {
                summary.skipped++;
                return;
            }
            items.push({filename: fn, code: q});
        });
    });
    return {items, summary};
}

async function lhlExamBankImportCurrentFile() {
    const folder = lhlExamBankGetFolder();
    if (!folder) {
        lhlExamBankSetUnifiedStatus ? lhlExamBankSetUnifiedStatus('⚠️ Chưa chọn thư mục ngân hàng.', 'err') : showToast('⚠️ Chưa chọn thư mục ngân hàng.');
        return;
    }

    if (typeof lhlExamBankRefreshFiles === 'function') await lhlExamBankRefreshFiles();
    const existingSet = lhlQBankGetExistingFileSetFromDialog();
    const data = lhlQBankBuildImportItemsFromCurrentEditorStrict(existingSet);
    const items = data.items || [];
    const sm = data.summary || {};

    if (!items.length) {
        const msg = `⚠️ Không có câu phù hợp để nhập. Tách được TN: ${sm.TN || 0}, Đ/S: ${sm.DS || 0}, TLN: ${sm.TLN || 0}, bỏ qua: ${sm.skipped || 0}.`;
        lhlExamBankSetUnifiedStatus ? lhlExamBankSetUnifiedStatus(msg, 'err') : showToast(msg);
        return;
    }

    let ok = true;
    if (typeof lhlExamBankConfirm === 'function') {
        ok = await lhlExamBankConfirm(
            'Nhập file hiện hành',
            `Phần mềm đã tách file đang mở:<br><br>
            Phần I/TN: <b>${sm.TN || 0}</b> câu<br>
            Phần II/Đ-S: <b>${sm.DS || 0}</b> câu<br>
            Phần III/TLN: <b>${sm.TLN || 0}</b> câu<br><br>
            Sẽ nhập: <b>${items.length}</b> câu vào các file đang có.<br>
            Bỏ qua vì không có file tương ứng: <b>${sm.skipped || 0}</b> câu.<br><br>
            <b>Không tự tạo thêm file mới.</b>`,
            'Nhập ngay',
            false
        );
    }
    if (!ok) return;

    lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus('⏳ Đang nhập file hiện hành vào ngân hàng...', 'warn');

    let res = null;
    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.qbank_bulk_append_questions_existing_only) {
            res = await window.pywebview.api.qbank_bulk_append_questions_existing_only(folder, items);
        } else if (window.pywebview && window.pywebview.api && window.pywebview.api.qbank_append_questions_to_file) {
            let okCount = 0, errCount = 0;
            for (const it of items) {
                const r = await window.pywebview.api.qbank_append_questions_to_file(folder, it.filename, it.code);
                if (r && r.ok) okCount++; else errCount++;
            }
            res = {ok: errCount === 0, ok_count: okCount, err_count: errCount, skipped: sm.skipped || 0};
        } else {
            lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus('❌ Chưa có API nhập ngân hàng.', 'err');
            return;
        }
    } catch(e) {
        lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus('❌ Lỗi nhập file hiện hành: ' + (e && e.message ? e.message : e), 'err');
        return;
    }

    await lhlExamBankRefreshFiles();
    if (res && (res.ok || (res.ok_count || 0) > 0)) {
        lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus(
            `✅ Đã nhập file hiện hành. Thành công: <b>${res.ok_count || 0}</b>, lỗi: <b>${res.err_count || 0}</b>, bỏ qua: <b>${res.skipped || 0}</b>. ` +
            `Tách được TN: ${sm.TN || 0}, Đ/S: ${sm.DS || 0}, TLN: ${sm.TLN || 0}.`,
            (res.err_count || 0) ? 'err' : 'ok'
        );
    } else {
        const err = (res && (res.error || res.message)) || `Không nhập được câu nào. Tách được TN: ${sm.TN || 0}, Đ/S: ${sm.DS || 0}, TLN: ${sm.TLN || 0}, bỏ qua: ${sm.skipped || 0}.`;
        lhlExamBankSetUnifiedStatus && lhlExamBankSetUnifiedStatus('❌ Lỗi nhập file hiện hành: ' + err, 'err');
    }
}

// Ghi đè refresh lần nữa để không hiện TN-1 làm snippet khi file rỗng.
if (typeof lhlExamBankRefreshFiles === 'function' && !window.__lhlFix61RefreshWrapped) {
    window.__lhlFix61RefreshWrapped = true;
    const __oldRefreshFix61 = lhlExamBankRefreshFiles;
    lhlExamBankRefreshFiles = async function() {
        await __oldRefreshFix61.apply(this, arguments);
        document.querySelectorAll('#examBankFileList .exam-bank-file').forEach(row => {
            const countText = row.querySelector('.exam-bank-count')?.textContent || '';
            const snippet = row.querySelector('.exam-bank-snippet');
            if (!snippet) return;
            const t = snippet.textContent.trim();
            if (/Câu:\s*0/.test(countText) || /^(TN|DS|TLN)-\d+$/i.test(t)) {
                snippet.textContent = 'Chưa có câu hỏi';
                snippet.classList.add('empty');
                snippet.setAttribute('title', 'Chưa có câu hỏi');
            }
        });
    };
}



