function lhlQBankHighlightStatsNumbersFix64() {
    const box = document.getElementById('examBankPendingInfo');
    if (!box) return;
    // Chỉ xử lý dòng thống kê tổng số câu, tránh đụng thông báo nhập/xóa.
    const text = box.textContent || '';
    if (!/Tổng số câu/i.test(text)) return;
    if (box.dataset.fix64Stats === '1') return;

    box.innerHTML = box.innerHTML
        .replace(/(Tổng số câu:\s*)(\d+)/i, '$1<span class="lhl-stat-number">$2</span>')
        .replace(/(TN:\s*)(\d+)/i, '$1<span class="lhl-stat-number">$2</span>')
        .replace(/(Đ\/S:\s*)(\d+)/i, '$1<span class="lhl-stat-number">$2</span>')
        .replace(/(TLN:\s*)(\d+)/i, '$1<span class="lhl-stat-number">$2</span>')
        .replace(/(Số file:\s*)(\d+)/i, '$1<span class="lhl-stat-number">$2</span>');
    box.dataset.fix64Stats = '1';
}

