function lhlQBankEnsureTopButtonsFix65() {
    const body = document.querySelector('#qbankOverlay .qbank-body');
    if (!body) return;

    let clearBtn = document.getElementById('examBankClearAllBtn') || Array.from(body.querySelectorAll('button')).find(b => /Xóa toàn bộ câu hỏi/i.test(b.textContent || ''));
    if (!clearBtn) return;

    if (!document.getElementById('examBankStatsBtn')) {
        const statBtn = document.createElement('button');
        statBtn.id = 'examBankStatsBtn';
        statBtn.className = clearBtn.className || 'exam-bank-btn';
        statBtn.style.marginLeft = '6px';
        statBtn.style.background = 'linear-gradient(#7e57c2,#512da8)';
        statBtn.textContent = '📊 Tổng số câu';
        statBtn.onclick = function(ev){ ev.preventDefault(); lhlExamBankShowStats(); };
        clearBtn.insertAdjacentElement('afterend', statBtn);
    }

    const statsBtn = document.getElementById('examBankStatsBtn');
    if (statsBtn && !document.getElementById('examBankImportCurrentBtn')) {
        const btn = document.createElement('button');
        btn.id = 'examBankImportCurrentBtn';
        btn.className = statsBtn.className || 'exam-bank-btn';
        btn.style.marginLeft = '6px';
        btn.style.background = 'linear-gradient(#009688,#00695c)';
        btn.textContent = '📥 Nhập file hiện hành';
        btn.onclick = function(ev){ ev.preventDefault(); lhlExamBankImportCurrentFile(); };
        statsBtn.insertAdjacentElement('afterend', btn);
    }
}

