function lhlQBankPolishRowsFix66() {
    document.querySelectorAll('#examBankFileList .exam-bank-file').forEach(row => {
        const count = row.querySelector('.exam-bank-count');
        if (count && !count.dataset.fix66Done) {
            const m = (count.textContent || '').match(/(\d+)/);
            const num = m ? m[1] : '0';
            count.innerHTML = `<span class="qbank-total-label">Tổng:</span> <b class="qbank-total-number">${num}</b>`;
            count.dataset.fix66Done = '1';
        }

        const pick = row.querySelector('.exam-bank-pick-box');
        if (pick) {
            const span = pick.querySelector('span');
            if (span) {
                span.textContent = 'Chọn/đề';
                span.classList.add('qbank-pick-label');
            } else if (!pick.querySelector('.qbank-pick-label')) {
                pick.insertAdjacentHTML('afterbegin', '<span class="qbank-pick-label">Chọn/đề</span>');
            }
        }

        const name = row.querySelector('.exam-bank-file-name b');
        if (name) name.classList.add('qbank-file-label');
    });
}

