// ============================================================
// FIX72-NH:
// 1) Cắt sạch dòng "---------- HẾT ----------" còn dính ở câu cuối phần III,
//    kể cả khi sau chữ HẾT có nối luôn "Câu 4...".
// 2) Giữ kích thước ảnh theo style gốc khi nhập/xem nhanh ngân hàng,
//    không ép ảnh phóng to quá mức.
// ============================================================
function lhlQBankCutExamFooterFromBlock(block) {
    let s = String(block || '');

    // Cắt dòng HẾT thật ở cuối đề. Mẫu này chỉ bắt khi trước HẾT là đầu dòng / <br> / thẻ đóng,
    // nên không ăn nhầm vào base64. Cho phép sau HẾT còn nối "Câu ..." do đã nhập lỗi trước đó.
    const hetPatterns = [
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|b|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*[-–—_= ]{2,}\s*HẾT\s*[-–—_= ]{2,}[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|b|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*HẾT\s*(?:<[^>]+>\s*)*(?:$|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|b)>)[\s\S]*$/i
    ];
    hetPatterns.forEach(re => { s = s.replace(re, ''); });

    // Cắt ghi chú cuối đề thật nếu còn sót.
    const notePatterns = [
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*Thí\s*sinh\s*không\s*được\s*sử\s*dụng\s*tài\s*liệu[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*Thi\s*sinh\s*khong\s*duoc\s*su\s*dung\s*tai\s*lieu[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*giám\s*thị\s*coi\s*thi\s*không\s*giải\s*thích\s*gì\s*thêm[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*giam\s*thi\s*coi\s*thi\s*khong\s*giai\s*thich\s*gi\s*them[\s\S]*$/i
    ];
    notePatterns.forEach(re => { s = s.replace(re, ''); });

    // Dọn br/trống cuối.
    s = s.replace(/(?:<br\s*\/?>|\s|&nbsp;)+$/ig, '');
    return s.trim();
}

function lhlQBankPreserveImageSizeInBody(html) {
    let s = String(html || '');

    // Nếu ảnh chưa có width trong style nhưng có width attr thì đưa vào style.
    s = s.replace(/<img\b([^>]*?)\bwidth=["']?(\d{1,4})%?["']?([^>]*?)>/gi, function(full, a, w, b){
        if (/style\s*=/.test(full) && /width\s*:/.test(full)) return full;
        if (/style\s*=/.test(full)) {
            return full.replace(/style=(["'])([\s\S]*?)\1/i, function(m, q, st){
                return `style=${q}width: ${w}px; ${st}${q}`;
            });
        }
        return `<img${a} width="${w}"${b} style="width: ${w}px; height: auto;">`;
    });

    // Với ảnh trong qbank-img-wrap/immini/table: không tự đổi width; giữ style gốc.
    // Nếu style đang có max-width:100% do bản cũ thêm vào nội tuyến thì bỏ, tránh phóng/ép sai.
    s = s.replace(/(<img\b[^>]*style=["'][^"']*)max-width\s*:\s*100%\s*!important\s*;?/gi, '$1');
    s = s.replace(/(<img\b[^>]*style=["'][^"']*)max-width\s*:\s*100%\s*;?/gi, '$1');

    return s;
}

// Ghi đè hàm build item để trước khi nhập: cắt HẾT + giữ size ảnh.
function lhlQBankBuildImportItemsFromCurrentEditorStrict(existingSet) {
    const editor = document.getElementById('editor');
    const code = editor ? editor.value : '';
    const parts = lhlQBankSplitPartsFromCurrentCode(code);
    const items = [];
    const summary = {TN:0, DS:0, TLN:0, skipped:0};

    [['TN','TN'], ['DS','DS'], ['TLN','TLN']].forEach(([part, prefix]) => {
        const qs = lhlQBankSplitQuestionsInPart(parts[part] || '').map(x => {
            let y = lhlQBankCutExamFooterFromBlock(x);
            y = lhlQBankPreserveImageSizeInBody(y);
            return y;
        }).filter(x => {
            const plain = String(x || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            return plain.length > 12;
        });

        summary[part] = qs.length;
        qs.forEach((q, idx) => {
            const fn = `${prefix}-${idx+1}.html`;
            if (existingSet && existingSet.size && !existingSet.has(fn.toLowerCase())) {
                summary.skipped++;
                return;
            }
            items.push({filename: fn, code: q});
        });
    });
    return {items, summary};
}

// Xem nhanh: render ảnh theo style gốc, không ép to toàn khung.
