// Khi xem/sửa nhanh, cũng lọc HẾT còn sót và giữ kích thước ảnh.
function lhlQBankNormalizePreviewBodyFromTextarea(text) {
    let s = String(text || '').trim();
    if (typeof lhlExamBankCleanBodyForView === 'function') s = lhlExamBankCleanBodyForView(s);
    s = lhlQBankCutExamFooterFromBlock(s);
    s = lhlQBankPreserveImageSizeInBody(s);
    s = s
      .replace(/<table\b(?=[^>]*class=["'][^"']*FontDung[^"']*["'])[^>]*>\s*<tbody>\s*<tr>\s*<td>\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi, '')
      .replace(/<table\b([^>]*)>\s*<tbody>\s*<tr>\s*<td([^>]*)>\s*(<img\b[\s\S]*?>)\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi, '<div class="qbank-img-wrap">$3</div>');
    return s;
}



// ============================================================
// FIX73-NH:
// 1) Cắt mạnh và an toàn mọi đoạn "----- HẾT -----" còn sót.
//    Chữ HẾT có dấu không xuất hiện trong base64 nên không ăn nhầm ảnh.
// 2) Ảnh trong xem nhanh/ngân hàng không bung quá to khi style gốc width:100%.
// ============================================================
function lhlQBankCutExamFooterFromBlock(block) {
    let s = String(block || '');

    // Chuẩn hóa một số entity thường gặp của chữ Ế nếu có.
    s = s.replace(/H(?:&#7870;|&#x1ebe;|&Ecirc;\u0301|Ê\u0301)T/gi, 'HẾT');

    // Cắt bất cứ đoạn "----- HẾT -----" nào trở về sau.
    // An toàn vì base64 không chứa chữ HẾT có dấu.
    s = s.replace(/[-–—_=]{2,}\s*HẾT\s*[-–—_=]{2,}[\s\S]*$/i, '');

    // Cắt dạng HẾT đứng riêng dòng hoặc nằm sau <br>/<div> nếu không có gạch.
    s = s.replace(/(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|b|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*HẾT\s*(?:<[^>]+>\s*)*(?:$|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|b)>)[\s\S]*$/i, '');

    // Cắt ghi chú cuối đề thật nếu còn sót.
    const notePatterns = [
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*Thí\s*sinh\s*không\s*được\s*sử\s*dụng\s*tài\s*liệu[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*Thi\s*sinh\s*khong\s*duoc\s*su\s*dung\s*tai\s*lieu[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*giám\s*thị\s*coi\s*thi\s*không\s*giải\s*thích\s*gì\s*thêm[\s\S]*$/i,
        /(?:^|[\n\r]|<br\s*\/?>|<\/(?:p|div|center|table|tbody|tr|td)>|>)\s*(?:<[^>]+>\s*)*giam\s*thi\s*coi\s*thi\s*khong\s*giai\s*thich\s*gi\s*them[\s\S]*$/i
    ];
    notePatterns.forEach(re => { s = s.replace(re, ''); });

    s = s.replace(/(?:<br\s*\/?>|\s|&nbsp;)+$/ig, '');
    return s.trim();
}

function lhlQBankPreserveImageSizeInBody(html) {
    let s = String(html || '');

    // Không động vào base64. Chỉ chỉnh style thẻ img.
    s = s.replace(/<img\b([^>]*)>/gi, function(full, attrs) {
        let tag = full;

        // Bỏ max-width inline cũ nếu có.
        tag = tag.replace(/max-width\s*:\s*100%\s*!important\s*;?/gi, '');
        tag = tag.replace(/max-width\s*:\s*100%\s*;?/gi, '');

        // Nếu ảnh đang width:100% thì trong NH đổi về width:60% để không bung toàn khung.
        // Những ảnh có width khác như 40%, 50%, 180px... giữ nguyên.
        if (/style\s*=/.test(tag) && /width\s*:\s*100%\s*;?/i.test(tag)) {
            tag = tag.replace(/width\s*:\s*100%\s*;?/i, 'width: 60%;');
            if (!/max-width\s*:/i.test(tag)) {
                tag = tag.replace(/style=(["'])([\s\S]*?)\1/i, function(m, q, st){
                    return `style=${q}${st}; max-width: 620px;${q}`;
                });
            }
        } else if (!/style\s*=/.test(tag)) {
            // Nếu không có style, thêm giới hạn hiển thị vừa phải.
            tag = tag.replace(/<img\b/i, '<img style="max-width: 620px; height: auto;"');
        } else if (!/max-width\s*:/i.test(tag)) {
            tag = tag.replace(/style=(["'])([\s\S]*?)\1/i, function(m, q, st){
                return `style=${q}${st}; max-width: 620px;${q}`;
            });
        }

        return tag;
    });

    return s;
}

// Ghi đè build item để nhập file hiện hành: cắt HẾT + giới hạn ảnh.
function lhlQBankBuildImportItemsFromCurrentEditorStrict(existingSet) {
    const editor = document.getElementById('editor');
    const code = editor ? editor.value : '';
    const parts = lhlQBankSplitPartsFromCurrentCode(code);
    const items = [];
    const summary = {TN:0, DS:0, TLN:0, skipped:0};

    [['TN','TN'], ['DS','DS'], ['TLN','TLN']].forEach(([part, prefix]) => {
        const qs = lhlQBankSplitQuestionsInPart(parts[part] || '').map(x => {
            let y = lhlQBankCutExamFooterFromBlock(x);
            y = lhlQBankPreserveImageSizeInBody(y);
            return y;
        }).filter(x => {
            const plain = String(x || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
            return plain.length > 12;
        });

        summary[part] = qs.length;
        qs.forEach((q, idx) => {
            const fn = `${prefix}-${idx+1}.html`;
            if (existingSet && existingSet.size && !existingSet.has(fn.toLowerCase())) {
                summary.skipped++;
                return;
            }
            items.push({filename: fn, code: q});
        });
    });
    return {items, summary};
}

