// ============================================================
// FIX74-NH:
// Theo yêu cầu thầy:
// - Không tiếp tục xử lý/cắt chữ HẾT tự động nữa.
// - Chỉ tập trung chỉnh ảnh trong khung Xem nhanh NH nhỏ gọn giống biên dịch ngoài.
// - Thêm hiệu ứng nhún/ấn cho các nút trong hộp thoại Ngân hàng.
// ============================================================

// Ghi đè: không tự cắt HẾT nữa, tránh ảnh hưởng nội dung câu hỏi. Thầy xóa HẾT thủ công nếu cần.
function lhlQBankCutExamFooterFromBlock(block) {
    return String(block || '').trim();
}

// Chỉ làm gọn ảnh khi render xem nhanh, không sửa phá code gốc quá nhiều.
function lhlQBankNormalizePreviewImagesOnly(html) {
    let s = String(html || '');

    // Gắn class cho wrapper ảnh để CSS khống chế hiển thị gọn.
    s = s.replace(/<div\s+class=["']qbank-img-wrap["'][^>]*>/gi, '<div class="qbank-img-wrap lhl-qbank-img-compact">');

    // Nếu ảnh nằm trong table 1 ô, đổi sang wrapper gọn để tránh khung bảng bao ảnh.
    s = s.replace(
        /<table\b([^>]*)>\s*<tbody>\s*<tr>\s*<td([^>]*)>\s*(<img\b[\s\S]*?>)\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi,
        '<div class="qbank-img-wrap lhl-qbank-img-compact">$3</div>'
    );

    // Ảnh có width:100% trong câu hỏi thường bung to trong khung preview.
    // Chỉ thêm data attribute để CSS giới hạn khi xem nhanh, không thay đổi src/base64.
    s = s.replace(/<img\b([^>]*)>/gi, function(full, attrs) {
        let tag = full;
        if (!/class\s*=/.test(tag)) {
            tag = tag.replace(/<img\b/i, '<img class="lhl-qbank-preview-img"');
        } else if (!/lhl-qbank-preview-img/.test(tag)) {
            tag = tag.replace(/class=(["'])(.*?)\1/i, function(m, q, cls) {
                return `class=${q}${cls} lhl-qbank-preview-img${q}`;
            });
        }

        if (/width\s*:\s*100%\s*;?/i.test(tag) || /width=["']?100%["']?/i.test(tag)) {
            if (!/data-qbank-wide-img=/.test(tag)) {
                tag = tag.replace(/<img\b/i, '<img data-qbank-wide-img="1"');
            }
        }
        return tag;
    });

    return s;
}

// Ghi đè hàm normalize preview: bỏ cắt HẾT, chỉ dọn ảnh và table trống.
function lhlQBankNormalizePreviewBodyFromTextarea(text) {
    let s = String(text || '').trim();
    if (typeof lhlExamBankCleanBodyForView === 'function') s = lhlExamBankCleanBodyForView(s);

    s = s
      .replace(/<table\b(?=[^>]*class=["'][^"']*FontDung[^"']*["'])[^>]*>\s*<tbody>\s*<tr>\s*<td>\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi, '');

    s = lhlQBankNormalizePreviewImagesOnly(s);
    return s;
}

