if (typeof lhlQBankBuildImportItemsFromCurrentEditorStrict === 'function' && !window.__lhlFix74ImportWrapped) {
    window.__lhlFix74ImportWrapped = true;
    const __oldBuildItemsFix74 = lhlQBankBuildImportItemsFromCurrentEditorStrict;
    lhlQBankBuildImportItemsFromCurrentEditorStrict = function(existingSet) {
        const data = __oldBuildItemsFix74.apply(this, arguments);
        if (data && Array.isArray(data.items)) {
            data.items = data.items.map(it => {
                if (it && typeof it.code === 'string') {
                    // Không cắt HẾT; chỉ chuẩn hóa nhẹ ảnh cho preview.
                    it.code = lhlQBankNormalizePreviewImagesOnly(it.code);
                }
                return it;
            });
        }
        return data;
    };
}

