// ============================================================
// FIX80-NH:
// Quay lại nền FIX75 ổn.
// Sửa an toàn nút "Lưu sửa nhanh" cùng dòng với "Đóng" trong đúng hộp
// "Xem file ngân hàng", không bắt nhầm nút Đóng của hộp Ngân hàng phía sau.
// ============================================================
function lhlQBankInstallFix80SafeSaveLineCSS() {
    const styleId = 'lhl-fix80-safe-save-same-line';
    let st = document.getElementById(styleId);
    if (!st) {
        st = document.createElement('style');
        st.id = styleId;
        document.head.appendChild(st);
    }
    st.textContent = `
    .lhl-qbank-view-modal-fix80{
        position: relative !important;
    }

    .lhl-qbank-view-modal-fix80 .lhl-fix80-save-btn{
        position: absolute !important;
        z-index: 1000 !important;
        margin: 0 !important;
        height: 40px !important;
        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;
        white-space: nowrap !important;
        transition: transform .12s ease, filter .12s ease, box-shadow .12s ease !important;
    }

    .lhl-qbank-view-modal-fix80 .lhl-fix80-save-btn:hover{
        transform: translateY(-1px) scale(1.035) !important;
        filter: brightness(1.08) !important;
        box-shadow: 0 6px 14px rgba(0,0,0,.28) !important;
    }

    .lhl-qbank-view-modal-fix80 .lhl-fix80-save-btn:active{
        transform: translateY(1px) scale(.96) !important;
        filter: brightness(.95) !important;
    }

    .lhl-qbank-view-modal-fix80 h1,
    .lhl-qbank-view-modal-fix80 h2,
    .lhl-qbank-view-modal-fix80 h3,
    .lhl-qbank-view-modal-fix80 h4{
        padding-right: 330px !important;
        box-sizing: border-box !important;
    }
    `;
}

function lhlQBankVisibleFix80(el) {
    if (!el) return false;
    const r = el.getBoundingClientRect();
    const st = window.getComputedStyle(el);
    return r.width > 0 && r.height > 0 && st.display !== 'none' && st.visibility !== 'hidden';
}

function lhlQBankFindCorrectViewModalFix80(saveBtn) {
    // Lấy modal gần nút Lưu nhất, có nội dung đặc trưng của hộp xem nhanh.
    let p = saveBtn;
    while (p && p !== document.body) {
        const txt = (p.textContent || '').slice(0, 2500);
        if (/Xem file ngân hàng/i.test(txt) && /Biên dịch nhanh/i.test(txt) && /Mã code nội dung/i.test(txt)) {
            return p;
        }
        p = p.parentElement;
    }

    // Fallback: tìm khối đang hiện, có save button, có tiêu đề xem file, và nhỏ nhất.
    const candidates = Array.from(document.querySelectorAll('div,section,article'))
        .filter(el => {
            if (!lhlQBankVisibleFix80(el)) return false;
            if (!el.contains(saveBtn)) return false;
            const txt = (el.textContent || '').slice(0, 2500);
            return /Xem file ngân hàng/i.test(txt) && /Biên dịch nhanh/i.test(txt);
        })
        .sort((a,b) => (a.getBoundingClientRect().width*a.getBoundingClientRect().height) - (b.getBoundingClientRect().width*b.getBoundingClientRect().height));

    return candidates[0] || null;
}

function lhlQBankMoveSaveSameLineFix80() {
    lhlQBankInstallFix80SafeSaveLineCSS();

    const visibleButtons = Array.from(document.querySelectorAll('button')).filter(lhlQBankVisibleFix80);
    const saveBtn = visibleButtons.find(b => /Lưu\s*sửa\s*nhanh/i.test((b.textContent || '').trim()));
    if (!saveBtn) return false;

    const modal = lhlQBankFindCorrectViewModalFix80(saveBtn);
    if (!modal) return false;

    // Chỉ tìm nút Đóng/Xong BÊN TRONG modal xem nhanh này, tránh bắt nút Đóng hộp NH phía sau.
    const closeBtn = Array.from(modal.querySelectorAll('button'))
        .filter(b => b !== saveBtn && lhlQBankVisibleFix80(b))
        .find(b => /^(Đóng|Xong)$/i.test((b.textContent || '').trim()));

    if (!closeBtn) return false;

    modal.classList.add('lhl-qbank-view-modal-fix80');
    saveBtn.classList.add('lhl-fix80-save-btn');

    const mRect = modal.getBoundingClientRect();
    const cRect = closeBtn.getBoundingClientRect();

    // Tính vị trí của nút Đóng trong modal rồi đặt Lưu cùng hàng, nằm bên trái Đóng.
    const top = Math.max(8, Math.round(cRect.top - mRect.top));
    const rightOfClose = Math.max(16, Math.round(mRect.right - cRect.left));
    const saveRight = rightOfClose + 12;

    saveBtn.style.setProperty('position', 'absolute', 'important');
    saveBtn.style.setProperty('top', top + 'px', 'important');
    saveBtn.style.setProperty('right', saveRight + 'px', 'important');
    saveBtn.style.setProperty('left', 'auto', 'important');
    saveBtn.style.setProperty('bottom', 'auto', 'important');
    saveBtn.style.setProperty('margin', '0', 'important');
    saveBtn.style.setProperty('z-index', '1000', 'important');
    saveBtn.style.setProperty('height', Math.round(cRect.height || 40) + 'px', 'important');
    saveBtn.style.setProperty('display', 'inline-flex', 'important');
    saveBtn.style.setProperty('align-items', 'center', 'important');
    saveBtn.style.setProperty('justify-content', 'center', 'important');

    // Không thay đổi vị trí nút Đóng để tránh sinh nút lỗi/đè hộp sau.
    return true;
}

if (typeof lhlExamBankViewFile === 'function' && !window.__lhlFix80ViewWrapped) {
    window.__lhlFix80ViewWrapped = true;
    const __oldViewFix80 = lhlExamBankViewFile;
    lhlExamBankViewFile = async function() {
        const ret = await __oldViewFix80.apply(this, arguments);
        [0, 60, 160, 350].forEach(t => setTimeout(lhlQBankMoveSaveSameLineFix80, t));
        return ret;
    };
}

document.addEventListener('click', function(ev) {
    const label = (ev.target && ev.target.textContent || '').trim();
    if (/^(Xem|Sửa)$/i.test(label)) {
        [80, 180, 360].forEach(t => setTimeout(lhlQBankMoveSaveSameLineFix80, t));
    }
}, true);

if (!window.__lhlFix80ObserverInstalled) {
    window.__lhlFix80ObserverInstalled = true;
    const obs = new MutationObserver(() => {
        lhlQBankMoveSaveSameLineFix80();
    });
    obs.observe(document.body, {childList: true, subtree: true});
}

setTimeout(lhlQBankInstallFix80SafeSaveLineCSS, 200);



