function lhlQBankFindTopPreviewModalFix85() {
    const candidates = Array.from(document.querySelectorAll('div,section,article'))
        .filter(el => {
            if (!lhlQBankVisibleFix85(el)) return false;
            const text = (el.textContent || '').slice(0, 3500);
            if (!/Xem file ngân hàng/i.test(text)) return false;
            if (!/Biên dịch nhanh/i.test(text)) return false;
            if (!/Mã code nội dung/i.test(text)) return false;
            const btns = Array.from(el.querySelectorAll('button')).filter(lhlQBankVisibleFix85);
            return btns.some(b => /Lưu\s*sửa\s*nhanh/i.test((b.textContent || '').trim()))
                && btns.some(b => /^(Đóng|Xong)$/i.test((b.textContent || '').trim()));
        })
        .map(el => {
            const r = el.getBoundingClientRect();
            return {el, area: r.width * r.height, top: r.top, left: r.left};
        })
        // Modal xem nhanh thường là khung lớn phía trên cùng, không phải modal ngân hàng phía sau
        .sort((a,b) => b.area - a.area);
    return candidates.length ? candidates[0].el : null;
}

