function lhlQBankVisibleFix86(el) {
    if (!el) return false;
    const r = el.getBoundingClientRect();
    const st = window.getComputedStyle(el);
    return r.width > 0 && r.height > 0 && st.display !== 'none' && st.visibility !== 'hidden';
}

function lhlQBankFindPreviewModalFix86(saveBtn, closeBtn) {
    // Đi từ nút save lên cha gần nhất có cả 2 nút và dấu hiệu xem file ngân hàng.
    let p = saveBtn;
    while (p && p !== document.body) {
        if (p.contains(closeBtn)) {
            const text = (p.textContent || '').slice(0, 4000);
            if (/Xem file ngân hàng/i.test(text) && /Biên dịch nhanh/i.test(text)) return p;
        }
        p = p.parentElement;
    }

    // Fallback: tìm khối nhỏ nhất chứa cả save/close và có Biên dịch nhanh.
    const candidates = Array.from(document.querySelectorAll('div,section,article'))
        .filter(el => {
            if (!lhlQBankVisibleFix86(el)) return false;
            if (!el.contains(saveBtn) || !el.contains(closeBtn)) return false;
            const text = (el.textContent || '').slice(0, 4000);
            return /Xem file ngân hàng/i.test(text) && /Biên dịch nhanh/i.test(text);
        })
        .sort((a,b) => {
            const ar = a.getBoundingClientRect(), br = b.getBoundingClientRect();
            return (a.contains(b) ? 1 : 0) || ((ar.width*ar.height) - (br.width*br.height));
        });

    return candidates[0] || null;
}

function lhlQBankForcePreviewButtonsFix86() {
    lhlQBankInstallFix86ForceButtonPositionCSS();

    // Tìm tất cả nút Lưu sửa nhanh đang hiện, ưu tiên nút nằm trong khối có "Xem file ngân hàng".
    const buttons = Array.from(document.querySelectorAll('button')).filter(lhlQBankVisibleFix86);
    const saveButtons = buttons.filter(b => /Lưu\s*sửa\s*nhanh/i.test((b.textContent || '').trim()));
    if (!saveButtons.length) return false;

    for (const saveBtn of saveButtons) {
        // Chỉ xét modal cha của nút save này.
        let p = saveBtn.parentElement;
        let modalCandidate = null;
        while (p && p !== document.body) {
            const text = (p.textContent || '').slice(0, 4000);
            if (/Xem file ngân hàng/i.test(text) && /Biên dịch nhanh/i.test(text)) {
                modalCandidate = p;
                break;
            }
            p = p.parentElement;
        }
        if (!modalCandidate) continue;

        const closeBtn = Array.from(modalCandidate.querySelectorAll('button'))
            .filter(b => b !== saveBtn && lhlQBankVisibleFix86(b))
            .find(b => /^(Đóng|Xong)$/i.test((b.textContent || '').trim()));

        if (!closeBtn) continue;

        const modal = lhlQBankFindPreviewModalFix86(saveBtn, closeBtn) || modalCandidate;

        modal.classList.add('lhl-qbank-preview-fix86');
        saveBtn.classList.add('lhl-fix86-save-btn');
        closeBtn.classList.add('lhl-fix86-close-btn');

        // Ép trực tiếp để thắng style cũ trong mọi file.
        modal.style.setProperty('position', 'relative', 'important');
        modal.style.setProperty('padding-top', '76px', 'important');
        modal.style.setProperty('box-sizing', 'border-box', 'important');

        closeBtn.style.setProperty('position', 'absolute', 'important');
        closeBtn.style.setProperty('top', '18px', 'important');
        closeBtn.style.setProperty('right', '20px', 'important');
        closeBtn.style.setProperty('bottom', 'auto', 'important');
        closeBtn.style.setProperty('left', 'auto', 'important');
        closeBtn.style.setProperty('z-index', '99999', 'important');
        closeBtn.style.setProperty('margin', '0', 'important');
        closeBtn.style.setProperty('float', 'none', 'important');
        closeBtn.style.setProperty('clear', 'none', 'important');
        closeBtn.style.setProperty('display', 'inline-flex', 'important');
        closeBtn.style.setProperty('height', '40px', 'important');

        saveBtn.style.setProperty('position', 'absolute', 'important');
        saveBtn.style.setProperty('top', '18px', 'important');
        saveBtn.style.setProperty('right', '122px', 'important');
        saveBtn.style.setProperty('bottom', 'auto', 'important');
        saveBtn.style.setProperty('left', 'auto', 'important');
        saveBtn.style.setProperty('z-index', '99998', 'important');
        saveBtn.style.setProperty('margin', '0', 'important');
        saveBtn.style.setProperty('float', 'none', 'important');
        saveBtn.style.setProperty('clear', 'none', 'important');
        saveBtn.style.setProperty('display', 'inline-flex', 'important');
        saveBtn.style.setProperty('height', '40px', 'important');

        return true;
    }

    return false;
}

