// ============================================================
// FIX88-NH:
// Sửa lỗi tạo đề từ NH báo thiếu câu, ví dụ TN-12 xem nhanh có 2 câu
// nhưng khi tạo đề chỉ nhận 1 câu.
// Nguyên nhân: bộ tách câu lúc tạo đề quá khó tính với vài cấu trúc HTML.
// FIX88 thêm bộ tách mềm hơn theo mốc "Câu 1., Câu 2., ..."
// và dùng bộ tách có số câu nhiều hơn.
// ============================================================

function lhlQBankStripOuterHtmlForSplitFix88(s) {
    s = String(s || '');
    s = s.replace(/<!DOCTYPE[\s\S]*?>/gi, '');
    s = s.replace(/<html\b[^>]*>/gi, '').replace(/<\/html>/gi, '');
    s = s.replace(/<head\b[\s\S]*?<\/head>/gi, '');
    s = s.replace(/<body\b[^>]*>/gi, '').replace(/<\/body>/gi, '');
    s = s.replace(/<h[1-6][^>]*class=["'][^"']*qbank-doc-title[^"']*["'][^>]*>[\s\S]*?<\/h[1-6]>/gi, '');
    s = s.replace(/<!--\s*LHL_QBANK_FILE:[\s\S]*?-->/gi, '');
    s = s.replace(/<script\b[\s\S]*?<\/script>/gi, '');
    s = s.replace(/<style\b[\s\S]*?<\/style>/gi, '');
    return s.trim();
}

function lhlQBankSplitByQuestionMarkersFix88(body) {
    let s = lhlQBankStripOuterHtmlForSplitFix88(body);
    if (!s) return [];

    // Dọn các title ngân hàng bị chèn vào nội dung, nếu có.
    s = s.replace(/<h[1-6][^>]*>\s*(?:TN|DS|Đ\/S|TLN)-\d+\s*<\/h[1-6]>/gi, '');

    // Mốc câu: bắt được cả:
    // <b> Câu 1. </b>
    // <br> Câu 2.
    // </div><div> Câu 3.
    // Câu 4.
    // Không bắt "câu" thường trong lời văn vì cần chữ C hoa và có số.
    const markerRe = /(?:^|[\n\r]|<br\s*\/?>|<\/(?:div|p|table|tbody|tr|td|label|center)>|<div\b[^>]*>|<p\b[^>]*>|<b\b[^>]*>|<strong\b[^>]*>)\s*(?:<[^>]{1,80}>\s*)*Câu\s*\d+\s*[\.:]?/gi;

    const hits = [];
    let m;
    while ((m = markerRe.exec(s)) !== null) {
        // Tìm vị trí bắt đầu chữ Câu thật, không lấy phần delimiter trước nó.
        const chunk = m[0];
        const rel = chunk.search(/Câu\s*\d+\s*[\.:]?/i);
        const pos = m.index + (rel >= 0 ? rel : 0);

        // Tránh trùng vị trí do regex bắt qua thẻ gần nhau.
        if (!hits.length || Math.abs(pos - hits[hits.length - 1]) > 10) {
            hits.push(pos);
        }
    }

    if (hits.length <= 1) return hits.length === 1 ? [s.slice(hits[0]).trim()] : [];

    const out = [];
    for (let i = 0; i < hits.length; i++) {
        const start = hits[i];
        const end = i + 1 < hits.length ? hits[i + 1] : s.length;
        let q = s.slice(start, end).trim();

        // Dọn rác cuối giữa các câu nhưng không đụng ảnh/base64.
        q = q.replace(/(?:<br\s*\/?>|\s|&nbsp;)+$/ig, '').trim();

        const plain = q.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        if (plain.length > 12) out.push(q);
    }
    return out;
}

function lhlQBankSplitBankFileQuestionsFix87(body) {
    let s = lhlQBankStripOuterHtmlForSplitFix88(body);
    let qsA = [];
    let qsB = [];

    try {
        if (typeof lhlQBankSplitQuestionsInPart === 'function') qsA = lhlQBankSplitQuestionsInPart(s) || [];
    } catch(e) {}

    try {
        if (typeof lhlMixSplitQuestions === 'function') qsB = lhlMixSplitQuestions(s) || [];
    } catch(e) {}

    const qsC = lhlQBankSplitByQuestionMarkersFix88(s);

    // Chọn kết quả tách được nhiều câu hơn, vì ngân hàng có thể lưu câu theo nhiều cấu trúc khác nhau.
    let best = qsA;
    if ((qsB || []).length > (best || []).length) best = qsB;
    if ((qsC || []).length > (best || []).length) best = qsC;

    if (!best || !best.length) {
        const plain = s.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
        if (plain.length > 12) best = [s];
    }

    return (best || []).map(x => String(x || '').trim()).filter(x => {
        const plain = x.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
        return plain.length > 12;
    });
}

// Đồng bộ luôn hàm đếm nếu nơi khác gọi lại.
if (typeof lhlExamBankCountQuestionsInBody === 'function' && !window.__lhlFix88CountWrapped) {
    window.__lhlFix88CountWrapped = true;
    const __oldCountFix88 = lhlExamBankCountQuestionsInBody;
    lhlExamBankCountQuestionsInBody = function(body) {
        try {
            const nNew = lhlQBankSplitBankFileQuestionsFix87(body).length;
            const nOld = __oldCountFix88.apply(this, arguments);
            return Math.max(nNew || 0, nOld || 0);
        } catch(e) {
            return __oldCountFix88.apply(this, arguments);
        }
    };
}



// ============================================================
// FIX89-NH:
// Sửa định dạng đề tạo từ Ngân hàng:
// 1) Header/tiêu đề đề thi dùng bảng + inline style cố định,
//    không phụ thuộc CSS ngoài nên mở lại/in PDF vẫn giữ bố cục đẹp.
// 2) Ảnh lấy từ ngân hàng không bung to; CSS khống chế giống xem nhanh.
// ============================================================

function lhlQBankNormalizeGeneratedExamImagesFix89(html) {
    let s = String(html || '');

    // Đổi wrapper ảnh ngân hàng thành wrapper gọn trong đề.
    s = s.replace(/<div\s+class=["']qbank-img-wrap(?:\s+[^"']*)?["'][^>]*>/gi, '<div class="qbank-img-wrap lhl-qbank-img-compact">');

    // Nếu ảnh bị bọc trong table 1 ô thì chuyển sang div để không sinh khung/không bung theo table.
    s = s.replace(
        /<table\b([^>]*)>\s*<tbody>\s*<tr>\s*<td([^>]*)>\s*(<img\b[\s\S]*?>)\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi,
        '<div class="qbank-img-wrap lhl-qbank-img-compact">$3</div>'
    );

    // Gắn class cho mọi ảnh trong đề ngân hàng để CSS quản lý.
    s = s.replace(/<img\b([^>]*)>/gi, function(full) {
        let tag = full;
        if (!/class\s*=/.test(tag)) {
            tag = tag.replace(/<img\b/i, '<img class="lhl-qbank-generated-img"');
        } else if (!/lhl-qbank-generated-img/.test(tag)) {
            tag = tag.replace(/class=(["'])(.*?)\1/i, function(m, q, cls) {
                return `class=${q}${cls} lhl-qbank-generated-img${q}`;
            });
        }
        if (/width\s*:\s*100%\s*;?/i.test(tag) || /width=["']?100%["']?/i.test(tag)) {
            if (!/data-qbank-wide-img=/.test(tag)) tag = tag.replace(/<img\b/i, '<img data-qbank-wide-img="1"');
        }
        return tag;
    });

    return s;
}

