function lhlQBankTemplatePartsFix87(sourceFullHtml) {
    // FIX89: dùng head/style từ mẫu hiện có nếu có, nhưng header luôn dùng header chuẩn fix89.
    const full = lhlQBankEnsureMixHelpersFix87(sourceFullHtml || lhlQBankDefaultTemplateFullHtmlFix87());
    const shell = (typeof lhlMixBodyAndShell === 'function') ? lhlMixBodyAndShell(full) : {head:'<head><meta charset="UTF-8"></head>', body: full};
    const body = shell.body || '';
    const parts = (typeof lhlMixFindPartTitles === 'function') ? lhlMixFindPartTitles(body) : {};
    if (!parts.I || !parts.II || !parts.III) {
        const def = lhlQBankDefaultTemplateFullHtmlFix87();
        const sh2 = (typeof lhlMixBodyAndShell === 'function') ? lhlMixBodyAndShell(def) : {head:'<head><meta charset="UTF-8"></head>', body:def};
        const b2 = sh2.body || '';
        const p2 = (typeof lhlMixFindPartTitles === 'function') ? lhlMixFindPartTitles(b2) : {};
        return {
            head: sh2.head,
            header: '',
            p1Title: p2.I ? p2.I.html : '<div class="exam-part-box">PHẦN I. Thí sinh trả lời từ câu 1 đến câu 12. Mỗi câu hỏi thí sinh chỉ chọn một phương án.</div>',
            p2Title: p2.II ? p2.II.html : '<div class="exam-part-box">PHẦN II. Thí sinh trả lời đúng hoặc sai.</div>',
            p3Title: p2.III ? p2.III.html : '<div class="exam-part-box">PHẦN III. Thí sinh trả lời ngắn.</div>',
            footer: '<div class="exam-end-line">---------- HẾT ----------</div>'
        };
    }
    const p1Title = parts.I.html;
    const p2Title = parts.II.html;
    const p3Title = parts.III.html;
    let afterP3 = body.slice(parts.III.end);
    let footer = '';
    const footerIdx = afterP3.search(/<div\b[^>]*class=["'][^"']*exam-end-line|[-–—]{3,}\s*(?:<strong[^>]*>)?\s*HẾT/i);
    if (footerIdx >= 0) footer = afterP3.slice(footerIdx);
    if (!footer.trim()) footer = '<div class="exam-end-line">---------- HẾT ----------</div>';
    return {head: shell.head, header: '', p1Title, p2Title, p3Title, footer};
}

function lhlQBankBuildExamFileFromSelectionsFix87(template, code, selections, opts) {
    const p1Ans = [], p2Ans = [], p3Ans = [];
    const p1Blocks = selections.TN.map((b,i) => {
        b = lhlQBankNormalizeGeneratedExamImagesFix89(b);
        const r = lhlQBankProcessQuestionForExamFix87(b, 'TN', i+1);
        p1Ans.push(r.answer || '');
        return lhlQBankWrapExamBlockFix87(lhlQBankNormalizeGeneratedExamImagesFix89(r.html));
    });
    const p2Blocks = selections.DS.map((b,i) => {
        b = lhlQBankNormalizeGeneratedExamImagesFix89(b);
        const r = lhlQBankProcessQuestionForExamFix87(b, 'DS', i+1);
        p2Ans.push(r.answer || '');
        return lhlQBankWrapExamBlockFix87(lhlQBankNormalizeGeneratedExamImagesFix89(r.html));
    });
    const p3Blocks = selections.TLN.map((b,i) => {
        b = lhlQBankNormalizeGeneratedExamImagesFix89(b);
        const r = lhlQBankProcessQuestionForExamFix87(b, 'TLN', i+1);
        p3Ans.push(r.answer || '');
        return lhlQBankWrapExamBlockFix87(lhlQBankNormalizeGeneratedExamImagesFix89(r.html));
    });

    const header = lhlQBankBuildHeaderFix89(opts || {}, code);
    const body = header
        + template.p1Title + '\n' + p1Blocks.join('\n')
        + '\n' + template.p2Title + '\n' + p2Blocks.join('\n')
        + '\n' + template.p3Title + '\n' + p3Blocks.join('\n')
        + '\n' + template.footer;

    let full = '<!DOCTYPE html>\n<html>\n' + template.head + '\n<body>\n' + body + '\n</body>\n</html>';
    full = lhlQBankInjectGeneratedExamCssFix89(full);

    // Không dùng lhlMixApplyCodeAndTime ở đây nữa vì header đã được dựng chuẩn fix89,
    // tránh làm lệch lại bố cục tiêu đề.
    return {content: full, p1Ans, p2Ans, p3Ans};
}



// ============================================================
// FIX90-NH:
// Tạo đề từ Ngân hàng dùng lại TIÊU ĐỀ/MẪU ĐỀ hiện hành của phần mềm,
// giống hướng nút Trộn đề, không tự dựng header riêng như FIX89 nữa.
// Mục tiêu:
// - Header đồng bộ với nút Tiêu đề/phần mềm.
// - Mã đề đi theo cơ chế có sẵn để in PDF có mã đề/trang chuẩn hơn.
// - Vẫn giữ khống chế ảnh ngân hàng không bung quá to.
// ============================================================

function lhlQBankNormalizeGeneratedExamImagesFix90(html) {
    let s = String(html || '');

    s = s.replace(/<div\s+class=["']qbank-img-wrap(?:\s+[^"']*)?["'][^>]*>/gi, '<div class="qbank-img-wrap lhl-qbank-img-compact">');

    s = s.replace(
        /<table\b([^>]*)>\s*<tbody>\s*<tr>\s*<td([^>]*)>\s*(<img\b[\s\S]*?>)\s*<\/td>\s*<\/tr>\s*<\/tbody>\s*<\/table>/gi,
        '<div class="qbank-img-wrap lhl-qbank-img-compact">$3</div>'
    );

    s = s.replace(/<img\b([^>]*)>/gi, function(full) {
        let tag = full;
        if (!/class\s*=/.test(tag)) {
            tag = tag.replace(/<img\b/i, '<img class="lhl-qbank-generated-img"');
        } else if (!/lhl-qbank-generated-img/.test(tag)) {
            tag = tag.replace(/class=(["'])(.*?)\1/i, function(m, q, cls) {
                return `class=${q}${cls} lhl-qbank-generated-img${q}`;
            });
        }
        if (/width\s*:\s*100%\s*;?/i.test(tag) || /width=["']?100%["']?/i.test(tag)) {
            if (!/data-qbank-wide-img=/.test(tag)) tag = tag.replace(/<img\b/i, '<img data-qbank-wide-img="1"');
        }
        return tag;
    });

    return s;
}

