function lhlQBankGetCurrentFullHtmlTemplateFix90() {
    // Ưu tiên dùng đúng HTML hiện hành do phần mềm tạo ra, vì nó chứa tiêu đề chuẩn
    // từ nút Tiêu đề/Mẫu đề và các CSS/in PDF hiện có.
    try {
        if (typeof generateFullHTML === 'function') {
            let html = generateFullHTML(false);
            if (html && /<body[\s>]/i.test(html) && /PHẦN\s*(I|1)/i.test(html)) return html;
        }
    } catch(e) {}

    try {
        if (typeof getFullHTML === 'function') {
            let html = getFullHTML(false);
            if (html && /<body[\s>]/i.test(html) && /PHẦN\s*(I|1)/i.test(html)) return html;
        }
    } catch(e) {}

    try {
        const editorEl = document.getElementById('editor') || document.querySelector('textarea');
        const raw = editorEl ? (editorEl.value || '') : '';
        if (raw && /<html[\s>]/i.test(raw) && /PHẦN\s*(I|1)/i.test(raw)) return raw;
    } catch(e) {}

    // Fallback về hàm cũ nếu có.
    try {
        if (typeof lhlQBankDefaultTemplateFullHtmlFix87 === 'function') return lhlQBankDefaultTemplateFullHtmlFix87();
    } catch(e) {}

    return `<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body>
<div class="exam-part-box">PHẦN I. Thí sinh trả lời từ câu 1 đến câu 12. Mỗi câu hỏi thí sinh chỉ chọn một phương án.</div>
<div class="exam-part-box">PHẦN II. Thí sinh trả lời đúng hoặc sai.</div>
<div class="exam-part-box">PHẦN III. Thí sinh trả lời ngắn.</div>
</body></html>`;
}

function lhlQBankRemoveOldQuestionsBetweenPartsFix90(body, parts) {
    const header = body.slice(0, parts.I.end);
    const p2Title = parts.II.html;
    const p3Title = parts.III.html;

    // Footer lấy sau phần III, nhưng bỏ câu hỏi cũ trong phần III.
    const afterP3 = body.slice(parts.III.end);
    let footer = '';
    const footerIdx = afterP3.search(/<div\b[^>]*class=["'][^"']*exam-end-line|[-–—]{3,}\s*(?:<[^>]+>\s*)*HẾT|Thí\s*sinh\s*không\s*được\s*sử\s*dụng\s*tài\s*liệu/i);
    if (footerIdx >= 0) footer = afterP3.slice(footerIdx);
    if (!footer.trim()) footer = '<div class="exam-end-line">---------- HẾT ----------</div>';

    return {
        headerThroughP1Title: header,
        p2Title,
        p3Title,
        footer
    };
}

function lhlQBankTemplatePartsFix87(sourceFullHtml) {
    let full = lhlQBankGetCurrentFullHtmlTemplateFix90();

    // Nếu hàm trộn đề có hàm bảo toàn MathJax/CSS thì dùng lại.
    try {
        if (typeof lhlMixEnsureMathJaxInFullHtmlV43 === 'function') full = lhlMixEnsureMathJaxInFullHtmlV43(full);
        else if (typeof lhlQBankEnsureMixHelpersFix87 === 'function') full = lhlQBankEnsureMixHelpersFix87(full);
    } catch(e) {}

    const shell = (typeof lhlMixBodyAndShell === 'function')
        ? lhlMixBodyAndShell(full)
        : {
            head: (full.match(/<head[\s\S]*?<\/head>/i) || ['<head><meta charset="UTF-8"></head>'])[0],
            body: ((full.match(/<body[^>]*>([\s\S]*?)<\/body>/i) || [null, full])[1] || full)
          };

    const body = shell.body || '';
    const parts = (typeof lhlMixFindPartTitles === 'function') ? lhlMixFindPartTitles(body) : {};

    if (!parts.I || !parts.II || !parts.III) {
        // Fallback thật sự mới dùng mẫu mặc định, nhưng vẫn tránh tự dựng header fix89.
        const fallback = `<!DOCTYPE html><html>${shell.head || '<head><meta charset="UTF-8"></head>'}<body>
<div class="exam-part-box">PHẦN I. Thí sinh trả lời từ câu 1 đến câu 12. Mỗi câu hỏi thí sinh chỉ chọn một phương án.</div>
<div class="exam-part-box">PHẦN II. Thí sinh trả lời đúng hoặc sai.</div>
<div class="exam-part-box">PHẦN III. Thí sinh trả lời ngắn.</div>
<div class="exam-end-line">---------- HẾT ----------</div>
</body></html>`;
        const sh2 = (typeof lhlMixBodyAndShell === 'function') ? lhlMixBodyAndShell(fallback) : {head:'<head><meta charset="UTF-8"></head>', body:fallback};
        const p2 = (typeof lhlMixFindPartTitles === 'function') ? lhlMixFindPartTitles(sh2.body || '') : {};
        return {
            head: sh2.head,
            headerThroughP1Title: p2.I ? (sh2.body || '').slice(0, p2.I.end) : '<div class="exam-part-box">PHẦN I. Thí sinh trả lời từ câu 1 đến câu 12. Mỗi câu hỏi thí sinh chỉ chọn một phương án.</div>',
            p2Title: p2.II ? p2.II.html : '<div class="exam-part-box">PHẦN II. Thí sinh trả lời đúng hoặc sai.</div>',
            p3Title: p2.III ? p2.III.html : '<div class="exam-part-box">PHẦN III. Thí sinh trả lời ngắn.</div>',
            footer: '<div class="exam-end-line">---------- HẾT ----------</div>'
        };
    }

    const core = lhlQBankRemoveOldQuestionsBetweenPartsFix90(body, parts);
    return {
        head: shell.head,
        headerThroughP1Title: core.headerThroughP1Title,
        p2Title: core.p2Title,
        p3Title: core.p3Title,
        footer: core.footer
    };
}

function lhlQBankApplyCodeUsingExistingSystemFix90(full, code, opts) {
    let s = String(full || '');

    // Ưu tiên dùng cơ chế sẵn của nút Trộn đề nếu có, để mã đề và in PDF đồng bộ.
    try {
        if (typeof lhlMixApplyCodeAndTime === 'function') {
            s = lhlMixApplyCodeAndTime(
                s,
                code,
                opts.duration,
                opts.examTitle || '',
                opts.examSubject || '',
                opts.examGrade || '',
                opts.schoolName || ''
            );
            return s;
        }
    } catch(e) {}

    // Fallback: thay Mã đề hiện có.
    if (/Mã\s*đề\s*\d+/i.test(s)) {
        s = s.replace(/Mã\s*đề\s*\d+/gi, 'Mã đề ' + String(code));
    } else {
        s = s.replace(/(<body[^>]*>)/i, '$1\n<div class="lhl-exam-code" style="float:right;border:1px solid #000;padding:4px 8px;font-weight:bold;">Mã đề ' + String(code) + '</div>\n');
    }

    return s;
}

function lhlQBankBuildExamFileFromSelectionsFix87(template, code, selections, opts) {
    opts = opts || {};
    const p1Ans = [], p2Ans = [], p3Ans = [];

    const p1Blocks = selections.TN.map((b,i) => {
        b = lhlQBankNormalizeGeneratedExamImagesFix90(b);
        const r = lhlQBankProcessQuestionForExamFix87(b, 'TN', i+1);
        p1Ans.push(r.answer || '');
        return lhlQBankWrapExamBlockFix87(lhlQBankNormalizeGeneratedExamImagesFix90(r.html));
    });

    const p2Blocks = selections.DS.map((b,i) => {
        b = lhlQBankNormalizeGeneratedExamImagesFix90(b);
        const r = lhlQBankProcessQuestionForExamFix87(b, 'DS', i+1);
        p2Ans.push(r.answer || '');
        return lhlQBankWrapExamBlockFix87(lhlQBankNormalizeGeneratedExamImagesFix90(r.html));
    });

    const p3Blocks = selections.TLN.map((b,i) => {
        b = lhlQBankNormalizeGeneratedExamImagesFix90(b);
        const r = lhlQBankProcessQuestionForExamFix87(b, 'TLN', i+1);
        p3Ans.push(r.answer || '');
        return lhlQBankWrapExamBlockFix87(lhlQBankNormalizeGeneratedExamImagesFix90(r.html));
    });

    // FIX90: giữ nguyên header + tiêu đề phần I của mẫu hiện hành.
    const body = (template.headerThroughP1Title || '')
        + '\n' + p1Blocks.join('\n')
        + '\n' + (template.p2Title || '') + '\n' + p2Blocks.join('\n')
        + '\n' + (template.p3Title || '') + '\n' + p3Blocks.join('\n')
        + '\n' + (template.footer || '');

    let full = '<!DOCTYPE html>\n<html>\n' + (template.head || '<head><meta charset="UTF-8"></head>') + '\n<body>\n' + body + '\n</body>\n</html>';

    full = lhlQBankInjectGeneratedExamCssFix90(full);
    full = lhlQBankApplyCodeUsingExistingSystemFix90(full, code, opts);

    return {content: full, p1Ans, p2Ans, p3Ans};
}

// Cập nhật mô tả hộp tạo đề cho đúng: dùng tiêu đề hiện hành.
if (typeof lhlQBankOpenGenerateExamDialogFix87 === 'function' && !window.__lhlFix90OpenGenWrapped) {
    window.__lhlFix90OpenGenWrapped = true;
    const __oldOpenGenFix90 = lhlQBankOpenGenerateExamDialogFix87;
    lhlQBankOpenGenerateExamDialogFix87 = function() {
        const ret = __oldOpenGenFix90.apply(this, arguments);
        setTimeout(() => {
            const note = document.querySelector('.lhl-bank-gen-note');
            if (note && !note.dataset.fix90) {
                note.dataset.fix90 = '1';
                note.innerHTML += '<br><b>FIX90:</b> Đề tạo ra sẽ dùng đúng tiêu đề/mẫu đề hiện hành của phần mềm để đồng bộ với nút Trộn đề và in PDF.';
            }
        }, 50);
        return ret;
    };
}



