// FIX93-NH:
// Nén thêm khoảng cách giữa các câu PHẦN III khi tạo đề từ Ngân hàng.
// Giữ khoảng cách vừa phải, không để các câu dính sát.
// ============================================================

function lhlQBankCompactP3BlockFix91(html) {
    let s = String(html || '').trim();

    // Dọn br/khoảng trắng đầu cuối.
    s = s.replace(/^(?:\s|&nbsp;|<br\s*\/?>)+/ig, '');
    s = s.replace(/(?:\s|&nbsp;|<br\s*\/?>)+$/ig, '');

    // Nén nhiều br liên tiếp.
    s = s.replace(/(?:<br\s*\/?>\s*){2,}/gi, '<br>');

    // Xóa p/div rỗng.
    s = s.replace(/<p[^>]*>\s*(?:&nbsp;|\s|<br\s*\/?>)*<\/p>/gi, '');
    s = s.replace(/<div[^>]*>\s*(?:&nbsp;|\s|<br\s*\/?>)*<\/div>/gi, '');

    // Xóa margin lớn trong inline style.
    s = s.replace(/margin-top\s*:\s*[^;]+;?/gi, 'margin-top:0;');
    s = s.replace(/margin-bottom\s*:\s*[^;]+;?/gi, 'margin-bottom:0;');
    s = s.replace(/padding-top\s*:\s*[^;]+;?/gi, 'padding-top:0;');
    s = s.replace(/padding-bottom\s*:\s*[^;]+;?/gi, 'padding-bottom:0;');

    // Nếu câu kết thúc bằng nhiều thẻ đóng + br thì dọn gọn.
    s = s.replace(/(<\/(?:p|div)>)\s*(?:<br\s*\/?>\s*)+/gi, '$1');
    s = s.replace(/(?:<br\s*\/?>\s*)+(?=<b>\s*Câu\s*\d+)/gi, '');

    return s.trim();
}

