function lhlQBankTightPreviewBlocksFix96(host) {
    let inP3 = false, blocks = [];
    Array.from(host.children).forEach(node => {
        const t = String(node.textContent || '').replace(/\s+/g, ' ').trim();
        if (/^PHẦN\s*(III|3)\b/i.test(t)) { inP3 = true; return; }
        if (inP3 && /(?:HẾT|Thí sinh không được sử dụng tài liệu)/i.test(t) &&
            !node.classList.contains('lhl-mix-question-block')) { inP3 = false; return; }
        if (inP3 && node.classList && node.classList.contains('lhl-mix-question-block')) {
            node.classList.add('lhl-qbank-p3-block');
            blocks.push(node);
        }
    });
    host.querySelectorAll('.lhl-qbank-p3-block').forEach(n => { if (!blocks.includes(n)) blocks.push(n); });

    blocks.forEach((block, i) => {
        // Sau khi Ẩn ĐA/ĐS, bỏ các dòng xuống hàng trống còn sót cuối câu.
        block.innerHTML = block.innerHTML
            .replace(/(?:\s|&nbsp;|<br\s*\/?>)+$/gi, '')
            .replace(/(?:<br\s*\/?>\s*){2,}/gi, '<br>');
        let last = block.lastChild;
        while (last) {
            if (last.nodeType === Node.TEXT_NODE && !String(last.textContent || '').trim()) {
                last.remove();
            } else if (last.nodeType === Node.ELEMENT_NODE &&
                       (/^BR$/i.test(last.tagName) ||
                        (!String(last.textContent || '').replace(/\u00a0/g,'').trim() && !last.querySelector('img')))) {
                last.remove();
            } else break;
            last = block.lastChild;
        }
        block.style.setProperty('margin-top', i === 0 ? '0px' : '-10px', 'important');
        block.style.setProperty('margin-bottom', '0', 'important');
        block.style.setProperty('padding', '0', 'important');
        block.style.setProperty('line-height', '1.16', 'important');
    });
}

// Ghi đè xử lý FIX95: phần biên dịch được nén P3; full HTML/PDF không bị ép ảnh rối nữa.
function lhlQBankPostprocessDomHtmlFix95(html, fullDocument) {
    let s = String(html || '');
    if (!s) return s;
    if (fullDocument) return lhlQBankRemoveOldGeneratedStylesFix96(s);

    try {
        const host = document.createElement('div');
        host.className = 'lhl-qbank-generated-exam';
        host.innerHTML = s;
        lhlQBankTightPreviewBlocksFix96(host);
        return '<div class="lhl-qbank-generated-exam">' + host.innerHTML + '</div>' +
               '<style id="lhl-fix96-preview-p3-css">' + lhlQBankTightPreviewCssFix96() + '</style>';
    } catch (e) {
        return s;
    }
}



