function lhlQBankOpenGenerateExamDialogFix87() {
    lhlQBankInstallFix100GenerateDialogStyle();

    const old = document.getElementById('lhlBankGenOverlay');
    if (old) old.remove();

    const overlay = document.createElement('div');
    overlay.id = 'lhlBankGenOverlay';
    overlay.className = 'lhl-bank-gen-overlay lhl-fix100-keep-dialog';

    overlay.innerHTML = `
    <div class="lhl-bank-gen-dialog">
        <div class="lhl-bank-gen-head">
            <h2>🧩 Tạo đề từ ngân hàng</h2>
        </div>
        <div class="lhl-bank-gen-body">
            <div class="lhl-bank-gen-grid">
                <div class="lhl-bank-gen-field"><label>Số mã đề cần tạo</label><input id="bankGenCount" type="number" min="1" max="100" value="4"></div>
                <div class="lhl-bank-gen-field"><label>Mã đề bắt đầu hoặc danh sách mã</label><input id="bankGenStartCode" type="text" value="1301"></div>
                <div class="lhl-bank-gen-field"><label>Thời gian làm bài</label><input id="bankGenDuration" type="number" min="1" value="90"></div>
                <div class="lhl-bank-gen-field"><label>Tên file đáp án</label><input id="bankGenAnswerName" type="text" value="Bang_Dap_An_NH.xls"></div>
                <div class="lhl-bank-gen-field"><label>Tên trường</label><input id="bankGenSchool" type="text" value=""></div>
                <div class="lhl-bank-gen-field"><label>Tiêu đề đề thi</label><input id="bankGenTitle" type="text" value=""></div>
                <div class="lhl-bank-gen-field"><label>Môn</label><input id="bankGenSubject" type="text" value="MÔN: TOÁN"></div>
                <div class="lhl-bank-gen-field"><label>Khối</label><input id="bankGenGrade" type="text" value="KHỐI 12"></div>
            </div>
            <div class="lhl-bank-gen-note">
                <b>Cách rút:</b> mỗi file <b>TN-1, TN-2, Đ/S-1, TLN-1...</b> là một vị trí câu trong đề.
                Phần mềm rút theo ô <b>Chọn</b> của từng file. Nếu thầy tick một số file thì chỉ dùng các file được tick; nếu không tick file nào thì dùng toàn bộ file có <b>Chọn &gt; 0</b>.
                <br><b>Lưu ý:</b> để các mã đề khác câu hoàn toàn, mỗi file cần có đủ số câu = số mã đề × số câu chọn.
            </div>
            <div id="bankGenError" class="lhl-bank-gen-error" role="alert" aria-live="polite"></div>
        </div>
        <div class="lhl-bank-gen-actions">
            <button type="button" class="lhl-bank-gen-cancel" id="bankGenCancel">Hủy</button>
            <button type="button" class="lhl-bank-gen-ok" id="bankGenOk">Tạo đề</button>
        </div>
    </div>`;

    document.body.appendChild(overlay);

    const errBox = overlay.querySelector('#bankGenError');
    const okBtn = overlay.querySelector('#bankGenOk');
    const cancelBtn = overlay.querySelector('#bankGenCancel');
    let isWorking = false;

    const keepDialogOpen = () => {
        // Phòng trường hợp sau hộp native/chức năng nền nào đó làm modal bị gỡ nhầm.
        if (!document.body.contains(overlay)) document.body.appendChild(overlay);
    };

    const close = () => {
        if (!isWorking && overlay.parentNode) overlay.remove();
    };

    const showErr = (msg) => {
        keepDialogOpen();
        const detail = String(msg || 'Có lỗi xảy ra.');
        errBox.innerHTML =
            '<div class="fix100-error-title">⚠️ Chưa tạo được đề</div>' +
            '<div>' + lhlQBankEscapeHtml(detail) + '</div>' +
            '<div class="fix100-error-help">Thầy sửa lại thông tin hoặc dữ liệu ngân hàng, rồi bấm Tạo đề tiếp.</div>';
        errBox.classList.add('show');
        errBox.scrollIntoView({block:'nearest', behavior:'smooth'});
    };

    const clearErr = () => {
        errBox.classList.remove('show');
        errBox.innerHTML = '';
    };

    const setWorking = (flag) => {
        isWorking = !!flag;
        okBtn.classList.toggle('is-working', isWorking);
        okBtn.disabled = isWorking;
        cancelBtn.disabled = isWorking;
        okBtn.textContent = isWorking ? 'Đang tạo...' : 'Tạo đề';
    };

    const val = id => String(overlay.querySelector('#' + id)?.value || '').trim();

    cancelBtn.onclick = function(ev) {
        ev.preventDefault();
        close();
    };

    // Không đóng khi click nền ngoài hộp thoại; tránh mất dữ liệu đang nhập.
    overlay.onclick = function(ev) {
        if (ev.target === overlay) ev.stopPropagation();
    };

    okBtn.onclick = async function(ev) {
        ev.preventDefault();
        ev.stopPropagation();
        if (isWorking) return;

        clearErr();
        setWorking(true);
        try {
            const opts = {
                count: val('bankGenCount'),
                startCode: val('bankGenStartCode') || '1301',
                duration: Math.max(1, parseInt(val('bankGenDuration'), 10) || 90),
                answerName: val('bankGenAnswerName') || 'Bang_Dap_An_NH.xls',
                schoolName: val('bankGenSchool'),
                examTitle: val('bankGenTitle'),
                examSubject: val('bankGenSubject'),
                examGrade: val('bankGenGrade')
            };

            const pack = await lhlQBankGenerateExamPackageFix87(opts);
            keepDialogOpen();

            if (!(window.pywebview && window.pywebview.api && window.pywebview.api.save_mixed_exam_package)) {
                showErr('Chức năng này cần chạy trong phần mềm desktop để chọn thư mục lưu.');
                return;
            }

            const res = await window.pywebview.api.save_mixed_exam_package(pack.files, pack.answerHtml, opts.answerName, pack.matrixHtml || "", pack.matrixFilename || "");
            keepDialogOpen();

            if (res && res.ok) {
                if (typeof showToast === 'function') {
                    showToast('✅ Đã tạo ' + pack.files.length + ' đề từ ngân hàng và file đáp án.');
                }
                isWorking = false;
                overlay.remove(); // Chỉ đóng khi thành công.
            } else if (res && res.cancelled) {
                showErr('Thầy đã hủy chọn thư mục lưu. Dữ liệu vẫn được giữ lại để thầy tạo tiếp.');
            } else {
                showErr('Lỗi lưu bộ đề: ' + ((res && res.error) || 'Không rõ lỗi'));
            }
        } catch(e) {
            console.error(e);
            keepDialogOpen();
            showErr(e && e.message ? e.message : String(e));
            if (typeof showToast === 'function') showToast('❌ Chưa tạo được đề từ ngân hàng.');
        } finally {
            if (document.body.contains(overlay)) setWorking(false);
        }
    };

    overlay.querySelector('#bankGenCount').focus();
    overlay.querySelector('#bankGenCount').select();
}



// ============================================================
// FIX101-NH - PHÁT TRIỂN TRÊN NỀN FIX100/FIX99 ỔN ĐỊNH
// 1) Không chặn tạo đề khi số câu trong file < số mã đề cần tạo.
// 2) Mỗi file rút theo chu kỳ xáo ngẫu nhiên không lặp:
//    dùng hết kho câu của file rồi mới xáo lại vòng mới để rút tiếp.
// 3) Mỗi đề: xáo thứ tự câu trong từng phần.
//    - TN: đảo thứ tự câu + lhlMixProcessPart1Block tiếp tục đảo A/B/C/D.
//    - Đ/S: chỉ đảo thứ tự câu, giữ thứ tự các ý.
//    - TLN: chỉ đảo thứ tự câu.
// Không đụng ảnh width 40%, PDF theo code và khoảng cách P3 của FIX99.
// ============================================================

function lhlQBankCycleDrawerFix101(questions) {
    const source = (questions || []).slice().filter(Boolean);
    let pool = [];
    let lastDrawn = null;

    function refill(avoidSet) {
        pool = lhlQBankShuffleCopyFix87(source);
        if (pool.length > 1) {
            // Tránh lặp ngay đúng câu vừa rút ở ranh giới hai vòng nếu có thể.
            let badFirst = lastDrawn && pool[0] === lastDrawn;
            if (avoidSet && avoidSet.has(pool[0])) badFirst = true;
            if (badFirst) {
                const swapIndex = pool.findIndex((q, i) => i > 0 && q !== lastDrawn && !(avoidSet && avoidSet.has(q)));
                if (swapIndex > 0) {
                    [pool[0], pool[swapIndex]] = [pool[swapIndex], pool[0]];
                }
            }
        }
    }

    return {
        draw: function(n) {
            const wanted = Math.max(0, parseInt(n, 10) || 0);
            const out = [];
            const usedThisExam = new Set();

            while (out.length < wanted) {
                if (!pool.length) refill(usedThisExam);
                if (!pool.length) break;

                // Nếu đang rút nhiều câu từ cùng file cho một đề,
                // ưu tiên không trùng trong chính đề đó khi kho cho phép.
                if (source.length >= wanted && usedThisExam.has(pool[0])) {
                    const swapIndex = pool.findIndex((q, i) => i > 0 && !usedThisExam.has(q));
                    if (swapIndex > 0) [pool[0], pool[swapIndex]] = [pool[swapIndex], pool[0]];
                }

                const q = pool.shift();
                out.push(q);
                usedThisExam.add(q);
                lastDrawn = q;
            }
            return out;
        }
    };
}

async function lhlQBankLoadBankEntriesForGenerateFix87(count) {
    const folder = lhlExamBankGetFolder();
    if (!folder) throw new Error('Thầy chưa chọn thư mục ngân hàng.');
    if (!(window.pywebview && window.pywebview.api && window.pywebview.api.qbank_list_exam_folder && window.pywebview.api.qbank_read_file)) {
        throw new Error('Chức năng tạo đề từ NH cần chạy trong phần mềm desktop.');
    }

    const list = await window.pywebview.api.qbank_list_exam_folder(folder);
    if (!list || !list.ok) throw new Error('Không đọc được thư mục NH: ' + ((list && list.error) || 'Không rõ lỗi'));

    const pickMap = lhlQBankGetRowPickMapFix87();
    const selected = lhlQBankSelectedFileNamesFix87();
    const selectedSet = new Set(selected.map(x => String(x).toLowerCase()));

    let files = (list.files || []).slice().sort(lhlQBankNaturalFileSortFix87);
    if (selectedSet.size) files = files.filter(f => selectedSet.has(String(f.filename || '').toLowerCase()));

    const entries = [];
    for (const f of files) {
        const filename = f.filename || '';
        const part = lhlQBankPartFromFilenameFix87(filename);
        if (!part) continue;

        const pick = Math.max(0, parseInt(pickMap[filename], 10) || 0);
        if (pick <= 0) continue;

        const read = await window.pywebview.api.qbank_read_file(folder, filename);
        if (!read || !read.ok) {
            throw new Error('Không đọc được file ' + filename + ': ' + ((read && read.error) || 'Không rõ lỗi'));
        }

        const body = lhlQBankBodyFromReadResultFix87(read);
        const qs = lhlQBankSplitBankFileQuestionsFix87(body);
        if (!qs.length) throw new Error('File ' + filename + ' chưa có câu hỏi để rút.');

        // FIX101: không báo thiếu câu khi tạo nhiều mã đề.
        // Kho câu sẽ tự chạy hết một vòng, rồi xáo lại để rút vòng kế tiếp.
        entries.push({
            filename: filename,
            part: part,
            pick: pick,
            questions: qs.slice(),
            drawer: lhlQBankCycleDrawerFix101(qs)
        });
    }

    if (!entries.length) {
        throw new Error('Chưa có file nào được chọn để tạo đề. Nếu không tick file nào, phần mềm dùng toàn bộ file có ô Chọn > 0.');
    }
    return entries;
}

async function lhlQBankGenerateExamPackageFix87(opts) {
    const count = Math.max(1, Math.min(100, parseInt(opts.count, 10) || 1));
    const codes = (typeof lhlMixBuildCodeList === 'function')
        ? lhlMixBuildCodeList(opts.startCode || '1301', count)
        : Array.from({length: count}, (_, i) => String(1301 + i));

    const entries = await lhlQBankLoadBankEntriesForGenerateFix87(count);
    const template = lhlQBankTemplatePartsFix87(lhlQBankGetTemplateForGenerateFix87());

    const files = [];
    const p1Rows = [], p2Rows = [], p3Rows = [];

    for (let k = 0; k < count; k++) {
        const selections = {TN: [], DS: [], TLN: []};

        entries.forEach(en => {
            const take = en.drawer.draw(en.pick);
            selections[en.part].push(...take);
        });

        // Xáo thứ tự câu độc lập trong từng phần của từng mã đề.
        selections.TN = lhlQBankShuffleCopyFix87(selections.TN);
        selections.DS = lhlQBankShuffleCopyFix87(selections.DS);
        selections.TLN = lhlQBankShuffleCopyFix87(selections.TLN);

        // lhlQBankBuildExamFileFromSelectionsFix87 gọi:
        // TN -> lhlMixProcessPart1Block: tiếp tục đảo phương án A/B/C/D.
        // DS -> lhlMixProcessPart2Block: giữ các ý Đ/S, chỉ thay số thứ tự câu.
        // TLN -> lhlMixProcessPart3Block: giữ nội dung, chỉ thay số thứ tự câu.
        const built = lhlQBankBuildExamFileFromSelectionsFix87(template, codes[k], selections, opts);
        p1Rows.push(built.p1Ans);
        p2Rows.push(built.p2Ans);
        p3Rows.push(built.p3Ans);
        files.push({filename: 'De_NH_' + codes[k] + '.html', content: built.content});
    }

    const answerHtml = (typeof lhlMixBuildAnswerXls === 'function')
        ? lhlMixBuildAnswerXls(codes, p1Rows, p2Rows, p3Rows)
        : '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body><pre>' +
          lhlQBankEscapeHtml(JSON.stringify({codes,p1Rows,p2Rows,p3Rows}, null, 2)) +
          '</pre></body></html>';

    return {files, answerHtml, codes};
}

// Cập nhật phần hướng dẫn trong hộp thoại, giữ nguyên cơ chế FIX100:
// báo lỗi thì hộp thoại vẫn mở để thầy sửa và tạo tiếp.
if (typeof lhlQBankOpenGenerateExamDialogFix87 === 'function' && !window.__lhlFix101WrappedOpenDialog) {
    window.__lhlFix101WrappedOpenDialog = true;
    const __oldOpenGenerateDialogFix101 = lhlQBankOpenGenerateExamDialogFix87;
    lhlQBankOpenGenerateExamDialogFix87 = function() {
        const ret = __oldOpenGenerateDialogFix101.apply(this, arguments);
        const overlay = document.getElementById('lhlBankGenOverlay');
        const note = overlay && overlay.querySelector('.lhl-bank-gen-note');
        if (note) {
            note.innerHTML =
                '<b>Cách rút:</b> mỗi file <b>TN-1, TN-2, Đ/S-1, TLN-1...</b> là một vị trí câu trong đề. ' +
                'Phần mềm rút theo ô <b>Chọn</b> của từng file. Nếu thầy tick một số file thì chỉ dùng các file được tick; ' +
                'nếu không tick file nào thì dùng toàn bộ file có <b>Chọn &gt; 0</b>.' +
                '<br><b>Cơ chế nhiều mã đề:</b> mỗi file được xáo ngẫu nhiên và rút hết một vòng không lặp. ' +
                'Nếu số đề cần tạo lớn hơn số câu đang có trong file, phần mềm tự xáo lại để rút vòng mới cho đủ số đề; ' +
                'vì vậy các đề bổ sung có thể trùng một số câu với vòng trước.' +
                '<br><b>Đảo đề:</b> Phần I đảo câu và phương án; Phần II và Phần III chỉ đảo thứ tự câu.';
        }
        return ret;
    };
}



// ============================================================
// FIX102-NH - PHÁT TRIỂN NHẸ TRÊN FIX101
// - Dọn hộp Tạo đề: bỏ dòng FIX kỹ thuật.
// - Bắt buộc nhập đầy đủ thông tin trước khi tạo.
// - Thông báo trong luồng tạo đề dùng "Thầy/Cô".
// - Tên file đáp án mặc định chuyển sang .xlsx thật.
// ============================================================

function lhlQBankMessageForAllUsersFix102(msg) {
    return String(msg || '')
        .replace(/\bThầy\b/g, 'Thầy/Cô')
        .replace(/\bthầy\b/g, 'Thầy/Cô');
}

function lhlQBankOpenGenerateExamDialogFix87() {
    lhlQBankInstallFix100GenerateDialogStyle();

    const old = document.getElementById('lhlBankGenOverlay');
    if (old) old.remove();

    const overlay = document.createElement('div');
    overlay.id = 'lhlBankGenOverlay';
    overlay.className = 'lhl-bank-gen-overlay lhl-fix100-keep-dialog';

    overlay.innerHTML = `
    <div class="lhl-bank-gen-dialog">
        <div class="lhl-bank-gen-head"><h2>🧩 Tạo đề từ ngân hàng</h2></div>
        <div class="lhl-bank-gen-body">
            <div class="lhl-bank-gen-grid">
                <div class="lhl-bank-gen-field"><label>Số mã đề cần tạo</label><input id="bankGenCount" type="number" min="1" max="100" value="4"></div>
                <div class="lhl-bank-gen-field"><label>Mã đề bắt đầu hoặc danh sách mã</label><input id="bankGenStartCode" type="text" value="1301"></div>
                <div class="lhl-bank-gen-field"><label>Thời gian làm bài</label><input id="bankGenDuration" type="number" min="1" value="90"></div>
                <div class="lhl-bank-gen-field"><label>Tên file đáp án</label><input id="bankGenAnswerName" type="text" value="Bang_Dap_An_NH.xls"></div>
                <div class="lhl-bank-gen-field"><label>Tên trường</label><input id="bankGenSchool" type="text" value=""></div>
                <div class="lhl-bank-gen-field"><label>Tiêu đề đề thi</label><input id="bankGenTitle" type="text" value=""></div>
                <div class="lhl-bank-gen-field"><label>Môn</label><input id="bankGenSubject" type="text" value="MÔN: TOÁN"></div>
                <div class="lhl-bank-gen-field"><label>Khối</label><input id="bankGenGrade" type="text" value="KHỐI 12"></div>
            </div>
            <div class="lhl-bank-gen-note">
                <b>Cách rút:</b> mỗi file <b>TN-1, TN-2, Đ/S-1, TLN-1...</b> là một vị trí câu trong đề.
                Phần mềm rút theo ô <b>Chọn</b> của từng file. Nếu Thầy/Cô tick một số file thì chỉ dùng các file được tick;
                nếu không tick file nào thì dùng toàn bộ file có <b>Chọn &gt; 0</b>.
                <br><b>Cơ chế nhiều mã đề:</b> mỗi file được xáo ngẫu nhiên và rút hết một vòng không lặp.
                Nếu số đề cần tạo lớn hơn số câu đang có trong file, phần mềm tự xáo lại để rút vòng mới cho đủ số đề;
                vì vậy các đề bổ sung có thể trùng một số câu với vòng trước.
                <br><b>Đảo đề:</b> Phần I đảo câu và phương án; Phần II và Phần III chỉ đảo thứ tự câu.
            </div>
            <div id="bankGenError" class="lhl-bank-gen-error" role="alert" aria-live="polite"></div>
        </div>
        <div class="lhl-bank-gen-actions">
            <button type="button" class="lhl-bank-gen-cancel" id="bankGenCancel">Hủy</button>
            <button type="button" class="lhl-bank-gen-ok" id="bankGenOk">Tạo đề</button>
        </div>
    </div>`;

    document.body.appendChild(overlay);

    const errBox = overlay.querySelector('#bankGenError');
    const okBtn = overlay.querySelector('#bankGenOk');
    const cancelBtn = overlay.querySelector('#bankGenCancel');
    let isWorking = false;
    const val = id => String(overlay.querySelector('#' + id)?.value || '').trim();

    const showErr = msg => {
        const detail = lhlQBankMessageForAllUsersFix102(msg || 'Có lỗi xảy ra.');
        errBox.innerHTML =
            '<div class="fix100-error-title">⚠️ Chưa tạo được đề</div>' +
            '<div>' + lhlQBankEscapeHtml(detail) + '</div>' +
            '<div class="fix100-error-help">Thầy/Cô sửa lại thông tin hoặc dữ liệu ngân hàng, rồi bấm Tạo đề tiếp.</div>';
        errBox.classList.add('show');
        errBox.scrollIntoView({block:'nearest', behavior:'smooth'});
    };
    const clearErr = () => {
        errBox.classList.remove('show');
        errBox.innerHTML = '';
    };
    const setWorking = flag => {
        isWorking = !!flag;
        okBtn.classList.toggle('is-working', isWorking);
        okBtn.disabled = isWorking;
        cancelBtn.disabled = isWorking;
        okBtn.textContent = isWorking ? 'Đang tạo...' : 'Tạo đề';
    };
    const validateRequired = () => {
        const required = [
            ['bankGenCount', 'Số mã đề cần tạo'],
            ['bankGenStartCode', 'Mã đề bắt đầu hoặc danh sách mã'],
            ['bankGenDuration', 'Thời gian làm bài'],
            ['bankGenAnswerName', 'Tên file đáp án'],
            ['bankGenSchool', 'Tên trường'],
            ['bankGenTitle', 'Tiêu đề đề thi'],
            ['bankGenSubject', 'Môn'],
            ['bankGenGrade', 'Khối']
        ];
        const missing = required.filter(item => !val(item[0]));
        if (missing.length) {
            overlay.querySelector('#' + missing[0][0])?.focus();
            return 'Thầy/Cô vui lòng nhập đầy đủ thông tin trước khi tạo đề. Còn thiếu: ' +
                missing.map(item => item[1]).join(', ') + '.';
        }
        const count = parseInt(val('bankGenCount'), 10);
        const duration = parseInt(val('bankGenDuration'), 10);
        if (!Number.isInteger(count) || count < 1 || count > 100) {
            overlay.querySelector('#bankGenCount')?.focus();
            return 'Thầy/Cô vui lòng nhập số mã đề từ 1 đến 100.';
        }
        if (!Number.isInteger(duration) || duration < 1) {
            overlay.querySelector('#bankGenDuration')?.focus();
            return 'Thầy/Cô vui lòng nhập thời gian làm bài hợp lệ.';
        }
        return '';
    };

    cancelBtn.onclick = ev => {
        ev.preventDefault();
        if (!isWorking) overlay.remove();
    };
    overlay.onclick = ev => {
        if (ev.target === overlay) ev.stopPropagation();
    };

    okBtn.onclick = async ev => {
        ev.preventDefault();
        ev.stopPropagation();
        if (isWorking) return;
        clearErr();

        const validationError = validateRequired();
        if (validationError) {
            showErr(validationError);
            return;
        }

        setWorking(true);
        try {
            let answerName = val('bankGenAnswerName').replace(/\.xls[x]?$/i, '') + '.xlsx';
            overlay.querySelector('#bankGenAnswerName').value = answerName;
            const opts = {
                count: val('bankGenCount'),
                startCode: val('bankGenStartCode'),
                duration: parseInt(val('bankGenDuration'), 10),
                answerName,
                schoolName: val('bankGenSchool'),
                examTitle: val('bankGenTitle'),
                examSubject: val('bankGenSubject'),
                examGrade: val('bankGenGrade')
            };
            const pack = await lhlQBankGenerateExamPackageFix87(opts);
            if (!(window.pywebview && window.pywebview.api && window.pywebview.api.save_mixed_exam_package)) {
                showErr('Chức năng này cần chạy trong phần mềm desktop để chọn thư mục lưu.');
                return;
            }
            const res = await window.pywebview.api.save_mixed_exam_package(pack.files, pack.answerHtml, opts.answerName, pack.matrixHtml || "", pack.matrixFilename || "");
            if (res && res.ok) {
                if (typeof showToast === 'function') showToast('✅ Đã tạo ' + pack.files.length + ' đề từ ngân hàng và file đáp án.');
                overlay.remove();
            } else if (res && res.cancelled) {
                showErr('Thầy/Cô đã hủy chọn thư mục lưu. Dữ liệu vẫn được giữ lại để tạo tiếp.');
            } else {
                showErr('Lỗi lưu bộ đề: ' + ((res && res.error) || 'Không rõ lỗi'));
            }
        } catch(e) {
            console.error(e);
            showErr(e && e.message ? e.message : String(e));
            if (typeof showToast === 'function') showToast('❌ Chưa tạo được đề từ ngân hàng.');
        } finally {
            if (document.body.contains(overlay)) setWorking(false);
        }
    };

    overlay.querySelector('#bankGenCount').focus();
    overlay.querySelector('#bankGenCount').select();
}



// ============================================================
// FIX103-NH - TỪ FIX102
// - Bỏ dòng FIX90 còn sót trong ghi chú hộp Tạo đề.
// - Sửa lỗi "Thầy/Cô/Cô".
// - Thông báo lỗi hiển thị gọn một dòng, không dư dòng hướng dẫn dưới.
// Không can thiệp logic rút đề, ảnh, PDF hay P3 đang ổn.
// ============================================================

function lhlQBankMessageForAllUsersFix102(msg) {
    return String(msg || '')
        .replace(/Thầy\/Cô(?:\/Cô)+/gi, 'Thầy/Cô')
        .replace(/\bThầy(?!\/Cô)\b/g, 'Thầy/Cô')
        .replace(/\bthầy(?!\/Cô)\b/g, 'Thầy/Cô');
}

function lhlQBankFix103CleanGenerateDialog() {
    const overlay = document.getElementById('lhlBankGenOverlay');
    if (!overlay) return;

    const note = overlay.querySelector('.lhl-bank-gen-note');
    if (note && /FIX90\s*:/i.test(note.innerHTML)) {
        note.innerHTML = note.innerHTML
            .replace(/<br\s*\/?>\s*<b>\s*FIX90\s*:\s*<\/b>[\s\S]*?(?=(?:<br\s*\/?>|$))/i, '')
            .replace(/<br\s*\/?>\s*FIX90\s*:[\s\S]*?(?=(?:<br\s*\/?>|$))/i, '');
    }

    // Thông báo chỉ giữ nội dung chính, bỏ dòng tiêu đề/phụ phía trên dưới.
    overlay.querySelectorAll('.fix100-error-title, .fix100-error-help').forEach(el => {
        el.style.setProperty('display', 'none', 'important');
    });

    // Phòng trường hợp lỗi đã được dựng bằng nội dung cũ trước khi patch chạy.
    const errorBox = overlay.querySelector('#bankGenError');
    if (errorBox && /Thầy\/Cô\/Cô/i.test(errorBox.innerHTML)) {
        errorBox.innerHTML = errorBox.innerHTML.replace(/Thầy\/Cô(?:\/Cô)+/gi, 'Thầy/Cô');
    }
}

(function lhlQBankFix103InstallDialogCleaner() {
    if (window.__lhlFix103DialogCleanerInstalled) return;
    window.__lhlFix103DialogCleanerInstalled = true;

    const observer = new MutationObserver(function() {
        lhlQBankFix103CleanGenerateDialog();
    });
    observer.observe(document.body, {childList:true, subtree:true});

    document.addEventListener('click', function() {
        setTimeout(lhlQBankFix103CleanGenerateDialog, 0);
        setTimeout(lhlQBankFix103CleanGenerateDialog, 60);
    }, true);

    const st = document.createElement('style');
    st.id = 'lhl-fix103-dialog-compact-error-style';
    st.textContent = `
        #lhlBankGenOverlay .fix100-error-title,
        #lhlBankGenOverlay .fix100-error-help { display:none !important; }
        #lhlBankGenOverlay .lhl-bank-gen-error.show {
            padding:12px 14px !important;
            line-height:1.45 !important;
        }
    `;
    document.head.appendChild(st);
})();



