// - Ngân hàng theo bài dùng DOM/CSS riêng lesson109-*.
// ============================================================
const LHL_LESSON109_FOLDER = 'lhl_lesson109_folder';
const LHL_LESSON109_PICKS = 'lhl_lesson109_picks';
// FIX147: KHỐI 10 / KHỐI 11 / KHỐI 12 dùng cùng tính năng nhưng tách trạng thái và thư mục ngân hàng.
const LHL_LESSON146_FOLDER_11 = 'lhl_lesson146_folder_khoi11';
const LHL_LESSON146_PICKS_11 = 'lhl_lesson146_picks_khoi11';
const LHL_LESSON147_FOLDER_12 = 'lhl_lesson147_folder_khoi12';
const LHL_LESSON147_PICKS_12 = 'lhl_lesson147_picks_khoi12';
const LHL_LESSON146_SELECTED = 'lhl_lesson146_selected_by_grade';
window.__lesson146ActiveGrade = window.__lesson146ActiveGrade || '10';
function lesson146Grade(){
    const grade=String(window.__lesson146ActiveGrade || '10');
    return grade === '11' || grade === '12' ? grade : '10';
}
function lesson146FolderStorageKey(){
    const grade=lesson146Grade();
    return grade === '12' ? LHL_LESSON147_FOLDER_12 : (grade === '11' ? LHL_LESSON146_FOLDER_11 : LHL_LESSON109_FOLDER);
}
function lesson146PicksStorageKey(){
    const grade=lesson146Grade();
    return grade === '12' ? LHL_LESSON147_PICKS_12 : (grade === '11' ? LHL_LESSON146_PICKS_11 : LHL_LESSON109_PICKS);
}
function lesson146SelectedMap(){ try { return JSON.parse(localStorage.getItem(LHL_LESSON146_SELECTED) || '{}') || {}; } catch(e) { return {}; } }
function lesson146SaveSelected(){
    const map=lesson146SelectedMap();
    map[lesson146Grade()]=String(window.__lesson111SelectedLessonId || '');
    localStorage.setItem(LHL_LESSON146_SELECTED, JSON.stringify(map));
}
function lesson146RestoreSelected(){
    const map=lesson146SelectedMap();
    window.__lesson111SelectedLessonId=String(map[lesson146Grade()] || '');
}
function lesson146IsGrade(grade){ return lesson146Grade() === String(grade); }
function lesson146OpenGrade(grade){
    lesson146SaveSelected();
    const target=String(grade || '10');
    window.__lesson146ActiveGrade = (target === '11' || target === '12') ? target : '10';
    lesson146RestoreSelected();
    window.__lesson142ExpandedLessons = {};
    if(typeof lesson109Open === 'function') lesson109Open();
}


function lesson109Esc(value) {
    if (typeof lhlQBankEscapeHtml === 'function') return lhlQBankEscapeHtml(value);
    return String(value || '').replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; });
}
function lesson109Js(value) { return String(value || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'"); }
function lesson109Folder() { return localStorage.getItem(lesson146FolderStorageKey()) || ''; }
function lesson109SetFolder(folder) { if (folder) localStorage.setItem(lesson146FolderStorageKey(), folder); }
function lesson109PickMap() { try { return JSON.parse(localStorage.getItem(lesson146PicksStorageKey()) || '{}') || {}; } catch(e) { return {}; } }
function lesson109PickKey(file, part) { return lesson109Folder() + '|' + file + '|' + part; }
function lesson109GetPick(file, part, total) {
    const map = lesson109PickMap(), key = lesson109PickKey(file, part);
    return Object.prototype.hasOwnProperty.call(map, key) ? map[key] : (parseInt(total, 10) || 0);
}
function lesson109SetPick(file, part, value) {
    const map = lesson109PickMap();
    map[lesson109PickKey(file, part)] = Math.max(0, parseInt(value, 10) || 0);
    localStorage.setItem(lesson146PicksStorageKey(), JSON.stringify(map));
}
function lesson109Status(message, type) {
    const status = document.getElementById('lesson109Status');
    if (!status) return;
    status.className = 'lesson109-status ' + (type || 'ok');
    status.innerHTML = message || '';
    status.style.display = message ? 'block' : 'none';
}

