// Chỉ bọc thao tác Lưu File để hỗ trợ file theo bài đã bấm Sửa; không chạm hộp Ngân hàng đề thi.
if (typeof lhlQBankSaveEditingFileIfNeeded === 'function' && !window.__lesson109SaveHook) {
    window.__lesson109SaveHook = true;
    const __lesson109OriginalSave = lhlQBankSaveEditingFileIfNeeded;
    lhlQBankSaveEditingFileIfNeeded = async function() {
        if (window.__lesson109Editing && window.__lesson109EditingFile && window.__lesson109EditingFolder) {
            let text = '';
            if (typeof editor !== 'undefined' && editor && typeof editor.getValue === 'function') text = editor.getValue();
            else if (document.getElementById('editor')) text = document.getElementById('editor').value || '';
            const res = await window.pywebview.api.lesson108_write_part(window.__lesson109EditingFolder, window.__lesson109EditingFile, text);
            if (typeof showToast === 'function') {
                showToast(res && res.ok ? '✅ Đã lưu đè ' + window.__lesson109EditingFile + '. Số câu: ' + res.count : '❌ Lỗi lưu file bài: ' + ((res && res.error) || 'Không rõ lỗi'));
            }
            return true;
        }
        return await __lesson109OriginalSave.apply(this, arguments);
    };
}


