async function lesson111ResetPickCounts() {
    const folder = lesson109Folder();
    const map = lesson109PickMap();
    Object.keys(map).forEach(k => {
        if (k.indexOf(folder + '|') === 0) delete map[k];
    });
    localStorage.setItem(lesson146PicksStorageKey(), JSON.stringify(map));
    await lesson109Refresh();
    lesson109Status('✅ Đã đưa toàn bộ ô Chọn về 0. Thầy/Cô nhập số lượng cần rút hoặc bấm nút tăng.', 'ok');
}

async function lesson111Stats() {
    if (!lesson109Folder()) return lesson109Status('⚠️ Thầy/Cô chưa chọn Ngân hàng theo bài.', 'warn');
    const res = await window.pywebview.api.lesson111_stats(lesson109Folder());
    if (!res || !res.ok) return lesson109Status('❌ ' + lesson109Esc((res && res.error) || 'Không thống kê được.'), 'err');
    const s = res.stats || {};
    const bar = document.getElementById('lesson111Stats');
    bar.style.display = 'block';
    bar.innerHTML = '📊 Tổng số câu: <b>' + (s.TOTAL || 0) + '</b> | TN: <b>' + (s.TN || 0) + '</b> | Đ/S: <b>' + (s.DS || 0) + '</b> | TLN: <b>' + (s.TLN || 0) + '</b> | Số file: <b>' + (s.files || 0) + '</b>';
}

