// Khi tạo bài xong, tự chọn bài vừa tạo làm nơi nhận Nhập file hiện hành.
const __lesson111OldCreate = lesson109Create;
lesson109Create = async function() {
    const before = (window.__lesson111Lessons || []).map(x => String(x.id));
    await __lesson111OldCreate.apply(this, arguments);
    const after = window.__lesson111Lessons || [];
    const newItem = after.find(x => !before.includes(String(x.id)));
    if (newItem) {
        window.__lesson111SelectedLessonId = String(newItem.id);
        await lesson109Refresh();
    }
};


