function lesson113QuestionPlainText(block) {
    return String(block || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();
}
function lesson113FinishQuestionBlock(block) {
    let s = String(block || '').trim();
    if (typeof lhlQBankCutExamFooterFromBlock === 'function') s = lhlQBankCutExamFooterFromBlock(s);
    return lesson113QuestionPlainText(s).length > 12 ? s : '';
}

// Ghi đè cuối cùng: không xóa thẻ chứa tiêu đề PHẦN trước khi tìm Câu đầu.
// Trước đây nếu tiêu đề phần và Câu 1 nằm trong cùng <p>/<div>, cả thẻ bị xóa nên mất đúng 1 câu mỗi phần.
function lhlQBankSplitQuestionsInPart(partCode) {
    const raw = String(partCode || '').trim();
    if (!raw) return [];

    // Trường hợp code đã có block chuẩn: tách ngay trên code gốc để giữ đủ block Câu đầu.
    const preparedBlocks = (typeof lhlQBankSplitByQuestionBlocks === 'function') ? lhlQBankSplitByQuestionBlocks(raw) : [];
    if (preparedBlocks && preparedBlocks.length) {
        return preparedBlocks.map(lesson113FinishQuestionBlock).filter(Boolean);
    }

    // Tìm nhãn Câu trực tiếp trong phần gốc, không xóa nguyên dòng/thẻ tiêu đề trước.
    const marks = [];
    const re = /((?:<(?:b|strong)\b[^>]*>\s*)?Câu\s*\d+\s*[\.:]?\s*(?:<\/(?:b|strong)>\s*)?)/g;
    let m;
    while ((m = re.exec(raw)) !== null) marks.push(m.index);

    if (!marks.length) {
        // File chỉ có một câu không ghi nhãn: vẫn giữ tương thích như trước.
        const cleaned = (typeof lhlQBankRemovePartHeaderStrict === 'function') ? lhlQBankRemovePartHeaderStrict(raw) : raw;
        const one = lesson113FinishQuestionBlock(cleaned);
        return one ? [one] : [];
    }

    const qs = [];
    for (let i = 0; i < marks.length; i++) {
        const start = marks[i];
        const end = (i + 1 < marks.length) ? marks[i + 1] : raw.length;
        const block = lesson113FinishQuestionBlock(raw.slice(start, end));
        if (block) qs.push(block);
    }
    return qs;
}

