// Giá trị mới chưa từng chỉnh sẽ bắt đầu từ 0 thay vì tự lấy toàn bộ số câu.
function lesson109GetPick(file, part, total) {
    const map = lesson109PickMap(), key = lesson109PickKey(file, part);
    return Object.prototype.hasOwnProperty.call(map, key) ? Math.max(0, parseInt(map[key], 10) || 0) : 0;
}

function lesson109PartRow(item, part, title) {
    const p = item.parts && item.parts[part];
    if (!p) return '';
    const filename = lesson109Js(p.filename);
    const total = parseInt(p.count, 10) || 0;
    const pick = lesson109GetPick(p.filename, part, total);
    const snippet = p.preview ? lesson109Esc(p.preview) : 'Chưa có câu hỏi';
    const pieces = title.split('. ');
    return `<div class="lesson109-part">
        <div class="lesson109-label"><b>${pieces[0]}.</b>${pieces[1]}</div>
        <div class="lesson109-snippet ${p.preview ? '' : 'empty'}">${snippet}</div>
        <div class="lesson109-total"><span class="lesson114-total-text">Tổng:</span><b>${total}</b></div>
        <div class="lesson109-pick">Chọn <input type="number" min="0" value="${pick}" onchange="lesson109SetPick('${filename}','${part}',this.value)"></div>
        <div class="lesson109-actions">
            <button onclick="lesson109Append('${filename}')">Nhập</button>
            <button onclick="lesson109View('${filename}')">Xem</button>
            <button onclick="lesson109Edit('${filename}')">Sửa</button>
            <button class="del" onclick="lesson109Delete('${filename}')">Xóa</button>
        </div>
    </div>`;
}

async function lesson114AddLessonToChapter(chapter) {
    const folder = lesson109Folder();
    if (!folder) return lesson109Status('⚠️ Thầy/Cô vui lòng chọn thư mục lưu trước khi thêm bài.', 'warn');
    let lesson = await lesson115Prompt({
        title: 'Thêm bài mới',
        message: 'Nhập tên bài mới trong <b>' + lesson109Esc(chapter) + '</b>:',
        value: '',
        placeholder: 'Ví dụ: Bài 4 - Tích phân từng phần',
        okText: 'Tạo bài'
    });
    if (lesson === null) return;
    lesson = String(lesson || '').trim();
    if (!lesson) return lesson109Status('⚠️ Tên bài không được để trống.', 'warn');
    const res = await window.pywebview.api.lesson108_create_lesson(folder, chapter, lesson);
    if (res && res.ok) {
        window.__lesson111SelectedLessonId = String(res.id || '');
        await lesson109Refresh();
        lesson109Status('✅ Đã thêm bài <b>' + lesson109Esc(lesson) + '</b> vào <b>' + lesson109Esc(chapter) + '</b>.', 'ok');
    } else {
        lesson109Status('❌ ' + lesson109Esc((res && res.error) || 'Không thêm được bài học.'), 'err');
    }
}

// Render cuối cùng cho tab Bài học: có nút thêm bài trực tiếp ở từng chương.
async function lesson109Refresh() {
    const list = document.getElementById('lesson109List');
    if (!list) return;
    const folder = lesson109Folder();
    const folderEl = document.getElementById('lesson109Folder');
    if (folderEl) folderEl.textContent = folder || 'Chưa chọn thư mục lưu';
    if (!folder) {
        window.__lesson111Lessons = [];
        list.innerHTML = '<div class="lesson109-empty">Thầy/Cô chọn thư mục lưu, nhập tên chương và tên bài để tạo bài học đầu tiên.</div>';
        lesson111UpdateReceiver();
        return;
    }
    const res = await window.pywebview.api.lesson108_list(folder);
    if (!res || !res.ok) {
        list.innerHTML = '<div class="lesson109-empty">Không đọc được danh sách bài.</div>';
        return;
    }
    const lessons = res.lessons || [];
    window.__lesson111Lessons = lessons;
    if (!lessons.some(it => String(it.id) === String(window.__lesson111SelectedLessonId))) {
        window.__lesson111SelectedLessonId = '';
    }
    if (!lessons.length) {
        list.innerHTML = '<div class="lesson109-empty">Thư mục chưa có bài học. Thầy/Cô nhập tên chương, tên bài rồi bấm Tạo bài.</div>';
        lesson111UpdateReceiver();
        return;
    }
    const grouped = {};
    lessons.forEach(item => {
        const chapter = item.chapter || 'Chưa phân chương';
        (grouped[chapter] ||= []).push(item);
    });
    let html = '';
    Object.keys(grouped).sort((a,b) => a.localeCompare(b, 'vi')).forEach(chapter => {
        html += '<div class="lesson109-chapter"><span class="lesson114-chapter-name">📚 ' + lesson109Esc(chapter) + '</span>' +
            '<div class="lesson115-chapter-tools">' +
            '<button class="lesson114-add-lesson" onclick="lesson114AddLessonToChapter(\'' + lesson109Js(chapter) + '\')">➕ Thêm bài</button>' +
            '<button class="lesson115-edit-chapter" onclick="lesson115OpenChapterEditor(\'' + lesson109Js(chapter) + '\')">✏️ Sửa</button>' +
            '</div></div>';
        grouped[chapter].forEach(item => {
            const isSel = String(item.id) === String(window.__lesson111SelectedLessonId);
            const total = ['TN','DS','TLN'].reduce((sum, part) => sum + ((item.parts[part] && item.parts[part].count) || 0), 0);
            html += '<div class="lesson109-lesson ' + (isSel ? 'lesson111-selected' : '') + '">📖 ' +
                lesson109Esc(item.lesson) + '<small>Tổng ' + total + ' câu</small>' +
                '<button class="lesson111-select-btn ' + (isSel ? 'selected' : '') + '" onclick="lesson111ChooseLesson(\'' + lesson109Js(item.id) + '\')">' +
                (isSel ? '✓ Đang chọn nhập file' : 'Chọn bài nhận file') + '</button></div>';
            html += lesson109PartRow(item, 'TN', 'A. TN');
            html += lesson109PartRow(item, 'DS', 'B. Đ/S');
            html += lesson109PartRow(item, 'TLN', 'C. TLN');
        });
    });
    list.innerHTML = html;
    lesson111UpdateReceiver();
    if (typeof lhlV86ScrollToBankFile === 'function') {
        const f = window.__lhlV86LastAppendFilename || '';
        if (f) lhlV86ScrollToBankFile(f);
    }
}


function lesson115CloseModal() {
    const mask = document.getElementById('lesson115ModalMask');
    if (mask) mask.remove();
}

function lesson115ModalBase(title, bodyHtml, footerHtml) {
    lesson115CloseModal();
    const wrap = document.createElement('div');
    wrap.id = 'lesson115ModalMask';
    wrap.innerHTML = '<div id="lesson115ModalBox">' +
        '<div class="lesson115-modal-head">' + title + '</div>' +
        '<div class="lesson115-modal-body">' + bodyHtml + '<div class="lesson115-actions">' + footerHtml + '</div></div>' +
        '</div>';
    document.body.appendChild(wrap);
    wrap.addEventListener('click', function(ev){ if (ev.target === wrap) lesson115CloseModal(); });
    return wrap;
}

function lesson115Prompt(opts) {
    opts = opts || {};
    return new Promise(resolve => {
        const body = '<div class="lesson115-modal-msg">' + (opts.message || '') + '</div>' +
            '<input id="lesson115PromptInput" class="lesson115-input" type="text" value="' + lesson109Esc(opts.value || '') + '" placeholder="' + lesson109Esc(opts.placeholder || '') + '">';
        const footer =
            '<button class="lesson115-btn gray" id="lesson115CancelBtn">Hủy</button>' +
            '<button class="lesson115-btn green" id="lesson115OkBtn">' + lesson109Esc(opts.okText || 'OK') + '</button>';
        const wrap = lesson115ModalBase(lesson109Esc(opts.title || 'Nhập nội dung'), body, footer);
        const input = wrap.querySelector('#lesson115PromptInput');
        const close = (val) => { lesson115CloseModal(); resolve(val); };
        wrap.querySelector('#lesson115CancelBtn').onclick = () => close(null);
        wrap.querySelector('#lesson115OkBtn').onclick = () => close(input.value);
        input.addEventListener('keydown', ev => {
            if (ev.key === 'Enter') { ev.preventDefault(); close(input.value); }
            if (ev.key === 'Escape') { ev.preventDefault(); close(null); }
        });
        setTimeout(() => { input.focus(); input.select(); }, 30);
    });
}

function lesson115Confirm(message, title) {
    return new Promise(resolve => {
        const body = '<div class="lesson115-modal-msg">' + message + '</div>';
        const footer =
            '<button class="lesson115-btn gray" id="lesson115NoBtn">Hủy</button>' +
            '<button class="lesson115-btn red" id="lesson115YesBtn">Đồng ý</button>';
        const wrap = lesson115ModalBase(lesson109Esc(title || 'Xác nhận'), body, footer);
        wrap.querySelector('#lesson115NoBtn').onclick = () => { lesson115CloseModal(); resolve(false); };
        wrap.querySelector('#lesson115YesBtn').onclick = () => { lesson115CloseModal(); resolve(true); };
    });
}

function lesson115ChapterLessons(chapter) {
    const all = Array.isArray(window.__lesson111Lessons) ? window.__lesson111Lessons : [];
    return all.filter(it => String((it && it.chapter) || '') === String(chapter || ''));
}

function lesson115SyncEditorLessonName() {
    const sel = document.getElementById('lesson115LessonSelect');
    const input = document.getElementById('lesson115LessonName');
    if (!sel || !input) return;
    const opt = sel.options[sel.selectedIndex];
    input.value = opt ? (opt.getAttribute('data-lesson-name') || '') : '';
}

async function lesson115SaveChapterName() {
    const folder = lesson109Folder();
    const oldChapter = window.__lesson115EditorChapter || '';
    const input = document.getElementById('lesson115ChapterName');
    const newChapter = String((input && input.value) || '').trim();
    if (!newChapter) return lesson109Status('⚠️ Tên chương không được để trống.', 'warn');
    if (newChapter === oldChapter) return lesson109Status('ℹ️ Tên chương chưa thay đổi.', 'warn');
    const res = await window.pywebview.api.lesson115_rename_chapter(folder, oldChapter, newChapter);
    if (res && res.ok) {
        window.__lesson115EditorChapter = newChapter;
        await lesson109Refresh();
        lesson115OpenChapterEditor(newChapter);
        lesson109Status('✅ Đã đổi tên chương thành <b>' + lesson109Esc(newChapter) + '</b>.', 'ok');
    } else {
        lesson109Status('❌ ' + lesson109Esc((res && res.error) || 'Không đổi được tên chương.'), 'err');
    }
}

async function lesson115SaveLessonName() {
    const folder = lesson109Folder();
    const sel = document.getElementById('lesson115LessonSelect');
    const input = document.getElementById('lesson115LessonName');
    const lessonId = String((sel && sel.value) || '').trim();
    const newName = String((input && input.value) || '').trim();
    if (!lessonId) return lesson109Status('⚠️ Thầy/Cô vui lòng chọn bài cần sửa.', 'warn');
    if (!newName) return lesson109Status('⚠️ Tên bài không được để trống.', 'warn');
    const res = await window.pywebview.api.lesson115_rename_lesson(folder, lessonId, newName);
    if (res && res.ok) {
        window.__lesson111SelectedLessonId = String(lessonId);
        await lesson109Refresh();
        lesson115OpenChapterEditor(window.__lesson115EditorChapter || '');
        const sel2 = document.getElementById('lesson115LessonSelect');
        if (sel2) { sel2.value = String(lessonId); lesson115SyncEditorLessonName(); }
        lesson109Status('✅ Đã đổi tên bài thành <b>' + lesson109Esc(newName) + '</b>.', 'ok');
    } else {
        lesson109Status('❌ ' + lesson109Esc((res && res.error) || 'Không đổi được tên bài.'), 'err');
    }
}

async function lesson115DeleteSelectedLesson() {
    const folder = lesson109Folder();
    const sel = document.getElementById('lesson115LessonSelect');
    if (!sel || !sel.value) return lesson109Status('⚠️ Thầy/Cô vui lòng chọn bài cần xóa.', 'warn');
    const lessonName = sel.options[sel.selectedIndex] ? sel.options[sel.selectedIndex].textContent : 'bài này';
    const ok = await lesson115Confirm('Thầy/Cô có chắc muốn xóa bài <b>' + lesson109Esc(lessonName) + '</b>?<br>Toàn bộ 3 phần TN / Đ-S / TLN của bài sẽ bị xóa.', 'Xóa bài học');
    if (!ok) return;
    const lessonId = String(sel.value);
    const res = await window.pywebview.api.lesson115_delete_lesson(folder, lessonId);
    if (res && res.ok) {
        if (String(window.__lesson111SelectedLessonId || '') === lessonId) window.__lesson111SelectedLessonId = '';
        await lesson109Refresh();
        const remain = lesson115ChapterLessons(window.__lesson115EditorChapter || '');
        if (remain.length) lesson115OpenChapterEditor(window.__lesson115EditorChapter || '');
        else lesson115CloseModal();
        lesson109Status('✅ Đã xóa bài <b>' + lesson109Esc(lessonName) + '</b>.', 'ok');
    } else {
        lesson109Status('❌ ' + lesson109Esc((res && res.error) || 'Không xóa được bài.'), 'err');
    }
}

async function lesson115DeleteChapter() {
    const folder = lesson109Folder();
    const chapter = window.__lesson115EditorChapter || '';
    const ok = await lesson115Confirm('Thầy/Cô có chắc muốn xóa toàn bộ chương <b>' + lesson109Esc(chapter) + '</b>?<br>Mọi bài trong chương này sẽ bị xóa.', 'Xóa nguyên chương');
    if (!ok) return;
    const res = await window.pywebview.api.lesson115_delete_chapter(folder, chapter);
    if (res && res.ok) {
        window.__lesson111SelectedLessonId = '';
        lesson115CloseModal();
        await lesson109Refresh();
        lesson109Status('✅ Đã xóa chương <b>' + lesson109Esc(chapter) + '</b>.', 'ok');
    } else {
        lesson109Status('❌ ' + lesson109Esc((res && res.error) || 'Không xóa được chương.'), 'err');
    }
}

function lesson116CurrentSelectedLessonId() {
    const sel = document.getElementById('lesson115LessonSelect');
    return String((sel && sel.value) || '').trim();
}

function lesson116RestoreEditorSelection(chapter, lessonId) {
    lesson115OpenChapterEditor(chapter);
    const sel = document.getElementById('lesson115LessonSelect');
    if (sel && lessonId) {
        sel.value = String(lessonId);
        lesson115SyncEditorLessonName();
    }
}

async function lesson116ReorderSelected(direction) {
    const folder = lesson109Folder();
    const lessonId = lesson116CurrentSelectedLessonId();
    const chapter = window.__lesson115EditorChapter || '';
    if (!lessonId) return lesson109Status('⚠️ Thầy/Cô vui lòng chọn bài cần đổi thứ tự.', 'warn');
    const res = await window.pywebview.api.lesson116_reorder_lesson(folder, lessonId, direction);
    if (res && res.ok) {
        await lesson109Refresh();
        lesson116RestoreEditorSelection(chapter, lessonId);
        lesson109Status(res.unchanged ? 'ℹ️ Bài đã ở vị trí giới hạn.' : '✅ Đã đổi thứ tự bài trong chương.', res.unchanged ? 'warn' : 'ok');
    } else {
        lesson109Status('❌ ' + lesson109Esc((res && res.error) || 'Không đổi được thứ tự bài.'), 'err');
    }
}

async function lesson116MoveSelectedLesson() {
    const folder = lesson109Folder();
    const lessonId = lesson116CurrentSelectedLessonId();
    const input = document.getElementById('lesson116TargetChapter');
    const target = String((input && input.value) || '').trim();
    if (!lessonId) return lesson109Status('⚠️ Thầy/Cô vui lòng chọn bài cần chuyển.', 'warn');
    if (!target) return lesson109Status('⚠️ Thầy/Cô vui lòng nhập tên chương đích.', 'warn');
    const res = await window.pywebview.api.lesson116_move_lesson(folder, lessonId, target);
    if (res && res.ok) {
        await lesson109Refresh();
        lesson116RestoreEditorSelection(target, lessonId);
        lesson109Status(res.unchanged ? 'ℹ️ Bài đang nằm trong chương này.' : '✅ Đã chuyển bài sang <b>' + lesson109Esc(target) + '</b>.', res.unchanged ? 'warn' : 'ok');
    } else {
        lesson109Status('❌ ' + lesson109Esc((res && res.error) || 'Không chuyển được bài.'), 'err');
    }
}

async function lesson116DuplicateSelectedLesson() {
    const folder = lesson109Folder();
    const lessonId = lesson116CurrentSelectedLessonId();
    const sel = document.getElementById('lesson115LessonSelect');
    if (!lessonId || !sel) return lesson109Status('⚠️ Thầy/Cô vui lòng chọn bài cần nhân bản.', 'warn');
    const option = sel.options[sel.selectedIndex];
    const oldName = option ? (option.getAttribute('data-lesson-name') || option.textContent || '') : '';
    let newName = await lesson115Prompt({
        title: 'Nhân bản bài học',
        message: 'Tạo một bài mới giữ nguyên nội dung từ <b>' + lesson109Esc(oldName) + '</b>.',
        value: oldName + ' - Bản sao',
        placeholder: 'Nhập tên bài mới',
        okText: 'Nhân bản'
    });
    if (newName === null) return;
    newName = String(newName || '').trim();
    if (!newName) return lesson109Status('⚠️ Tên bài mới không được để trống.', 'warn');
    const res = await window.pywebview.api.lesson116_duplicate_lesson(folder, lessonId, newName);
    if (res && res.ok) {
        window.__lesson111SelectedLessonId = String(res.id || '');
        await lesson109Refresh();
        lesson116RestoreEditorSelection(res.chapter || window.__lesson115EditorChapter || '', res.id);
        lesson109Status('✅ Đã nhân bản thành bài <b>' + lesson109Esc(newName) + '</b>.', 'ok');
    } else {
        lesson109Status('❌ ' + lesson109Esc((res && res.error) || 'Không nhân bản được bài.'), 'err');
    }
}

function lesson115OpenChapterEditor(chapter) {
    window.__lesson115EditorChapter = String(chapter || '');
    const lessons = lesson115ChapterLessons(window.__lesson115EditorChapter);
    let options = '';
    lessons.forEach((it, idx) => {
        options += '<option value="' + lesson109Esc(String(it.id)) + '" data-lesson-name="' + lesson109Esc(it.lesson || '') + '">' + lesson109Esc(it.lesson || ('Bài ' + (idx + 1))) + '</option>';
    });
    const firstLessonName = lessons[0] ? (lessons[0].lesson || '') : '';
    const body =
        '<div class="lesson115-modal-msg">Chỉnh sửa tên chương, tên bài hoặc xóa nhanh ngay trong chương đang chọn.</div>' +
        '<div class="lesson115-field"><label>Tên chương</label><input id="lesson115ChapterName" class="lesson115-input" type="text" value="' + lesson109Esc(window.__lesson115EditorChapter) + '"></div>' +
        '<div class="lesson115-inline-actions"><button class="lesson115-btn orange" id="lesson115SaveChapterBtn">Lưu tên chương</button><button class="lesson115-btn red" id="lesson115DeleteChapterBtn">Xóa nguyên chương</button></div>' +
        '<div class="lesson115-section">' +
        '<div class="lesson115-field"><label>Chọn bài trong chương</label><select id="lesson115LessonSelect" class="lesson115-select">' + options + '</select></div>' +
        '<div class="lesson115-field"><label>Tên bài</label><input id="lesson115LessonName" class="lesson115-input" type="text" value="' + lesson109Esc(firstLessonName) + '" ' + (lessons.length ? '' : 'disabled') + '></div>' +
        '<div class="lesson115-inline-actions"><button class="lesson115-btn orange" id="lesson115SaveLessonBtn" ' + (lessons.length ? '' : 'disabled') + '>Lưu tên bài</button><button class="lesson115-btn red" id="lesson115DeleteLessonBtn" ' + (lessons.length ? '' : 'disabled') + '>Xóa bài</button></div>' +
        '<div class="lesson116-tools-panel">' +
        '<div class="lesson116-tools-title">Công cụ sắp xếp và sao chép bài</div>' +
        '<div class="lesson116-row"><button class="lesson115-btn blue" id="lesson116UpBtn" ' + (lessons.length ? '' : 'disabled') + '>⬆ Đưa lên</button><button class="lesson115-btn blue" id="lesson116DownBtn" ' + (lessons.length ? '' : 'disabled') + '>⬇ Đưa xuống</button><button class="lesson115-btn purple" id="lesson116DuplicateBtn" ' + (lessons.length ? '' : 'disabled') + '>⧉ Nhân bản</button></div>' +
        '<div class="lesson116-row"><input id="lesson116TargetChapter" class="lesson115-input" list="lesson116ChapterList" type="text" placeholder="Tên chương muốn chuyển bài sang"><datalist id="lesson116ChapterList">' + Array.from(new Set((window.__lesson111Lessons || []).map(it => String(it.chapter || '')).filter(Boolean))).map(ch => '<option value="' + lesson109Esc(ch) + '"></option>').join('') + '</datalist><button class="lesson115-btn green" id="lesson116MoveBtn" ' + (lessons.length ? '' : 'disabled') + '>Chuyển bài</button></div>' +
        '</div>' +
        '<div class="lesson115-note">Có thể đổi thứ tự trong chương, chuyển bài sang chương đã có hoặc nhập tên chương mới.</div>' +
        '</div>';
    const footer = '<button class="lesson115-btn gray" id="lesson115CloseBtn">Đóng</button>';
    const wrap = lesson115ModalBase('Sửa chương / bài học', body, footer);
    wrap.querySelector('#lesson115CloseBtn').onclick = lesson115CloseModal;
    wrap.querySelector('#lesson115SaveChapterBtn').onclick = lesson115SaveChapterName;
    wrap.querySelector('#lesson115DeleteChapterBtn').onclick = lesson115DeleteChapter;
    const sel = wrap.querySelector('#lesson115LessonSelect');
    if (sel) sel.onchange = lesson115SyncEditorLessonName;
    const saveLessonBtn = wrap.querySelector('#lesson115SaveLessonBtn');
    const delLessonBtn = wrap.querySelector('#lesson115DeleteLessonBtn');
    if (saveLessonBtn) saveLessonBtn.onclick = lesson115SaveLessonName;
    if (delLessonBtn) delLessonBtn.onclick = lesson115DeleteSelectedLesson;
    const upBtn = wrap.querySelector('#lesson116UpBtn');
    const downBtn = wrap.querySelector('#lesson116DownBtn');
    const duplicateBtn = wrap.querySelector('#lesson116DuplicateBtn');
    const moveBtn = wrap.querySelector('#lesson116MoveBtn');
    if (upBtn) upBtn.onclick = () => lesson116ReorderSelected('up');
    if (downBtn) downBtn.onclick = () => lesson116ReorderSelected('down');
    if (duplicateBtn) duplicateBtn.onclick = lesson116DuplicateSelectedLesson;
    if (moveBtn) moveBtn.onclick = lesson116MoveSelectedLesson;
    const chapterInput = wrap.querySelector('#lesson115ChapterName');
    if (chapterInput) setTimeout(() => chapterInput.focus(), 30);
}

lesson114InstallUi();
if (typeof lesson109Open === 'function' && !window.__lesson114OpenWrapped) {
    window.__lesson114OpenWrapped = true;
    const __lesson114Open = lesson109Open;
    lesson109Open = function() {
        const ret = __lesson114Open.apply(this, arguments);
        lesson114InstallUi();
        const chooseFolderBtn = document.querySelector('#lesson109Overlay .lesson109-toolbar > button:first-child');
        if (chooseFolderBtn) chooseFolderBtn.textContent = '📂 Chọn thư mục lưu';
        return ret;
    };
}

