// ============================================================
// FIX126 - DANH DAU CHON TUNG CAU TRONG XEM NHANH CUA HAI TAB
// - Them checkbox truoc moi cau trong iframe Bien dich nhanh.
// - Luu trang thai tick theo thu muc + ten file trong localStorage.
// - Tab Ngan hang de thi: cau tick duoc uu tien/bat buoc dua vao de khi tao.
// - Neu tick nhieu hon o Chon, tu nang so cau lay toi thieu bang so cau da tick.
// - Tab Bai hoc: luu cau da danh dau va dong bo o Chon de phuc vu luong rut bai hoc.
// ============================================================
const LHL_Q126_EXAM_MARKS = 'lhl_q126_exam_question_marks';
const LHL_Q126_LESSON_MARKS = 'lhl_q126_lesson_question_marks';

function q126Esc(s){
    return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
}
function q126StorageName(scope){ return scope === 'lesson' ? LHL_Q126_LESSON_MARKS : LHL_Q126_EXAM_MARKS; }
function q126Folder(scope){ return scope === 'lesson' ? (typeof lesson109Folder === 'function' ? lesson109Folder() : '') : (typeof lhlExamBankGetFolder === 'function' ? lhlExamBankGetFolder() : ''); }
function q126MarkKey(scope, filename){ return q126Folder(scope) + '|' + String(filename || ''); }
function q126ReadAll(scope){ try{return JSON.parse(localStorage.getItem(q126StorageName(scope)) || '{}') || {};}catch(e){return {};} }
function q126GetMarks(scope, filename){
    const arr=q126ReadAll(scope)[q126MarkKey(scope,filename)] || [];
    return Array.from(new Set((arr || []).map(n=>parseInt(n,10)).filter(n=>n>0))).sort((a,b)=>a-b);
}
function q126SetMarks(scope, filename, marks){
    const map=q126ReadAll(scope), key=q126MarkKey(scope,filename);
    map[key]=Array.from(new Set((marks || []).map(n=>parseInt(n,10)).filter(n=>n>0))).sort((a,b)=>a-b);
    localStorage.setItem(q126StorageName(scope), JSON.stringify(map));
    q126RaisePickMinimum(scope,filename,map[key].length);
    q126UpdateToolbar(scope,filename,map[key].length);
}
function q126LessonPartFromFile(filename){
    const m=String(filename || '').match(/-(TN|DS|TLN)\.(?:html?|HTML?)$/i);
    return m ? m[1].toUpperCase() : '';
}
function q126RaisePickMinimum(scope,filename,need){
    need=Math.max(0,parseInt(need,10)||0);
    if(!need)return;
    if(scope==='lesson'){
        const part=q126LessonPartFromFile(filename);
        if(part && typeof lesson109GetPick==='function' && typeof lesson109SetPick==='function'){
            const old=lesson109GetPick(filename,part,0);
            if((parseInt(old,10)||0)<need){
                lesson109SetPick(filename,part,need);
                const rows=Array.from(document.querySelectorAll('#lesson109List .lesson109-part'));
                rows.forEach(row=>{
                    const btn=Array.from(row.querySelectorAll('button')).find(b => String(b.getAttribute('onclick')||'').includes("lesson109View('"+filename+"')"));
                    if(btn){ const inp=row.querySelector('.lesson109-pick input'); if(inp)inp.value=String(need); }
                });
            }
        }
    }else{
        Array.from(document.querySelectorAll('#examBankFileList .exam-bank-file')).forEach(row=>{
            if(String(row.getAttribute('data-file')||'')===String(filename||'')){
                const inp=row.querySelector('.exam-bank-pick-count');
                if(inp && (parseInt(inp.value,10)||0)<need){
                    inp.value=String(need);
                    inp.dispatchEvent(new Event('change',{bubbles:true}));
                }
            }
        });
    }
}
function q126QuestionMarkers(doc){
    if(!doc || !doc.body)return [];
    return Array.from(doc.body.querySelectorAll('b,strong')).filter(el=>/^\s*Câu\s*\d+\s*[.:]/i.test(String(el.textContent||'')));
}
function q126UpdateToolbar(scope,filename,count){
    const bar=document.querySelector('.q126-toolbar[data-scope="'+scope+'"][data-file="'+CSS.escape(String(filename||''))+'"]');
    if(!bar)return;
    const n=bar.querySelector('.q126-selected-count'); if(n)n.textContent=String(count||0);
    bar.classList.toggle('has-selected',(count||0)>0);
}
function q126DecorateFrame(iframe){
    try{
        const scope=iframe.dataset.q126Scope||'';
        const filename=iframe.dataset.q126File||'';
        const doc=iframe.contentDocument;
        if(!scope || !filename || !doc || !doc.body)return;
        if(!doc.getElementById('q126-frame-style')){
            const st=doc.createElement('style'); st.id='q126-frame-style';
            st.textContent='.q126-mark{display:inline-flex;align-items:center;justify-content:center;vertical-align:middle;margin:0 12px 0 0;cursor:pointer;user-select:none;background:transparent!important;border:0!important;box-shadow:none!important;border-radius:0!important;width:auto!important;height:auto!important}.q126-mark:hover,.q126-mark.active{background:transparent!important;border:0!important;box-shadow:none!important}.q126-mark input{width:19px;height:19px;accent-color:#22a350;cursor:pointer;margin:0;vertical-align:middle}';
            doc.head.appendChild(st);
        }
        doc.querySelectorAll('.q126-mark').forEach(x=>x.remove());
        const markers=q126QuestionMarkers(doc);
        let marks=q126GetMarks(scope,filename).filter(i=>i<=markers.length);
        if(marks.length!==q126GetMarks(scope,filename).length)q126SetMarks(scope,filename,marks);
        markers.forEach((marker,idx)=>{
            const number=idx+1;
            const label=doc.createElement('label');
            label.className='q126-mark'+(marks.includes(number)?' active':'');
            label.title='Chọn câu này để rút ra';
            const cb=doc.createElement('input'); cb.type='checkbox'; cb.checked=marks.includes(number);
            cb.addEventListener('change',()=>{
                let current=q126GetMarks(scope,filename);
                if(cb.checked && !current.includes(number))current.push(number);
                if(!cb.checked)current=current.filter(n=>n!==number);
                current.sort((a,b)=>a-b);
                label.classList.toggle('active',cb.checked);
                q126SetMarks(scope,filename,current);
            });
            label.appendChild(cb);
            marker.parentNode.insertBefore(label,marker);
        });
        q126UpdateToolbar(scope,filename,marks.length);
    }catch(e){ console.warn('FIX126 decorate preview:',e); }
}
function q126SelectAll(scope,filename,checked){
    const iframe=scope==='lesson' ? document.getElementById('lesson109Frame') : document.querySelector('#qbankPreviewBody .qbank-preview-iframe');
    if(!iframe)return;
    try{
        const markers=q126QuestionMarkers(iframe.contentDocument);
        const marks=checked ? markers.map((_,i)=>i+1) : [];
        q126SetMarks(scope,filename,marks);
        q126DecorateFrame(iframe);
    }catch(e){}
}
function q126ToolbarHtml(scope,filename){
    return '<div class="q126-toolbar" data-scope="'+q126Esc(scope)+'" data-file="'+q126Esc(filename)+'">'+
        '<span class="q126-label">☑ Chọn câu cần rút:</span><b><span class="q126-selected-count">'+q126GetMarks(scope,filename).length+'</span> câu</b>'+
        '<button type="button" onclick="q126SelectAll(\''+q126Esc(scope)+'\',\''+String(filename||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'")+'\',true)">Chọn tất cả</button>'+
        '<button type="button" class="clear" onclick="q126SelectAll(\''+q126Esc(scope)+'\',\''+String(filename||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'")+'\',false)">Bỏ chọn</button>'+
        '<span class="q126-note">Câu đã tick được ưu tiên rút trước.</span></div>';
}
function q126InstallCss(){
    if(document.getElementById('q126-css'))return;
    const st=document.createElement('style'); st.id='q126-css';
    st.textContent=`
    .q126-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;background:#eef7f0;border:1px solid #81c784;border-radius:8px;padding:7px 10px;margin:4px 0 7px;font-family:"Segoe UI",Arial,Tahoma,sans-serif;font-size:13.5px;color:#1b5e20;box-sizing:border-box;}
    .q126-toolbar.has-selected{background:#e1f4e5;border-color:#2e7d32;}
    .q126-toolbar .q126-label{font-weight:800;}
    .q126-toolbar b{color:#087f3e;font-size:14px;min-width:48px;}
    .q126-toolbar button{height:29px;border:0;border-radius:7px;padding:0 11px;background:linear-gradient(#42a5f5,#1976d2);color:#fff;font-family:"Segoe UI",Arial,Tahoma,sans-serif;font-size:12.5px;font-weight:750;cursor:pointer;transition:transform .12s ease,filter .12s ease,box-shadow .12s ease;}
    .q126-toolbar button.clear{background:linear-gradient(#78909c,#455a64);}
    .q126-toolbar button:hover{transform:translateY(-1px);filter:brightness(1.08);box-shadow:0 4px 10px rgba(0,0,0,.18);}
    .q126-toolbar button:active{transform:translateY(1px);}
    .q126-toolbar .q126-note{color:#486453;margin-left:auto;font-style:italic;}
    #lesson109Preview .q126-toolbar{margin:5px 0 7px;}
    `;
    document.head.appendChild(st);
}
function q126MountToolbar(scope,filename,host,iframe){
    if(!host || !iframe)return;
    q126InstallCss();
    host.querySelectorAll('.q126-toolbar').forEach(x=>x.remove());
    const wrap=document.createElement('div'); wrap.innerHTML=q126ToolbarHtml(scope,filename);
    const bar=wrap.firstElementChild;
    host.insertBefore(bar,iframe);
    iframe.dataset.q126Scope=scope; iframe.dataset.q126File=filename;
    iframe.onload=()=>q126DecorateFrame(iframe);
    setTimeout(()=>q126DecorateFrame(iframe),80);
}

