if(typeof lhlQBankLoadBankEntriesForGenerateFix87==='function' && !window.__q126GenerateWrapped){
    window.__q126GenerateWrapped=true;
    const __q126LoadEntries=lhlQBankLoadBankEntriesForGenerateFix87;
    lhlQBankLoadBankEntriesForGenerateFix87=async function(count){
        const entries=await __q126LoadEntries.apply(this,arguments);
        const folder=typeof lhlExamBankGetFolder==='function' ? lhlExamBankGetFolder() : '';
        entries.forEach(en=>{
            const marks=q126GetMarks('exam',en.filename).filter(i=>i<=en.questions.length);
            if(!marks.length)return;
            const forced=marks.map(i=>en.questions[i-1]).filter(Boolean);
            const unmarked=en.questions.filter((_,i)=>!marks.includes(i+1));
            const fillSource=unmarked.length ? unmarked : en.questions;
            const filler=(typeof lhlQBankCycleDrawerFix101==='function') ? lhlQBankCycleDrawerFix101(fillSource) : null;
            en.pick=Math.max(parseInt(en.pick,10)||0,forced.length);
            en.drawer={draw:function(n){
                n=Math.max(0,parseInt(n,10)||0);
                const fixed=forced.slice(0,Math.min(n,forced.length));
                const remain=Math.max(0,n-fixed.length);
                let more=[];
                if(remain && filler && typeof filler.draw==='function')more=filler.draw(remain);
                else if(remain)more=fillSource.slice(0,remain);
                return fixed.concat(more);
            }};
        });
        return entries;
    };
}
