function q129BadgeHtml(scope, filename){
    const n=(typeof q126GetMarks==='function' ? q126GetMarks(scope,filename).length : 0);
    return '<span class="q129-tick-badge '+(n?'':'zero')+'" data-q129-scope="'+q126Esc(scope)+'" data-q129-file="'+q126Esc(filename)+'">Tick: '+n+'</span>';
}
function q129SetBadge(el, n){
    if(!el) return false;
    const count=Math.max(0,parseInt(n,10)||0);
    const nextText='Tick: '+String(count);
    const shouldZero=!(count>0);
    let changed=false;
    // FIX132: chỉ ghi vào DOM khi giá trị thực sự đổi để không kích hoạt vòng lặp render.
    if(el.textContent!==nextText){ el.textContent=nextText; changed=true; }
    if(el.classList.contains('zero')!==shouldZero){ el.classList.toggle('zero',shouldZero); changed=true; }
    return changed;
}
function q129LessonRowFilename(row){
    const buttons=Array.from(row.querySelectorAll('button'));
    for(const b of buttons){
        const oc=String(b.getAttribute('onclick')||'');
        const m=oc.match(/lesson109View\('([^']+)'\)/);
        if(m) return m[1].replace(/\\'/g,"'").replace(/\\\\/g,'\\');
    }
    return '';
}
function q129RefreshTickBadges(){
    q129InstallCss();
    document.querySelectorAll('#examBankFileList .exam-bank-file').forEach(row=>{
        const fn=String(row.getAttribute('data-file')||''); if(!fn) return;
        const box=row.querySelector('.exam-bank-pick-box'); if(!box) return;
        let badge=box.querySelector('.q129-tick-badge');
        if(!badge){box.insertAdjacentHTML('beforeend',q129BadgeHtml('exam',fn));badge=box.querySelector('.q129-tick-badge');}
        q129SetBadge(badge,q126GetMarks('exam',fn).length);
        const label=box.querySelector('.qbank-pick-label') || box.querySelector('span:not(.q129-tick-badge)');
        if(label && /^\s*Chọn\s*$/i.test(label.textContent||'')) label.textContent='Chọn/đề';
    });
    document.querySelectorAll('#lesson109List .lesson109-part').forEach(row=>{
        const fn=q129LessonRowFilename(row); if(!fn) return;
        const box=row.querySelector('.lesson109-pick'); if(!box) return;
        let badge=box.querySelector('.q129-tick-badge');
        if(!badge){box.insertAdjacentHTML('beforeend',q129BadgeHtml('lesson',fn));badge=box.querySelector('.q129-tick-badge');}
        q129SetBadge(badge,q126GetMarks('lesson',fn).length);
        if(box.firstChild && box.firstChild.nodeType===3 && /^\s*Chọn\s*/i.test(box.firstChild.textContent||'')) box.firstChild.textContent='Chọn/đề ';
    });
}

// Câu tick tạo thành kho ưu tiên: dùng hết một vòng rồi mới lặp lại.
function q129PriorityDrawer(questions, marks){
    const all=(questions||[]).slice().filter(Boolean);
    const set=new Set((marks||[]).map(n=>parseInt(n,10)).filter(n=>n>0 && n<=all.length));
    const priority=all.filter((_,i)=>set.has(i+1));
    const remainder=all.filter((_,i)=>!set.has(i+1));
    const allDrawer=(typeof lhlQBankCycleDrawerFix101==='function') ? lhlQBankCycleDrawerFix101(all) : null;
    const priorityDrawer=priority.length && typeof lhlQBankCycleDrawerFix101==='function' ? lhlQBankCycleDrawerFix101(priority) : null;
    const remainderDrawer=remainder.length && typeof lhlQBankCycleDrawerFix101==='function' ? lhlQBankCycleDrawerFix101(remainder) : null;
    function fallbackDraw(source,n){ return (source||[]).slice(0,n); }
    return {draw:function(n){
        const wanted=Math.max(0,parseInt(n,10)||0);
        if(!wanted) return [];
        if(!priority.length) return allDrawer ? allDrawer.draw(wanted) : fallbackDraw(all,wanted);
        const fromPriority=Math.min(wanted,priority.length);
        let out=priorityDrawer ? priorityDrawer.draw(fromPriority) : fallbackDraw(priority,fromPriority);
        const remain=wanted-out.length;
        if(remain>0){
            const sourceDrawer=remainderDrawer || allDrawer;
            out=out.concat(sourceDrawer ? sourceDrawer.draw(remain) : fallbackDraw(remainder.length?remainder:all,remain));
        }
        return out;
    }};
}

// Tab Ngân hàng đề thi: lấy đúng giá trị Chọn/mỗi đề do thầy nhập, không bị ép bằng số tick.
if(typeof lhlQBankLoadBankEntriesForGenerateFix87==='function' && !window.__q129ExamPriorityWrapped){
    window.__q129ExamPriorityWrapped=true;
    const __q129PreviousExamLoader=lhlQBankLoadBankEntriesForGenerateFix87;
    lhlQBankLoadBankEntriesForGenerateFix87=async function(count){
        const entries=await __q129PreviousExamLoader.apply(this,arguments);
        const picks=(typeof lhlQBankGetRowPickMapFix87==='function') ? lhlQBankGetRowPickMapFix87() : {};
        entries.forEach(en=>{
            const manual=Math.max(0,parseInt(picks[en.filename],10)||0);
            en.pick=manual;
            en.drawer=q129PriorityDrawer(en.questions,q126GetMarks('exam',en.filename));
        });
        return entries.filter(en=>(parseInt(en.pick,10)||0)>0);
    };
}

// Tab Ngân hàng theo bài: cũng giữ nguyên Chọn/mỗi đề và dùng kho tick theo vòng.
lesson128MakeDrawer = function(questions, marks, pick){
    return {pick:Math.max(0,parseInt(pick,10)||0), draw:q129PriorityDrawer(questions,marks).draw};
};

