function lesson142LessonKey(row, fallbackIndex){
    const selectBtn=row.querySelector('.lesson111-select-btn');
    const oc=selectBtn ? String(selectBtn.getAttribute('onclick') || '') : '';
    const m=oc.match(/lesson111ChooseLesson\('([^']+)'\)/);
    return m ? m[1] : ('row_' + fallbackIndex);
}

function lesson142SetLessonExpanded(key, expanded){
    window.__lesson142ExpandedLessons = window.__lesson142ExpandedLessons || {};
    if(expanded) window.__lesson142ExpandedLessons[key]=true;
    else delete window.__lesson142ExpandedLessons[key];
}

function lesson142ApplyOneLesson(row, key){
    const expanded=!!(window.__lesson142ExpandedLessons && window.__lesson142ExpandedLessons[key]);
    let btn=row.querySelector('.lesson142-toggle');
    if(!btn){
        btn=document.createElement('button');
        btn.type='button';
        btn.className='lesson142-toggle';
        btn.setAttribute('aria-label','Mở các phần của bài');
        row.insertBefore(btn,row.firstChild);
    }
    btn.textContent=expanded ? '−' : '+';
    btn.title=expanded ? 'Thu gọn các phần' : 'Mở các phần TN / Đ-S / TLN';
    btn.setAttribute('aria-expanded',expanded ? 'true' : 'false');
    btn.classList.toggle('expanded',expanded);
    btn.onclick=function(ev){
        ev.preventDefault(); ev.stopPropagation();
        const next=!btn.classList.contains('expanded');
        lesson142SetLessonExpanded(key,next);
        lesson142ApplyOneLesson(row,key);
    };
    let el=row.nextElementSibling;
    while(el && el.classList.contains('lesson109-part')){
        el.classList.toggle('lesson142-part-visible',expanded);
        el.setAttribute('aria-hidden',expanded ? 'false' : 'true');
        el=el.nextElementSibling;
    }
}

function lesson142ApplyCollapse(){
    lesson142InstallCollapseCss();
    const list=document.getElementById('lesson109List');
    if(!list) return;
    list.querySelectorAll('.lesson109-lesson').forEach((row,index)=>{
        lesson142ApplyOneLesson(row,lesson142LessonKey(row,index));
    });
}

