function lesson143EnsureNameSpan(row){
    if(!row) return null;
    let span=row.querySelector(':scope > .lesson143-name');
    let raw='';
    if(span){
        if(span.querySelector('.lesson143-prefix')) return span;
        raw=String(span.textContent||'');
    }else{
        const nodes=Array.from(row.childNodes);
        const textNode=nodes.find(node=>node.nodeType===3 && String(node.textContent||'').trim());
        if(!textNode) return null;
        raw=String(textNode.textContent||'');
        span=document.createElement('span');
        span.className='lesson143-name';
        row.replaceChild(span,textNode);
    }
    const m=raw.match(/^(\s*📖\s*)?(BÀI\s+\d+)([\s\S]*)$/i);
    if(m){
        span.innerHTML='<span class="lesson143-book">'+lesson109Esc(m[1]||'')+'</span>' +
            '<span class="lesson143-prefix">'+lesson109Esc(m[2]||'')+'</span>' +
            '<span class="lesson143-title">'+lesson109Esc(m[3]||'')+'</span>';
    }else{
        span.innerHTML='<span class="lesson143-title">'+lesson109Esc(raw)+'</span>';
    }
    return span;
}

function lesson143ReadPickedCounts(row){
    const values={TN:0,'ĐS':0,TLN:0};
    const keys=['TN','ĐS','TLN'];
    let el=row ? row.nextElementSibling : null;
    let index=0;
    while(el && el.classList.contains('lesson109-part') && index<3){
        const input=el.querySelector('.lesson109-pick input');
        values[keys[index]]=Math.max(0,parseInt(input ? input.value : '0',10)||0);
        index+=1;
        el=el.nextElementSibling;
    }
    return values;
}

function lesson143UpdateLessonRow(row){
    if(!row) return;
    lesson143EnsureNameSpan(row);
    const counts=lesson143ReadPickedCounts(row);
    const parts=[];
    if(counts.TN>0) parts.push(counts.TN+'-TN');
    if(counts['ĐS']>0) parts.push(counts['ĐS']+'-ĐS');
    if(counts.TLN>0) parts.push(counts.TLN+'-TLN');
    const hasPicks=parts.length>0;
    row.classList.toggle('lesson143-has-picks',hasPicks);
    let badge=row.querySelector(':scope > .lesson143-picked-summary');
    if(!badge){
        badge=document.createElement('span');
        badge.className='lesson143-picked-summary';
        const total=row.querySelector(':scope > small');
        if(total) total.insertAdjacentElement('afterend',badge);
        else row.appendChild(badge);
    }
    const nextText=parts.join('; ');
    if(badge.textContent!==nextText) badge.textContent=nextText;
    badge.title=hasPicks ? 'Số câu lấy vào mỗi đề của bài này' : '';
}

