lesson109DecorateNativeExamHeader = function(){
    const overlay=document.getElementById('qbankOverlay');
    if(!overlay) return;
    const header=overlay.querySelector('.qbank-title');
    if(!header) return;
    lesson109InstallCss();
    lesson146InstallThreeTabsCss();
    header.classList.add('lesson109-native-tabs');
    const close=header.querySelector('.qbank-close');
    const existing=header.querySelectorAll('.lesson146-grade-tab');
    if(existing.length===3 && header.querySelector('.lesson148-id-tab')) return;
    existing.forEach(x=>x.remove());
    header.querySelectorAll('.lesson109-open-btn').forEach(x=>x.remove());
    ['10','11','12'].forEach(grade=>{
        const btn=document.createElement('button');
        btn.type='button';
        btn.className='lesson109-open-btn lesson146-grade-tab';
        btn.textContent='KHỐI ' + grade;
        btn.onclick=function(ev){
            ev.preventDefault();
            if(typeof lhlExamBankCaptureSelection==='function') lhlExamBankCaptureSelection();
            document.getElementById('qbankOverlay')?.remove();
            lesson146OpenGrade(grade);
        };
        header.insertBefore(btn,close || null);
    });
    const idBtn=document.createElement('button');
    idBtn.type='button';
    idBtn.className='lesson109-open-btn lesson148-id-tab';
    idBtn.textContent='GÁN ID';
    idBtn.onclick=function(ev){
        ev.preventDefault();
        if(typeof lhlExamBankCaptureSelection==='function') lhlExamBankCaptureSelection();
        lesson148OpenIdTab();
    };
    header.insertBefore(idBtn,close || null);
};
