function lesson151ShortSelect(select, shortLabel, optionsHtml, disabled){
    if(!select) return;
    select.innerHTML='<option value="" selected>'+lesson148Esc(shortLabel)+'</option>'+(optionsHtml||'');
    select.value='';
    select.disabled=!!disabled;
}

// Lưu lựa chọn thật trong state, còn mặt select chỉ hiện CHƯƠNG/BÀI/FILE cho gọn.
const __lesson151UpdateTargetsBase = lesson148UpdateTargets;
lesson148UpdateTargets = async function(){
    const dest=document.getElementById('lesson148Dest')?.value||'10';
    const chapter=document.getElementById('lesson148Chapter');
    const lesson=document.getElementById('lesson148Lesson');
    const part=document.getElementById('lesson148Part');
    const state=window.__lesson148State||(window.__lesson148State={questions:[],active:-1,inventories:{}});
    if(state.lesson151Dest!==dest){
        state.lesson151Dest=dest;
        state.lesson151Chapter=''; state.lesson151Lesson=''; state.lesson151ExamFile='';
    }
    const inv=await lesson148LoadInventory(dest); state.inventories[dest]=inv;
    const status=document.getElementById('lesson148LoadedState');
    if(dest==='EXAM'){
        const fileOptions=(inv.files||[]).map(f=>'<option value="'+lesson148Esc(f.filename)+'">'+lesson148Esc(String(f.filename||'').replace(/\.html?$/i,''))+'</option>').join('');
        lesson151ShortSelect(chapter,'FILE',fileOptions,!!inv.error);
        lesson151ShortSelect(lesson,'BÀI','',true);
        lesson151ShortSelect(part,'PHẦN','',true);
    }else{
        const chapterOptions=(inv.chapters||[]).map((c,i)=>'<option value="'+i+'">'+lesson148Esc(c)+'</option>').join('');
        lesson151ShortSelect(chapter,'CHƯƠNG',chapterOptions,!!inv.error || !(inv.chapters||[]).length);
        lesson151ShortSelect(lesson,'BÀI','',true);
        if(part){
            part.disabled=false;
            part.innerHTML='<option value="A">A - TN</option><option value="B">B - Đ/S</option><option value="C">C - TLN</option>';
            part.value='A';
        }
    }
    if(status){ status.textContent=inv.error?('⚠️ '+inv.error):('✅ Đã load đích: '+(dest==='EXAM'?'ĐỀ THI':'KHỐI '+dest)); status.className='lesson148-status '+(inv.error?'warn':'ok'); }
};

lesson148UpdateLessonSelect = function(){
    const state=window.__lesson148State||(window.__lesson148State={questions:[],active:-1,inventories:{}});
    const dest=document.getElementById('lesson148Dest')?.value||'10';
    const chapterSel=document.getElementById('lesson148Chapter');
    const lessonSel=document.getElementById('lesson148Lesson');
    if(dest==='EXAM'){
        if(chapterSel && chapterSel.value) state.lesson151ExamFile=chapterSel.value;
        const inv=state.inventories[dest]||{};
        const fileOptions=(inv.files||[]).map(f=>'<option value="'+lesson148Esc(f.filename)+'">'+lesson148Esc(String(f.filename||'').replace(/\.html?$/i,''))+'</option>').join('');
        lesson151ShortSelect(chapterSel,'FILE',fileOptions,!!inv.error);
        lesson151ShortSelect(lessonSel,'BÀI','',true);
        return;
    }
    if(chapterSel && chapterSel.value!=='') state.lesson151Chapter=chapterSel.value;
    const inv=state.inventories[dest]||{};
    const ci=Number(state.lesson151Chapter);
    const arr=Number.isInteger(ci) && ci>=0 ? ((inv.grouped||{})[(inv.chapters||[])[ci]]||[]) : [];
    const chapterOptions=(inv.chapters||[]).map((c,i)=>'<option value="'+i+'">'+lesson148Esc(c)+'</option>').join('');
    lesson151ShortSelect(chapterSel,'CHƯƠNG',chapterOptions,!!inv.error || !(inv.chapters||[]).length);
    const lessonOptions=arr.map((it,i)=>'<option value="'+i+'">'+lesson148Esc(it.lesson||('Bài '+(i+1)))+'</option>').join('');
    lesson151ShortSelect(lessonSel,'BÀI',lessonOptions,!arr.length);
};

function lesson151RememberLesson(){
    const state=window.__lesson148State||(window.__lesson148State={questions:[],active:-1,inventories:{}});
    const sel=document.getElementById('lesson148Lesson');
    const dest=document.getElementById('lesson148Dest')?.value||'10';
    if(dest!=='EXAM' && sel && sel.value!=='') state.lesson151Lesson=sel.value;
    const inv=state.inventories[dest]||{};
    const ci=Number(state.lesson151Chapter);
    const arr=Number.isInteger(ci)&&ci>=0 ? ((inv.grouped||{})[(inv.chapters||[])[ci]]||[]) : [];
    const options=arr.map((it,i)=>'<option value="'+i+'">'+lesson148Esc(it.lesson||('Bài '+(i+1)))+'</option>').join('');
    lesson151ShortSelect(sel,'BÀI',options,!arr.length);
}

lesson148SelectedRoute = function(){
    const state=window.__lesson148State||{};
    const dest=document.getElementById('lesson148Dest')?.value||'10';
    if(dest==='EXAM'){
        const fn=String(state.lesson151ExamFile||'');
        return fn ? ('['+fn.replace(/\.html?$/i,'').toUpperCase()+']') : '';
    }
    const ci=Number(state.lesson151Chapter), li=Number(state.lesson151Lesson);
    if(!Number.isInteger(ci)||ci<0||!Number.isInteger(li)||li<0) return '';
    const part=document.getElementById('lesson148Part')?.value||'A';
    return '['+dest+'-'+(ci+1)+'-'+(li+1)+'-'+part+']';
};

