// - Sua loi FIX151 lam select CHUONG/BAI mat gia tri do thay bang placeholder sau moi lan chon.
// - Giu bo cuc va hang tab co dinh da on dinh cua FIX151.
// ============================================================
function lesson152InstallUi(){
    let st=document.getElementById('lesson152Ui');
    if(!st){ st=document.createElement('style'); st.id='lesson152Ui'; document.head.appendChild(st); }
    st.textContent=`
    html body #lesson148Overlay .lesson148-route-input{
        width:252px!important;min-width:252px!important;max-width:252px!important;
        padding:0 8px!important;font-size:13px!important;
    }
    @media(max-width:1160px){
        html body #lesson148Overlay .lesson148-route-input{
            width:238px!important;min-width:238px!important;max-width:238px!important;
            font-size:12px!important;
        }
    }`;
}
function lesson152SetSelect(select, placeholder, optionsHtml, wantedValue, disabled){
    if(!select) return;
    select.innerHTML='<option value="">'+lesson148Esc(placeholder)+'</option>'+(optionsHtml||'');
    select.disabled=!!disabled;
    const want=String(wantedValue==null?'':wantedValue);
    const has=Array.from(select.options||[]).some(o=>String(o.value)===want && want!=='');
    select.value=has?want:'';
}
function lesson152LessonChanged(){
    const state=window.__lesson148State||(window.__lesson148State={questions:[],active:-1,inventories:{}});
    const dest=document.getElementById('lesson148Dest')?.value||'10';
    const lesson=document.getElementById('lesson148Lesson');
    if(dest!=='EXAM' && lesson) state.lesson151Lesson=lesson.value||'';
}
lesson148UpdateTargets = async function(){
    const state=window.__lesson148State||(window.__lesson148State={questions:[],active:-1,inventories:{}});
    const dest=document.getElementById('lesson148Dest')?.value||'10';
    const chapter=document.getElementById('lesson148Chapter');
    const lesson=document.getElementById('lesson148Lesson');
    const part=document.getElementById('lesson148Part');
    if(state.lesson151Dest!==dest){
        state.lesson151Dest=dest;
        state.lesson151Chapter=''; state.lesson151Lesson=''; state.lesson151ExamFile='';
    }
    const inv=await lesson148LoadInventory(dest); state.inventories[dest]=inv;
    const status=document.getElementById('lesson148LoadedState');
    if(dest==='EXAM'){
        const fileOptions=(inv.files||[]).map(f=>'<option value="'+lesson148Esc(f.filename)+'">'+lesson148Esc(String(f.filename||'').replace(/\.html?$/i,''))+'</option>').join('');
        lesson152SetSelect(chapter,'FILE',fileOptions,state.lesson151ExamFile,!!inv.error);
        lesson152SetSelect(lesson,'BÀI','', '', true);
        lesson152SetSelect(part,'PHẦN','', '', true);
        chapter.onchange=function(){ state.lesson151ExamFile=this.value||''; };
    }else{
        const chapterOptions=(inv.chapters||[]).map((c,i)=>'<option value="'+i+'">'+lesson148Esc(c)+'</option>').join('');
        lesson152SetSelect(chapter,'CHƯƠNG',chapterOptions,state.lesson151Chapter,!!inv.error || !(inv.chapters||[]).length);
        if(part){
            const oldPart=part.value||'A';
            part.disabled=false;
            part.innerHTML='<option value="A">A - TN</option><option value="B">B - Đ/S</option><option value="C">C - TLN</option>';
            part.value=/^[ABC]$/.test(oldPart)?oldPart:'A';
        }
        chapter.onchange=function(){ state.lesson151Chapter=this.value||''; state.lesson151Lesson=''; lesson148UpdateLessonSelect(); };
        lesson148UpdateLessonSelect();
    }
    if(status){
        status.textContent=inv.error?('⚠️ '+inv.error):('✅ Đã load đích: '+(dest==='EXAM'?'ĐỀ THI':'KHỐI '+dest));
        status.className='lesson148-status '+(inv.error?'warn':'ok');
    }
};
lesson148UpdateLessonSelect = function(){
    const state=window.__lesson148State||(window.__lesson148State={questions:[],active:-1,inventories:{}});
    const dest=document.getElementById('lesson148Dest')?.value||'10';
    if(dest==='EXAM') return;
    const inv=state.inventories[dest]||{};
    const chapterSel=document.getElementById('lesson148Chapter');
    const lessonSel=document.getElementById('lesson148Lesson');
    if(!chapterSel || !lessonSel) return;
    const chosenChapter=chapterSel.value||state.lesson151Chapter||'';
    state.lesson151Chapter=chosenChapter;
    const ci=(chosenChapter==='')?-1:Number(chosenChapter);
    const chapterName=(Number.isInteger(ci)&&ci>=0)?(inv.chapters||[])[ci]:'';
    const arr=chapterName ? ((inv.groups||{})[chapterName]||[]) : [];
    const lessonOptions=arr.map((it,i)=>'<option value="'+i+'">'+lesson148Esc(it.lesson||('Bài '+(i+1)))+'</option>').join('');
    lesson152SetSelect(lessonSel,'BÀI',lessonOptions,state.lesson151Lesson,!arr.length);
    lessonSel.onchange=lesson152LessonChanged;
};
lesson148SelectedRoute = function(){
    const dest=document.getElementById('lesson148Dest')?.value||'10';
    if(dest==='EXAM'){
        const fn=document.getElementById('lesson148Chapter')?.value||'';
        return fn?('['+fn.replace(/\.html?$/i,'').toUpperCase()+']'):'';
    }
    const chapter=document.getElementById('lesson148Chapter')?.value||'';
    const lesson=document.getElementById('lesson148Lesson')?.value||'';
    if(chapter==='' || lesson==='') return '';
    const part=document.getElementById('lesson148Part')?.value||'A';
    return '['+dest+'-'+(Number(chapter)+1)+'-'+(Number(lesson)+1)+'-'+part+']';
};
lesson152InstallUi();
if(typeof lesson148OpenIdTab==='function' && !window.__lesson152IdOpenWrapped){
    window.__lesson152IdOpenWrapped=true;
    const __lesson152Open=lesson148OpenIdTab;
    lesson148OpenIdTab=function(){
        lesson152InstallUi();
        const ret=__lesson152Open.apply(this,arguments);
        const lesson=document.getElementById('lesson148Lesson');
        if(lesson) lesson.onchange=lesson152LessonChanged;
        return ret;
    };
}


