function lesson154PaperContentWidth(){
    const paper=document.getElementById('paper');
    if(!paper) return 733;
    try{
        const cs=getComputedStyle(paper);
        const rect=paper.getBoundingClientRect();
        const offset=paper.offsetWidth || parseFloat(cs.width) || 1;
        const scale=rect.width>0 ? rect.width/offset : 1;
        const pad=(parseFloat(cs.paddingLeft)||0)+(parseFloat(cs.paddingRight)||0);
        const w=(offset-pad)*scale;
        return Number.isFinite(w)&&w>300 ? Math.round(w) : 733;
    }catch(e){ return 733; }
}
function lesson154SyncRenderFrame(){
    const overlay=document.getElementById('lesson148Overlay');
    if(!overlay) return;
    overlay.style.setProperty('--lesson154-paper-content-width',lesson154PaperContentWidth()+'px');
}
