// ============================================================
// FIX155 - DANH DAU TAM THOI NOI VUA NHAP CAU TRONG PHIEN NGAN HANG
// Nen: FIX154. Chi bo sung nhan biet giao dien, khong ghi trang thai vao file NH.
// - KHOI 10/11/12: to do dong "Tong ... cau" cua bai vua nhan cau.
// - DE THI: to do cot Tong/Số câu cua file vua nhan cau.
// - Dong hop thoai Ngan hang roi mo lai: tu dong bo to do.
// ============================================================
window.__lesson155Recent = window.__lesson155Recent || { exam:new Set(), lessons:new Set() };
function lesson155InstallCss(){
    let st=document.getElementById('lesson155RecentCss');
    if(!st){ st=document.createElement('style'); st.id='lesson155RecentCss'; document.head.appendChild(st); }
    st.textContent=`
    html body #lesson109Overlay .lesson109-lesson.lesson155-recent-import > small{
        color:#ff3131!important;font-weight:950!important;text-shadow:0 0 1px rgba(255,49,49,.30)!important;
    }
    html body #examBankFileList .exam-bank-file.lesson155-recent-import .exam-bank-count,
    html body #examBankFileList .exam-bank-file.lesson155-recent-import .exam-bank-count b{
        color:#ff3131!important;font-weight:950!important;text-shadow:0 0 1px rgba(255,49,49,.28)!important;
    }
    `;
}
function lesson155ClearRecent(){
    window.__lesson155Recent={exam:new Set(),lessons:new Set()};
}
function lesson155LessonKey(grade,filename){ return String(grade||'10')+'|'+String(filename||'').toLowerCase(); }
function lesson155MarkExam(filename){ if(filename) window.__lesson155Recent.exam.add(String(filename).toLowerCase()); }
function lesson155MarkLesson(grade,filename){ if(filename) window.__lesson155Recent.lessons.add(lesson155LessonKey(grade,filename)); }
function lesson155ExamStatusOk(){
    const el=document.getElementById('examBankPendingInfo');
    return !!(el && /✅|Đã nhập/i.test(String(el.textContent||'')) && !/Lỗi nhập/i.test(String(el.textContent||'')));
}
function lesson155LessonStatusOk(){
    const el=document.getElementById('lesson109Status');
    return !!(el && (el.classList.contains('ok') || /✅|Đã nhập/i.test(String(el.textContent||''))));
}
function lesson155ApplyExam(){
    lesson155InstallCss();
    document.querySelectorAll('#examBankFileList .exam-bank-file').forEach(row=>{
        const fn=String(row.getAttribute('data-file')||'').toLowerCase();
        row.classList.toggle('lesson155-recent-import',window.__lesson155Recent.exam.has(fn));
    });
}
function lesson155ApplyLessons(){
    lesson155InstallCss();
    const list=document.getElementById('lesson109List');
    if(!list) return;
    const grade=(typeof lesson146Grade==='function')?lesson146Grade():'10';
    const lessons=Array.isArray(window.__lesson111Lessons)?window.__lesson111Lessons:[];
    const rows=Array.from(list.querySelectorAll('.lesson109-lesson'));
    rows.forEach((row,i)=>{
        const item=lessons[i];
        let marked=false;
        if(item && item.parts){
            ['TN','DS','TLN'].forEach(part=>{
                const fn=item.parts[part] && item.parts[part].filename;
                if(fn && window.__lesson155Recent.lessons.has(lesson155LessonKey(grade,fn))) marked=true;
            });
        }
        row.classList.toggle('lesson155-recent-import',marked);
    });
}
lesson155InstallCss();

// Xóa dấu nhận biết khi thầy thực sự đóng hộp thoại Ngân hàng; chuyển tab thì vẫn giữ dấu.
if(!window.__lesson155CloseListener){
    window.__lesson155CloseListener=true;
    document.addEventListener('click',function(ev){
        const close=ev.target && ev.target.closest ? ev.target.closest('#qbankOverlay .qbank-close, #lesson109Overlay .lesson109-close, #lesson148Overlay .lesson109-close') : null;
        if(close) lesson155ClearRecent();
    },true);
}

// Mỗi lần danh sách render lại, phục hồi đúng màu đánh dấu của phiên hiện hành.
if(typeof lhlExamBankRefreshFiles==='function' && !window.__lesson155ExamRefreshWrapped){
    window.__lesson155ExamRefreshWrapped=true;
    const __lesson155ExamRefresh=lhlExamBankRefreshFiles;
    lhlExamBankRefreshFiles=async function(){
        const ret=await __lesson155ExamRefresh.apply(this,arguments);
        lesson155ApplyExam();
        return ret;
    };
}
if(typeof lesson109Refresh==='function' && !window.__lesson155LessonRefreshWrapped){
    window.__lesson155LessonRefreshWrapped=true;
    const __lesson155LessonRefresh=lesson109Refresh;
    lesson109Refresh=async function(){
        const ret=await __lesson155LessonRefresh.apply(this,arguments);
        lesson155ApplyLessons();
        return ret;
    };
}

// Nhập câu bôi đen vào một file của tab ĐỀ THI.
if(typeof lhlExamBankAppend==='function' && !window.__lesson155ExamAppendWrapped){
    window.__lesson155ExamAppendWrapped=true;
    const __lesson155ExamAppend=lhlExamBankAppend;
    lhlExamBankAppend=async function(filename){
        const ret=await __lesson155ExamAppend.apply(this,arguments);
        if(lesson155ExamStatusOk()){
            lesson155MarkExam(filename);
            lesson155ApplyExam();
        }
        return ret;
    };
}
// Nhập nguyên file hiện hành vào tab ĐỀ THI.
if(typeof lhlExamBankImportCurrentFile==='function' && !window.__lesson155ExamWholeWrapped){
    window.__lesson155ExamWholeWrapped=true;
    const __lesson155ExamWhole=lhlExamBankImportCurrentFile;
    lhlExamBankImportCurrentFile=async function(){
        let files=[];
        try{
            const existing=typeof lhlQBankGetExistingFileSetFromDialog==='function' ? lhlQBankGetExistingFileSetFromDialog() : null;
            const d=typeof lhlQBankBuildImportItemsFromCurrentEditorStrict==='function' ? lhlQBankBuildImportItemsFromCurrentEditorStrict(existing) : null;
            files=(d && d.items ? d.items : []).map(it=>it.filename);
        }catch(e){}
        const ret=await __lesson155ExamWhole.apply(this,arguments);
        if(lesson155ExamStatusOk()){
            files.forEach(lesson155MarkExam);
            lesson155ApplyExam();
        }
        return ret;
    };
}

// Nhập câu bôi đen vào một phần của bài trong KHỐI 10/11/12.
if(typeof lesson109Append==='function' && !window.__lesson155LessonAppendWrapped){
    window.__lesson155LessonAppendWrapped=true;
    const __lesson155LessonAppend=lesson109Append;
    lesson109Append=async function(filename){
        const grade=(typeof lesson146Grade==='function')?lesson146Grade():'10';
        const ret=await __lesson155LessonAppend.apply(this,arguments);
        if(lesson155LessonStatusOk()){
            lesson155MarkLesson(grade,filename);
            lesson155ApplyLessons();
        }
        return ret;
    };
}
// Nhập nguyên file hiện hành vào bài đã chọn của KHỐI 10/11/12.
if(typeof lesson111ImportCurrentFile==='function' && !window.__lesson155LessonWholeWrapped){
    window.__lesson155LessonWholeWrapped=true;
    const __lesson155LessonWhole=lesson111ImportCurrentFile;
    lesson111ImportCurrentFile=async function(){
        const grade=(typeof lesson146Grade==='function')?lesson146Grade():'10';
        const id=String(window.__lesson111SelectedLessonId||'');
        const item=(window.__lesson111Lessons||[]).find(it=>String(it.id)===id);
        const files=item && item.parts ? ['TN','DS','TLN'].map(p=>item.parts[p]&&item.parts[p].filename).filter(Boolean) : [];
        const ret=await __lesson155LessonWhole.apply(this,arguments);
        if(lesson155LessonStatusOk()){
            files.forEach(fn=>lesson155MarkLesson(grade,fn));
            lesson155ApplyLessons();
        }
        return ret;
    };
}

// Nhập theo ID: đánh dấu mọi file/bài đích đã nhập thành công trong phiên hiện tại.
if(typeof lesson148ImportRouted==='function' && !window.__lesson155IdImportWrapped){
    window.__lesson155IdImportWrapped=true;
    const __lesson155IdImport=lesson148ImportRouted;
    lesson148ImportRouted=async function(){
        const candidates=[];
        try{
            for(const q of (window.__lesson148State.questions||[])){
                const id=lesson148TagText(q.id); if(!id) continue;
                const route=lesson148ParseRoute(id);
                const dest=await lesson148ResolveDestination(route);
                if(!dest || dest.error || q.part!==dest.part) continue;
                candidates.push(dest);
            }
        }catch(e){}
        const ret=await __lesson155IdImport.apply(this,arguments);
        const status=document.getElementById('lesson148Status');
        if(status && /Đã nhập/i.test(String(status.textContent||''))){
            candidates.forEach(dest=>{
                if(dest.scope==='EXAM') lesson155MarkExam(dest.filename);
                else lesson155MarkLesson(dest.scope,dest.filename);
            });
        }
        return ret;
    };
}


// ============================================================
// FIX156 - DONG BO HOP XEM CAC TAB THEO VUNG HIEN THI GAN ID
// Nen: FIX155.
// - Xem nhanh DE THI va KHOI 10/11/12 dung cung kho noi dung, le chu, cach dan dap an nhu GAN ID.
