// LHL Tool 1.0 ONLINE SAFE
// - File HTML moi va luong IN PDF khong con goi polyfill.io; MathJax online van giu nguyen.

// ============================================================
// LHL Tool 1.0 - HIEU UNG HOP THOAI V2 AN TOAN
// - Khong animate khi chuyen tab trong Ngan hang / GAN ID de tranh chop.
// - Chi animate khi mo Ngan hang tu thanh cong cu va khi dong nut Dong.
// - Khong sua logic du lieu, tao de, nhap ID hay render danh sach.
// ============================================================
(function lhlInstallModalMotionV2(){
    if(window.__lhlModalMotionV2Installed) return;
    window.__lhlModalMotionV2Installed=true;
    let switchingBankTab=false;
    let switchTimer=null;
    function markBankTabSwitch(){
        switchingBankTab=true;
        clearTimeout(switchTimer);
        switchTimer=setTimeout(function(){ switchingBankTab=false; },180);
    }
    function addEnterOnce(el){
        if(!el || switchingBankTab) return;
        el.classList.remove('lhl-dialog-exit-v2');
        el.classList.add('lhl-dialog-enter-v2');
        setTimeout(function(){ if(el && el.isConnected) el.classList.remove('lhl-dialog-enter-v2'); },230);
    }
    function animateCloseOverlay(overlay){
        if(!overlay || !overlay.isConnected || overlay.classList.contains('lhl-dialog-exit-v2')) return;
        overlay.classList.remove('lhl-dialog-enter-v2');
        overlay.classList.add('lhl-dialog-exit-v2');
        setTimeout(function(){ if(overlay && overlay.isConnected) overlay.remove(); },155);
    }
    // Bao hieu thao tac chuyen tab truoc khi ham tab remove/tao overlay moi.
    document.addEventListener('pointerdown',function(ev){
        const tab=ev.target && ev.target.closest ? ev.target.closest('.lesson109-open-btn, .lesson109-tab, .lesson148-id-tab') : null;
        if(tab && !tab.classList.contains('active')) markBankTabSwitch();
    },true);
    // Nut Dong cua hop Ngan hang / cac tab Khoi / GAN ID: thu nhe roi moi dong.
    document.addEventListener('click',function(ev){
        const btn=ev.target && ev.target.closest ? ev.target.closest('#qbankOverlay .qbank-close, #lesson109Overlay .lesson109-close, #lesson148Overlay .lesson109-close') : null;
        if(!btn) return;
        const overlay=btn.closest('#qbankOverlay, #lesson109Overlay, #lesson148Overlay');
        if(!overlay) return;
        ev.preventDefault();
        ev.stopPropagation();
        ev.stopImmediatePropagation();
        animateCloseOverlay(overlay);
    },true);
    // Chi Nut Ngan hang ngoai giao dien moi kich hoat animation mo qbank.
    const bankButton=document.querySelector('button[onmousedown*="openQuestionBankDialog"]');
    if(bankButton){
        bankButton.addEventListener('pointerdown',function(){ switchingBankTab=false; },true);
    }
    if(typeof openQuestionBankDialog==='function' && !window.__lhlModalOpenQBankV2){
        window.__lhlModalOpenQBankV2=true;
        const originalOpenQuestionBankDialog=openQuestionBankDialog;
        openQuestionBankDialog=function(){
            const isTabTransition=switchingBankTab;
            const ret=originalOpenQuestionBankDialog.apply(this,arguments);
            if(!isTabTransition) addEnterOnce(document.getElementById('qbankOverlay'));
            return ret;
        };
    }
})();



// ============================================================
// LHL Tool 1.0 - HIEU UNG HOP THOAI V3 MO RONG (CHI GIAO DIEN)
// - Chi tri hoan thao tac remove/hide trong 175ms de thay hieu ung dong.
// - Loai tru cac overlay tab Ngan hang/GAN ID khi chuyen tab; V2 da xu ly nut Dong rieng.
// - Khong observer, khong lap render, khong sua du lieu/nghiep vu.
// ============================================================
(function lhlInstallModalMotionV3Extended(){
    if(window.__lhlModalMotionV3ExtendedInstalled) return;
    window.__lhlModalMotionV3ExtendedInstalled=true;
    const CLOSE_MS=178;
    const closableSelector=[
        '.exam-modal-mask', '.lhl-bank-gen-overlay', '.lhl-gs-overlay',
        '.lhl-config-overlay', '.lhl-mix-overlay', '.lhl-merge-overlay',
        '.lhl-cv-overlay', '#qbank123DialogMask', '#q133MatrixOverlay',
        '#lesson111DeleteModal', '#lesson115DialogOverlay', '#lesson128GenOverlay'
    ].join(',');
    const nativeRemove=Element.prototype.remove;
    Element.prototype.remove=function(){
        try{
            if(this && this.matches && this.matches(closableSelector) && this.isConnected && !this.__lhlRemoveImmediate){
                if(this.__lhlExitPending) return;
                this.__lhlExitPending=true;
                this.classList.add('lhl-pop-exit-v3');
                const el=this;
                setTimeout(function(){
                    if(el && el.isConnected){
                        el.__lhlRemoveImmediate=true;
                        nativeRemove.call(el);
                    }
                }, CLOSE_MS);
                return;
            }
        }catch(e){ console.warn('LHL modal close effect:',e); }
        return nativeRemove.call(this);
    };
    function closeStaticSmooth(id, after){
        const overlay=document.getElementById(id);
        if(!overlay || overlay.style.display==='none') { after(); return; }
        if(overlay.__lhlStaticExitPending) return;
        overlay.__lhlStaticExitPending=true;
        overlay.classList.add('lhl-static-exit-v3');
        setTimeout(function(){
            overlay.classList.remove('lhl-static-exit-v3');
            overlay.__lhlStaticExitPending=false;
            after();
        }, CLOSE_MS);
    }
    // Hai hop xac nhan co dinh trong index dung display:none thay vi remove().
    if(typeof cancelClose==='function' && !window.__lhlV3CancelCloseWrapped){
        window.__lhlV3CancelCloseWrapped=true;
        const fn=cancelClose;
        cancelClose=function(){ const args=arguments, ctx=this; closeStaticSmooth('save-confirm-overlay', function(){fn.apply(ctx,args);}); };
    }
    if(typeof dontSaveAndClose==='function' && !window.__lhlV3DontSaveWrapped){
        window.__lhlV3DontSaveWrapped=true;
        const fn=dontSaveAndClose;
        dontSaveAndClose=function(){ const args=arguments, ctx=this; closeStaticSmooth('save-confirm-overlay', function(){fn.apply(ctx,args);}); };
    }
    if(typeof confirmSaveAndClose==='function' && !window.__lhlV3SaveCloseWrapped){
        window.__lhlV3SaveCloseWrapped=true;
        const fn=confirmSaveAndClose;
        confirmSaveAndClose=function(){ const args=arguments, ctx=this; closeStaticSmooth('save-confirm-overlay', function(){fn.apply(ctx,args);}); };
    }
    if(typeof closeCustomConfirm==='function' && !window.__lhlV3CustomConfirmWrapped){
        window.__lhlV3CustomConfirmWrapped=true;
        const fn=closeCustomConfirm;
        closeCustomConfirm=function(){ const args=arguments, ctx=this; closeStaticSmooth('custom-confirm-overlay', function(){fn.apply(ctx,args);}); };
    }
})();


