// LHL Tool 1.0 - HIEU UNG HOP THOAI V4: KHONG CHOP KHI VE TAB DE THI
// - Chi tat hieu ung/trang thai preparing khi chuyen NOI BO tu KHOI/GAN ID ve DE THI.
// - Mo hop Ngan hang tu nut ben ngoai van giu hieu ung mem V3.
// - Khong sua du lieu, ham nghiep vu hay bo cuc giao dien.
// ============================================================
(function lhlDisableExamTabReopenFlashV4(){
    if(window.__lhlDisableExamTabReopenFlashV4Installed) return;
    window.__lhlDisableExamTabReopenFlashV4Installed=true;
    window.__lhlInternalGoExamTabV4=false;

    function settleExamTabInstantlyV4(){
        const ov=document.getElementById('qbankOverlay');
        if(!ov) return;
        ov.classList.add('lhl-bank-tab-instant-v4');
        ov.classList.remove('lhl-dialog-enter-v2','lhl-dialog-exit-v2','lhl-pop-exit-v3','lhl-static-exit-v3','lhl-qbank-preparing');
        ov.classList.add('lhl-qbank-ready');
        const body=ov.querySelector('.qbank-body');
        if(body){
            body.style.opacity='1';
            body.style.visibility='visible';
        }
    }
    function finishInstantV4(){
        const ov=document.getElementById('qbankOverlay');
        if(!ov) return;
        settleExamTabInstantlyV4();
        setTimeout(function(){
            if(ov && ov.isConnected){
                ov.classList.remove('lhl-bank-tab-instant-v4');
                const body=ov.querySelector('.qbank-body');
                if(body){ body.style.opacity=''; body.style.visibility=''; }
            }
        }, 320);
    }
    function beginInternalGoExamV4(){ window.__lhlInternalGoExamTabV4=true; }

    if(typeof lesson109OpenExamBack==='function' && !window.__lhlV4LessonExamWrapped){
        window.__lhlV4LessonExamWrapped=true;
        const fn=lesson109OpenExamBack;
        lesson109OpenExamBack=function(){ beginInternalGoExamV4(); return fn.apply(this, arguments); };
    }
    if(typeof lesson148GoExam==='function' && !window.__lhlV4IdExamWrapped){
        window.__lhlV4IdExamWrapped=true;
        const fn=lesson148GoExam;
        lesson148GoExam=function(){ beginInternalGoExamV4(); return fn.apply(this, arguments); };
    }
    if(typeof openQuestionBankDialog==='function' && !window.__lhlV4OpenExamWrapped){
        window.__lhlV4OpenExamWrapped=true;
        const fn=openQuestionBankDialog;
        openQuestionBankDialog=function(){
            const internal=!!window.__lhlInternalGoExamTabV4;
            const ret=fn.apply(this, arguments);
            window.__lhlInternalGoExamTabV4=false;
            if(internal){
                settleExamTabInstantlyV4();
                setTimeout(settleExamTabInstantlyV4, 0);
                setTimeout(settleExamTabInstantlyV4, 35);
                setTimeout(settleExamTabInstantlyV4, 130);
                setTimeout(finishInstantV4, 235);
            }
            return ret;
        };
    }
})();

