        if (!convertedI || !convertedII || !convertedIII || missed.length) {
            throw new Error('Chưa nhận diện đầy đủ câu VMath (I=' + convertedI + ', II=' + convertedII + ', III=' + convertedIII + ', thiếu=' + missed.length + ').');
        }
        let result = normalizeIntegral(out.join('\n'));

        // V20: dựng lại ba tiêu đề theo chuẩn LHL và tự chèn số câu thực tế.
        const canonicalTitles = {
            I: '<div class="exam-part-box"><b>PHẦN I. Thí sinh trả lời từ câu 1 đến câu ' + convertedI + '. Mỗi câu hỏi thí sinh chỉ chọn một phương án.</b></div>',
            II: '<div class="exam-part-box exam-part-box-wide"><b>PHẦN II. Thí sinh trả lời từ câu 1 đến câu ' + convertedII + '. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.</b></div>',
            III: '<div class="exam-part-box"><b>PHẦN III. Thí sinh trả lời từ câu 1 đến câu ' + convertedIII + '.</b></div>'
        };
        result = result.replace('<!--LHL_V20_PART_I-->', canonicalTitles.I)
            .replace('<!--LHL_V20_PART_II-->', canonicalTitles.II)
            .replace('<!--LHL_V20_PART_III-->', canonicalTitles.III);

        // V20: chuẩn hóa dấu quan hệ nằm trong công thức TeX của file VMath.
        // Dùng lệnh LaTeX thay cho entity {&lt;}/{&gt;} để MathJax render ổn định.
        function fixRelations(math) {
            return String(math || '')
                .replace(/\{?\s*(?:&lt;|<)\s*\}?/gi, ' \\lt ')
                .replace(/\{?\s*(?:&gt;|>)\s*\}?/gi, ' \\gt ')
                .replace(/\{?\s*(?:&le;|&leq;|≤)\s*\}?/gi, ' \\leq ')
                .replace(/\{?\s*(?:&ge;|&geq;|≥)\s*\}?/gi, ' \\geq ')
                .replace(/(?:&ne;|≠|\\ne(?!q))/gi, '\\neq')
                .replace(/\s{2,}/g, ' ');
        }
        result = result.replace(/\$([^$]*?)\$/g, function(_all, math) { return '$' + fixRelations(math) + '$'; })
            .replace(/\\\(([\s\S]*?)\\\)/g, function(_all, math) { return '\\(' + fixRelations(math) + '\\)'; });

        result = result.replace(/<p\b[^>]*class=["'][^"']*FontDung[^"']*["'][^>]*>/gi, '<p>');
        result = result.replace(/\n{3,}/g, '\n\n').trim();
