    function dec36(s){ const ta=document.createElement('textarea'); ta.innerHTML=String(s||''); return ta.value; }
    function esc36(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
    function text36(el){ return String(el && (el.textContent || el.innerText) || '').replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim(); }
    function stripTags36(s){ return dec36(String(s||'').replace(/<br\s*\/?\s*>/gi,' ').replace(/<[^>]*>/g,' ')).replace(/\s+/g,' ').trim(); }
