        const qCount = (txt.match(/Câu\s*\d+\s*[:.]/gi)||[]).length;
        const specific = /(Sữa\s*chua|vòm\s*sắt|thùng\s*rượu|Trả\s*lời\s*[:：]|chiều\s*cao\s*\(đơn\s*vị|12A2|Radar|lactic)/i.test(txt);
