                if(el.querySelector('img') && !/^\s*$/.test(text36(el))){ arr.push({el:el,text:text36(el),html:el.innerHTML||'',imgs:Array.from(el.querySelectorAll('img'))}); return; }
                if(el.querySelector('img') && !el.querySelector('p')){ arr.push({el:el,text:text36(el),html:el.innerHTML||'',imgs:Array.from(el.querySelectorAll('img'))}); return; }
