        let h='<table class="lhl-rendered-latex-table" style="border-collapse: collapse; margin: 10px auto; text-align: center;"><tbody>';
        rows.forEach((r,idx)=>{ h+='<tr>'+r.map(c=>'<td>'+(idx===0?'<b>'+c+'</b>':c)+'</td>').join('')+'</tr>'; });
