        // Ngắt PHẦN II câu 2 khỏi câu 1 nếu bị dính sau dấu chấm.
        out=out.replace(/(hàm\s*f\\left\(\s*x\s*\\right\)\s*xác\s*định\.?)\s*(<b>\s*Câu\s*2\s*[\.:]\s*<\/b>)/i,'$1<br>\n$2');
        out=out.replace(/(hàm\s*f\s*\(\s*x\s*\)\s*xác\s*định\.?)\s*(<b>\s*Câu\s*2\s*[\.:]\s*<\/b>)/i,'$1<br>\n$2');
        // Nếu PHẦN III bị mất tiêu đề và dính sau PHẦN II câu 4.
