        out=out.replace(/\$?\\left\\\{\s*1\s*;\s*2\s*;\s*3\s*;\s*5\s*;\s*6\s*\\right\s*\$?\s*(?:[\\{}\s]*\$+|[\\{}\s]+)+/gi, '$\\left\\{1;2;3;5;6\\right\\}$')
