        out=out.replace(/<b>\s*Câu\s*2\s*[\.:]\s*<\/b>[\s\S]*?(?=<div\s+class="choices\s+cols-4")/i, fixedQuestion);
        // Hậu dọn nếu vẫn còn sót sau khi render từ nguồn khác.
