        if(p3Index < 0) p3Index = out.length;
        let head = out.slice(0,p2Index), mid = out.slice(p2Index,p3Index), tail = out.slice(p3Index);
        // Không để Câu 2/3/4 dính sau câu trước.
        mid = mid.replace(/([^>\n])\s*(<b>\s*Câu\s*[2-4]\s*[\.:]\s*<\/b>)/gi, '$1<br>\n$2');
        mid = mid.replace(/([^>\n])\s+Câu\s*([2-4])\s*[\.:]\s+/gi, '$1<br>\n<b>Câu $2.</b> ');
        // Căn lại a), b), c), d) dạng dòng riêng, in đậm nhãn.
        mid = mid.replace(/(<b>\s*Câu\s*\d+\s*[\.:]\s*<\/b>[\s\S]*?)(?=\s*a\))/gi, '$1<br>\n');
